def _reply_kb(rows: list[list[str]]) -> ReplyKeyboardMarkup:
    return ReplyKeyboardMarkup(
        keyboard=[[KeyboardButton(text=t) for t in row] for row in rows],
        resize_keyboard=True,
        selective=True,
    )


def _grid(items: list[str], cols: int = 2) -> list[list[str]]:
    """Разбивает плоский список кнопок на ряды по `cols` штук — так клавиатура
    выглядит компактной сеткой, а не длинной «лесенкой» из одиночных кнопок."""
    return [items[i:i + cols] for i in range(0, len(items), cols)]


def private_confirm_kb(yes_text: str = "✅ Да, подтвердить") -> ReplyKeyboardMarkup:
    """Клавиатура подтверждения для личных диалогов (админ-панель, жалобы)."""
    return _reply_kb([[yes_text, BTN_CANCEL]])


