_HTML_TAG_RE = ru_text.rx(r"<[^>]+>")


def plain_name(name: Optional[str]) -> str:
    """Имя без HTML-разметки — для того, что ХРАНИТСЯ и потом экранируется.

    display_name()/display_name_by_id() всегда возвращают HTML-ссылку. Записав
    её в базу как есть, при показе получаем экранированные теги прямо в тексте
    («&lt;a href=...&gt;»). Чистим и при записи, и при показе: записи,
    сделанные до починки, уже лежат с разметкой.
    """
    return html.unescape(_HTML_TAG_RE.sub("", name or "")).strip() or "—"


async def plain_name_by_id(chat_id: int, user_id: int) -> str:
    """Имя человека без разметки: ник чата, иначе то, что знает кэш."""
    nickname = await db.get_nickname(chat_id, user_id)
    if nickname:
        return plain_name(nickname)
    return plain_name(_plain_display_name(user_id))


def _plain_display_name(user_id: int, max_len: int = 25) -> str:
    """Имя пользователя без HTML-разметки — для кнопок ReplyKeyboardMarkup
    (в отличие от mention_id()/display_name(), которые всегда возвращают
    HTML-ссылку — Telegram не рендерит разметку в тексте обычных кнопок).
    Берётся из user_registry (кэш известных боту людей, см. load_caches());
    если человека там нет — просто показываем голый ID, как было раньше."""
    cached = user_registry.get(user_id)
    if cached:
        name = cached.get("full_name") or (f"@{cached['username']}" if cached.get("username") else None)
        if name:
            name = name.strip()
            if len(name) > max_len:
                name = name[:max_len - 1].rstrip() + "…"
            return name
    return str(user_id)


def admins_menu_kb(actor_id: int) -> ReplyKeyboardMarkup:
    actor_level = get_level(actor_id)
    removable = [
        f"❌ {_plain_display_name(admin_id)} ({admin_id})"
        for admin_id, level in sorted(admin_levels.items(), key=lambda kv: (-kv[1], kv[0]))
        if actor_level > level
    ]
    rows = _grid(removable, cols=1)
    last_row = []
    if actor_level >= LEVEL_SENIOR:
        last_row.append(f"➕ {LBL_ADD_ADMIN}")
    last_row.append(BTN_BACK)
    rows.append(last_row)
    return _reply_kb(rows)


def admin_level_pick_kb(max_level: int) -> ReplyKeyboardMarkup:
    """Клавиатура выбора уровня для нового администратора (нельзя выдать выше своего)."""
    items = [LEVEL_NAMES[level] for level in (LEVEL_MODERATOR, LEVEL_ADMIN, LEVEL_SENIOR) if level <= max_level]
    rows = _grid(items)
