# Тексты справки живут в help_texts.py — это ~830 строк текста без логики.
# Собираются функцией: часть строк подставляет настройки, которые меняются
# в рантайме, поэтому значения передаём явно, а не импортируем константы.
HELP_SECTIONS: dict[str, dict] = build_help_sections(
    DIVIDER, ROLE_RESERVE_TIMEOUT_HOURS, STICKER_CMD_MAX_MESSAGES
)


HELP_MENU_TEXT = (
    "📖 <b>Помощь по командам</b>\n\n"
    "Выберите раздел ниже — или ищите сразу:\n"
    "<code>помощь ачивки</code>, <code>помощь бан</code>, <code>помощь роль</code>\n\n"
    "Поиск смотрит и по командам, и по текстам разделов."
)


def _rp_actions_help_text() -> str:
    """Собирает читаемый список всех РП-действий (инфинитив / повелительная
    форма) по одному в строку — прямо из RP_ACTIONS/RP_ACTION_SYNONYMS, чтобы
    список в хелпе никогда не расходился с реально работающими командами."""
    synonyms_by_action: dict[str, list[str]] = {}
    for synonym, action in RP_ACTION_SYNONYMS.items():
        synonyms_by_action.setdefault(action, []).append(synonym)

    lines = [
        "🎭 <b>РП-действия</b>",
        "Отправьте одну из фраз ниже <b>ответом</b> на сообщение человека.",
        DIVIDER,
    ]
    for action in RP_ACTIONS:
        synonyms = " / ".join(synonyms_by_action.get(action, []))
        entry = f"<b>{action}</b>" + (f" / {synonyms}" if synonyms else "")
        lines.append(entry)
    return "\n".join(lines)


def help_menu_kb() -> InlineKeyboardMarkup:
    """Клавиатура главного меню помощи — по одной кнопке на раздел."""
    return InlineKeyboardMarkup(
        inline_keyboard=[
            [InlineKeyboardButton(text=section["title"], callback_data=f"help_sec:{key}")]
            for key, section in HELP_SECTIONS.items()
        ]
    )


def help_section_kb(section_key: str) -> InlineKeyboardMarkup:
    """Клавиатура раздела — по кнопке на каждый под-раздел (ветку), плюс
    «Назад» в главное меню. Так текст раздела не отправляется одним большим
    сообщением, а разбивается на пары «кнопка → короткий текст»."""
    section = HELP_SECTIONS.get(section_key, {})
    rows: list[list[InlineKeyboardButton]] = [
        [InlineKeyboardButton(text=sub["title"], callback_data=f"help_subsec:{section_key}:{sub_key}")]
        for sub_key, sub in section.get("subsections", {}).items()
    ]
    rows.append([InlineKeyboardButton(text="⬅️ Назад", callback_data="help_menu")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


def help_subsection_kb(section_key: str, sub_key: str) -> InlineKeyboardMarkup:
    """Клавиатура под-раздела — «Назад» в список под-разделов текущего
    раздела. Для «рп → действия» дополнительно есть кнопка с полным списком
    РП-действий и их синонимов (генерируется динамически, см. HELP_RP_ACTIONS_TEXT)."""
    rows: list[list[InlineKeyboardButton]] = []
    if section_key == "rp" and sub_key == "actions":
        rows.append([InlineKeyboardButton(text="📋 Полный список действий", callback_data="help_rp_actions")])
    rows.append([InlineKeyboardButton(text="⬅️ Назад", callback_data=f"help_sec:{section_key}")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


