# ----------------------------------------------------------------------------
# «сайт» / «/site» в личке — выдать одноразовый код для входа на веб-панель
# как УЧАСТНИК (read-only). Код кладём в panel_link_codes, панель гасит его при
# входе и заводит/находит member-аккаунт, привязанный к этому Telegram id.
# Доступно всем: это вход для обычных участников, не админов.
# ----------------------------------------------------------------------------
PANEL_LINK_CODE_TTL_MIN = 10
_PANEL_CODE_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"  # без похожих 0/O/1/I
# Адрес панели снаружи. Берётся из PANEL_PUBLIC_URL (см. rp_photos) — тем же
# значением бот собирает ссылки на картинки-реакции, так что переезд на
# другой домен правится в одном месте, а не в двух.
PANEL_SITE_URL = rp_photos.public_base_url() + "/"

# Дублирует webpanel/auth.py: MIN_PASSWORD_LENGTH/_hasher/validate_password/
# validate_username/hash_password — панель отдельный процесс, импортировать
# нельзя (см. webpanel-README про дублирование констант уровней доступа).
# Править вместе с webpanel/auth.py, если меняете там.
PANEL_MIN_PASSWORD_LENGTH = 10
_panel_password_hasher = PasswordHasher()


def _panel_hash_password(password: str) -> str:
    return _panel_password_hasher.hash(password)


def _panel_validate_password(password: str) -> Optional[str]:
    if len(password) < PANEL_MIN_PASSWORD_LENGTH:
        return f"Пароль должен быть не короче {PANEL_MIN_PASSWORD_LENGTH} символов."
    if password.isdigit():
        return "Пароль из одних цифр слишком легко подобрать."
    if password.lower() in {"password", "qwerty123456", "administrator"}:
        return "Это слишком очевидный пароль."
    return None


def _panel_validate_username(username: str) -> Optional[str]:
    if not (3 <= len(username) <= 64):
        return "Логин должен быть от 3 до 64 символов."
    if not all(ch.isalnum() or ch in "._-" for ch in username):
        return "В логине можно использовать буквы, цифры, точку, дефис и подчёркивание."
    return None


def _gen_panel_link_code() -> str:
    return "".join(secrets.choice(_PANEL_CODE_ALPHABET) for _ in range(8))


@router.message(
    F.chat.type == "private",
    F.text.func(lambda t: bool(t) and t.strip().casefold().split("@")[0] in ("сайт", "/site")),
)
async def cmd_site_code(message: Message):
    code = _gen_panel_link_code()
    expires_at = datetime.utcnow() + timedelta(minutes=PANEL_LINK_CODE_TTL_MIN)
    await db.create_panel_link_code(
        code, message.from_user.id, message.from_user.username,
        message.from_user.full_name or str(message.from_user.id), expires_at,
    )
    await message.answer(
        "🔑 <b>Код для сайта</b>\n\n"
        f"<code>{code}</code>\n\n"
        f"🌐 Сайт: {PANEL_SITE_URL}\n"
        f"Если у вас ЕЩЁ НЕТ аккаунта персонала — этот код для входа участника "
        "устарел, используйте команду «аккаунт», чтобы задать логин/пароль.\n"
        "Если вы уже вошли на сайте как персонал (admin/owner) — введите этот код "
        "в разделе привязки Telegram в панели, чтобы привязать свой аккаунт к тг. "
        f"Код одноразовый и действует {PANEL_LINK_CODE_TTL_MIN} минут.",
        reply_markup=InlineKeyboardMarkup(
            inline_keyboard=[
                # Приложению код не нужен — Telegram сам подтверждает, кто вы.
                [InlineKeyboardButton(text="🎮 Открыть приложение", web_app=WebAppInfo(url=WEBAPP_URL))],
                [InlineKeyboardButton(text="🌐 Сайт в браузере", url=PANEL_SITE_URL)],
            ]
        ),
    )


# ---------------------------------------------------------------------------
# Мини-приложение Telegram: тот же раздел участника, но экраном вместо команд.
#
# Вход не нужен вообще: Telegram сам передаёт приложению подписанные данные о
# том, кто его открыл (проверка подписи — webapp_auth.py на стороне панели).
# Поэтому «сайт» с одноразовым кодом остаётся только для персонала и для
# обычного браузера.
#
# ВАЖНО про кнопки: web_app-кнопку Telegram разрешает ТОЛЬКО в личке с ботом.
# В группе такая кнопка просто не отрисуется, поэтому там даём обычную ссылку
# на личку бота — оттуда человек и откроет приложение.
# ---------------------------------------------------------------------------
WEBAPP_URL = rp_photos.public_base_url() + "/app"
WEBAPP_TRIGGERS = ("приложение", "/app", "мини", "апп")


def webapp_keyboard() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(
        inline_keyboard=[[
            InlineKeyboardButton(text="🎮 Открыть приложение", web_app=WebAppInfo(url=WEBAPP_URL))
        ]]
    )


@router.message(
    F.chat.type == "private",
    F.text.func(lambda t: bool(t) and t.strip().casefold().split("@")[0] in WEBAPP_TRIGGERS),
)
async def cmd_webapp(message: Message):
    # Как и у прочих команд уровня 0: порог можно поднять через ДК/сайт.
    # Без этой проверки запись в дереве команд была бы декорацией.
    if not _check_misc_access(message.from_user.id, "webapp"):
        return
    await message.answer(
        "🎮 <b>Приложение бота</b>\n\n"
        "Профиль и активность, брак и отношения, семья (дом, питомцы, дети), "
        "клан и действия с партнёром — всё кнопками, прямо внутри Telegram.\n\n"
        "Вводить ничего не нужно: бот узнаёт вас сам.",
        reply_markup=webapp_keyboard(),
    )


async def setup_webapp_menu_button() -> None:
    """Ставит постоянную кнопку-меню рядом с полем ввода в личке бота.

    Один вызов на старте — и приложение доступно всем и всегда, без команд.
    Ошибку глотаем намеренно: не настроилось меню — бот всё равно работает,
    а приложение открывается командой «приложение».
    """
    try:
        from aiogram.types import MenuButtonWebApp

        await bot.set_chat_menu_button(
            menu_button=MenuButtonWebApp(text="Приложение", web_app=WebAppInfo(url=WEBAPP_URL))
        )
        logger.info("Кнопка-меню мини-приложения установлена: %s", WEBAPP_URL)
    except Exception:
        logger.warning(
            "Не удалось поставить кнопку-меню мини-приложения (нужен https-адрес "
            "в PANEL_PUBLIC_URL). Приложение остаётся доступным по команде «приложение».",
            exc_info=True,
        )


@router.message(
    F.chat.type == "private",
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "аккаунт"),
)
async def cmd_panel_account_start(message: Message, state: FSMContext):
    existing_staff = await db.get_panel_user_by_tg(message.from_user.id)
    if existing_staff and existing_staff["role"] in ("owner", "admin"):
        await message.reply(
            "Вы уже привязаны на сайте как персонал (логин "
            f"«{html.escape(existing_staff['username'])}»). Отдельный аккаунт участника "
            "заводить не нужно — вход по обычному логину/паролю."
        )
        return
    existing_member = await db.get_panel_member_by_tg(message.from_user.id)
    await state.update_data(
        panel_account_existing_id=(existing_member["id"] if existing_member else None)
    )
    await state.set_state(PanelAccountStates.waiting_username)
    await message.answer(
        "🔑 <b>Аккаунт на сайте</b>\n\n"
        "Придумайте логин для входа (буквы, цифры, точка, дефис, подчёркивание, "
        "от 3 до 64 символов):"
    )


@router.message(F.chat.type == "private", StateFilter(PanelAccountStates.waiting_username))
async def panel_account_username_step(message: Message, state: FSMContext):
    username = (message.text or "").strip()
    error = _panel_validate_username(username)
    if error:
        await message.reply(error)
        return
    data = await state.get_data()
    existing_id = data.get("panel_account_existing_id")
    if await db.is_username_taken_by_other(username, exclude_user_id=existing_id):
        await message.reply(f"Логин «{html.escape(username)}» уже занят, придумайте другой:")
        return
    await state.update_data(panel_account_username=username)
    await state.set_state(PanelAccountStates.waiting_password)
    await message.answer(
        f"Логин: <code>{html.escape(username)}</code>. Теперь придумайте пароль "
        f"(от {PANEL_MIN_PASSWORD_LENGTH} символов) — сообщение с паролем сразу "
        "удалится из чата."
    )


@router.message(F.chat.type == "private", StateFilter(PanelAccountStates.waiting_password))
async def panel_account_password_step(message: Message, state: FSMContext):
    password = message.text or ""
    try:
        await message.delete()
    except Exception:
        logger.exception("Не удалось удалить сообщение с паролем")

    error = _panel_validate_password(password)
    if error:
        await message.reply(f"{error} Придумайте пароль ещё раз:")
        return

    data = await state.get_data()
    username = data.get("panel_account_username")
    if not username:
        await state.clear()
        await message.answer("⚠️ Что-то пошло не так, начните заново командой «аккаунт».")
        return

    password_hash = _panel_hash_password(password)
    await db.upsert_panel_member_account(
        message.from_user.id, username, password_hash,
        message.from_user.full_name or str(message.from_user.id),
    )
    await state.clear()
    await message.answer(
        f"✅ Готово! Логин: <code>{html.escape(username)}</code>. "
        f"Заходите на сайт ({PANEL_SITE_URL}) по обычной форме входа."
    )


