# ---------- Тексты сообщений ----------
def _setting_preview(text: Optional[str], empty: str = "— не задано —", limit: int = 160) -> str:
    """Короткое превью текущего значения настройки для обзора в меню: схлопывает
    переносы, обрезает по длине и экранирует — чтобы недописанная HTML-разметка
    не сломала разбор всего сообщения меню."""
    if not text:
        return empty
    flat = " ".join(str(text).split())
    if len(flat) > limit:
        flat = flat[:limit].rstrip() + "…"
    return html.escape(flat)


def texts_overview_text() -> str:
    """Обзор всех настраиваемых текстов сразу — чтобы было видно, что сейчас
    стоит, не заходя по очереди в каждый (см. жалобу на UX: «много листать»)."""
    return (
        "✏️ <b>Тексты сообщений</b>\n\n"
        "Сейчас настроено — нажмите кнопку ниже, чтобы изменить нужный:\n"
        f"{DIVIDER}\n"
        f"👋 <b>Приветствие (/start)</b>\n{_setting_preview(welcome_text())}\n\n"
        f"🔗 <b>Сообщение со ссылкой</b>\n"
        f"{_setting_preview(settings.get('link_message_template') or DEFAULT_LINK_TEMPLATE)}\n\n"
        f"❌ <b>Сообщение об отказе</b>\n{_setting_preview(reject_text())}\n\n"
        f"🚪 <b>Приветствие в группе (вход)</b>\n"
        f"{_setting_preview(group_join_text(), empty='— отключено —')}"
    )


