@router.message(F.chat.type == "private", StateFilter(AdminStates.menu_testmode), F.text.func(lambda t: bool(t) and t.strip() in ("⏹ Выключить", "▶️ Включить")))
async def testmode_toggle(message: Message, state: FSMContext):
    if not has_level(message.from_user.id, LEVEL_SENIOR):
        await message.answer("Нет доступа")
        return

    uid = message.from_user.id
    if uid in test_mode_admins:
        await db.disable_test_mode(uid)
        test_mode_admins.discard(uid)
        await db.add_log("testmode_off", actor_id=uid)
        turned_on = False
    else:
        await db.enable_test_mode(uid)
        test_mode_admins.add(uid)
        await db.clear_user_requests(uid)  # чтобы следующее сообщение стало «новой» заявкой
        await db.add_log("testmode_on", actor_id=uid)
        turned_on = True

    status = "🟢 включён" if turned_on else "🔴 выключен"
    text = (
        "🧪 <b>Режим «Входящего» (тест заявки)</b>\n\n"
        f"Статус для вас: {status}\n\n"
        + ("Напишите боту любое сообщение — оно уйдёт в топик как новая заявка."
           if turned_on else
           "Обычное поведение восстановлено: ваши сообщения снова обрабатываются как от админа.")
    )
    await message.answer(text, reply_markup=testmode_kb(turned_on))


# ---------- Управление админами и их уровнями ----------
# Правило иерархии: назначать/снимать можно только тех, чей уровень строго
# ниже своего. Владельцы (.env) выше уровня 3 и могут управлять кем угодно,
# в т.ч. выдавать/забирать 3 уровень. Старшие администраторы (3) могут
# назначать и снимать только 1 и 2 уровень.
#
# Bot API не даёт реального presence (это возможно только через MTProto с
# пользовательской сессией, не через бота) — поэтому «онлайн» здесь означает
# «писал в любом чате, где есть бот, не позже ONLINE_THRESHOLD назад». Не
# идеально точно, но единственный практический прокси, доступный боту.
ONLINE_THRESHOLD = timedelta(minutes=5)


def _online_marker(last_seen: Optional[datetime]) -> str:
    if last_seen is not None and datetime.utcnow() - last_seen <= ONLINE_THRESHOLD:
        return "🟢"
    return "⚪"


async def admins_list_text(actor_id: int) -> str:
    count = len(admin_levels)
    icon = admin_icon_display()
    last_seen_map = await db.get_last_seen_map(list(admin_levels.keys()))
    lines = [f"👥 <b>Администраторы</b> — {count}"]
    for level in (LEVEL_SENIOR, LEVEL_ADMIN, LEVEL_MODERATOR):
        ids = [uid for uid, lv in admin_levels.items() if lv == level]
        if ids:
            lines.append(f"\n{icon} {level_name(level)}:")
            lines.extend(f"{_online_marker(last_seen_map.get(uid))} {mention_id(uid)}" for uid in sorted(ids))
    if not has_level(actor_id, LEVEL_SENIOR):
        lines.append("\n\nℹ️ Назначать/снимать администраторов может старший администратор или владелец.")
    return "\n".join(lines)


