# ----------------------------------------------------------------------------
# Меню «РП-действия» (кнопки, личка) — то же самое, что текстовые команды
# «рп ...» (см. ниже, ближе к RP_ACTIONS/handle_rp_action), но пошагово через
# ReplyKeyboard, без необходимости набирать синтаксис руками. Обе точки входа
# работают с одними и теми же таблицами в БД и одинаково вызывают
# refresh_rp_caches(), так что результат идентичен.
# ----------------------------------------------------------------------------

async def rp_actions_overview() -> dict[str, dict]:
    """{action_key: {"phrases": [строки из list_rp_actions_rows], "active": bool}} —
    в отличие от RP_ACTIONS (живой кэш, только активные — им пользуется чат),
    здесь показаны ВСЕ действия, включая выключенные, иначе их нельзя было бы
    включить обратно через меню."""
    rows = await db.list_rp_actions_rows()
    result: dict[str, dict] = {}
    for r in rows:
        entry = result.setdefault(r["action_key"], {"phrases": [], "active": False})
        entry["phrases"].append(r)
        if r["is_active"]:
            entry["active"] = True
    return result


def rp_menu_text(overview: dict[str, dict]) -> str:
    if not overview:
        return "🎭 <b>РП-действия</b>\n\nСписок пуст. Нажмите «➕ Новое действие», чтобы добавить первое."
    synonyms_by_action: dict[str, list[str]] = {}
    for synonym, key in RP_ACTION_SYNONYMS.items():
        synonyms_by_action.setdefault(key, []).append(synonym)
    lines = ["🎭 <b>РП-действия</b>", DIVIDER]
    for key, info in overview.items():
        mark = "✅" if info["active"] else "🚫"
        synonyms = " / ".join(synonyms_by_action.get(key, []))
        lines.append(
            f"{mark} <b>{html.escape(key)}</b>" + (f" ({synonyms})" if synonyms else "")
            + f" — {len(info['phrases'])} фраз(ы)"
        )
    lines.append(DIVIDER + "Нажмите на действие, чтобы им управлять.")
    return "\n".join(lines)


def rp_menu_kb(overview: dict[str, dict]) -> ReplyKeyboardMarkup:
    items = [("✅ " if info["active"] else "🚫 ") + key for key, info in overview.items()]
    rows = _grid(items, cols=2)
    rows.append([f"➕ {LBL_RP_ADD_ACTION}", BTN_BACK])
    return _reply_kb(rows)


def rp_action_menu_text(action_key: str, info: dict) -> str:
    synonyms = [s for s, k in RP_ACTION_SYNONYMS.items() if k == action_key]
    status = "✅ включено" if info["active"] else "🚫 выключено"
    return (
        f"🎭 <b>{html.escape(action_key)}</b> — {status}\n"
        + DIVIDER
        + f"Фраз: {len(info['phrases'])}\n"
        f"Синонимы: {' / '.join(html.escape(s) for s in synonyms) if synonyms else '—'}"
    )


def rp_action_menu_kb(is_active: bool) -> ReplyKeyboardMarkup:
    toggle_text = "🚫 Выключить действие" if is_active else "✅ Включить действие"
    return _reply_kb([
        ["➕ Добавить фразу", "📋 Фразы"],
        ["🔤 Добавить синоним", "➖ Синонимы"],
        [toggle_text],
        [BTN_BACK],
    ])


def rp_phrases_text(action_key: str, phrases: list[dict]) -> str:
    if not phrases:
        return f"📋 <b>{html.escape(action_key)}</b>\n\nФраз пока нет."
    lines = [f"📋 <b>{html.escape(action_key)}</b> — фразы", DIVIDER]
    for p in phrases:
        suffix = "" if p["is_active"] else " (выкл)"
        lines.append(f"#{p['id']}{suffix}: {html.escape(p['phrase'])}")
    lines.append(DIVIDER + "Нажмите ❌ id, чтобы удалить фразу.")
    return "\n".join(lines)


def rp_phrases_kb(phrases: list[dict]) -> ReplyKeyboardMarkup:
    rows = _grid([f"❌ {p['id']}" for p in phrases], cols=4)
    rows.append([BTN_BACK])
    return _reply_kb(rows)


def rp_synonyms_text(action_key: str, synonyms: list[str]) -> str:
    if not synonyms:
        return f"🔤 <b>{html.escape(action_key)}</b>\n\nСинонимов пока нет."
    lines = [f"🔤 <b>{html.escape(action_key)}</b> — синонимы", DIVIDER]
    lines.extend(f"• {html.escape(s)}" for s in synonyms)
    lines.append(DIVIDER + "Нажмите ❌, чтобы удалить синоним.")
    return "\n".join(lines)


def rp_synonyms_kb(synonyms: list[str]) -> ReplyKeyboardMarkup:
    rows = _grid([f"❌ {s}" for s in synonyms], cols=2)
    rows.append([BTN_BACK])
    return _reply_kb(rows)


def _rp_manage_allowed(user_id: int) -> bool:
    return has_level(user_id, required_level("rp_manage"))


async def _show_rp_menu(message: Message, state: FSMContext) -> None:
    overview = await rp_actions_overview()
    await state.set_state(AdminStates.menu_rp)
    await message.answer(rp_menu_text(overview), reply_markup=rp_menu_kb(overview))


async def _show_rp_action_menu(message: Message, state: FSMContext, action_key: str) -> bool:
    """Возвращает True, если действие найдено и меню показано; False — если
    действия больше нет (например, все фразы удалили) — тогда откатывает
    на верхний уровень «РП-действия»."""
    overview = await rp_actions_overview()
    info = overview.get(action_key)
    if info is None:
        await message.answer("Это действие больше не существует.")
        await _show_rp_menu(message, state)
        return False
    await state.update_data(rp_action_key=action_key)
    await state.set_state(AdminStates.menu_rp_action)
    await message.answer(rp_action_menu_text(action_key, info), reply_markup=rp_action_menu_kb(info["active"]))
    return True


