# ----------------------------------------------------------------------------
# Меню «Себяшки» (self_actions) — полный аналог меню «РП-действия» выше, но
# без синонимов: себяшка матчится по своему же action_key (см. _self_action_match
# и SELF_ACTIONS), а не по отдельной таблице синонимов. Работает с той же
# парой таблиц self_actions (см. db.py: list_self_actions_rows/add_self_action_phrase/
# delete_self_action_phrase/set_self_action_key_active), которую использует
# рантайм-обработчик handle_self_action.
# ----------------------------------------------------------------------------

async def refresh_self_caches() -> None:
    """Лёгкий рефреш только кэша себяшек — вызывается после каждой правки
    через меню «Себяшки», чтобы новое действие/фраза сразу заработали в
    чатах, без перезапуска бота."""
    self_actions = await db.list_self_actions(active_only=True)
    SELF_ACTIONS.clear()
    SELF_ACTIONS.update(self_actions or _SELF_ACTIONS_DEFAULT)


# Сигнал «панель поменяла РП/себяшки». Бот и веб-панель — разные процессы, и
# у бота нет способа узнать о правке в панели: RP_ACTIONS/SELF_ACTIONS живут в
# его памяти и обновляются только своими же командами (refresh_*_caches) или
# при старте. Панель после каждой правки пишет новое значение в bot_data по
# этому ключу, а бот раз в PANEL_RELOAD_INTERVAL секунд проверяет его и, если
# оно изменилось, перечитывает кэши. Так правки из панели применяются в чатах
# без перезапуска. (Флаг общий для РП и себяшек — перечитать оба дёшево.)
PANEL_ACTION_RELOAD_KEY = "panel_action_reload"
PANEL_RELOAD_INTERVAL = 10  # секунд


async def panel_action_reload_loop() -> None:
    last_seen: Optional[str] = None
    # Первое чтение — только запомнить текущее значение, не перечитывать: кэши
    # и так свежие после load_caches() на старте.
    try:
        row = await db.get_data(PANEL_ACTION_RELOAD_KEY)
        last_seen = row["data_value"] if row else None
    except Exception:
        logger.exception("panel_action_reload_loop: не удалось прочитать стартовое значение флага")

    while True:
        await asyncio.sleep(PANEL_RELOAD_INTERVAL)
        try:
            row = await db.get_data(PANEL_ACTION_RELOAD_KEY)
            value = row["data_value"] if row else None
            if value != last_seen:
                last_seen = value
                await refresh_rp_caches()
                await refresh_self_caches()
                await relationships_v2.load_gestures()
                WORD_FILTER.clear()
                WORD_FILTER.update(word_filter.normalize(w) for w in await db.list_filter_words())
                # Оверрайды уровней команд (панель → «дерево команд») — мутируем
                # тот же dict, что читает required_level, чтобы правки применялись
                # без перезапуска бота.
                command_level_overrides.clear()
                command_level_overrides.update(await db.list_command_levels())
                # Свои сроки автоочистки команд — оттуда же, из «дерева команд».
                command_cleanup_overrides.clear()
                command_cleanup_overrides.update(await db.list_command_cleanup())
                reward_degree_level_overrides.clear()
                reward_degree_level_overrides.update(await db.list_reward_degree_levels())
                await refresh_propose_caches()
                # Настройки строки settings (часовой пояс показа, автоочистка
                # команд, тексты) панель правит своим процессом — без этой
                # перечитки бот жил бы со старым значением до перезапуска, и
                # владелец, сменивший пояс на сайте, не увидел бы разницы.
                # Обновляем СОДЕРЖИМОЕ существующего dict, а не заменяем сам
                # объект: на него уже держат ссылки замыкания.
                fresh_settings = await db.fetch_settings()
                if fresh_settings is not None:
                    settings.clear()
                    settings.update(fresh_settings)
                logger.info(
                    "РП/себяшки/жесты отн/фильтр слов/права команд/предложения/настройки "
                    "перечитаны по сигналу из панели"
                )
        except Exception:
            # База могла моргнуть — не роняем цикл, попробуем на следующей итерации.
            logger.exception("panel_action_reload_loop: ошибка перечитки")


async def self_actions_overview() -> dict[str, dict]:
    """{action_key: {"phrases": [строки из list_self_actions_rows], "active": bool}} —
    в отличие от SELF_ACTIONS (живой кэш, только активные — им пользуется чат),
    здесь показаны ВСЕ действия, включая выключенные, иначе их нельзя было бы
    включить обратно через меню."""
    rows = await db.list_self_actions_rows()
    result: dict[str, dict] = {}
    for r in rows:
        entry = result.setdefault(r["action_key"], {"phrases": [], "active": False})
        entry["phrases"].append(r)
        if r["is_active"]:
            entry["active"] = True
    return result


def self_menu_text(overview: dict[str, dict]) -> str:
    if not overview:
        return "🙋 <b>Себяшки</b>\n\nСписок пуст. Нажмите «➕ Новое действие», чтобы добавить первое."
    lines = ["🙋 <b>Себяшки</b>", DIVIDER]
    for key, info in overview.items():
        mark = "✅" if info["active"] else "🚫"
        lines.append(f"{mark} <b>[{html.escape(key)}</b> — {len(info['phrases'])} фраз(ы)")
    lines.append(DIVIDER + "Нажмите на действие, чтобы им управлять.")
    return "\n".join(lines)


def self_menu_kb(overview: dict[str, dict]) -> ReplyKeyboardMarkup:
    items = [("✅ " if info["active"] else "🚫 ") + key for key, info in overview.items()]
    rows = _grid(items, cols=2)
    rows.append([f"➕ {LBL_SELF_ADD_ACTION}", BTN_BACK])
    return _reply_kb(rows)


def self_action_menu_text(action_key: str, info: dict) -> str:
    status = "✅ включено" if info["active"] else "🚫 выключено"
    return (
        f"🙋 <b>[{html.escape(action_key)}</b> — {status}\n"
        + DIVIDER
        + f"Фраз: {len(info['phrases'])}"
    )


def self_action_menu_kb(is_active: bool) -> ReplyKeyboardMarkup:
    toggle_text = "🚫 Выключить действие" if is_active else "✅ Включить действие"
    return _reply_kb([
        ["➕ Добавить фразу", "📋 Фразы"],
        [toggle_text],
        [BTN_BACK],
    ])


def self_phrases_text(action_key: str, phrases: list[dict]) -> str:
    if not phrases:
        return f"📋 <b>[{html.escape(action_key)}</b>\n\nФраз пока нет."
    lines = [f"📋 <b>[{html.escape(action_key)}</b> — фразы", DIVIDER]
    for p in phrases:
        suffix = "" if p["is_active"] else " (выкл)"
        lines.append(f"#{p['id']}{suffix}: {html.escape(p['phrase'])}")
    lines.append(DIVIDER + "Нажмите ❌ id, чтобы удалить фразу.")
    return "\n".join(lines)


def self_phrases_kb(phrases: list[dict]) -> ReplyKeyboardMarkup:
    rows = _grid([f"❌ {p['id']}" for p in phrases], cols=4)
    rows.append([BTN_BACK])
    return _reply_kb(rows)


def _self_manage_allowed(user_id: int) -> bool:
    return has_level(user_id, required_level("self_manage"))


async def _show_self_menu(message: Message, state: FSMContext) -> None:
    overview = await self_actions_overview()
    await state.set_state(AdminStates.menu_self)
    await message.answer(self_menu_text(overview), reply_markup=self_menu_kb(overview))


async def _show_self_action_menu(message: Message, state: FSMContext, action_key: str) -> bool:
    """Возвращает True, если действие найдено и меню показано; False — если
    действия больше нет (например, все фразы удалили) — тогда откатывает
    на верхний уровень «Себяшки»."""
    overview = await self_actions_overview()
    info = overview.get(action_key)
    if info is None:
        await message.answer("Это действие больше не существует.")
        await _show_self_menu(message, state)
        return False
    await state.update_data(self_action_key=action_key)
    await state.set_state(AdminStates.menu_self_action)
    await message.answer(self_action_menu_text(action_key, info), reply_markup=self_action_menu_kb(info["active"]))
    return True


