    if not _self_manage_allowed(message.from_user.id):
        return
    action_key = (message.text or "").strip().casefold()
    if not action_key or "|" in action_key or " " in action_key:
        await message.answer(
            "Название не должно быть пустым, не должно содержать «|» и пробелы (это одно слово после «[»). "
            "Попробуйте ещё раз.",
            reply_markup=cancel_kb(),
        )
        return
    await state.update_data(self_action_key=action_key)
    await state.set_state(AdminStates.waiting_self_new_phrase)
    await message.answer(
        f"Теперь пришлите первую фразу для «[{html.escape(action_key)}».\n"
        "В тексте можно использовать <code>{user}</code> (кто вызвал действие).\n"
        f"Например: <code>💃 {{user}} пустился(-лась) в пляс на глазах у всех</code>",
        reply_markup=cancel_kb(),
    )


