async def _complaint_decide(message: Message, state: FSMContext, complaint_id: int, status: str) -> None:
    if not has_level(message.from_user.id, required_level("complaints")):
        if get_level(message.from_user.id) > 0:
            await message.answer("Нет доступа")
        return

    complaint = await db.get_complaint(complaint_id)
    if not complaint or complaint["status"] != "pending":
        await message.answer("Жалоба уже рассмотрена или не найдена.")
        return

    await db.set_complaint_status(complaint_id, status, message.from_user.id)
    global pending_complaints_count
    pending_complaints_count = max(0, pending_complaints_count - 1)
    await db.add_log(
        f"complaint_{status}", actor_id=message.from_user.id,
        target_id=complaint["target_id"], details=f"жалоба №{complaint_id}",
    )

    target_id = complaint["target_id"]
    rows = await db.list_complaints_for_target(target_id)
    await message.answer("Принято ✅" if status == "accepted" else "Отклонено ❌")
    await message.answer(complaint_detail_text(target_id, rows), reply_markup=complaint_detail_kb(rows))

    verdict = (
        "✅ Ваша жалоба рассмотрена и принята администрацией."
        if status == "accepted"
        else "❌ Ваша жалоба рассмотрена и отклонена администрацией."
    )
    try:
        await bot.send_message(
            complaint["reporter_id"],
            f"{verdict}\n\nПричина, которую вы указывали:\n{html.escape(complaint['reason'])}",
        )
    except Exception as exc:
        log_suppressed("_complaint_decide", exc)


@router.message(F.chat.type == "private", StateFilter(ComplaintStates.menu_detail), F.text.func(lambda t: bool(t) and re.match(r"^✅ Принять №(\d+)$", t.strip())))
async def complaint_accept(message: Message, state: FSMContext):
    complaint_id = int(re.match(r"^✅ Принять №(\d+)$", message.text.strip()).group(1))
    await _complaint_decide(message, state, complaint_id, "accepted")


@router.message(F.chat.type == "private", StateFilter(ComplaintStates.menu_detail), F.text.func(lambda t: bool(t) and re.match(r"^❌ Отклонить №(\d+)$", t.strip())))
async def complaint_decline(message: Message, state: FSMContext):
    complaint_id = int(re.match(r"^❌ Отклонить №(\d+)$", message.text.strip()).group(1))
    await _complaint_decide(message, state, complaint_id, "declined")


@router.message(F.chat.type == "private", StateFilter(ComplaintStates.menu_detail), F.text.func(lambda t: bool(t) and re.match(r"^🗑 Удалить жалобу №(\d+)$", t.strip())))
async def complaint_delete(message: Message, state: FSMContext):
    # Удаляет саму жалобу (запись в БД) — не пользователя, на которого
    # жаловались, и не человека из списка «для жалоб» (roster known_users).
    if not has_level(message.from_user.id, required_level("complaints")):
        if get_level(message.from_user.id) > 0:
            await message.answer("Нет доступа")
        return

    complaint_id = int(re.match(r"^🗑 Удалить жалобу №(\d+)$", message.text.strip()).group(1))
    complaint = await db.get_complaint(complaint_id)
    if not complaint:
        await message.answer("Эта жалоба уже удалена.")
    else:
        was_pending = complaint["status"] == "pending"
        await db.delete_complaint(complaint_id)
        if was_pending:
            global pending_complaints_count
            pending_complaints_count = max(0, pending_complaints_count - 1)
        await db.add_log(
            "complaint_delete", actor_id=message.from_user.id,
            target_id=complaint["target_id"], details=f"жалоба №{complaint_id}",
        )
        await message.answer(f"🗑 Жалоба №{complaint_id} удалена.")

    data = await state.get_data()
    target_id = data.get("complaint_view_target") or (complaint["target_id"] if complaint else None)
    rows = await db.list_complaints_for_target(target_id) if target_id is not None else []
    if not rows:
        all_rows = await db.list_complaint_targets()
        await state.set_state(ComplaintStates.menu_list)
        await message.answer(complaints_targets_text(all_rows), reply_markup=complaints_targets_kb(all_rows))
    else:
        await message.answer(complaint_detail_text(target_id, rows), reply_markup=complaint_detail_kb(rows))


# ----------------------------------------------------------------------------
# Анонимные сообщения — полностью в личке бота.
#   «аноним»            — любой пользователь: отправить анонимное сообщение
#                          кому-то (тот же ростер known_users, что и для
#                          жалоб — settings.complaint_chat_id).
#   «анонимки выкл/вкл» — включить/выключить получение анонимок себе.
# Получатель никогда не видит sender_id — он остаётся только в БД
# (anon_messages.sender_id) для разбора жалоб администрацией, если анонимку
# используют для травли (см. кнопку «🚫 Пожаловаться» на присланном
# сообщении и хендлер anon_report ниже).
# ----------------------------------------------------------------------------
ANON_PICKER_PAGE_SIZE = 8
BTN_ANON_SEND = "✅ Отправить"


def anon_cancel_kb() -> ReplyKeyboardMarkup:
    return _reply_kb([[BTN_CANCEL]])


def anon_confirm_kb() -> ReplyKeyboardMarkup:
    return _reply_kb([[BTN_ANON_SEND, BTN_CANCEL]])


def _admins_at_or_above(min_level: int) -> list[int]:
    """ID всех, кто может разбирать жалобы на анонимки: владельцы (OWNER_IDS)
    + обычные админы бота с уровнем не ниже min_level."""
    ids = set(OWNER_IDS)
    ids.update(uid for uid, lvl in admin_levels.items() if lvl >= min_level)
    return list(ids)


async def anon_picker_page(chat_id: int, page: int, query: Optional[str] = None) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    """Список известных боту участников чата `chat_id` для выбора адресата
    анонимного сообщения. Источник данных (known_users) и логика — те же,
    что и в complaint_picker_page, но с отдельными callback-префиксами
    (ampick / ampick_page), чтобы не пересекаться с пикером жалоб."""
    page = max(page, 0)
    if query:
        rows, total = await db.search_known_users(chat_id, query, limit=ANON_PICKER_PAGE_SIZE, offset=page * ANON_PICKER_PAGE_SIZE)
    else:
        rows, total = await db.list_known_users(chat_id, limit=ANON_PICKER_PAGE_SIZE, offset=page * ANON_PICKER_PAGE_SIZE)

    if not rows:
        if query:
            return f"По запросу «{html.escape(query)}» никого не нашлось.", None
        return "Список участников этого чата пока пуст — бот ещё никого там не видел.", None

    buttons = []
    for row in rows:
        label = row["full_name"]
        if row.get("username"):
            label += f" (@{row['username']})"
        buttons.append([InlineKeyboardButton(text=label[:64], callback_data=f"ampick:{row['user_id']}")])

    pages = (total + ANON_PICKER_PAGE_SIZE - 1) // ANON_PICKER_PAGE_SIZE
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="⬅️", callback_data=f"ampick_page:{page - 1}"))
    nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page + 1 < pages:
        nav.append(InlineKeyboardButton(text="➡️", callback_data=f"ampick_page:{page + 1}"))
    if nav:
        buttons.append(nav)

    prefix = f"Результаты по «{html.escape(query)}»" if query else f"Известно боту участников: {total}"
    return prefix, InlineKeyboardMarkup(inline_keyboard=buttons)


async def _anon_target_error(sender_id: int, target_id: int) -> Optional[str]:
    """Текст ошибки, если этому пользователю нельзя отправить анонимку, иначе None."""
    if target_id == sender_id:
        return "Нельзя отправить анонимное сообщение самому себе 🙂"
    if target_id == bot.id:
        return "Боту анонимки отправлять нет смысла 🤖"
    if await db.is_anon_opt_out(target_id):
        return "Этот человек отключил получение анонимных сообщений."
    return None


async def _anon_rate_limited(sender_id: int) -> bool:
    sent = await db.count_recent_anon_messages(sender_id, ANON_MSG_RATE_WINDOW_MINUTES)
    return sent >= ANON_MSG_RATE_LIMIT


ANON_RATE_LIMIT_TEXT = (
    f"⏳ Вы отправили слишком много анонимных сообщений за последнее время "
    f"(лимит: {ANON_MSG_RATE_LIMIT} за {ANON_MSG_RATE_WINDOW_MINUTES} мин). Попробуйте позже."
)


@router.message(
    F.chat.type == "private",
    StateFilter(None),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "аноним"),
)
async def cmd_anon_start(message: Message, state: FSMContext):
    if await _anon_rate_limited(message.from_user.id):
        await message.answer(ANON_RATE_LIMIT_TEXT, reply_markup=private_menu_kb(message.from_user.id))
        return

    await state.set_state(AnonMessageStates.waiting_target)
    anon_chat_id = settings.get("complaint_chat_id")
    await state.update_data(anon_picker_chat=anon_chat_id, anon_picker_query=None)

    hint = " Или напишите часть имени, чтобы найти по списку." if anon_chat_id else ""
    await message.answer(
        "🙈 <b>Анонимное сообщение</b>\n\n"
        "Кому пишем? Перешлите сюда любое его сообщение или пришлите его числовой ID." + hint,
        reply_markup=anon_cancel_kb(),
    )
    if anon_chat_id:
        await sync_known_admins(anon_chat_id)
        text, kb = await anon_picker_page(anon_chat_id, 0)
        if kb:
            await message.answer("Или выберите из списка:\n\n" + text, reply_markup=kb)


@router.message(
    F.chat.type == "private",
    StateFilter(AnonMessageStates.waiting_target, AnonMessageStates.waiting_text, AnonMessageStates.waiting_confirm),
    F.text == BTN_CANCEL,
)
async def anon_cancel(message: Message, state: FSMContext):
    await state.clear()
    await message.answer("Отменено — сообщение не отправлено.", reply_markup=private_menu_kb(message.from_user.id))


@router.callback_query(F.data.startswith("ampick_page:"), StateFilter(AnonMessageStates.waiting_target))
async def anon_picker_paginate(callback: CallbackQuery, state: FSMContext):
    try:
        page = int(callback.data.split(":", maxsplit=1)[1])
    except (IndexError, ValueError):
        await callback.answer("Не удалось открыть эту страницу.", show_alert=True)
        return
    data = await state.get_data()
    chat_id = data.get("anon_picker_chat")
    query = data.get("anon_picker_query")
    if not chat_id:
        await callback.answer("Список устарел, начните заново словом «аноним».", show_alert=True)
        return
    text, kb = await anon_picker_page(chat_id, page, query)
    try:
        await callback.message.edit_text("Выберите из списка (или напишите часть имени для поиска):\n\n" + text, reply_markup=kb)
    except TelegramBadRequest:
        pass
    await callback.answer()


@router.callback_query(F.data.startswith("ampick:"), StateFilter(AnonMessageStates.waiting_target))
async def anon_picker_select(callback: CallbackQuery, state: FSMContext):
    try:
        target_id = int(callback.data.split(":", maxsplit=1)[1])
    except (IndexError, ValueError):
        await callback.answer("Не удалось распознать пользователя.", show_alert=True)
        return

    error = await _anon_target_error(callback.from_user.id, target_id)
    if error:
        await callback.answer(error, show_alert=True)
        return

    await state.update_data(anon_target=target_id)
    await state.set_state(AnonMessageStates.waiting_text)
    try:
        await callback.message.edit_text("✅ Адресат выбран.")
    except TelegramBadRequest:
        pass
    await callback.answer()

    label = await user_label(target_id)
    await bot.send_message(
        callback.from_user.id,
        f"🎯 Сообщение для: {label}\n\n📝 Напишите текст сообщения одним сообщением.",
        reply_markup=anon_cancel_kb(),
    )


@router.message(StateFilter(AnonMessageStates.waiting_target), F.chat.type == "private")
async def process_anon_target(message: Message, state: FSMContext):
    target_id = None
    if message.forward_from:
        target_id = message.forward_from.id
    elif message.text and message.text.strip().isdigit():
        target_id = int(message.text.strip())

    if target_id is None:
        data = await state.get_data()
        anon_chat_id = data.get("anon_picker_chat")
        query = (message.text or "").strip()
        if anon_chat_id and query:
            await state.update_data(anon_picker_query=query)
            text, kb = await anon_picker_page(anon_chat_id, 0, query)
            await message.answer(
                "Выберите из списка (или напишите часть имени для поиска):\n\n" + text,
                reply_markup=kb,
            )
            return

        await message.answer(
            "Не удалось распознать пользователя. Перешлите его сообщение или пришлите числовой ID.",
            reply_markup=anon_cancel_kb(),
        )
        return

    error = await _anon_target_error(message.from_user.id, target_id)
    if error:
        await message.answer(error, reply_markup=anon_cancel_kb())
        return

    await state.update_data(anon_target=target_id)
    await state.set_state(AnonMessageStates.waiting_text)
    label = await user_label(target_id)
    await message.answer(
        f"🎯 Сообщение для: {label}\n\n📝 Напишите текст сообщения одним сообщением.",
        reply_markup=anon_cancel_kb(),
    )


@router.message(StateFilter(AnonMessageStates.waiting_text), F.chat.type == "private")
async def process_anon_text(message: Message, state: FSMContext):
    if not message.text or not message.text.strip():
        await message.answer("Нужен текстовый ответ. Напишите текст анонимного сообщения.", reply_markup=anon_cancel_kb())
        return

    data = await state.get_data()
    target_id = data.get("anon_target")
    if target_id is None:
        await state.clear()
        await message.answer("⚠️ Что-то пошло не так, начните заново словом «аноним».", reply_markup=private_menu_kb(message.from_user.id))
        return

    text = message.text.strip()[:2000]
    await state.update_data(anon_text=text)
    await state.set_state(AnonMessageStates.waiting_confirm)

    label = await user_label(target_id)
    await message.answer(
        f"🎯 Кому: {label}\n\n"
        f"💬 Текст:\n{html.escape(text)}\n\n"
        "Получатель не увидит, кто отправитель. Отправляем?",
        reply_markup=anon_confirm_kb(),
    )


@router.message(StateFilter(AnonMessageStates.waiting_confirm), F.chat.type == "private", F.text == BTN_ANON_SEND)
async def process_anon_confirm(message: Message, state: FSMContext):
    data = await state.get_data()
    target_id = data.get("anon_target")
    text = data.get("anon_text")
    anon_chat_id = data.get("anon_picker_chat") or settings.get("complaint_chat_id") or 0
    if target_id is None or not text:
        await state.clear()
        await message.answer("⚠️ Что-то пошло не так, начните заново словом «аноним».", reply_markup=private_menu_kb(message.from_user.id))
        return

    if await _anon_rate_limited(message.from_user.id):
        await state.clear()
        await message.answer(ANON_RATE_LIMIT_TEXT, reply_markup=private_menu_kb(message.from_user.id))
        return

    error = await _anon_target_error(message.from_user.id, target_id)
    if error:
        await state.clear()
        await message.answer(error, reply_markup=private_menu_kb(message.from_user.id))
        return

    anon_message_id = await db.add_anon_message(anon_chat_id, message.from_user.id, target_id, text, delivered=True)
    report_kb = InlineKeyboardMarkup(
        inline_keyboard=[[InlineKeyboardButton(text="🚫 Пожаловаться", callback_data=f"amreport:{anon_message_id}")]]
    )

    delivered = True
    try:
        sent = await bot.send_message(
            target_id,
            f"🙈 <b>Вам анонимное сообщение:</b>\n\n{html.escape(text)}\n\n"
            "↩️ Чтобы ответить (тоже анонимно) — просто нажмите «Ответить» (Reply) на этом сообщении.",
            reply_markup=report_kb,
        )
        await db.add_anon_delivery(anon_message_id, message.from_user.id, target_id, sent.message_id, text)
    except (TelegramForbiddenError, TelegramBadRequest):
        delivered = False
        await db.set_anon_message_delivered(anon_message_id, False)

    await db.add_log(
        "anon_message_sent", actor_id=message.from_user.id, target_id=target_id, details=text[:200]
    )
    await state.clear()

    if delivered:
        await message.answer(
            "✅ Отправлено анонимно. Получатель не узнает, что это были вы.",
            reply_markup=private_menu_kb(message.from_user.id),
        )
    else:
        await message.answer(
            "⚠️ Не удалось доставить сообщение — получатель ещё не открывал бота в личке "
            "или заблокировал его. Сообщение сохранено, но не доставлено.",
            reply_markup=private_menu_kb(message.from_user.id),
        )


@router.callback_query(F.data.startswith("amreport:"))
async def anon_report(callback: CallbackQuery):
    try:
        anon_message_id = int(callback.data.split(":", maxsplit=1)[1])
    except (IndexError, ValueError):
        await callback.answer()
        return

    row = await db.get_anon_message(anon_message_id)
    if row is None:
        await callback.answer("Сообщение не найдено.", show_alert=True)
        return
    if row["target_id"] != callback.from_user.id:
        # Пожаловаться может только тот, кому реально пришло это сообщение —
        # иначе кто угодно смог бы деанонимизировать чужую анонимку.
        await callback.answer("Пожаловаться может только получатель этого сообщения.", show_alert=True)
        return

    already_reported = bool(row["reported"])
    row = await db.mark_anon_message_reported(anon_message_id)
    try:
        await callback.message.edit_reply_markup(reply_markup=None)
    except TelegramBadRequest:
        pass

    if already_reported:
        await callback.answer("Жалоба уже отправлена ранее.", show_alert=True)
        return

    await callback.answer("Жалоба отправлена администраторам.", show_alert=True)
    await db.add_log(
        "anon_message_reported", actor_id=callback.from_user.id,
        target_id=row["sender_id"], details=f"анонимка №{anon_message_id}",
    )

    sender_label = await user_label(row["sender_id"])
    recipient_label = await user_label(callback.from_user.id)
    notify_text = (
        f"🚫 <b>Жалоба на анонимное сообщение №{anon_message_id}</b>\n\n"
        f"Реальный отправитель: {sender_label}\n"
        f"Получатель: {recipient_label}\n\n"
        f"Текст:\n{html.escape(row['text'])}"
    )
    for admin_id in _admins_at_or_above(required_level("complaints")):
        try:
            await bot.send_message(admin_id, notify_text)
        except Exception as exc:
            log_suppressed("anon_report", exc)


@router.message(
    F.chat.type == "private",
    StateFilter(None),
    F.reply_to_message,
    F.text,
)
async def anon_thread_reply(message: Message, state: FSMContext):
    # Ловим Reply на любое сообщение в личке с ботом. Если это не ответ на
    # анонимку/её продолжение — просто пропускаем дальше (SkipHandler),
    # чтобы не мешать остальным хендлерам (например, обычному общению).
    link = await db.get_anon_delivery(message.from_user.id, message.reply_to_message.message_id)
    if link is None:
        raise SkipHandler

    reply_to_id = link["sender_id"]  # тот, кому теперь уходит ответ
    root_id = link["root_id"]

    if reply_to_id == message.from_user.id:
        raise SkipHandler  # подстраховка от кривых данных

    if await _anon_rate_limited(message.from_user.id):
        await message.reply(ANON_RATE_LIMIT_TEXT)
        return
    if await db.is_anon_opt_out(reply_to_id):
        await message.reply("Собеседник отключил получение анонимных сообщений — ответ не доставлен.")
        return

    text = message.text.strip()[:2000]
    report_kb = InlineKeyboardMarkup(
        inline_keyboard=[[InlineKeyboardButton(text="🚫 Пожаловаться", callback_data=f"amreport:{root_id}")]]
    )

    try:
        sent = await bot.send_message(
            reply_to_id,
            f"🙈 <b>Ответ в анонимной переписке:</b>\n\n{html.escape(text)}\n\n"
            "↩️ Ответить дальше — тоже через «Ответить» (Reply) на этом сообщении.",
            reply_markup=report_kb,
        )
        await db.add_anon_delivery(root_id, message.from_user.id, reply_to_id, sent.message_id, text)
        await db.add_log(
            "anon_message_sent", actor_id=message.from_user.id, target_id=reply_to_id, details=text[:200]
        )
        await message.reply("✅ Ответ отправлен анонимно.")
    except (TelegramForbiddenError, TelegramBadRequest):
        await message.reply(
            "⚠️ Не удалось доставить ответ — собеседник ещё не открывал бота в личке или заблокировал его."
        )


@router.message(
    F.chat.type == "private",
    StateFilter(None),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "анонимки выкл"),
)
async def cmd_anon_opt_out(message: Message):
    await db.set_anon_opt_out(message.from_user.id, True)
    await message.answer(
        "🔕 Готово, теперь вам не будут присылать анонимные сообщения. "
        "Включить обратно — «анонимки вкл».",
        reply_markup=private_menu_kb(message.from_user.id),
    )


@router.message(
    F.chat.type == "private",
    StateFilter(None),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "анонимки вкл"),
)
async def cmd_anon_opt_in(message: Message):
    await db.set_anon_opt_out(message.from_user.id, False)
    await message.answer(
        "🔔 Готово, анонимные сообщения снова можно вам присылать.",
        reply_markup=private_menu_kb(message.from_user.id),
    )


# ----------------------------------------------------------------------------
# Настройка топика: команда отправляется прямо в группе, в нужном топике
# ----------------------------------------------------------------------------
@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "топик сюда"),
)
async def cmd_settopic(message: Message):
    if not has_level(message.from_user.id, required_level("settopic")):
        if get_level(message.from_user.id) > 0:
            await message.reply("⛔ Настраивать топик может только администратор бота.")
        return

    await db.save_setting("notify_chat_id", message.chat.id)
    await db.save_setting("notify_topic_id", message.message_thread_id)
    settings["notify_chat_id"] = message.chat.id
    settings["notify_topic_id"] = message.message_thread_id

    # НОВОЕ: бот сам получает/создаёт пригласительную ссылку, если админ
    # ещё не задал её вручную.
    link_note = ""
    if not settings.get("invite_link"):
        try:
            link = await bot.export_chat_invite_link(message.chat.id)
            await db.save_setting("invite_link", link)
            settings["invite_link"] = link
            link_note = f"\n🔗 Ссылка получена автоматически: {link}"
        except Exception:
            logger.exception("Не удалось автоматически получить ссылку-приглашение")
            link_note = "\n⚠️ Не удалось автоматически получить ссылку — задайте её вручную в «админка»."

    await message.reply(
        "✅ Готово! Заявки на вступление теперь будут приходить сюда.\n\n"
        f"chat_id: <code>{message.chat.id}</code>\n"
        f"topic_id: <code>{message.message_thread_id}</code>"
        f"{link_note}"
    )



