@router.callback_query(F.data.startswith("rpick:"))
async def role_pick_select(callback: CallbackQuery):
    try:
        role_id = int(callback.data.split(":", maxsplit=1)[1])
    except (IndexError, ValueError):
        await callback.answer()
        return
    chat_id = await roles_context_chat_id(callback.message)
    if not chat_id:
        await callback.answer("Чат для ролей не настроен.", show_alert=True)
        return
    user_id = callback.from_user.id
    role = await db.get_role(chat_id, role_id)
    if role is None:
        await callback.answer("Эта роль больше не существует.", show_alert=True)
        return
    member = await is_chat_member(chat_id, user_id)
    if member:
        ok = await db.take_role(chat_id, role_id, user_id)
        if not ok:
            await callback.answer("Увы, эту роль уже кто-то занял.", show_alert=True)
            return
        await db.add_log("role_take", chat_id=chat_id, actor_id=user_id, details=role["name"])
        await grant_achievement(chat_id, user_id, "role_taken")
        await sync_role_title(chat_id, user_id)
        try:
            await callback.message.edit_text(f"✅ Роль «{html.escape(role['name'])}» закреплена за вами.")
        except TelegramBadRequest:
            pass
        await callback.answer()
    else:
        ok = await db.reserve_role(chat_id, role_id, user_id)
        if not ok:
            await callback.answer("Увы, эту роль уже кто-то занял или забронировал.", show_alert=True)
            return
        await db.add_log("role_reserve", chat_id=chat_id, actor_id=user_id, details=role["name"])
        try:
            await callback.message.edit_text(
                f"🗡 Роль «{html.escape(role['name'])}» забронирована за вами.\n"
                f"Она закрепится автоматически, как только вы вступите в группу "
                f"(бронь действует {ROLE_RESERVE_TIMEOUT_HOURS} ч.)."
            )
        except TelegramBadRequest:
            pass
        await callback.answer()
        # Если заявка на вход ещё не рассмотрена — сообщаем админам, что
        # заявитель выбрал роль и теперь ему можно выдать ссылку.
        if await db.get_request_status(user_id) in (None, "pending"):
            notify_chat = settings.get("notify_chat_id")
            if notify_chat:
                try:
                    await bot.send_message(
                        notify_chat,
                        message_thread_id=settings.get("notify_topic_id"),
                        text=(
                            f"🎭 {mention_id(user_id)} выбрал роль «{html.escape(role['name'])}» — "
                            "теперь можно выдать ссылку («Дать ссылку на вход» под его заявкой)."
                        ),
                    )
                except Exception:
                    logger.exception("Не удалось уведомить админов о выборе роли заявителем")


@router.message(F.text.func(lambda t: bool(t) and t.strip().casefold() == "снять роль"))
async def cmd_role_release(message: Message):
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Роли пока не настроены для этого чата.")
        return
    role = await db.get_user_role(chat_id, message.from_user.id)
    if role is None:
        reservation = await db.get_user_reservation(chat_id, message.from_user.id)
        if reservation is not None:
            await db.cancel_reservation(chat_id, reservation["id"])
            await db.add_log("role_cancel_reservation", chat_id=chat_id, actor_id=message.from_user.id, details=reservation["name"])
            await message.reply(f"Бронь роли «{html.escape(reservation['name'])}» снята.")
            return
        await message.reply("У вас сейчас нет ни закреплённой роли, ни брони.")
        return
    await db.release_role(chat_id, role["id"])
    await sync_role_title(chat_id, message.from_user.id) 
    await db.add_log("role_release", chat_id=chat_id, actor_id=message.from_user.id, details=role["name"])
    await message.reply(f"Роль «{html.escape(role['name'])}» освобождена.")


