@router.message(F.text.func(lambda t: bool(t) and t.strip().casefold().startswith("предложить роль")))
async def cmd_role_propose(message: Message):
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Роли пока не настроены для этого чата.")
        return
    raw = message.text.strip()
    name = raw[len("предложить роль"):].strip(" :—-")
    if not name:
        await message.reply("Укажите название: «предложить роль» + название, например «предложить роль Капитан».")
        return
    if len(name) > 64:
        await message.reply("Слишком длинное название (максимум 64 символа).")
        return
    role_id = await db.propose_role(chat_id, name, category=None, proposed_by=message.from_user.id)
    if role_id is None:
        await message.reply("Роль с таким названием уже есть в списке (свободна, занята или на модерации).")
        return
    await db.add_log("role_propose", chat_id=chat_id, actor_id=message.from_user.id, details=name)
    await message.reply(f"📝 Заявка на роль «{html.escape(name)}» отправлена на модерацию (№{role_id}).")
    notify_chat = settings.get("notify_chat_id")
    if notify_chat:
        try:
            sent = await bot.send_message(
                notify_chat,
                message_thread_id=settings.get("notify_topic_id"),
                text=(
                    f"📝 Новая заявка на роль «{html.escape(name)}» от {mention_id(message.from_user.id)}."
                ),
                reply_markup=role_proposal_kb(role_id),
            )
            # Запоминаем карточку: решение, принятое в веб-панели, правит именно
            # её — иначе в чате остались бы активные кнопки по уже закрытой
            # заявке (см. db.ensure_role_proposal_message_columns).
            await db.set_role_proposal_message(chat_id, role_id, sent.chat.id, sent.message_id)
        except Exception:
            logger.exception("Не удалось уведомить о новой заявке на роль")


