@router.message(F.text.func(lambda t: bool(t) and bool(re.match(r"^роль принять (\d+)$", t.strip().casefold()))))
async def cmd_role_approve(message: Message):
    if not has_level(message.from_user.id, required_level("role_approve")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Одобрять роли может «{level_name(required_level('role_approve'))}» и выше.")
        return
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Роли пока не настроены для этого чата.")
        return
    role_id = int(re.match(r"^роль принять (\d+)$", message.text.strip().casefold()).group(1))
    role = await db.approve_role_proposal(chat_id, role_id)
    if role is None:
        await message.reply("Такой заявки нет (возможно, уже обработана).")
        return
    proposer = role.get("proposed_by")
    status_note = ""
    if proposer and not await is_chat_member(chat_id, proposer):
        if await db.reserve_role(chat_id, role_id, proposer):
            status_note = " (забронирована за автором — он ещё не в группе)"
    await db.add_log("role_approve", chat_id=chat_id, actor_id=message.from_user.id, details=role["name"])
    await message.reply(f"✅ Роль «{html.escape(role['name'])}» добавлена в список{status_note}.")
    if proposer:
        try:
            await bot.send_message(proposer, f"✅ Ваша заявка на роль «{html.escape(role['name'])}» одобрена.")
        except Exception as exc:
            log_suppressed("cmd_role_approve", exc)


@router.message(F.text.func(lambda t: bool(t) and bool(re.match(r"^роль отклонить (\d+)$", t.strip().casefold()))))
async def cmd_role_reject(message: Message):
    if not has_level(message.from_user.id, required_level("role_reject")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Отклонять роли может «{level_name(required_level('role_reject'))}» и выше.")
        return
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Роли пока не настроены для этого чата.")
        return
    role_id = int(re.match(r"^роль отклонить (\d+)$", message.text.strip().casefold()).group(1))
