ROLE_GIVE_BY_USERNAME_RE = ru_text.rx(r"^роль\s+отдать\s+@(?P<username>\w{4,32})\s+(?P<name>.+)$", re.IGNORECASE | re.DOTALL)


# ----------------------------------------------------------------------------
# «роль отдать @username Название» — тот же принудительный выбор роли, что и
# cmd_role_force_give выше, но цель указывается тегом прямо в тексте, а не
# ответом на сообщение игрока. Нужно, чтобы работало из ЛС бота (там нечего
# «отвечать» — переписки с игроком у админа может и не быть), но команда
# точно так же работает и в группе. Права те же — «role_force_give».
# ----------------------------------------------------------------------------
@router.message(F.text.func(lambda t: bool(t) and ROLE_GIVE_BY_USERNAME_RE.match(t.strip())))
async def cmd_role_force_give_by_username(message: Message):
    if not has_level(message.from_user.id, required_level("role_force_give")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Назначать роли принудительно может «{level_name(required_level('role_force_give'))}» и выше.")
        return
    match = ROLE_GIVE_BY_USERNAME_RE.match(message.text.strip())
    username = match.group("username")
    name = match.group("name").strip(" :—-")
    if not name:
        await message.reply("Укажите название роли после юзернейма, например «роль отдать @example_user Каору Нагиса».")
        return
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Роли пока не настроены для этого чата (см. «чат сюда»).")
        return

    target_id: Optional[int] = None
    target_username = username
    target_full_name: Optional[str] = None
    known = await db.get_known_user_by_username(username)
    if known:
        target_id = known["user_id"]
        target_username = known.get("username") or username
        target_full_name = known.get("full_name")
    else:
        try:
            chat = await bot.get_chat(username)
            if chat.type == "private":
                target_id = chat.id
                target_username = chat.username or username
                target_full_name = chat.full_name or chat.first_name
        except Exception:
            target_id = None

    if target_id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(username)} — бот его ещё не видел "
            "(должен был хоть раз написать в группу или боту). Попробуйте назначить "
            "роль ответом на его сообщение в группе."
        )
        return

    role = await db.get_role_by_name(chat_id, name)
    if role is None:
        await message.reply("Роль с таким названием не найдена в списке.")
        return

    await db.force_set_role(chat_id, role["id"], target_id)
    await sync_role_title(chat_id, target_id)
    await db.add_log("role_force_give", chat_id=chat_id, actor_id=message.from_user.id, target_id=target_id, details=role["name"])
    mention = mention_id(target_id, full_name=target_full_name, username=target_username)
    await message.reply(f"✅ Роль «{html.escape(role['name'])}» принудительно закреплена за {mention}.")


