ROLE_TAKE_BY_USERNAME_RE = ru_text.rx(r"^роль\s+снять\s+@(?P<username>\w{4,32})\s*$", re.IGNORECASE)


# ----------------------------------------------------------------------------
# «роль снять @username» — то же самое, что и cmd_role_force_take выше, но
# цель указывается тегом прямо в тексте, а не ответом на сообщение (та же
# причина, что и у «роль отдать/забронировать @username» — из ЛС бота
# отвечать физически не на что). Права те же — «role_force_take». Ищем через
# ГЛОБАЛЬНЫЙ db.get_known_user_by_username (как и соседние *_by_username
# хендлеры выше), а не chat-scoped резолвер модерации — чтобы поведение
# username-поиска было одинаковым у всех «роль ...» команд.
# ----------------------------------------------------------------------------
@router.message(F.text.func(lambda t: bool(t) and ROLE_TAKE_BY_USERNAME_RE.match(t.strip())))
async def cmd_role_force_take_by_username(message: Message):
    if not has_level(message.from_user.id, required_level("role_force_take")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Снимать роли принудительно может «{level_name(required_level('role_force_take'))}» и выше.")
        return
    match = ROLE_TAKE_BY_USERNAME_RE.match(message.text.strip())
    username = match.group("username")

    target_id: Optional[int] = None
    known = await db.get_known_user_by_username(username)
    if known:
        target_id = known["user_id"]
    else:
        try:
            chat = await bot.get_chat(username)
            if chat.type == "private":
                target_id = chat.id
        except Exception:
            target_id = None

    if target_id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(username)} — бот его ещё не видел "
            "(должен был хоть раз написать боту или в любой из чатов, где он есть). "
            "Попробуйте снять роль ответом на его сообщение, если оно есть."
        )
        return

    await _role_force_take_for(message, target_id)


async def _role_force_take_for(message: Message, target_id: int) -> None:
    """Общее тело «роль снять» — вынесено, чтобы reply- и @username-варианты
    не дублировали логику поиска/снятия роли или брони."""
    chat_id = await roles_context_chat_id(message)
    if not chat_id:
        await message.reply("Роли пока не настроены для этого чата.")
        return
    role = await db.get_user_role(chat_id, target_id)
    if role is not None:
        await db.release_role(chat_id, role["id"])
        
        await db.add_log("role_force_take", chat_id=chat_id, actor_id=message.from_user.id, target_id=target_id, details=role["name"])
        await message.reply(f"✅ Роль «{html.escape(role['name'])}» снята с {mention_id(target_id)} — теперь свободна.")
        return
    reservation = await db.get_user_reservation(chat_id, target_id)
    if reservation is not None:
        await db.cancel_reservation(chat_id, reservation["id"])
        await db.add_log("role_force_take", chat_id=chat_id, actor_id=message.from_user.id, target_id=target_id, details=reservation["name"])
        await message.reply(f"✅ Бронь роли «{html.escape(reservation['name'])}» за {mention_id(target_id)} отменена — роль снова свободна.")
        return
    await message.reply(f"У {mention_id(target_id)} сейчас нет ни закреплённой роли, ни брони.")


# ----------------------------------------------------------------------------
# Кнопки-шорткаты «Забронировать роль» / «Снять роль» / «Справка по ролям»
# (личка бота, только для админов с правами role_force_reserve/role_force_take —
# см. private_menu_kb()). Делают то же самое, что текстовые команды
# «роль забронировать»/«роль снять» выше, но пошагово, через FSM, без
# необходимости помнить точный синтаксис и обязательно отвечать на чьё-то
# сообщение. Каждое действие пишется в лог через db.add_log — так же, как и
# у текстовых команд.
# ----------------------------------------------------------------------------
ADMIN_ROLE_HELP_TEXT = (
    "👑 <b>Админ-команды ролей:</b>\n"
    "• <code>роль забронировать [Название]</code> (ответом на сообщение) — "
    "забронировать роль за юзером.\n"
    "• <code>роль забронировать [@username] [Название]</code> — "
    "забронировать роль по юзернейму.\n"
    "• <code>роль снять</code> — снимает занятую или забронированную роль с пользователя.\n\n"
    "Всё то же самое можно сделать кнопками «Забронировать роль» / «Снять роль» "
    f"ниже — бот сам спросит нужные данные по шагам (бронь действует {ROLE_RESERVE_TIMEOUT_HOURS} ч.)."
)


async def _resolve_role_target(message: Message) -> tuple[Optional[int], Optional[str], Optional[str]]:
    """Определяет пользователя-цель для принудительного действия с ролью по
    сообщению админа: пересланное сообщение → числовой Telegram ID → @username
    (сперва среди уже виденных ботом людей, затем — прямой запрос к Telegram).
    Возвращает (user_id, username, full_name); все поля кроме user_id могут
    быть None. user_id is None, если распознать не удалось."""
    if message.forward_from:
        u = message.forward_from
        return u.id, u.username, u.full_name
    text = (message.text or "").strip()
    if text.isdigit():
        return int(text), None, None
    if text.startswith("@") and len(text) > 1:
        username = text[1:].strip()
        known = await db.get_known_user_by_username(username)
        if known:
            return known["user_id"], known.get("username") or username, known.get("full_name")
        try:
            chat = await bot.get_chat(username)
            if chat.type == "private":
                return chat.id, chat.username or username, chat.full_name or chat.first_name
        except Exception as exc:
            log_suppressed("_resolve_role_target", exc)
    return None, None, None


def role_force_target_prompt(action_hint: str) -> str:
    return (
        f"👤 Введите <b>@username</b> пользователя, его числовой Telegram ID, "
        f"или перешлите сюда его сообщение — {action_hint}.\n\n"
        "Узнать ID можно у @userinfobot."
    )


