HELP_RP_ACTIONS_TEXT = _rp_actions_help_text()

_RP_ACTION_ALL_KEYS = sorted(
    (RP_ACTIONS.keys() | RP_ACTION_SYNONYMS.keys()),
    key=lambda k: len(k.split()),
    reverse=True,
)

# Явно сексуализированные/описанные как насильственные действия — им новый
# способ указания цели (@username/ID без reply) сознательно НЕ выдаётся.
# Это реальные люди в реальном чате; снижать порог, требуемый для того,
# чтобы направить такое действие на конкретного человека (сейчас нужно
# отвечать на его настоящее сообщение), мы не будем — остаются только reply,
# как было раньше.
RP_ACTIONS_RESTRICTED_NO_TEXT_TARGET = {
    "трахнуть", "выебать", "изнасиловать", "отлизать", "отсосать",
    "облить спермой", "обрыгать", "отстрапонить",
}


def _match_rp_action_prefix(text: Optional[str]) -> Optional[tuple[str, int]]:
    """Проверяет, начинается ли текст с одного из RP-действий (или его
    синонима-повелительной формы). Действия бывают из нескольких слов
    («взять за руку», «дать подзатыльник по-дружески»), поэтому ключи
    проверяются от самых длинных к самым коротким — чтобы не словить
    случайное частичное совпадение. Возвращает (raw_action_key,
    число_слов_в_триггере) или None, если действие не распознано."""
    if not text:
        return None
    words = text.strip().lower().split()
    for key in _RP_ACTION_ALL_KEYS:
        key_words = key.split()
        n = len(key_words)
        if len(words) >= n and words[:n] == key_words:
            return key, n
    return None
def _split_command_line(text: str) -> tuple[str, Optional[str]]:
    """Первая строка — сама команда (действие + опционально цель); всё, что
    идёт после первого переноса строки — необязательная «реплика», которая
    просто цитируется в ответе бота и не мешает выполнению действия."""
    if "\n" not in text:
        return text.strip(), None
    first, rest = text.split("\n", 1)
    rest = rest.strip()
    return first.strip(), (rest or None)

# Слова-указатели на цель («поцелуй ЕГО», «обнять ЕЁ») — это не свободный текст,
# а способ показать, кого имеют в виду (обычно вместе с ответом на сообщение).
# Поэтому они НЕ считаются «свободным текстом»: «обнять его» — валидная команда
# (цель из reply), а «обнять снова тест» — уже обычная фраза, не команда.
_RP_TARGET_POINTER_WORDS = {
    "его", "её", "ее", "их", "него", "неё", "нее", "них",
    "этого", "эту", "этих", "этому", "ему", "ей", "им", "нему", "ней",
}


def _rp_reply_text(remaining_words: list[str], trigger_word_count: int) -> str:
    """Свободный текст после триггера действия (то, что осталось за вычетом
    самого действия и токена цели). Пустая строка — значит это чистое «действие
    1в1» (возможно с местоимением-указателем его/её), которое НАДО выполнить.
    Непустая — значит после действия дописан произвольный текст, и это обычная
    фраза, а не команда (действие выполнять не нужно)."""
    tail = remaining_words[trigger_word_count:]
    if tail and all(ru_text.yo(w.casefold()).strip(".,!?…") in _RP_TARGET_POINTER_WORDS
                    for w in tail):
        return ""
    return " ".join(tail).strip()


def _is_rp_action_command(t: Optional[str]) -> bool:
    if not t:
        return False
    first_line, _ = _split_command_line(t)
    matched = _match_rp_action_prefix(first_line)
    if not matched:
        return False
    raw_action, n = matched
    words = first_line.split()
    if len(words) == n:
        return True
    action = RP_ACTION_SYNONYMS.get(raw_action, raw_action)
    return action not in RP_ACTIONS_RESTRICTED_NO_TEXT_TARGET


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_rp_action_command),
)
async def handle_rp_action(message: Message):
    first_line, reply_text = _split_command_line(message.text or "")
    raw_action, n = _match_rp_action_prefix(first_line)
    action = RP_ACTION_SYNONYMS.get(raw_action, raw_action)

    target_user, remaining = await resolve_command_target(message, trigger_words=n, text=first_line)
    if target_user is None and message.reply_to_message:
        target_user = message.reply_to_message.from_user
        remaining = first_line
    if target_user is None:
        raise SkipHandler
    # Лишний текст блокирует действие, только если он в ТОЙ ЖЕ строке, что и
    # само действие («обнять снова тест»). Текст после переноса строки — это
    # отдельная «реплика», она действие не блокирует (см. reply_text ниже).
    # Проверяем ОСТАТОК после вычитания уже найденной цели (@username/ID), а
    # не исходную строку — иначе "обнять @username" всегда считался бы
    # «действием с лишним текстом», и SkipHandler срабатывал бы даже при явно
    # указанной цели.
    if _rp_reply_text(remaining.split(), n):
        raise SkipHandler
    if target_user.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target_user.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return

    if target_user.id == message.from_user.id:
        await message.reply("Действие направлено на самого себя? Пожалуй, воздержимся 🙂")
        return

    actor_name = await display_name_link(message.chat.id, message.from_user)
    target_name = await display_name_link(message.chat.id, target_user)
    phrase = random.choice(RP_ACTIONS[action]).format(actor=actor_name, target=target_name)
    if reply_text:
        phrase += f"\n💬 С репликой: «{html.escape(reply_text)}»"

    if message.reply_to_message:
        await message.answer(phrase, reply_to_message_id=message.reply_to_message.message_id)
    else:
        await message.answer(phrase)
    await db.add_log(
        f"rp_{action}", chat_id=message.chat.id, actor_id=message.from_user.id, target_id=target_user.id
    )


def _match_propose_action_prefix(text: Optional[str]) -> Optional[tuple[str, int]]:
    """«предложить <синоним>» (цель — reply или @username в любом месте фразы,
    как раньше), а теперь ещё и «предложить @username <синоним>» — цель сразу
    после слова «предложить», перед названием действия.

    Синонимы бывают многословными («полить цветы», «дуэль на щелбанчики»),
    поэтому проверяются от самых длинных к самым коротким (см.
    _match_rp_action_prefix). Возвращает (action_key, trigger_words) —
    trigger_words нужен resolve_command_target(), чтобы понять, на каком
    слове по счёту искать голый числовой ID (мешки не мешают, @username и
    text_mention resolve_command_target находит по всему тексту вне
    зависимости от trigger_words)."""
    if not text:
        return None
    raw_words = text.strip().split()
    if not raw_words or raw_words[0].casefold() != "предложить":
        return None

    words_cf = [w.casefold() for w in raw_words]
    rest_cf = words_cf[1:]

    # Есть ли явный токен-цель (@username или голое число) сразу после
    # «предложить», перед названием действия?
    has_leading_target = bool(rest_cf) and (raw_words[1].startswith("@") or raw_words[1].isdigit())
    action_rest_cf = rest_cf[1:] if has_leading_target else rest_cf

    for synonym in _PROPOSE_ACTION_ALL_KEYS:
        syn_words = synonym.split()
        n = len(syn_words)
        if len(action_rest_cf) >= n and action_rest_cf[:n] == syn_words:
            action_key = PROPOSE_ACTION_SYNONYMS[synonym]
            # Цель перед действием — голый ID (если он есть) стоит сразу
            # после «предложить», значит trigger_words=1 (слово[1] —
            # это и есть цель). Цель после действия (старый формат) —
            # trigger_words = 1 + n, как раньше.
            trigger_words = 1 if has_leading_target else 1 + n
            return action_key, trigger_words
    return None

    

def _is_propose_action_command(t: Optional[str]) -> bool:
    return _match_propose_action_prefix(t) is not None


async def refresh_propose_caches() -> None:
    """Лёгкий рефреш кэшей «Предложить действие» — вызывается после правок
    через личку/сайт и из panel_action_reload_loop, без полного load_caches()."""
    global _PROPOSE_ACTION_ALL_KEYS

    propose_actions = await db.list_propose_actions(active_only=True)
    PROPOSE_ACTIONS.clear()
    PROPOSE_ACTIONS.update(propose_actions)

    propose_synonyms = await db.list_propose_action_synonyms()
    PROPOSE_ACTION_SYNONYMS.clear()
    PROPOSE_ACTION_SYNONYMS.update(propose_synonyms)

    _PROPOSE_ACTION_ALL_KEYS = sorted(
        PROPOSE_ACTION_SYNONYMS.keys(), key=lambda k: len(k.split()), reverse=True,
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_propose_action_command),
)
async def handle_propose_action(message: Message):
    matched = _match_propose_action_prefix(message.text)
    if matched is None:
        # В реальной работе роутер уже отфильтровал такие сообщения через
        # F.text.func(_is_propose_action_command), сюда они не попадают; но
        # хендлер может быть вызван и напрямую (например, в тестах) — тогда
        # нераспознанный триггер тоже должен молча игнорироваться.
        raise SkipHandler
    action_key, n = matched
    if action_key not in PROPOSE_ACTIONS:
        raise SkipHandler  # неизвестно или выключено — молча, как выключенные РП

    target, _remaining = await resolve_command_target(message, trigger_words=n)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Укажите, кому предлагаете: ответьте (reply) на сообщение или укажите @username."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return
    if target.id == message.from_user.id:
        await message.reply("Предложить это самому себе? Пожалуй, воздержимся 🙂")
        return
    if target.is_bot:
        await message.reply("Боту такое не предложишь 🙂")
        return

    wait_seconds = await db.check_and_touch_propose_cooldown(
        message.chat.id, action_key, message.from_user.id, target.id,
        PROPOSE_ACTIONS[action_key]["cooldown_seconds"],
    )
    if wait_seconds is not None:
        await message.reply(f"Подождите ещё {wait_seconds}с — не так часто ⏳")
        return

    actor_name = await display_name_link(message.chat.id, message.from_user)
    target_name = await display_name_link(message.chat.id, target)
    phrase = random.choice(PROPOSE_ACTIONS[action_key]["propose"]).format(actor=actor_name, target=target_name)

    # request_id нужен ДО отправки (чтобы сразу вшить его в callback_data), а
    # настоящий message_id известен только ПОСЛЕ отправки (Telegram отдаёт его
    # только в ответе) — поэтому строка сперва создаётся с message_id=0 и
    # дописывается сразу после отправки, без повторной правки клавиатуры.
    request_id = await db.create_or_replace_propose_request(
        message.chat.id, 0, action_key, message.from_user.id, target.id,
    )
    sent = await message.answer(
        phrase,
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="✅ Да", callback_data=f"propose_yes:{request_id}"),
            InlineKeyboardButton(text="❌ Нет", callback_data=f"propose_no:{request_id}"),
        ]]),
    )
    await db.set_propose_request_message_id(request_id, sent.message_id)
    await db.add_log(f"propose_{action_key}", chat_id=message.chat.id, actor_id=message.from_user.id, target_id=target.id)


async def _propose_decision(callback: CallbackQuery, agree: bool) -> None:
    """Общая логика Да/Нет — по образцу _role_proposal_decision: ответ
    отображается изменением того же сообщения, без отдельного текста."""
    try:
        request_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer()
        return

    req = await db.get_propose_request(request_id)
    if req is None:
        # Не трогаем клавиатуру: если запись уже удалена (отвечено/протухло/
        # перезаписано новым предложением), повторный клик так и будет получать
        # тот же alert — этого достаточно, отдельная правка сообщения не нужна.
        await callback.answer("Предложение больше не активно.", show_alert=True)
        return

    if callback.from_user.id != req["to_user_id"]:
        await callback.answer("Это предложение адресовано не вам", show_alert=True)
        return

    action_key = req["action_key"]
    action = PROPOSE_ACTIONS.get(action_key)
    kind = "agree" if agree else "decline"
    phrases = action[kind] if action else ["Готово."]

    # В момент клика под рукой только id (строка propose_requests), а не живой
    # aiogram User — display_name_link ждёт объект с .full_name и упадёт;
    # display_name_by_id как раз для этого случая ("объекта User нет под рукой").
    actor_name = await display_name_by_id(req["chat_id"], req["from_user_id"])
    target_name = await display_name_by_id(req["chat_id"], req["to_user_id"])
    phrase = random.choice(phrases).format(actor=actor_name, target=target_name)

    try:
        await callback.message.edit_text(phrase, reply_markup=None)
    except TelegramBadRequest:
        pass
    await db.delete_propose_request(request_id)
    await db.add_log(
        f"propose_{action_key}_{kind}", chat_id=req["chat_id"],
        actor_id=req["from_user_id"], target_id=req["to_user_id"],
    )
    await callback.answer("Готово ✅" if agree else "Отклонено")


@router.callback_query(F.data.startswith("propose_yes:"))
async def propose_yes_callback(callback: CallbackQuery):
    await _propose_decision(callback, agree=True)


@router.callback_query(F.data.startswith("propose_no:"))
async def propose_no_callback(callback: CallbackQuery):
    await _propose_decision(callback, agree=False)


async def _process_expired_propose_requests() -> int:
    """Одна проверка просроченных предложений — вызывается из
    propose_expiry_loop (Task 6) и напрямую тестами. Возвращает число
    обработанных строк."""
    rows = await db.list_expired_propose_requests(datetime.utcnow())
    for row in rows:
        try:
            await bot.edit_message_text(
                chat_id=row["chat_id"], message_id=row["message_id"],
                text="⌛ Предложение устарело.",
            )
        except TelegramBadRequest:
            pass
        except Exception:
            logger.exception("propose_expiry: не удалось отредактировать сообщение %s", row["id"])
        await db.delete_propose_request(row["id"])
    return len(rows)


async def propose_expiry_loop() -> None:
    while True:
        await asyncio.sleep(30)
        try:
            await _process_expired_propose_requests()
        except Exception:
            logger.exception("propose_expiry_loop: ошибка обработки просрочки")


# ----------------------------------------------------------------------------
# Управление действиями «Предложить» через бота (в личке) — по образцу
# rp_admin_command. Каждая мутирующая команда сразу вызывает
# refresh_propose_caches(), чтобы новое действие/фраза/синоним заработали в
# чатах немедленно.
# ----------------------------------------------------------------------------

_PROPOSE_KIND_ALIASES = {"предложение": "propose", "согласие": "agree", "отказ": "decline"}

PROPOSE_ADMIN_HELP = (
    "🛠 <b>Управление «Предложить действие»</b> (только в личке боту)\n"
    + DIVIDER +
    "<code>предложения добавить ключ | фраза-предложения</code>\n"
    "Создаёт действие (если такого ключа ещё не было) и его первую фразу «предложение». "
    "В фразе можно использовать <code>{actor}</code> и <code>{target}</code>.\n\n"
    "<code>предложения фраза ключ вид | фраза</code>\n"
    "Добавляет ещё вариант фразы к существующему действию. вид — предложение/согласие/отказ.\n"
    "Пример: <code>предложения фраза ромашка согласие | Есть контакт! {target} и {actor} гадают 🌼</code>\n\n"
    "<code>предложения синоним синоним | ключ</code> — добавляет синоним-триггер.\n"
    "<code>предложения список</code> — все действия, кулдаун/таймаут, число фраз.\n"
    "<code>предложения удалить_фраза id</code> / <code>предложения удалить_синоним синоним</code>\n"
    "<code>предложения вкл ключ</code> / <code>предложения выкл ключ</code>\n"
    "<code>предложения кулдаун ключ секунды</code> / <code>предложения таймаут ключ секунды</code>\n"
)


@router.message(
    F.chat.type == "private",
    F.text.func(lambda t: bool(t) and (t.strip().casefold().split() or [""])[0] == "предложения"),
)
async def propose_admin_command(message: Message):
    # Важно: и «нет сообщения об отказе» (обычный пользователь — не спалить
    # само существование команды), и «есть сообщение об отказе» (админ ниже
    # нужного уровня) — оба случая должны ОСТАНОВИТЬ выполнение, поэтому
    # return в обеих ветках, а не только когда есть текст отказа.
    if not has_level(message.from_user.id, required_level("propose_manage")):
        if get_level(message.from_user.id) > 0:
            await message.reply(
                f"⛔ Команда доступна только с уровнем «{level_name(required_level('propose_manage'))}» и выше."
            )
        return

    tokens = message.text.strip().split(maxsplit=2)
    sub = tokens[1].casefold() if len(tokens) >= 2 else ""
    rest = tokens[2] if len(tokens) >= 3 else ""

    if not sub or sub in {"помощь", "хелп", "help"}:
        await message.answer(PROPOSE_ADMIN_HELP)
        return

    if sub == "добавить":
        key_part, sep, phrase_part = rest.partition("|")
        action_key = key_part.strip().casefold()
        phrase = phrase_part.strip()
        if not sep or not action_key or not phrase:
            await message.reply(
                "Формат: <code>предложения добавить ключ | фраза</code>\n"
                "Пример: <code>предложения добавить турнир | {actor} вызывает {target} на турнир!</code>"
            )
            return
        await db.add_propose_phrase(action_key, "propose", phrase)
        await refresh_propose_caches()
        await db.add_log("propose_phrase_added", actor_id=message.from_user.id, details=f"{action_key}: {phrase}")
        await message.answer(f"✅ Фраза добавлена (действие «{html.escape(action_key)}»).")
        return

    if sub == "фраза":
        head, sep, phrase_part = rest.partition("|")
        head_tokens = head.split()
        phrase = phrase_part.strip()
        if not sep or len(head_tokens) != 2 or not phrase:
            await message.reply(
                "Формат: <code>предложения фраза ключ вид | фраза</code> "
                "(вид — предложение/согласие/отказ)\n"
                "Пример: <code>предложения фраза ромашка согласие | Есть контакт! 🌼</code>"
            )
            return
        action_key, kind_word = head_tokens[0].casefold(), head_tokens[1].casefold()
        kind = _PROPOSE_KIND_ALIASES.get(kind_word)
        if kind is None:
            await message.reply("Вид должен быть один из: предложение, согласие, отказ.")
            return
        await db.add_propose_phrase(action_key, kind, phrase)
        await refresh_propose_caches()
        await db.add_log("propose_phrase_added", actor_id=message.from_user.id, details=f"{action_key}/{kind}: {phrase}")
        await message.answer(f"✅ Фраза добавлена (действие «{html.escape(action_key)}», вид «{kind_word}»).")
        return

    if sub == "синоним":
        syn_part, sep, key_part = rest.partition("|")
        synonym = syn_part.strip().casefold()
        action_key = key_part.strip().casefold()
        if not sep or not synonym or not action_key:
            await message.reply(
                "Формат: <code>предложения синоним синоним | ключ</code>\n"
                "Пример: <code>предложения синоним погадать на ромашке | romashka</code>"
            )
            return
        await db.add_propose_action_synonym(synonym, action_key)
        await refresh_propose_caches()
        await db.add_log("propose_synonym_added", actor_id=message.from_user.id, details=f"{synonym} -> {action_key}")
        await message.answer(f"✅ Синоним «{html.escape(synonym)}» → «{html.escape(action_key)}» добавлен.")
        return

    if sub == "список":
        rows = await db.list_propose_actions_rows()
        if not rows:
            await message.answer("Действий пока нет.")
            return
        lines = ["🎲 <b>Предложить действие</b>", DIVIDER]
        for r in rows:
            status = "✅" if r["is_active"] else "🚫"
            lines.append(
                f"{status} <b>{html.escape(r['action_key'])}</b> — "
                f"кулдаун {r['cooldown_seconds']}с, таймаут {r['timeout_seconds']}с"
            )
        await message.answer("\n".join(lines))
        return

    if sub == "удалить_фраза":
        try:
            phrase_id = int(rest.strip())
        except ValueError:
            await message.reply("Формат: <code>предложения удалить_фраза id</code>")
            return
        if not await db.delete_propose_phrase(phrase_id):
            await message.answer(f"Фраза с id {phrase_id} не найдена.")
            return
        await refresh_propose_caches()
        await db.add_log("propose_phrase_deleted", actor_id=message.from_user.id, details=str(phrase_id))
        await message.answer(f"🗑 Фраза #{phrase_id} удалена.")
        return

    if sub == "удалить_синоним":
        synonym = rest.strip().casefold()
        if not synonym or not await db.delete_propose_action_synonym(synonym):
            await message.answer(f"Синоним «{html.escape(synonym)}» не найден.")
            return
        await refresh_propose_caches()
        await db.add_log("propose_synonym_deleted", actor_id=message.from_user.id, details=synonym)
        await message.answer(f"🗑 Синоним «{html.escape(synonym)}» удалён.")
        return

    if sub in {"вкл", "выкл"}:
        action_key = rest.strip().casefold()
        if not action_key:
            await message.reply(f"Формат: <code>предложения {sub} ключ</code>")
            return
        is_active = sub == "вкл"
        changed = await db.set_propose_action_active(action_key, is_active)
        if not changed:
            await message.answer(f"Действие «{html.escape(action_key)}» не найдено.")
            return
        await refresh_propose_caches()
        await db.add_log(
            "propose_action_toggled", actor_id=message.from_user.id,
            details=f"{action_key}: {'on' if is_active else 'off'}",
        )
        state_text = "включено ✅" if is_active else "выключено 🚫"
        await message.answer(f"Действие «{html.escape(action_key)}» {state_text}.")
        return

    if sub in {"кулдаун", "таймаут"}:
        parts = rest.split()
        if len(parts) != 2 or not parts[1].isdigit():
            await message.reply(f"Формат: <code>предложения {sub} ключ секунды</code>")
            return
        action_key, seconds = parts[0].casefold(), int(parts[1])
        kwargs = {"cooldown_seconds": seconds} if sub == "кулдаун" else {"timeout_seconds": seconds}
        if not await db.set_propose_action_settings(action_key, **kwargs):
            await message.answer(f"Действие «{html.escape(action_key)}» не найдено.")
            return
        await refresh_propose_caches()
        await db.add_log(f"propose_{sub}_set", actor_id=message.from_user.id, details=f"{action_key}: {seconds}")
        await message.answer(f"✅ {sub.capitalize()} действия «{html.escape(action_key)}» — {seconds}с.")
        return

    await message.reply(PROPOSE_ADMIN_HELP)

# ----------------------------------------------------------------------------
# Управление РП-действиями через бота (в личке).
# Раньше правки предполагались через отдельный сайт-админку (см. функции
# add_rp_action_phrase/add_rp_action_synonym и т.п. в db.py) — сайта не будет,
# поэтому то же самое доступно текстовыми командами прямо в личке боту.
# Все команды сразу вызывают refresh_rp_caches(), чтобы новое действие или
# синоним заработал в чатах немедленно, без перезапуска бота.
# ----------------------------------------------------------------------------

RP_ADMIN_HELP = (
    "🛠 <b>Управление РП-действиями</b> (только в личке боту)\n"
    + DIVIDER +
    "<code>рп добавить ключ | фраза</code>\n"
    "Добавляет фразу действию (если такого ключа ещё не было — создаётся новый). "
    "В фразе можно использовать <code>{actor}</code> и <code>{target}</code>.\n"
    "Пример: <code>рп добавить поспать | 😴 {actor} укладывается спать рядом с {target}</code>\n\n"
    "<code>рп синоним синоним | ключ</code>\n"
    "Добавляет повелительную форму действия.\n"
    "Пример: <code>рп синоним поспи | поспать</code>\n\n"
    "<code>рп список</code> — все действия и число фраз в каждом.\n"
    "<code>рп список ключ</code> — все фразы действия с их id.\n\n"
    "<code>рп удалить id</code> — удаляет одну фразу по её id (см. «рп список ключ»).\n"
    "<code>рп вкл ключ</code> / <code>рп выкл ключ</code> — включить/выключить действие целиком.\n"
    "<code>рп удалить_синоним синоним</code> — удаляет синоним.\n"
)


async def refresh_rp_caches() -> None:
    """Лёгкий рефреш только РП-кэшей (без полного load_caches()) — вызывается
    после каждой правки через команды «рп ...», чтобы новые действия/синонимы
    сразу заработали в чатах."""
    global HELP_RP_ACTIONS_TEXT, _RP_ACTION_ALL_KEYS

    rp_actions = await db.list_rp_actions(active_only=True)
    RP_ACTIONS.clear()
    RP_ACTIONS.update(rp_actions or _RP_ACTIONS_DEFAULT)

    rp_synonyms = await db.list_rp_action_synonyms()
    RP_ACTION_SYNONYMS.clear()
    RP_ACTION_SYNONYMS.update(rp_synonyms or _RP_ACTION_SYNONYMS_DEFAULT)

    HELP_RP_ACTIONS_TEXT = _rp_actions_help_text()
    _RP_ACTION_ALL_KEYS = sorted(
        (RP_ACTIONS.keys() | RP_ACTION_SYNONYMS.keys()),
        key=lambda k: len(k.split()),
        reverse=True,
    )


def _rp_admin_denied(user_id: int) -> Optional[str]:
    """None — доступ есть. Иначе — текст отказа (или None молча, если человек
    вообще не админ, чтобы не палить наличие команды рядовым пользователям)."""
    if has_level(user_id, required_level("rp_manage")):
        return None
    if get_level(user_id) > 0:
        return f"⛔ Команда доступна только с уровнем «{level_name(required_level('rp_manage'))}» и выше."
    return None


@router.message(
    F.chat.type == "private",
    F.text.func(lambda t: bool(t) and (t.strip().casefold().split() or [""])[0] == "рп"),
)
async def rp_admin_command(message: Message):
    denied = _rp_admin_denied(message.from_user.id)
    if denied is not None:
        await message.reply(denied)
        return

    tokens = message.text.strip().split(maxsplit=2)
    sub = tokens[1].casefold() if len(tokens) >= 2 else ""
    rest = tokens[2] if len(tokens) >= 3 else ""

    if not sub or sub in {"помощь", "хелп", "help"}:
        await message.answer(RP_ADMIN_HELP)
        return

    if sub == "добавить":
        key_part, sep, phrase_part = rest.partition("|")
        action_key = key_part.strip().casefold()
        phrase = phrase_part.strip()
        if not sep or not action_key or not phrase:
            await message.reply(
                "Формат: <code>рп добавить ключ | фраза</code>\n"
                "Пример: <code>рп добавить поспать | 😴 {actor} укладывается спать рядом с {target}</code>"
            )
            return
        new_id = await db.add_rp_action_phrase(action_key, phrase)
        await refresh_rp_caches()
        await db.add_log("rp_action_phrase_added", actor_id=message.from_user.id, details=f"{action_key}: {phrase}")
        await message.answer(
            f"✅ Фраза добавлена к действию «{html.escape(action_key)}» (id {new_id}).\n"
            f"Всего фраз у этого действия теперь: {len(RP_ACTIONS.get(action_key, []))}."
        )
        return

    if sub == "синоним":
        syn_part, sep, key_part = rest.partition("|")
        synonym = syn_part.strip().casefold()
        action_key = key_part.strip().casefold()
        if not sep or not synonym or not action_key:
            await message.reply(
                "Формат: <code>рп синоним синоним | ключ</code>\n"
                "Пример: <code>рп синоним поспи | поспать</code>"
            )
            return
        if action_key not in RP_ACTIONS:
            await message.reply(
                f"Действия «{html.escape(action_key)}» пока не существует — сначала добавьте фразу командой "
                f"<code>рп добавить {html.escape(action_key)} | фраза</code>."
            )
            return
        await db.add_rp_action_synonym(synonym, action_key)
        await refresh_rp_caches()
        await db.add_log("rp_action_synonym_added", actor_id=message.from_user.id, details=f"{synonym} -> {action_key}")
        await message.answer(f"✅ Синоним «{html.escape(synonym)}» → «{html.escape(action_key)}» добавлен.")
        return

    if sub == "список":
        query_key = rest.strip().casefold()
        if not query_key:
            if not RP_ACTIONS:
                await message.answer("Действий пока нет.")
                return
            synonyms_by_action: dict[str, list[str]] = {}
            for synonym, action in RP_ACTION_SYNONYMS.items():
                synonyms_by_action.setdefault(action, []).append(synonym)
            lines = ["🎭 <b>РП-действия</b>", DIVIDER]
            for key, phrases in RP_ACTIONS.items():
                synonyms = " / ".join(synonyms_by_action.get(key, []))
                lines.append(
                    f"<b>{html.escape(key)}</b>" + (f" ({synonyms})" if synonyms else "")
                    + f" — {len(phrases)} фраз(ы)"
                )
            lines.append(DIVIDER + "Подробно по одному действию: <code>рп список ключ</code>")
            await message.answer("\n".join(lines))
            return

        rows = [r for r in await db.list_rp_actions_rows() if r["action_key"] == query_key]
        if not rows:
            await message.answer(f"Действие «{html.escape(query_key)}» не найдено.")
            return
        lines = [f"🎭 <b>{html.escape(query_key)}</b>", DIVIDER]
        for r in rows:
            status = "" if r["is_active"] else " (выключено)"
            lines.append(f"#{r['id']}{status}: {html.escape(r['phrase'])}")
        await message.answer("\n".join(lines))
        return

    if sub == "удалить":
        phrase_id_raw = rest.strip()
        if not phrase_id_raw.isdigit():
            await message.reply("Формат: <code>рп удалить id</code> — id смотрите через «рп список ключ».")
            return
        ok = await db.delete_rp_action_phrase(int(phrase_id_raw))
        if not ok:
            await message.answer(f"Фраза с id {phrase_id_raw} не найдена.")
            return
        await refresh_rp_caches()
        await db.add_log("rp_action_phrase_deleted", actor_id=message.from_user.id, details=phrase_id_raw)
        await message.answer(f"🗑 Фраза #{phrase_id_raw} удалена.")
        return

    if sub in {"вкл", "выкл"}:
        action_key = rest.strip().casefold()
        if not action_key:
            await message.reply(f"Формат: <code>рп {sub} ключ</code>")
            return
        is_active = sub == "вкл"
        changed = await db.set_rp_action_key_active(action_key, is_active)
        if not changed:
            await message.answer(f"Действие «{html.escape(action_key)}» не найдено.")
            return
        await refresh_rp_caches()
        await db.add_log(
            "rp_action_toggled", actor_id=message.from_user.id, details=f"{action_key}: {'on' if is_active else 'off'}"
        )
        state_text = "включено ✅" if is_active else "выключено 🚫"
        await message.answer(f"Действие «{html.escape(action_key)}» {state_text}.")
        return

    if sub == "удалить_синоним":
        synonym = rest.strip().casefold()
        if not synonym:
            await message.reply("Формат: <code>рп удалить_синоним синоним</code>")
            return
        ok = await db.delete_rp_action_synonym(synonym)
        if not ok:
            await message.answer(f"Синоним «{html.escape(synonym)}» не найден.")
            return
        await refresh_rp_caches()
        await db.add_log("rp_action_synonym_deleted", actor_id=message.from_user.id, details=synonym)
        await message.answer(f"🗑 Синоним «{html.escape(synonym)}» удалён.")
        return

    await message.reply("Не понял подкоманду. Напишите просто «рп», чтобы увидеть список команд.")


