# Живой кэш себяшек — заполняется в load_caches() из db.list_self_actions().
SELF_ACTIONS: dict[str, list[str]] = dict(_SELF_ACTIONS_DEFAULT)


def _self_action_match(text: Optional[str]) -> Optional[str]:
    """Возвращает ключ действия, если текст — это «[действие» (без пробела
    между скобкой и словом, регистр не важен, хвостовой текст после слова
    игнорируется — «[пукнуть громко» тоже сработает)."""
    if not text:
        return None
    stripped = text.strip()
    if not stripped.startswith("["):
        return None
    first_word = stripped[1:].split(maxsplit=1)[0].casefold() if len(stripped) > 1 else ""
    return first_word if first_word in SELF_ACTIONS else None


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: _self_action_match(t) is not None),
)
async def handle_self_action(message: Message):
    action = _self_action_match(message.text)
    actor_name = await display_name(message.chat.id, message.from_user)
    phrase = random.choice(SELF_ACTIONS[action]).format(user=actor_name)
    await message.answer(phrase)


# ============================================================================
# «Бот Инфа»: шуточное определение вероятности чего-либо.
# Триггер — сообщение, начинающееся с «бот инфа » (регистр не важен).
# ============================================================================

@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().lower().startswith("бот инфа")),
)
async def cmd_bot_infa(message: Message):
    raw = message.text.strip()
    # Отрезаем префикс "бот инфа" (учитываем регистр исходного текста)
    phrase = raw[len("бот инфа"):].strip()

    if not phrase:
        await message.reply(
            "🤔 Напишите: <code>бот инфа {фраза}</code>\n"
            "Например: <code>бот инфа что сегодня будет дождь</code>"
        )
        return

    chance = random.randint(0, 101)
    await message.reply(f"🤔 Я думаю, что вероятность {phrase}  {chance} %")


