# ============================================================================
# Медленный режим — свой лимит частоты сообщений на человека (без встроенного
# Telegram slow mode, который нельзя настраивать по ролям). Настройка хранится
# в bot_data (как +чат/+рстик), последний момент сообщения — в памяти.
# ============================================================================
def _slowmode_key(chat_id: int) -> str:
    return f"slowmode:{chat_id}"


_slowmode_last_message: dict[tuple, float] = {}


async def get_slowmode_seconds(chat_id: int) -> int:
    row = await db.get_data(_slowmode_key(chat_id))
    if not row or not row.get("data_value"):
        return 0
    try:
        return int(row["data_value"])
    except (TypeError, ValueError):
        return 0


async def _enforce_slowmode(event: "Message") -> bool:
    """True — сообщение пришло слишком рано и было удалено (дальше не
    обрабатывать). Админы освобождены — им не нужно ограничение частоты."""
    if is_admin(event.from_user.id):
        return False
    seconds = await get_slowmode_seconds(event.chat.id)
    if seconds <= 0:
        return False
    key = (event.chat.id, event.from_user.id)
    now = time.monotonic()
    last = _slowmode_last_message.get(key)
    if last is not None and (now - last) < seconds:
        try:
            await event.delete()
        except (TelegramBadRequest, TelegramForbiddenError):
            return True
        return True
    _slowmode_last_message[key] = now
    return False


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().casefold().split() or [""])[0] == "+медленный"),
)
async def cmd_slowmode_on(message: Message):
    min_level = required_level("slowmode")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше.")
        return
    parts = message.text.strip().split(maxsplit=1)
    if len(parts) < 2:
        await message.reply("Укажите интервал, например: <code>+медленный 10с</code>")
        return
    duration = parse_duration(parts[1])
    if duration is None or duration.total_seconds() < 1:
        await message.reply("⚠️ Не понял интервал. Например: <code>+медленный 10с</code>, <code>+медленный 1м</code>")
        return
    seconds = min(int(duration.total_seconds()), 3600)  # предохранитель — не больше часа
    await db.set_data(_slowmode_key(message.chat.id), str(seconds), updated_by=message.from_user.id)
    await message.reply(
        f"🐌 Медленный режим включён: не чаще одного сообщения раз в "
        f"{format_duration_ru(timedelta(seconds=seconds))} на человека (админов не касается)."
    )
    await db.add_log("slowmode_on", chat_id=message.chat.id, actor_id=message.from_user.id, details=str(seconds))


