@router.message(
    F.text.func(lambda t: bool(t) and ru_text.yo(t.strip().casefold()) in ("+бесконечность", "-бесконечность")),
)
async def cmd_infinite_money_toggle(message: Message):
    if not is_owner(message.from_user.id):
        return  # молчание — не подтверждаем и не выдаём существование команды
    global INFINITE_MONEY_USERS
    enable = message.text.strip().casefold() == "+бесконечность"
    if enable:
        INFINITE_MONEY_USERS.add(message.from_user.id)
    else:
        INFINITE_MONEY_USERS.discard(message.from_user.id)
    await db.set_data("infinite_money_users", ",".join(str(u) for u in INFINITE_MONEY_USERS))
    await db.add_log("infinite_money_toggle", actor_id=message.from_user.id, details=str(enable))
    await message.reply(
        "♾️ Бесконечные деньги включены — ваши покупки больше не списывают i¢."
        if enable else
        "♾️ Бесконечные деньги выключены — траты снова списываются как обычно."
    )
# ----------------------------------------------------------------------------
# Владелец: заморозка счёта и конфискация i¢ — доступно ТОЛЬКО OWNER_IDS (.env),
# по тому же принципу, что и «+бесконечность» выше (молчание для всех остальных,
# существование команды не выдаётся). Заморозка хранится в bot_data
# (db.set_data/get_data/delete_data) под ключом frozen:{chat_id}:{user_id} —
# как и другие лёгкие тумблеры бота (+чат, +рстик и т.п.).
# ----------------------------------------------------------------------------
def _frozen_key(chat_id: int, user_id: int) -> str:
    return f"frozen:{chat_id}:{user_id}"


async def is_account_frozen(chat_id: int, user_id: int) -> bool:
    row = await db.get_data(_frozen_key(chat_id, user_id))
    return bool(row and row.get("data_value") == "1")


def _is_freeze_command(text: Optional[str]) -> bool:
    if not text:
        return False
    words = text.strip().casefold().split()
    return len(words) >= 2 and words[0] in ("заморозить", "разморозить") and words[1] in ("счет", "счёт")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_freeze_command),
)
async def cmd_freeze_account(message: Message):
    if not is_owner(message.from_user.id):
        return  # молчание — как и у +бесконечность, не выдаём существование команды

    target, _remaining = await resolve_command_target(message, trigger_words=2)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Укажите цель: ответьте этой командой на сообщение нужного человека, "
            "либо укажите @username или ID сразу после «заморозить счет»."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате."
        )
        return

    freeze = (message.text.strip().casefold().split() or [""])[0] == "заморозить"
    key = _frozen_key(message.chat.id, target.id)
    name = await display_name(message.chat.id, target)
    if freeze:
        await db.set_data(key, "1", updated_by=message.from_user.id)
        await message.reply(f"🧊 Счёт {name} заморожен — фарм, покупки и переводы недоступны.")
    else:
        await db.delete_data(key)
        await message.reply(f"✅ Счёт {name} разморожен.")
    await db.add_log(
        "account_freeze", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=str(freeze),
    )


def _is_confiscate_command(text: Optional[str]) -> bool:
    if not text:
        return False
    return (text.strip().casefold().split() or [""])[0] == "конфисковать"


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_confiscate_command),
)
async def cmd_confiscate(message: Message):
    if not is_owner(message.from_user.id):
        return

    target, remaining = await resolve_command_target(message, trigger_words=1, allow_bare_id=False)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Укажите цель: ответьте этой командой на сообщение нужного человека, "
            "либо укажите @username сразу после «конфисковать»."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате."
        )
        return

    wallet = await db.get_wallet(message.chat.id, target.id)
    balance = int(wallet.get("coins", 0))

    amount = find_amount(remaining)  # без суммы — забрать всё, поддерживает 1к/1м/3млрд
    if amount is None:
        amount = balance
    amount = max(0, min(amount, balance))

    if amount <= 0:
        await message.reply("У этого пользователя нечего конфисковывать (баланс 0 i¢).")
        return

    # take_coins_up_to не даст балансу уйти в минус, даже если человек
    # успел потратить монеты между чтением баланса выше и этой строкой.
    taken = await db.take_coins_up_to(message.chat.id, target.id, amount)
    name = await display_name(message.chat.id, target)
    left = await db.get_wallet(message.chat.id, target.id)
    await message.reply(
        f"👮 Конфисковано у {name}: <b>{taken}</b> i¢. Остаток: {left.get('coins', 0)} i¢."
    )
    await db.add_log(
        "account_confiscate", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=str(amount),
    )

@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split() or [""])[0].casefold() == "кик"),
)
async def cmd_kick(message: Message):
    """Исключает участника из группы без постоянного бана — он может зайти
    обратно по новой пригласительной ссылке. Как «кик» у Iris."""
    target, remaining = await _require_moderation_target(message, command_key="kick")
    if target is None:
        return

    parts = remaining.strip().split(maxsplit=1)[1:]
    reason = parts[0] if parts else None

    try:
        await bot.ban_chat_member(chat_id=message.chat.id, user_id=target.id)
        await bot.unban_chat_member(chat_id=message.chat.id, user_id=target.id, only_if_banned=True)
    except TelegramForbiddenError:
        await message.reply("⚠️ У бота недостаточно прав, чтобы исключать участников.")
        return
    except TelegramBadRequest as e:
        await message.reply(f"⚠️ Не удалось кикнуть: {e.message}")
        return

    actor_name = await display_name(message.chat.id, message.from_user)
    target_name = await display_name(message.chat.id, target)
    reason_text = html.escape(reason) if reason else "не указана"
    await message.reply(
        "👢 <b>Участник исключён</b>\n"
        f"{DIVIDER}\n"
        f"👤 Кто: {actor_name}\n"
        f"🎯 Кого: {target_name}\n"
        f"📝 Причина: {reason_text}"
    )
    await db.add_log(
        "kick", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=reason,
    )

RED_ROULETTE_NUMBERS = {1, 3, 5, 7, 9, 12, 14, 16, 18, 19, 21, 23, 25, 27, 30, 32, 34, 36}


# Ниже по файлу эта же функция объявлена второй раз — работала именно та копия,
# а эта была мёртвой (и ещё раз перечисляла те же числа локальной переменной).
# Удалена, чтобы правка «красных» чисел не уходила в никуда: менять надо
