# ============================================================================
# Русская рулетка: шуточная игра, 1 шанс из 6 — кик из чата (не бан, можно
# зайти обратно по новой ссылке). Перед первой игрой бот обязательно берёт
# явное согласие через инлайн-кнопки — оно запоминается один раз навсегда,
# дальше команда сразу крутит барабан. Доступно всем, без уровня доступа.
# ============================================================================
ROULETTE_TRIGGER = "русскаяру"
def _roulette_enabled_key(chat_id: int) -> str:
    return f"roulette_enabled:{chat_id}"


async def is_roulette_enabled(chat_id: int) -> bool:
    row = await db.get_data(_roulette_enabled_key(chat_id))
    if row is None:
        return True  # по умолчанию включена
    return row.get("data_value") != "0"
# «Рулетка {N}» — N прокруток барабана подряд одной командой (см. п.1 доработки).
# Без числа — обычная одиночная игра, как раньше. Верхний предел — чтобы
# командой с большим числом нельзя было заспамить чат простынёй строк.
ROULETTE_MAX_SPINS = 6
_ROULETTE_COMMAND_RE = ru_text.rx(r"^русскаяру(?:\s+(\d+))?$", re.IGNORECASE)


def _parse_roulette_count(text: Optional[str]) -> Optional[int]:
    """Разбирает «русскаяру» / «русскаяру {N}». Возвращает число прокруток
    (по умолчанию 1, если числа нет) или None, если это вообще не команда
    рулетки. Число зажимается в диапазон [1; ROULETTE_MAX_SPINS]."""
    if not text:
        return None
    match = _ROULETTE_COMMAND_RE.match(text.strip())
    if not match:
        return None
    raw = match.group(1)
    if raw is None:
        return 1
    count = int(raw)
    return max(1, min(count, ROULETTE_MAX_SPINS))


def _roulette_consent_key(user_id: int) -> str:
    return f"roulette_consent:{user_id}"


async def _has_roulette_consent(user_id: int) -> bool:
    row = await db.get_data(_roulette_consent_key(user_id))
    return bool(row and row.get("data_value"))


def roulette_consent_kb(user_id: int, count: int = 1) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(
        inline_keyboard=[[
            InlineKeyboardButton(text="🔫 Согласен, крутить", callback_data=f"roulette_consent:{user_id}:{count}"),
            InlineKeyboardButton(text="❌ Не буду", callback_data=f"roulette_cancel:{user_id}"),
        ]]
    )


async def _roulette_is_admin(chat_id: int, user_id: int) -> bool:
    try:
        member = await bot.get_chat_member(chat_id, user_id)
    except (TelegramForbiddenError, TelegramBadRequest):
        return False
    return member is not None and member.status in ("administrator", "creator")


async def _roulette_spin(chat_id: int, user_id: int) -> str:
    """Один прокрут барабана: 1 шанс из 6 — кик. Возвращает код исхода:
    'miss' — пусто, 'kick' — исключён, 'no_rights' — патрон был, но бот
    не смог кикнуть (не хватает прав)."""
    chamber = random.randint(1, 6)
    if chamber != 1:
        return "miss"
    try:
        await bot.ban_chat_member(chat_id=chat_id, user_id=user_id)
        await bot.unban_chat_member(chat_id=chat_id, user_id=user_id, only_if_banned=True)
    except (TelegramForbiddenError, TelegramBadRequest):
        return "no_rights"
    await db.add_log("roulette_kick", chat_id=chat_id, target_id=user_id)
    return "kick"


async def _play_roulette(chat_id: int, user) -> str:
    """Одиночная игра: крутит барабан один раз, возвращает готовый HTML-текст результата."""
    name = await display_name(chat_id, user)
    if await _roulette_is_admin(chat_id, user.id):
        return f"🔫 {name}, барабан крутится... 🚫 Рулетка не трогает админов чата — тут без исключений."

    outcome = await _roulette_spin(chat_id, user.id)
    if outcome == "kick":
        return (
            f"🔫 {name}, барабан провернулся...\n"
            "💥 <b>БАХ!</b> Не повезло — до встречи, зайти обратно можно по новой ссылке."
        )
    if outcome == "no_rights":
        return f"🔫 {name}, барабан провернулся... 💥 Патрон был, но бот не смог тебя исключить (не хватает прав)."
    return f"🔫 {name}, барабан провернулся...\n😮‍💨 <i>Щёлк.</i> Пусто — повезло, живём дальше."


_ROULETTE_OUTCOME_LINES = {
    "miss": "😮‍💨 <i>Щёлк.</i> Пусто.",
    "kick": "💥 <b>БАХ!</b> Не повезло — исключён(а) из чата.",
    "no_rights": "💥 Патрон был, но бот не смог исключить (не хватает прав).",
}


async def _play_roulette_multi(chat_id: int, user, count: int) -> str:
    """«Русскаяру {N}»: крутит барабан count раз подряд одной командой.
    Останавливается раньше, если участника кикнули по ходу серии — крутить
    для него дальше уже некому."""
    if count <= 1:
        return await _play_roulette(chat_id, user)

    name = await display_name(chat_id, user)
    if await _roulette_is_admin(chat_id, user.id):
        return f"🔫 {name}, барабан крутится... 🚫 Рулетка не трогает админов чата — тут без исключений."

    lines = [f"🔫 {name} крутит барабан {count} раз(а) подряд...", DIVIDER]
    spins_done = 0
    stopped_early = False
    for i in range(1, count + 1):
        outcome = await _roulette_spin(chat_id, user.id)
        lines.append(f"{i}. {_ROULETTE_OUTCOME_LINES[outcome]}")
        spins_done = i
        if outcome == "kick":
            stopped_early = True
            break

    lines.append("")
    if stopped_early:
        lines.append(f"Серия остановлена на {spins_done}-м прокруте — участник исключён из чата.")
    else:
        lines.append(f"🍀 Пережил(а) все {count} прокрутов подряд!")
    return "\n".join(lines)

@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and ru_text.yo(t.strip().casefold()) in ("+рулетка", "-рулетка")),
)
async def cmd_roulette_toggle(message: Message):
    min_level = required_level("roulette_toggle")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Включать/выключать русскаяру может «{level_name(min_level)}» и выше.")
        return
    enable = message.text.strip().casefold() == "+рулетка"
    if enable:
        await db.delete_data(_roulette_enabled_key(message.chat.id))
        await message.reply("🔫 Русскаяру снова доступна в этом чате.")
    else:
        await db.set_data(_roulette_enabled_key(message.chat.id), "0", updated_by=message.from_user.id)
        await message.reply("🚫 Русскаяру отключена в этом чате.")
    await db.add_log("roulette_toggle", chat_id=message.chat.id, actor_id=message.from_user.id, details=str(enable))



@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: _parse_roulette_count(t) is not None),
)
async def cmd_roulette(message: Message):
    user = message.from_user
    if user is None:
        return
    if not await is_roulette_enabled(message.chat.id):
        return  # отключена в этом чате — молчим, как выключенные РП-действия
    count = _parse_roulette_count(message.text) or 1

    if await _has_roulette_consent(user.id):
        result = await _play_roulette_multi(message.chat.id, user, count)
        await message.answer(result)
        return

    extra_line = f"Сейчас будет запущено <b>{count}</b> прокрутов подряд.\n" if count > 1 else ""
    await message.answer(
        "🔫 <b>Русскаяру</b>\n"
        f"{DIVIDER}\n"
        "Шанс вылететь из чата — <b>1 из 6</b> за каждый прокрут.\n"
        f"{extra_line}"
        "Это кик, не бан — сможешь зайти обратно по новой ссылке, но всё равно неприятно.\n\n"
        "Играешь на свой страх и риск. Соглашаешься, что с шансом 1/6 за прокрут бот тебя исключит из чата?",
        reply_markup=roulette_consent_kb(user.id, count),
    )


@router.callback_query(F.data.startswith("roulette_consent:"))
async def cb_roulette_consent(callback: CallbackQuery):
    parts = callback.data.split(":")
    owner_id = int(parts[1])
    count = int(parts[2]) if len(parts) > 2 else 1
    if callback.from_user.id != owner_id:
        await callback.answer("Это не твоя рулетка 🙂", show_alert=True)
        return

    await db.set_data(_roulette_consent_key(owner_id), "1", updated_by=owner_id)
    result = await _play_roulette_multi(callback.message.chat.id, callback.from_user, count)
    try:
        await callback.message.edit_text(result, reply_markup=None)
    except TelegramBadRequest:
        pass
    await callback.answer()


@router.callback_query(F.data.startswith("roulette_cancel:"))
async def cb_roulette_cancel(callback: CallbackQuery):
    owner_id = int(callback.data.split(":", 1)[1])
    if callback.from_user.id != owner_id:
        await callback.answer("Это не твоя рулетка 🙂", show_alert=True)
        return
    try:
        await callback.message.edit_text("Ладно, в другой раз 🙂", reply_markup=None)
    except TelegramBadRequest:
        pass
    await callback.answer()


# ============================================================================
# Модуль «Дуэли» (по образцу Iris) — пошаговый бой двух участников чата:
#   «дуэль {ссылка}» / ответом на смс   — вызвать на бой
#   «дуэль да» / «дуэль нет»            — принять / отклонить вызов (только цель)
#   «дуэль отмена»                      — отменить ещё не принятый вызов (только вызвавший)
#   «выстрел»                           — выстрелить (только тот, чей ход)
#   «прицелиться»                       — повысить шанс попадания следующего
#                                          выстрела ценой хода
#   «сбросить прицел»                   — сбросить накопленный бонус прицела
#                                          (не тратит ход)
# У каждого участника чата не может быть больше одной незавершённой дуэли
# одновременно (см. db.get_user_active_duel) — так исключается путаница,
# какая именно дуэль имеется в виду в командах без явного id.
# При проигрыше применяется настраиваемый исход (DUEL_OUTCOME, см. «дуэли
# исход ...» ниже) — как и у русской рулетки/rp-модуля, то же самое можно
# было бы продублировать триггерами, но здесь это встроенная настройка.
# ============================================================================

DUEL_AIM_STEP = 20          # на сколько процентных пунктов повышает шанс попадания одно «прицелиться»
DUEL_AIM_MAX = 40           # максимум накопленного бонуса (2 прицеливания)
DUEL_BASE_HIT_CHANCE = 50   # базовый шанс попадания выстрела без прицеливания, %

DUEL_OUTCOME_LABELS = {
    "0": "ничего не делать",
    "kick": "кик",
    "ban_minute": "бан на 1 минуту",
    "ban_10min": "бан на 10 минут",
    "ban_hour": "бан на 1 час",
    "ban_day": "бан на сутки",
    "ban_forever": "бан навсегда",
    "mute_minute": "мут на 1 минуту",
    "mute_10min": "мут на 10 минут",
    "mute_hour": "мут на 1 час",
    "mute_day": "мут на сутки",
    "mute_forever": "мут навсегда",
}
DUEL_OUTCOME_DURATIONS: dict[str, timedelta] = {
    "ban_minute": timedelta(minutes=1),
    "ban_10min": timedelta(minutes=10),
    "ban_hour": timedelta(hours=1),
    "ban_day": timedelta(days=1),
    # "ban_forever" — нет в словаре: until_date=None у ban_chat_member значит «навсегда».
    "mute_minute": timedelta(minutes=1),
    "mute_10min": timedelta(minutes=10),
    "mute_hour": timedelta(hours=1),
    "mute_day": timedelta(days=1),
    # "mute_forever" — аналогично ban_forever: until_date=None значит «навсегда».
}
DUEL_OUTCOME_WORDS = {
    "0": "0",
    "кик": "kick",
    "бан": "ban_forever",
    "бан минута": "ban_minute",
    "бан 10 минут": "ban_10min",
    "бан час": "ban_hour",
    "бан сутки": "ban_day",
    "бан навсегда": "ban_forever",
    "мут": "mute_forever",
    "мут минута": "mute_minute",
    "мут 10 минут": "mute_10min",
    "мут час": "mute_hour",
    "мут сутки": "mute_day",
    "мут навсегда": "mute_forever",
}

DUEL_RESERVED_WORDS = {"да", "нет", "отмена"}


def _duel_challenge_match(text: Optional[str]) -> bool:
    """«дуэль {ссылка}» / голая «дуэль» (ответом на смс) — но не «дуэль да/нет/отмена»,
    у них свои отдельные обработчики ниже."""
    if not text:
        return False
    words = text.strip().split()
    if not words or words[0].casefold() != "дуэль":
        return False
    if len(words) >= 2 and words[1].casefold() in DUEL_RESERVED_WORDS:
        return False
    return True


def _duel_access_denied(user_id: int) -> Optional[str]:
    if has_level(user_id, required_level("duel_play")):
        return None
    return f"⛔ Дуэли доступны только с уровня «{level_name(required_level('duel_play'))}» и выше."


def _duel_aim_text(aim: int) -> str:
    return f"🎯 +{aim}%" if aim else "без прицела"


async def _end_duel(chat_id: int, duel: dict, winner_id: int, loser_id: int) -> None:
    """Общая часть завершения дуэли: снимает запись из активных, записывает
    статистику и применяет исход к проигравшему."""
    await db.delete_duel(duel["id"])
    await db.record_duel_result(chat_id, winner_id, loser_id)
    winner_name = await display_name_by_id(chat_id, winner_id)
    loser_name = await display_name_by_id(chat_id, loser_id)
    outcome_text = await _apply_duel_outcome(chat_id, loser_id)
    await bot.send_message(
        chat_id,
        f"🏆 {winner_name} побеждает в дуэли! {loser_name} проигрывает.\n{outcome_text}",
    )
    await db.add_log("duel_finished", chat_id=chat_id, actor_id=winner_id, target_id=loser_id)
    await grant_achievement(chat_id, winner_id, "duel_win")
    wins = await db.get_duel_wins(chat_id, winner_id)
    if wins >= 10:
        await grant_achievement(chat_id, winner_id, "duel_master")


async def _apply_duel_outcome(chat_id: int, loser_id: int) -> str:
    """Применяет DUEL_OUTCOME к проигравшему. Возвращает готовую строку-описание
    результата для итогового сообщения о дуэли."""
    outcome = DUEL_OUTCOME
    if outcome == "0":
        return "Наказание за проигрыш отключено — соперник остаётся в чате."
    if outcome == "kick":
        try:
            await bot.ban_chat_member(chat_id=chat_id, user_id=loser_id)
            await bot.unban_chat_member(chat_id=chat_id, user_id=loser_id, only_if_banned=True)
            await db.add_log("duel_kick", chat_id=chat_id, target_id=loser_id)
            return "🚪 Проигравший исключён из чата (кик) — вернуться можно по новой ссылке."
        except (TelegramForbiddenError, TelegramBadRequest):
            return "⚠️ Проигравший должен был получить кик, но у бота не хватило прав."
    duration = DUEL_OUTCOME_DURATIONS.get(outcome)
    until = datetime.utcnow() + duration if duration else None

    if outcome.startswith("mute_"):
        try:
            await bot.restrict_chat_member(
                chat_id=chat_id, user_id=loser_id, permissions=MUTE_PERMISSIONS, until_date=until,
            )
            await db.add_mute(chat_id, loser_id, loser_id, until, "проигрыш в дуэли")
            await db.add_log("duel_mute", chat_id=chat_id, target_id=loser_id, details=outcome)
            return f"🔇 Проигравший замучен ({DUEL_OUTCOME_LABELS.get(outcome, outcome)})."
        except (TelegramForbiddenError, TelegramBadRequest):
            return "⚠️ Проигравший должен был получить мут, но у бота не хватило прав."

    try:
        await bot.ban_chat_member(chat_id=chat_id, user_id=loser_id, until_date=until)
        await db.add_ban(chat_id, loser_id, loser_id, "проигрыш в дуэли")
        await db.add_log("duel_ban", chat_id=chat_id, target_id=loser_id, details=outcome)
        return f"🔨 Проигравший забанен ({DUEL_OUTCOME_LABELS.get(outcome, outcome)})."
    except (TelegramForbiddenError, TelegramBadRequest):
        return "⚠️ Проигравший должен был получить бан, но у бота не хватило прав."


# --- Инлайн-кнопки дуэлей ---------------------------------------------------
# Дублируют текстовые команды («дуэль да/нет/отмена», «выстрел», «прицелиться»,
# «сбросить прицел») — текстовые команды по-прежнему работают, кнопки просто
# даёт более удобный способ сыграть, не печатая руками. Вся игровая логика
# вынесена в отдельные async-функции _duel_do_*, которые вызывают и текстовые
# хендлеры, и обработчики callback_query — код не дублируется.

def _duel_challenge_kb(duel_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(
        inline_keyboard=[
            [
                InlineKeyboardButton(text="✅ Принять", callback_data=f"duel_accept:{duel_id}"),
                InlineKeyboardButton(text="❌ Отклонить", callback_data=f"duel_decline:{duel_id}"),
            ],
            [InlineKeyboardButton(text="🚫 Отменить вызов", callback_data=f"duel_cancel:{duel_id}")],
        ]
    )


def _duel_battle_kb(duel_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(
        inline_keyboard=[
            [
                InlineKeyboardButton(text="🔫 Выстрел", callback_data=f"duel_shoot:{duel_id}"),
                InlineKeyboardButton(text="🎯 Прицелиться", callback_data=f"duel_aim:{duel_id}"),
            ],
            [InlineKeyboardButton(text="🔄 Сбросить прицел", callback_data=f"duel_resetaim:{duel_id}")],
        ]
    )


# Соглашение о возвращаемых значениях у всех _duel_do_*: None или "" — действие
# выполнено (или тихо проигнорировано), сообщение уже отправлено в чат;
# непустая строка — текст ошибки, который вызывающий хендлер должен показать
# пользователю сам (message.reply — для текстовой команды, callback.answer с
# show_alert=True — для кнопки).

async def _duel_do_accept(chat_id: int, user_id: int) -> Optional[str]:
    duel = await db.get_user_active_duel(chat_id, user_id)
    if duel is None or duel["status"] != "pending" or duel["target_id"] != user_id:
        return "У вас нет вызова на дуэль, который можно принять."
    first_turn = random.choice([duel["challenger_id"], duel["target_id"]])
    await db.activate_duel(duel["id"], first_turn)
    challenger_name = await display_name_by_id(chat_id, duel["challenger_id"])
    target_name = await display_name_by_id(chat_id, duel["target_id"])
    first_name = await display_name_by_id(chat_id, first_turn)
    await bot.send_message(
        chat_id,
        f"⚔️ Дуэль между {challenger_name} и {target_name} начинается!\n"
        f"🎲 Первый ход достаётся: {first_name}.\n\n"
        "Жмите кнопки ниже или пишите текстом: «выстрел», «прицелиться» "
        f"(+{DUEL_AIM_STEP}% к попаданию следующего выстрела, но тратит ход), "
        "«сбросить прицел» (не тратит ход).",
        reply_markup=_duel_battle_kb(duel["id"]),
    )
    return None


async def _duel_do_decline(chat_id: int, user_id: int) -> Optional[str]:
    duel = await db.get_user_active_duel(chat_id, user_id)
    if duel is None or duel["status"] != "pending" or duel["target_id"] != user_id:
        return "У вас нет вызова на дуэль, который можно отклонить."
    await db.delete_duel(duel["id"])
    target_name = await display_name_by_id(chat_id, duel["target_id"])
    await bot.send_message(chat_id, f"🚫 {target_name} отклонил(а) вызов на дуэль.")
    return None


async def _duel_do_cancel(chat_id: int, user_id: int) -> Optional[str]:
    duel = await db.get_user_active_duel(chat_id, user_id)
    if duel is None or duel["status"] != "pending" or duel["challenger_id"] != user_id:
        return "У вас нет ещё не принятого вызова, который можно отменить."
    await db.delete_duel(duel["id"])
    challenger_name = await display_name_by_id(chat_id, duel["challenger_id"])
    await bot.send_message(chat_id, f"❌ {challenger_name} отменил(а) вызов на дуэль.")
    return None


async def _duel_do_shoot(chat_id: int, user_id: int) -> Optional[str]:
    duel = await db.get_user_active_duel(chat_id, user_id)
    if duel is None or duel["status"] != "active":
        return ""  # тихо игнорируем — вне боя «выстрел» не относится к дуэлям
    if duel["turn_user_id"] != user_id:
        return "Сейчас не ваш ход."

    is_challenger = duel["challenger_id"] == user_id
    shooter_aim = duel["challenger_aim"] if is_challenger else duel["target_aim"]
    opponent_id = duel["target_id"] if is_challenger else duel["challenger_id"]

    hit_chance = min(DUEL_BASE_HIT_CHANCE + shooter_aim, 95)
    hit = random.randint(1, 100) <= hit_chance
    shooter_name = await display_name_by_id(chat_id, user_id)
    opponent_name = await display_name_by_id(chat_id, opponent_id)

    if hit:
        await bot.send_message(
            chat_id,
            f"🔫 {shooter_name} стреляет в {opponent_name}... 💥 <b>Попадание!</b> (шанс был {hit_chance}%)",
        )
        await _end_duel(chat_id, duel, winner_id=user_id, loser_id=opponent_id)
        return None

    # Промах: свой накопленный прицел сгорает, ход переходит к сопернику.
    if is_challenger:
        await db.set_duel_aim(duel["id"], 0, duel["target_aim"])
    else:
        await db.set_duel_aim(duel["id"], duel["challenger_aim"], 0)
    await db.set_duel_turn(duel["id"], opponent_id)
    await bot.send_message(
        chat_id,
        f"🔫 {shooter_name} стреляет в {opponent_name}... 😮‍💨 <i>Мимо!</i> (шанс был {hit_chance}%)\n"
        f"Ход переходит к {opponent_name}.",
        reply_markup=_duel_battle_kb(duel["id"]),
    )
    return None


async def _duel_do_aim(chat_id: int, user_id: int) -> Optional[str]:
    duel = await db.get_user_active_duel(chat_id, user_id)
    if duel is None or duel["status"] != "active":
        return ""
    if duel["turn_user_id"] != user_id:
        return "Сейчас не ваш ход."

    is_challenger = duel["challenger_id"] == user_id
    current_aim = duel["challenger_aim"] if is_challenger else duel["target_aim"]
    new_aim = min(current_aim + DUEL_AIM_STEP, DUEL_AIM_MAX)
    opponent_id = duel["target_id"] if is_challenger else duel["challenger_id"]

    if is_challenger:
        await db.set_duel_aim(duel["id"], new_aim, duel["target_aim"])
    else:
        await db.set_duel_aim(duel["id"], duel["challenger_aim"], new_aim)
    await db.set_duel_turn(duel["id"], opponent_id)

    shooter_name = await display_name_by_id(chat_id, user_id)
    opponent_name = await display_name_by_id(chat_id, opponent_id)
    await bot.send_message(
        chat_id,
        f"🎯 {shooter_name} прицеливается — бонус к следующему выстрелу {_duel_aim_text(new_aim)}.\n"
        f"Ход переходит к {opponent_name}.",
        reply_markup=_duel_battle_kb(duel["id"]),
    )
    return None


async def _duel_do_reset_aim(chat_id: int, user_id: int) -> Optional[str]:
    duel = await db.get_user_active_duel(chat_id, user_id)
    if duel is None or duel["status"] != "active":
        return ""
    is_challenger = duel["challenger_id"] == user_id
    if is_challenger:
        await db.set_duel_aim(duel["id"], 0, duel["target_aim"])
    else:
        await db.set_duel_aim(duel["id"], duel["challenger_aim"], 0)
    shooter_name = await display_name_by_id(chat_id, user_id)
    await bot.send_message(
        chat_id,
        f"🔄 {shooter_name} сбрасывает накопленный прицел. Ход при этом не тратится.",
        reply_markup=_duel_battle_kb(duel["id"]),
    )
    return None


async def _duel_try_remove_markup(callback: CallbackQuery) -> None:
    """Убирает кнопки со старого сообщения после клика, чтобы им нельзя было
    воспользоваться повторно (актуальная клавиатура уже в новом сообщении,
    которое отправила _duel_do_*)."""
    try:
        await callback.message.edit_reply_markup(reply_markup=None)
    except TelegramBadRequest:
        pass


@router.message(F.chat.type.in_({"group", "supergroup"}), F.text.func(_duel_challenge_match))
async def cmd_duel_challenge(message: Message):
    denied = _duel_access_denied(message.from_user.id)
    if denied:
        await message.reply(denied)
        return

    challenger = message.from_user
    target, _remaining = await resolve_command_target(message, trigger_words=1)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Ответьте этой командой на сообщение соперника, либо укажите @username/ID сразу после «дуэль»."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате."
        )
        return
    if target.id == challenger.id:
        await message.reply("С самим собой дуэль не сыграть 🙂")
        return
    if getattr(target, "is_bot", False):
        await message.reply("Ботов на дуэль не вызывают 🤖")
        return

    if await db.get_user_active_duel(message.chat.id, challenger.id):
        await message.reply("У вас уже есть незавершённая дуэль в этом чате — сначала разберитесь с ней.")
        return
    if await db.get_user_active_duel(message.chat.id, target.id):
        await message.reply("Этот участник уже занят другой дуэлью.")
        return

    duel_id = await db.create_duel(message.chat.id, challenger.id, target.id)
    challenger_name = await display_name(message.chat.id, challenger)
    target_name = await display_name_by_id(message.chat.id, target.id)
    await message.answer(
        f"⚔️ {challenger_name} вызывает {target_name} на дуэль!\n"
        f"{target_name}, жмите «✅ Принять» / «❌ Отклонить» или пишите «дуэль да» / «дуэль нет».\n"
        f"Отменить ещё не принятый вызов может {challenger_name} — кнопкой «🚫 Отменить вызов» "
        "или командой «дуэль отмена».",
        reply_markup=_duel_challenge_kb(duel_id),
    )


