@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold().startswith("дуэли исход")),
)
async def cmd_duel_outcome_set(message: Message):
    if not has_level(message.from_user.id, required_level("duel_outcome")):
        await message.reply(f"⛔ Настраивать исход дуэлей может «{level_name(required_level('duel_outcome'))}» и выше.")
        return
    raw = message.text.strip()[len("дуэли исход"):].strip().casefold()
    code = DUEL_OUTCOME_WORDS.get(raw)
    if code is None:
        await message.reply(
            "Неизвестный исход. Доступные варианты:\n"
            "<code>дуэли исход 0</code> (ничего не делать)\n"
            "<code>дуэли исход кик</code>\n"
            "<code>дуэли исход бан минута</code>\n"
            "<code>дуэли исход бан 10 минут</code>\n"
            "<code>дуэли исход бан час</code>\n"
            "<code>дуэли исход бан сутки</code>\n"
            "<code>дуэли исход бан навсегда</code>\n"
            "<code>дуэли исход мут минута</code>\n"
            "<code>дуэли исход мут 10 минут</code>\n"
            "<code>дуэли исход мут час</code>\n"
            "<code>дуэли исход мут сутки</code>\n"
            "<code>дуэли исход мут навсегда</code>"
        )
        return
    global DUEL_OUTCOME
    DUEL_OUTCOME = code
    await db.save_setting("duel_outcome", code)
    await db.add_log("duel_outcome_changed", actor_id=message.from_user.id, details=code)
    await message.answer(f"✅ Исход проигрыша в дуэли: «{DUEL_OUTCOME_LABELS[code]}».")


