# ============================================================================
# Модуль «Фото-команды» (.сдб, .цитата) и «Озвучка» (.скажи) — по образцу
# команд из https://teletype.in/@celestiana/photo-commands и
# https://teletype.in/@celestiana/misc-commands. Картинки рисуются на лету
# через Pillow (без внешних шаблонов/API), озвучка — через gTTS + ffmpeg.
# ============================================================================


async def _fetch_avatar_bytes(user_id: int) -> Optional[bytes]:
    """Скачивает текущее фото профиля пользователя (самое крупное доступное).
    None, если фото нет или Telegram не отдал (приватность/бот и т.п.) —
    вызывающий код рисует заглушку вместо реального аватара."""
    try:
        photos = await bot.get_user_profile_photos(user_id, limit=1)
        if not photos.photos:
            return None
        file_id = photos.photos[0][-1].file_id
        buf = BytesIO()
        await bot.download(file_id, destination=buf)
        buf.seek(0)
        return buf.read()
    except Exception:
        return None


def _load_font(size: int, bold: bool = False, italic: bool = False) -> ImageFont.FreeTypeFont:
    """Ищет DejaVu Sans (кириллица «из коробки» почти на любом Linux-сервере
    с установленным пакетом fonts-dejavu-core — часто уже стоит как
    зависимость matplotlib/Pillow). Если не нашли — падаем на растровый
    шрифт Pillow по умолчанию (без кириллицы, но хотя бы не падаем)."""
    if italic and bold:
        names = ["DejaVuSans-BoldOblique.ttf"]
    elif italic:
        names = ["DejaVuSans-Oblique.ttf"]
    elif bold:
        names = ["DejaVuSans-Bold.ttf"]
    else:
        names = ["DejaVuSans.ttf"]
    dirs = ["/usr/share/fonts/truetype/dejavu/", "/usr/share/fonts/truetype/liberation/", ""]
    for d in dirs:
        for name in names:
            try:
                return ImageFont.truetype(d + name, size)
            except Exception:
                continue
    return ImageFont.load_default()


def _circular_avatar(data: Optional[bytes], size: int) -> Image.Image:
    """Аватар, вписанный в круг размером size×size (RGBA с альфа-маской).
    Если данных нет/не открылись — рисует нейтральную серую заглушку."""
    im = None
    if data:
        try:
            im = ImageOps.fit(Image.open(BytesIO(data)).convert("RGB"), (size, size), Image.LANCZOS)
        except Exception:
            im = None
    if im is None:
        im = Image.new("RGB", (size, size), (100, 100, 112))
        d = ImageDraw.Draw(im)
        d.ellipse([size * 0.28, size * 0.16, size * 0.72, size * 0.58], fill=(160, 160, 172))
        d.ellipse([size * 0.08, size * 0.60, size * 0.92, size * 1.25], fill=(160, 160, 172))
    mask = Image.new("L", (size, size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, size, size), fill=255)
    out = Image.new("RGBA", (size, size))
    out.paste(im, (0, 0), mask)
    return out


async def _plain_target_name(chat_id: int, target: SimpleNamespace) -> str:
    """Имя цели БЕЗ HTML-разметки — для рисования текста на изображении
    (в отличие от display_name_by_id, который всегда возвращает <a> ссылку)."""
    nickname = await db.get_nickname(chat_id, target.id) if target.id else None
    if nickname:
        return nickname
    if getattr(target, "full_name", None):
        return target.full_name
    if getattr(target, "username", None):
        return f"@{target.username}"
    return str(target.id) if target.id else "Неизвестный"


