# ---- .скажи — озвучка текста голосовым сообщением (TTS) --------------------
# В отличие от «!скажи» (бот просто повторяет текст своим сообщением), это
# «.скажи» из документации Celestiana — генерирует настоящее голосовое
# сообщение. Нужны gTTS (pip install gTTS) и системный ffmpeg с поддержкой
# libopus (конвертация mp3 -> ogg/opus, формат голосовых Telegram).
TTS_MAX_LEN = 500


async def _tts_to_ogg_opus(text: str) -> bytes:
    mp3_buf = BytesIO()
    await asyncio.to_thread(lambda: gTTS(text=text, lang="ru").write_to_fp(mp3_buf))
    mp3_bytes = mp3_buf.getvalue()
    proc = await asyncio.create_subprocess_exec(
        "ffmpeg", "-y", "-i", "pipe:0", "-c:a", "libopus", "-b:a", "64k", "-f", "ogg", "pipe:1",
        stdin=asyncio.subprocess.PIPE, stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,
    )
    out, err = await proc.communicate(input=mp3_bytes)
    if proc.returncode != 0:
        raise RuntimeError(err.decode(errors="ignore")[:500])
    return out


@router.message(
    F.chat.type.in_({"group", "supergroup", "private"}),
    F.text.func(lambda t: bool(t) and (t.strip().casefold().split() or [""])[0] == ".скажи"),
)
async def cmd_tts_say(message: Message):
    if not _check_misc_access(message.from_user.id, "tts_say"):
        return
    if not _GTTS_AVAILABLE:
        await message.reply("⚠️ Озвучка недоступна: на сервере не установлен пакет <code>gTTS</code> (<code>pip install gTTS</code>).")
        return
    parts = message.text.strip().split(maxsplit=1)
    text = parts[1].strip() if len(parts) > 1 else ""
    if not text:
        await message.reply("Использование: <code>.скажи {текст}</code> (до 500 символов).")
        return
    if len(text) > TTS_MAX_LEN:
        await message.reply(f"Слишком длинный текст — максимум {TTS_MAX_LEN} символов (у вас {len(text)}).")
        return
    try:
        ogg_bytes = await asyncio.wait_for(_tts_to_ogg_opus(text), timeout=30)
    except Exception:
        logger.exception("Не удалось озвучить текст")
        await message.reply(
            "Не получилось озвучить текст — проверьте, что на сервере установлены "
            "<code>gTTS</code> и <code>ffmpeg</code> (с поддержкой libopus)."
        )
        return
    await message.answer_voice(BufferedInputFile(ogg_bytes, filename="tts.ogg"))


def _parse_bang_cmd(text: str, bang: str, word: str) -> Optional[str]:
    """Аргумент команды, вызванной как «{bang} {arg}» (напр. «!выбери …») или
    разговорно «бот {word} {arg}» (напр. «бот выбери …»). Пустая строка — команда
    без аргумента (покажем подсказку); None — это вообще не эта команда."""
    parts = text.strip().split()
    if not parts:
        return None
    first = parts[0].casefold()
    if first == bang:
        return text.strip().split(maxsplit=1)[1] if len(parts) > 1 else ""
    if first == "бот" and len(parts) >= 2 and parts[1].casefold() == word:
        return text.strip().split(maxsplit=2)[2] if len(parts) > 2 else ""
    return None


@router.message(
    F.chat.type.in_({"group", "supergroup", "private"}),
    F.text.func(lambda t: bool(t) and _parse_bang_cmd(t, "!выбери", "выбери") is not None),
)
async def cmd_misc_choose(message: Message):
    if not _check_misc_access(message.from_user.id, "misc_choose"):
        return
    rest_text = _parse_bang_cmd(message.text, "!выбери", "выбери") or ""
    parts = re.split(r"\s+или\s+", rest_text, maxsplit=1, flags=re.IGNORECASE)
    parts = [p.strip() for p in parts if p.strip()]
    if len(parts) != 2:
        await message.reply("Использование: <code>!выбери {первое} или {второе}</code> или <code>бот выбери …</code>\nНапример: <code>бот выбери чай или кофе</code>")
        return
    choice = random.choice(parts)
    await message.answer(f"🤔 Выбираю: <b>{html.escape(choice)}</b>")


_YESNO_YES = (
    "По моим данным — «да»",
    "Мой ответ — «да»",
    "Однозначно — «да»",
    "Даже не сомневайся — «да»",
    "Всё указывает на «да»",
    "Тут без вариантов — «да»",
    "Звёзды сошлись — «да»",
    "Шар не врёт — «да»",
    "Спойлер: «да»",
    "Отвечу прямо — «да»",
    "Так и запишем — «да»",
    "Расклад такой — «да»",
)

_YESNO_NO = (
    "По моим данным — «нет»",
    "Мой ответ — «нет»",
    "Однозначно — «нет»",
    "Даже не надейся — «нет»",
    "Всё указывает на «нет»",
    "Тут без вариантов — «нет»",
    "Звёзды против — «нет»",
    "Шар не врёт — «нет»",
    "Спойлер: «нет»",
    "Отвечу прямо — «нет»",
    "Так и запишем — «нет»",
    "Расклад такой — «нет»",
)

# Уклончивые ответы выпадают заметно реже: они забавные, но если попадаются
# часто, команда перестаёт быть полезной.
_YESNO_MAYBE = (
    "Тут даже я в замешательстве",
    "Шар помутнел — спроси попозже",
    "Затрудняюсь ответить",
    "Не рискну предполагать",
    "Спроси ещё раз, но с чувством",
    "Данные противоречивы, увы",
)

# Триггеры: «!данет {вопрос}» и разговорные «бот данет …» / «бот да нет …».
YESNO_CMD_RE = ru_text.rx(r"^(?:!?данет|бот\s+данет|бот\s+да\s+нет)\b\s*(.*)$", re.IGNORECASE | re.DOTALL)


def _yesno_answer() -> str:
    roll = random.random()
    if roll < 0.45:
        pool = _YESNO_YES
    elif roll < 0.90:
        pool = _YESNO_NO
    else:
        pool = _YESNO_MAYBE
    return random.choice(pool)


@router.message(
    F.chat.type.in_({"group", "supergroup", "private"}),
    F.text.func(lambda t: bool(t) and bool(YESNO_CMD_RE.match(t.strip()))),
)
async def cmd_misc_yesno(message: Message):
    if not _check_misc_access(message.from_user.id, "misc_yesno"):
        return
    match = YESNO_CMD_RE.match(message.text.strip())
    question = (match.group(1) or "").strip() if match else ""
    if not question:
        await message.reply(
            "Использование: <code>!данет {вопрос}</code> или <code>бот да нет {вопрос}</code>\n"
            "Например: <code>бот да нет будет ли завтра дождь</code>"
        )
        return
    who = await display_name_by_id(message.chat.id, message.from_user.id)
    await message.answer(f"🎱 {who} {_yesno_answer()}")


def _extract_draw_candidates(message: Message) -> list[str]:
    """Собирает список кандидатов для «!жребий»: сначала все mention/text_mention
    из текста (кликабельные ссылки на людей), если их нет — делит остаток
    текста после команды по запятым (или по пробелу, если запятых нет)."""
    text = message.text or ""
    candidates: list[str] = []
    for entity in message.entities or []:
        if entity.type == "text_mention" and entity.user is not None:
            u = entity.user
            candidates.append(mention_id(u.id, full_name=u.full_name, username=u.username))
        elif entity.type == "mention":
            username = text[entity.offset + 1: entity.offset + entity.length]
            candidates.append(f"@{html.escape(username)}")
    if candidates:
        return candidates

    rest_text = _parse_bang_cmd(text, "!жребий", "жребий") or ""
    if not rest_text.strip():
        return []
    if "," in rest_text:
        raw_items = rest_text.split(",")
    else:
        raw_items = rest_text.split()
    return [html.escape(item.strip()) for item in raw_items if item.strip()]


@router.message(
    F.chat.type.in_({"group", "supergroup", "private"}),
    F.text.func(lambda t: bool(t) and _parse_bang_cmd(t, "!жребий", "жребий") is not None),
)
async def cmd_misc_draw(message: Message):
    if not _check_misc_access(message.from_user.id, "misc_draw"):
        return
    candidates = _extract_draw_candidates(message)
    if len(candidates) < 2:
        await message.reply(
            "Использование: <code>!жребий {ссылки}</code> или <code>бот жребий …</code>\n"
            "Укажите минимум двух участников — по @username, ответом/пересылкой (несколько "
            "text_mention), или просто именами через запятую.\n"
            "Например: <code>бот жребий Аня, Вася, Оля</code>"
        )
        return
    winner = random.choice(candidates)
    await message.answer(f"🎟 Жребий пал на: {winner}!")


async def _random_known_user(chat_id: int) -> Optional[dict]:
    """Возвращает случайного известного боту участника чата, либо None, если
    таких пока нет (никто не писал/не вступал при боте)."""
    _rows, total = await db.list_known_users(chat_id, limit=1)
    if not total:
        return None
    offset = random.randint(0, total - 1)
    rows, _total = await db.list_known_users(chat_id, limit=1, offset=offset)
    return rows[0] if rows else None


# Вступления для «!кто {текст}» / «бот кто {текст}» — случайная фраза в стиле
# чат-менеджеров: {who} = упоминание случайного участника, {q} = текст вопроса.
_WHO_TEMPLATES = [
    "🤔 Я думаю, что {who} {q}",
    "🔮 Ясно вижу, что {who} {q}",
    "✨ Мне кажется, что {who} {q}",
    "🎯 Совершенно точно, что {who} {q}",
    "😏 Ни для кого не секрет, что {who} {q}",
    "🧙 Магический шар говорит, что {who} {q}",
    "📢 Официально заявляю: {who} {q}",
    "🕵️ Расследование показало, что {who} {q}",
    "💫 Звёзды сошлись — {who} {q}",
    "🎲 Жребий брошен: {who} {q}",
]


def _parse_who_topic(text: str) -> Optional[str]:
    """Тема вопроса для «!кто {текст}» и «бот кто {текст}»."""
    return _parse_bang_cmd(text, "!кто", "кто")


