# ============================================================================
# Модуль «Шипперинг» — шуточная «совместимость» пары (по образцу Iris),
# хранится в ship_pairs (db.py) для топов «пейринг»/«общий пейринг». Уровень
# доступа каждой команды переопределяется как обычно через «право»/«дк»
# (ключи ship_* в COMMAND_REGISTRY).
# ============================================================================
def _ship_first_name(target: SimpleNamespace) -> str:
    full_name = getattr(target, "full_name", None)
    if full_name:
        return full_name.split()[0]
    username = getattr(target, "username", None)
    if username:
        return username
    return str(target.id)


def _ship_couple_name(name_a: str, name_b: str) -> str:
    """Портманто из двух имён (первая половина первого + вторая половина
    второго) — как «Ирис» лепит имена пар."""
    a, b = name_a.strip(), name_b.strip()
    if not a or not b:
        return (a or b).capitalize()
    cut_a = max(1, (len(a) + 1) // 2)
    cut_b = max(1, len(b) // 2)
    combined = a[:cut_a] + b[len(b) - cut_b:]
    return combined.capitalize()


def _ship_percent_bar(percent: int) -> str:
    filled = round(percent / 10)
    return "❤️" * filled + "🤍" * (10 - filled)


def _ship_comment(percent: int) -> str:
    if percent >= 90:
        return "🔥 Родственные души!"
    if percent >= 70:
        return "😍 Отличная пара!"
    if percent >= 50:
        return "🙂 Неплохо, есть шанс!"
    if percent >= 25:
        return "😐 Так себе совместимость..."
    return "💔 Лучше остаться друзьями."


async def _random_ship_pair(chat_id: int) -> Optional[tuple[SimpleNamespace, SimpleNamespace]]:
    """Случайная пара известных боту участников чата, ни один из которых не
    отказался от шипперинга (см. -шип меня). None, если некого шипперить."""
    _rows, total = await db.list_known_users(chat_id, limit=1)
    if total < 2:
        return None
    opted_out = await db.list_ship_opt_out_ids()
    sample_size = min(total, 100)
    offset = random.randint(0, max(0, total - sample_size))
    rows, _total = await db.list_known_users(chat_id, limit=sample_size, offset=offset)
    eligible = [r for r in rows if r["user_id"] not in opted_out]
    if len(eligible) < 2:
        return None
    a, b = random.sample(eligible, 2)
    return (
        SimpleNamespace(id=a["user_id"], full_name=a.get("full_name"), username=a.get("username"), is_bot=False),
        SimpleNamespace(id=b["user_id"], full_name=b.get("full_name"), username=b.get("username"), is_bot=False),
    )


async def _resolve_ship_candidates(message: Message) -> list[SimpleNamespace]:
    """Собирает кандидатов для «шипперим {ссылка 1} {ссылка 2}»: сначала
    reply (если есть), затем все mention/text_mention из текста, и в
    последнюю очередь — голые числовые ID словами после команды. Дубликаты
    (один и тот же человек указан дважды) схлопываются."""
    candidates: list[SimpleNamespace] = []
    if message.reply_to_message and message.reply_to_message.from_user:
        u = message.reply_to_message.from_user
        candidates.append(SimpleNamespace(id=u.id, full_name=u.full_name, username=u.username, is_bot=u.is_bot))

    text = message.text or ""
    for entity in message.entities or []:
        if entity.type == "text_mention" and entity.user is not None:
            u = entity.user
            candidates.append(SimpleNamespace(id=u.id, full_name=u.full_name, username=u.username, is_bot=u.is_bot))
        elif entity.type == "mention":
            username = text[entity.offset + 1: entity.offset + entity.length]
            known = await db.get_known_user_by_username_in_chat(message.chat.id, username)
            if known:
                candidates.append(SimpleNamespace(
                    id=known["user_id"], full_name=known.get("full_name"),
                    username=known.get("username") or username, is_bot=False,
                ))
            else:
                candidates.append(SimpleNamespace(id=None, full_name=None, username=username, is_bot=None))

    if len(candidates) < 2:
        rest = text.strip().split(maxsplit=1)
        rest_text = rest[1] if len(rest) > 1 else ""
        for token in rest_text.split():
            if token.isdigit():
                candidates.append(SimpleNamespace(id=int(token), full_name=None, username=None, is_bot=None))

    seen: set = set()
    unique: list[SimpleNamespace] = []
    for c in candidates:
        key = c.id if c.id is not None else f"@{(c.username or '').casefold()}"
        if key in seen:
            continue
        seen.add(key)
        unique.append(c)
    return unique


async def _send_ship_result(message: Message, target_a: SimpleNamespace, target_b: SimpleNamespace) -> None:
    opted_out = await db.list_ship_opt_out_ids()
    blocked = None
    if target_a.id in opted_out:
        blocked = target_a
    elif target_b.id in opted_out:
        blocked = target_b
    if blocked is not None:
        name = mention_id(blocked.id, full_name=getattr(blocked, "full_name", None), username=getattr(blocked, "username", None))
        await message.reply(f"🚫 {name} запретил(а) себя шипперить (см. «-шип меня»).")
        return

    percent = random.randint(0, 100)
    await db.add_ship(message.chat.id, target_a.id, target_b.id, message.from_user.id, percent)
    ship_count = await db.count_ships_by_author(message.chat.id, message.from_user.id)
    if ship_count >= 50:
        await grant_achievement(message.chat.id, message.from_user.id, "matchmaker_50")
    name_a = mention_id(target_a.id, full_name=getattr(target_a, "full_name", None), username=getattr(target_a, "username", None))
    name_b = mention_id(target_b.id, full_name=getattr(target_b, "full_name", None), username=getattr(target_b, "username", None))
    couple_name = _ship_couple_name(_ship_first_name(target_a), _ship_first_name(target_b))
    await message.answer(
        f"💘 <b>{html.escape(couple_name)}</b>\n"
        f"{name_a} + {name_b}\n"
        f"{_ship_percent_bar(percent)} <b>{percent}%</b>\n"
        f"{_ship_comment(percent)}"
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().casefold().split() or [""])[0] == "шипперим"),
)
async def cmd_ship(message: Message):
    text = message.text.strip()
    has_extra = len(text.split(maxsplit=1)) > 1 or bool(message.reply_to_message)

    if not has_extra:
        if not _check_misc_access(message.from_user.id, "ship_random"):
            return
        pair = await _random_ship_pair(message.chat.id)
        if pair is None:
            await message.reply("🤷 Пока некого шипперить — бот знает меньше двух участников чата (или все отказались).")
            return
        await _send_ship_result(message, *pair)
        return

    if not _check_misc_access(message.from_user.id, "ship_target"):
        return
    candidates = await _resolve_ship_candidates(message)
    if len(candidates) < 2:
        await message.reply(
            "Использование: <code>шипперим {ссылка 1} {ссылка 2}</code>\n"
            "Укажите обоих: ответом на сообщение одного + @username/ID второго сразу после "
            "команды, либо два @username/ID подряд.\n"
            "Без цели — просто <code>шипперим</code> — берёт двух случайных участников."
        )
        return
    target_a, target_b = candidates[0], candidates[1]
    if target_a.id is None or target_b.id is None:
        unknown = target_a if target_a.id is None else target_b
        await message.reply(f"🔍 Не удалось найти @{html.escape(unknown.username or '')} — бот его ещё не видел в этом чате.")
        return
    if target_a.id == target_b.id:
        await message.reply("Нужно указать двух разных людей 🙂")
        return
    if target_a.is_bot or target_b.is_bot:
        await message.reply("Ботов это не касается 🤖")
        return
    await _send_ship_result(message, target_a, target_b)


