# --- Поломки и срочные предложения ------------------------------------------
# Цикл раз в BUSINESS_TICK заглядывает во все бизнесы всех чатов и с небольшой
# вероятностью ломает один или подкидывает владельцу выгодное предложение.
#
# Вероятность за тик выводится из желаемого срока, а не подбирается на глаз:
# при тике в 20 минут и цели «в среднем раз в 2.5 суток» это
#   20 мин / (2.5 * 24 * 60 мин) = 0.0056.
# Меняете тик — вероятности пересчитаются сами, и частота поломок не поедет.
BUSINESS_TICK = timedelta(minutes=20)
BUSINESS_BREAK_EVERY = timedelta(days=2.5)
BUSINESS_OFFER_EVERY = timedelta(days=1.5)
BUSINESS_BREAK_CHANCE = BUSINESS_TICK / BUSINESS_BREAK_EVERY
BUSINESS_OFFER_CHANCE = BUSINESS_TICK / BUSINESS_OFFER_EVERY
# Сколько живёт срочное предложение, пока владелец не нажал кнопку.
BUSINESS_URGENT_TTL = timedelta(hours=2)

_business_urgent: dict[tuple[int, int], dict] = {}   # (chat_id, message_id) -> предложение


def _business_repair_kb(cost: int, closed: bool = False) -> InlineKeyboardMarkup:
    text = "Починено" if closed else f"🔧 Починить за {cost} i¢"
    return InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text=text, callback_data="business_repair")
    ]])


def _business_urgent_kb(cost: int, closed: bool = False) -> InlineKeyboardMarkup:
    text = "Предложение закрыто" if closed else f"💡 Вложить {cost} i¢"
    return InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text=text, callback_data="business_urgent")
    ]])


async def _dm_or_none(user_id: int, text: str, keyboard=None):
    """Пишет в личку. None — не дошло (лс закрыты, бот заблокирован).

    Повторять такую отправку бессмысленно, поэтому вызывающий просто
    продолжает работу: состояние поломки всё равно видно по команде «бизнес».
    """
    try:
        return await bot.send_message(user_id, text, reply_markup=keyboard)
    except (TelegramForbiddenError, TelegramBadRequest):
        return None
    except Exception as exc:
        log_suppressed("_dm_or_none", exc)
        return None


async def _break_business(chat_id: int, row: dict) -> None:
    """Ломает один бизнес и, если получится, пишет владельцу в личку."""
    item = business_catalog.BY_KEY.get(row["business_key"])
    if item is None:
        return
    level = int(row["level"])
    user_id = int(row["user_id"])
    # Страховка гасит ровно одну поломку и тратится. Проверяем ДО того, как
    # что-то менять: иначе застрахованный бизнес успел бы сломаться, а заряд
    # сгорел бы вхолостую.
    if await db.consume_item_effect(chat_id, user_id, shop_effects.EFFECT_SHIELD):
        await db.add_log("business_shielded", chat_id=chat_id, actor_id=user_id,
                         details=item.key)
        await _dm_or_none(
            user_id,
            f"🛡 В {item.name} случилась было авария — но сработала страховка. "
            f"Бизнес работает как ни в чём не бывало, страховка потрачена."
        )
        return

    kind = random.choice(business_catalog.BREAKDOWNS.get(item.key, ("поломка",)))
    pending = _business_pending(row)
    if not await db.set_business_broken(chat_id, user_id, item.key, kind,
                                        pending, datetime.utcnow()):
        return                      # уже сломан — второй раз не ломаем
    cost = business_catalog.repair_cost(item, level)
    await db.add_log("business_broken", chat_id=chat_id, actor_id=user_id,
                     details=f"{item.key}:{kind}:{cost}")

    sent = await _dm_or_none(
        user_id,
        f"🛠 <b>ЧП в вашем бизнесе</b>\n{DIVIDER}\n"
        f"{item.name} — <b>{kind}</b>.\n\n"
        f"Пока не почините, бизнес <b>не приносит доход</b>. "
        f"Уже накопленные {pending} i¢ никуда не денутся — их можно забрать "
        f"как обычно.\n\n"
        f"Ремонт: <b>{cost}</b> i¢.\n"
        f"Починить можно и в чате: <code>бизнес починить {item.key}</code>",
        _business_repair_kb(cost),
    )
    if sent is not None:
        _business_urgent[(sent.chat.id, sent.message_id)] = {
            "kind": "repair", "chat_id": chat_id, "user_id": user_id,
            "key": item.key, "cost": cost,
        }


async def _offer_business_upgrade(chat_id: int, row: dict) -> None:
    """Подкидывает владельцу срочное предложение — вложиться и поднять доход."""
    item = business_catalog.BY_KEY.get(row["business_key"])
    if item is None:
        return
    level = int(row["level"])
    user_id = int(row["user_id"])
    what = random.choice(business_catalog.OFFERS.get(item.key, ("вложиться",)))
    cost = business_catalog.offer_cost(item, level)
    profit = business_catalog.offer_profit(item, level)

    sent = await _dm_or_none(
        user_id,
        f"💡 <b>Срочное предложение</b>\n{DIVIDER}\n"
        f"{item.name}: можно <b>{what}</b>.\n\n"
        f"Вложите <b>{cost}</b> i¢ — и ближайшие "
        f"{business_catalog.OFFER_HOURS} ч доход будет на "
        f"<b>+{business_catalog.OFFER_BONUS_PERCENT}%</b> выше "
        f"({item.income(level)} → "
        f"{int(item.income(level) * (100 + business_catalog.OFFER_BONUS_PERCENT) / 100)} i¢/час).\n"
        f"Итого лишних примерно <b>{profit}</b> i¢ — если успеете забирать копилку.\n\n"
        f"Предложение действует {format_duration_ru(BUSINESS_URGENT_TTL)}.",
        _business_urgent_kb(cost),
    )
    if sent is not None:
        _business_urgent[(sent.chat.id, sent.message_id)] = {
            "kind": "offer", "chat_id": chat_id, "user_id": user_id,
            "key": item.key, "cost": cost,
            "expires_at": datetime.utcnow() + BUSINESS_URGENT_TTL,
        }


async def businesses_loop() -> None:
    """Раз в BUSINESS_TICK ломает случайные бизнесы и подкидывает предложения."""
    while True:
        try:
            await asyncio.sleep(BUSINESS_TICK.total_seconds())
            for chat_id in await db.list_active_chat_ids():
                try:
                    # Инвентарь на проход читаем по разу на человека, а не на
                    # каждый его бизнес: цикл идёт раз в 20 минут по всем чатам
                    # сразу, и лишний запрос на бизнес тут заметно дороже.
                    perk_cache: dict[int, int] = {}

                    async def _tools_perk(uid: int) -> int:
                        if uid not in perk_cache:
                            perk_cache[uid] = await _item_perk(
                                chat_id, uid, shop_effects.PERK_BREAK_RESIST)
                        return perk_cache[uid]

                    for row in await db.list_chat_businesses(chat_id):
                        if row.get("broken_kind"):
                            continue          # сломанный уже не сломать сильнее
                        chance = BUSINESS_BREAK_CHANCE
                        # «Хорошая аппаратура» — оснащение бизнеса: ломается реже.
                        if business_catalog.UPGRADE_GEAR in await db.list_business_upgrades(
                                chat_id, int(row["user_id"]), row["business_key"]):
                            chance *= business_catalog.GEAR_BREAK_FACTOR
                        # «Механик» (питомец) тоже бережёт технику.
                        mehanik = await _pet_bonus(chat_id, int(row["user_id"]), "guard_break")
                        if mehanik:
                            chance *= (100 - mehanik) / 100
                        # «Ящик инструментов» (ачивка «Мастер на все руки») —
                        # постоянная прибавка к живучести, ничего не тратит.
                        tools = await _tools_perk(int(row["user_id"]))
                        if tools:
                            chance *= (100 - tools) / 100
                        if random.random() < chance:
                            await _break_business(chat_id, row)
                        elif random.random() < BUSINESS_OFFER_CHANCE:
                            await _offer_business_upgrade(chat_id, row)
                except Exception:
                    logger.exception("Сбой обслуживания бизнесов в чате %s", chat_id)
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception("Сбой в цикле бизнесов")


BUSINESS_REPAIR_RE = ru_text.rx(r"(?i)^бизнес\s+(?:починить|ремонт)\s+(\S+)$")
BUSINESS_EQUIP_LIST_RE = ru_text.rx(r"(?i)^бизнес\s+оснащение(?:\s+(\S+))?$")
BUSINESS_EQUIP_BUY_RE = ru_text.rx(r"(?i)^бизнес\s+оснастить\s+(\S+)\s+(\S+)$")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(BUSINESS_EQUIP_LIST_RE.match(t.strip()))),
)
async def cmd_business_equipment(message: Message):
    """Что можно поставить в бизнес и что уже стоит."""
    if not _check_misc_access(message.from_user.id, "business_equip"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    raw = BUSINESS_EQUIP_LIST_RE.match(message.text.strip()).group(1)
    item = business_catalog.resolve(raw) if raw else None
    if raw and item is None:
        await message.reply("Такого бизнеса нет — посмотрите <code>бизнесы</code>.")
        return

    lines = ["🔧 <b>Оснащение бизнеса</b>", DIVIDER]
    if item is None:
        lines.append("Разовые покупки, которые остаются с бизнесом навсегда.")
        lines.append("")
        for up in business_catalog.UPGRADES:
            lines.append(f"{up.emoji} <b>{up.name}</b> (<code>{up.key}</code>) — {up.description}")
        lines += [
            "",
            "Цена зависит от бизнеса: чем он дороже, тем дороже оснащение.",
            "Посмотреть цены и что стоит: <code>бизнес оснащение {ключ}</code>",
            "Поставить: <code>бизнес оснастить {бизнес} {что}</code>",
        ]
        await message.reply("\n".join(lines))
        return

    row = await _load_business(chat_id, user_id, item.key)
    installed = (row or {}).get("upgrades") or set()
    lines.append(f"{item.name}" + ("" if row else " — <i>у вас его нет</i>"))
    lines.append("")
    for up in business_catalog.UPGRADES:
        mark = "✅ стоит" if up.key in installed else f"{up.price(item)} i¢"
        lines.append(f"{up.emoji} <b>{up.name}</b> (<code>{up.key}</code>) — {mark}\n"
                     f"   {up.description}")
    if row:
        lines += ["", f"Поставить: <code>бизнес оснастить {item.key} {{что}}</code>"]
    await message.reply("\n".join(lines))


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(BUSINESS_EQUIP_BUY_RE.match(t.strip()))),
)
async def cmd_business_equip(message: Message):
    if not _check_misc_access(message.from_user.id, "business_equip"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    match = BUSINESS_EQUIP_BUY_RE.match(message.text.strip())
    item = business_catalog.resolve(match.group(1))
    upgrade = business_catalog.resolve_upgrade(match.group(2))
    if item is None:
        await message.reply("Такого бизнеса нет — посмотрите <code>бизнесы</code>.")
        return
    if upgrade is None:
        await message.reply("Такого оснащения нет — посмотрите <code>бизнес оснащение</code>.")
        return
    row = await _load_business(chat_id, user_id, item.key)
    if row is None:
        await message.reply(f"{item.name} вам не принадлежит.")
        return
    if upgrade.key in ((row.get("upgrades") or set())):
        await message.reply(f"{upgrade.emoji} {upgrade.name} уже стоит в этом бизнесе.")
        return
    if await is_account_frozen(chat_id, user_id):
        await message.reply("🧊 Ваш счёт заморожен администрацией — покупка недоступна.")
        return

    price = upgrade.price(item)
    if not await spend_coins(chat_id, user_id, price):
        wallet = await db.get_wallet(chat_id, user_id)
        await message.reply(
            f"Недостаточно монет: {upgrade.name} для «{item.name}» стоит "
            f"<b>{price}</b> i¢, а у вас {wallet.get('coins', 0)} i¢."
        )
        return
    if not await db.add_business_upgrade(chat_id, user_id, item.key, upgrade.key,
                                         datetime.utcnow()):
        # Гонка: то же оснащение успели поставить между проверкой и вставкой.
        await db.add_coins(chat_id, user_id, price)
        await message.reply("Это оснащение уже стоит — деньги вернулись.")
        return

    await db.add_log("business_equip", chat_id=chat_id, actor_id=user_id,
                     details=f"{item.key}:{upgrade.key}:{price}")
    await message.reply(
        f"{upgrade.emoji} <b>{upgrade.name}</b> установлена в «{item.name}» "
        f"за {price} i¢.\n{upgrade.description}."
    )


BUSINESS_PIN_RE = ru_text.rx(r"(?i)^бизнес\s+закрепить\s+(\S+)$")
BUSINESS_UNPIN_TRIGGERS = {"бизнес открепить", "бизнес снять закреп"}


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(BUSINESS_PIN_RE.match(t.strip()))),
)
async def cmd_business_pin(message: Message):
    """Показывать бизнес в карточке профиля — рядом с закрепом и ачивкой."""
    if not _check_misc_access(message.from_user.id, "business_pin"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    item = business_catalog.resolve(BUSINESS_PIN_RE.match(message.text.strip()).group(1))
    if item is None:
        await message.reply("Такого бизнеса нет — посмотрите <code>бизнесы</code>.")
        return
    # Закреплять можно только свой: карточка профиля иначе показывала бы
    # бизнес, которого у человека нет.
    if not await db.get_user_business(chat_id, user_id, item.key):
        await message.reply(f"{item.name} вам не принадлежит.")
        return
    await db.set_pinned_business(chat_id, user_id, item.key)
    await message.reply(
        f"📌 {item.name} закреплён в профиле.\n"
        f"Открепить: <code>бизнес открепить</code>"
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and ru_text.yo(t.strip().casefold()) in BUSINESS_UNPIN_TRIGGERS),
)
async def cmd_business_unpin(message: Message):
    if not _check_misc_access(message.from_user.id, "business_pin"):
        return
    await db.set_pinned_business(message.chat.id, message.from_user.id, None)
    await message.reply("📌 Бизнес больше не показывается в профиле.")


async def _do_repair(chat_id: int, user_id: int, key: str) -> tuple[bool, str]:
    """Общий ремонт для команды и для кнопки. (получилось, текст ответа)."""
    item = business_catalog.BY_KEY.get(key)
    row = await db.get_user_business(chat_id, user_id, key)
    if item is None or row is None:
        return False, "Этот бизнес вам не принадлежит."
    if not row.get("broken_kind"):
        return False, f"{item.name} и так работает — чинить нечего."
    if await is_account_frozen(chat_id, user_id):
        return False, "🧊 Ваш счёт заморожен администрацией — ремонт недоступен."

    cost = business_catalog.repair_cost(item, int(row["level"]))
    remontnik = await _pet_bonus(chat_id, user_id, "discount_repair")
    if remontnik:
        cost = max(1, cost - cost * remontnik // 100)
    if not await spend_coins(chat_id, user_id, cost):
        wallet = await db.get_wallet(chat_id, user_id)
        return False, (f"Ремонт стоит <b>{cost}</b> i¢, а у вас "
                       f"{wallet.get('coins', 0)} i¢.")
    if not await db.repair_business(chat_id, user_id, key, datetime.utcnow()):
        # Починили из другого места, пока мы списывали, — деньги вернуть.
        await db.add_coins(chat_id, user_id, cost)
        return False, f"{item.name} уже починили."

    await db.add_log("business_repair", chat_id=chat_id, actor_id=user_id,
                     details=f"{key}:{cost}")
    return True, (f"🔧 {item.name} снова работает — ремонт обошёлся в "
                  f"<b>{cost}</b> i¢.\nДоход пошёл заново.")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(BUSINESS_REPAIR_RE.match(t.strip()))),
)
async def cmd_business_repair(message: Message):
    if not _check_misc_access(message.from_user.id, "business_repair"):
        return
    item = business_catalog.resolve(BUSINESS_REPAIR_RE.match(message.text.strip()).group(1))
    if item is None:
        await message.reply("Такого бизнеса нет — посмотрите <code>бизнесы</code>.")
        return
    _, text = await _do_repair(message.chat.id, message.from_user.id, item.key)
    await message.reply(text)


@router.callback_query(F.data == "business_repair")
async def cb_business_repair(callback: CallbackQuery):
    deal = _business_urgent.get((callback.message.chat.id, callback.message.message_id))
    if deal is None or deal.get("kind") != "repair":
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if callback.from_user.id != deal["user_id"]:
        await callback.answer("Это не ваш бизнес.", show_alert=True)
        return

    ok, text = await _do_repair(deal["chat_id"], deal["user_id"], deal["key"])
    if not ok:
        await callback.answer(re.sub(r"</?b>", "", text), show_alert=True)
        return
    _business_urgent.pop((callback.message.chat.id, callback.message.message_id), None)
    try:
        await callback.message.edit_text(
            text, reply_markup=_business_repair_kb(deal["cost"], closed=True)
        )
    except TelegramBadRequest:
        pass
    await callback.answer("Готово!")


@router.callback_query(F.data == "business_urgent")
async def cb_business_urgent(callback: CallbackQuery):
    key_ = (callback.message.chat.id, callback.message.message_id)
    deal = _business_urgent.get(key_)
    if deal is None or deal.get("kind") != "offer":
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if datetime.utcnow() >= deal["expires_at"]:
        _business_urgent.pop(key_, None)
        await callback.answer("Предложение уже неактуально.", show_alert=True)
        return
    if callback.from_user.id != deal["user_id"]:
        await callback.answer("Это не ваш бизнес.", show_alert=True)
        return

    chat_id, user_id = deal["chat_id"], deal["user_id"]
    item = business_catalog.BY_KEY.get(deal["key"])
    row = await db.get_user_business(chat_id, user_id, deal["key"])
    if item is None or row is None:
        _business_urgent.pop(key_, None)
        await callback.answer("Этого бизнеса у вас уже нет.", show_alert=True)
        return
    if row.get("broken_kind"):
        await callback.answer("Сначала почините бизнес.", show_alert=True)
        return
    if not await spend_coins(chat_id, user_id, deal["cost"]):
        await callback.answer(f"Нужно {deal['cost']} i¢, а у вас меньше.", show_alert=True)
        return

    # Копилку фиксируем до включения надбавки: время до этого момента шло по
    # обычной ставке, и задним числом пересчитывать его нельзя.
    pending = _business_pending(row)
    until = datetime.utcnow() + timedelta(hours=business_catalog.OFFER_HOURS)
    await db.set_business_boost(chat_id, user_id, deal["key"], until,
                                pending, datetime.utcnow())
    await db.add_log("business_offer", chat_id=chat_id, actor_id=user_id,
                     details=f"{deal['key']}:{deal['cost']}")
    _business_urgent.pop(key_, None)

    level = int(row["level"])
    try:
        await callback.message.edit_text(
            f"💡 Вложено <b>{deal['cost']}</b> i¢ в {item.name}.\n"
            f"Ближайшие {business_catalog.OFFER_HOURS} ч доход "
            f"<b>{int(item.income(level) * (100 + business_catalog.OFFER_BONUS_PERCENT) / 100)}</b> "
            f"i¢/час вместо {item.income(level)}.",
            reply_markup=_business_urgent_kb(deal["cost"], closed=True),
        )
    except TelegramBadRequest:
        pass
    await callback.answer("Вложено!")


# ============================================================================
# ⚔️ БОСС ЧАТА — единственное занятие, где чат играет ВМЕСТЕ.
#
# Весь баланс (здоровье, урон, награда) — в bosses.py. Здесь бой и деньги.
#
# Устройство намеренно такое:
#
#  * Нажатие кнопки НЕ редактирует сообщение. Оно только копит урон в памяти.
#    Перерисовывает отдельная задача, раз в BOSS_REDRAW_SECONDS. Иначе при
#    двадцати бьющих бот упрётся в флуд-контроль Telegram и бой встанет.
#
#  * Состояние боя живёт в памяти, а не в БД: бой идёт минуты, и после
#    перезапуска кнопка честно скажет «бой закончен» — так же, как у шапки
#    по кругу и сделок с бизнесом.
#
#  * Урон человека считается ОДИН раз за бой и кэшируется: профессия и
#    бизнесы за пятнадцать минут не меняются, а без кэша каждое нажатие
#    стоило бы трёх запросов в базу.
# ============================================================================
BOSS_REDRAW_SECONDS = 3
BOSS_SPAWN_TICK = timedelta(minutes=30)
BOSS_SPAWN_EVERY = timedelta(days=3)
BOSS_SPAWN_CHANCE = BOSS_SPAWN_TICK / BOSS_SPAWN_EVERY

# (chat_id, message_id) -> бой
_boss_fights: dict[tuple[int, int], dict] = {}


def _boss_off_key(chat_id: int) -> str:
    return f"boss_off:{chat_id}"


async def boss_enabled(chat_id: int) -> bool:
    return (await db.get_data(_boss_off_key(chat_id))) is None


def _boss_kb(closed: bool = False) -> InlineKeyboardMarkup:
    text = "Бой окончен" if closed else "⚔️ Атаковать"
    return InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text=text, callback_data="boss_hit")
    ]])


def _boss_text(fight: dict) -> str:
    boss = fight["boss"]
    bar = boss_catalog.hp_bar(fight["hp"], boss.hp)
    left = fight["expires_at"] - datetime.utcnow()
    lines = [
        f"⚔️ <b>{boss.title}</b>",
        DIVIDER,
        boss.taunt,
        "",
        f"{bar}  <b>{max(0, fight['hp'])}</b> / {boss.hp}",
        f"Бьют: {len(fight['damage'])} чел. · осталось "
        f"{format_duration_ru(left) if left.total_seconds() > 0 else '0 сек'}",
    ]
    top = boss_catalog.top_fighters(fight["damage"], places=3)
    if top:
        lines.append("")
        medals = ("🥇", "🥈", "🥉")
        for i, (user_id, dealt) in enumerate(top):
            lines.append(f"{medals[i]} {mention_id(user_id)} — {dealt}")
    lines.append("")
    lines.append(
        f"Награда за победу: <b>{boss.pool}</b> i¢ — делится по вкладу. "
        f"Удар раз в {boss_catalog.HIT_COOLDOWN_SECONDS} сек."
    )
    return "\n".join(lines)


async def _boss_power(chat_id: int, user_id: int) -> tuple[int, int, int]:
    """Из чего складывается урон: уровень профессии, сумма уровней бизнесов,
    звёздность фермы. Три запроса — поэтому результат кэшируется на весь бой."""
    prof = await db.get_profession_stats(chat_id, user_id)
    businesses = await db.list_user_businesses(chat_id, user_id)
    wallet = await db.get_wallet(chat_id, user_id)
    return (
        int(prof.get("prof_level") or 0) if prof.get("profession_key") else 0,
        sum(int(b["level"]) for b in businesses),
        wallet_stars(wallet),
    )


async def _finish_boss_fight(key: tuple[int, int], won: bool) -> None:
    """Раздаёт награду (или забирает казну) и закрывает бой."""
    fight = _boss_fights.get(key)
    if fight is None:
        return
    chat_id, message_id = key
    boss = fight["boss"]
    _boss_fights.pop(key, None)

    if won:
        shares = boss_catalog.split_reward(boss.pool, fight["damage"])
        for user_id, amount in shares.items():
            await db.add_coins(chat_id, user_id, amount)
        # Верхним местам — ещё и предмет.
        trophy = shop_effects.BY_KEY.get("talisman")
        top = boss_catalog.top_fighters(fight["damage"])
        if trophy is not None:
            await db.seed_extra_shop_items(chat_id, shop_effects.shop_rows())
            for user_id, _dealt in top:
                await db.add_inventory_item(chat_id, user_id, trophy.key)
        await db.add_log("boss_defeated", chat_id=chat_id,
                         details=f"{boss.key}:{sum(shares.values())}")
        lines = [
            f"🏆 <b>{boss.title} повержен!</b>",
            DIVIDER,
            f"Награда: <b>{sum(shares.values())}</b> i¢ на {len(shares)} чел., по вкладу.",
        ]
        medals = ("🥇", "🥈", "🥉")
        for i, (user_id, dealt) in enumerate(top):
            got = shares.get(user_id, 0)
            lines.append(f"{medals[i]} {mention_id(user_id)} — {dealt} урона, +{got} i¢")
        if top and trophy is not None:
            lines.append(f"\n{trophy.emoji} Топ-{len(top)} получают «{trophy.name}».")
    else:
        treasury = int(await db.get_chat_coins(chat_id))
        stolen = max(0, int(treasury * boss_catalog.DEFEAT_TREASURY_SHARE))
        if stolen:
            await db.add_chat_coins(chat_id, -stolen)
        await db.add_log("boss_escaped", chat_id=chat_id, details=f"{boss.key}:{stolen}")
        lines = [f"💀 <b>{boss.title} ушёл.</b>", DIVIDER, boss.defeat_line]
        if stolen:
            lines.append(f"Казна чата потеряла <b>{stolen}</b> i¢.")
        else:
            lines.append("В казне и так было пусто — забирать оказалось нечего.")

    try:
        await bot.edit_message_text(
            chat_id=chat_id, message_id=message_id, text="\n".join(lines),
            reply_markup=_boss_kb(closed=True),
        )
    except (TelegramBadRequest, TelegramForbiddenError) as exc:
        log_suppressed("_finish_boss_fight", exc)


async def _boss_ticker(key: tuple[int, int]) -> None:
    """Перерисовывает полосу здоровья и закрывает бой по времени.

    Единственное место, которое трогает сообщение во время боя, — поэтому
    сколько бы человек ни жало кнопку, запросов к Telegram будет не больше
    одного в BOSS_REDRAW_SECONDS.
    """
    try:
        while True:
            await asyncio.sleep(BOSS_REDRAW_SECONDS)
            fight = _boss_fights.get(key)
            if fight is None:
                return                      # бой уже закрыт добивающим ударом
            if datetime.utcnow() >= fight["expires_at"]:
                await _finish_boss_fight(key, won=False)
                return
            if not fight["dirty"]:
                continue
            fight["dirty"] = False
            try:
                await bot.edit_message_text(
                    chat_id=key[0], message_id=key[1], text=_boss_text(fight),
                    reply_markup=_boss_kb(),
                )
            except TelegramBadRequest:
                pass                        # текст не изменился — не беда
    except asyncio.CancelledError:
        raise
    except Exception:
        logger.exception("Сбой в отрисовке боя с боссом %s", key)


async def spawn_boss(chat_id: int, boss: boss_catalog.Boss) -> bool:
    """Выпускает босса в чат. False — отправить сообщение не удалось."""
    now = datetime.utcnow()
    fight = {
        "boss": boss,
        "hp": boss.hp,
        "damage": {},
        "last_hit": {},
        "power": {},          # кэш урона: user_id -> сколько бьёт
        "expires_at": now + timedelta(minutes=boss_catalog.FIGHT_MINUTES),
        "dirty": False,
        "closed": False,
    }
    try:
        sent = await bot.send_message(chat_id, _boss_text(fight),
                                      reply_markup=_boss_kb())
    except Exception:
        logger.exception("Не удалось выпустить босса в чат %s", chat_id)
        return False
    key = (chat_id, sent.message_id)
    _boss_fights[key] = fight
    await db.add_log("boss_spawned", chat_id=chat_id, details=boss.key)
    asyncio.create_task(_boss_ticker(key))
    return True


@router.callback_query(F.data == "boss_hit")
async def cb_boss_hit(callback: CallbackQuery):
    key = (callback.message.chat.id, callback.message.message_id)
    fight = _boss_fights.get(key)
    if fight is None or fight["closed"]:
        await callback.answer("Этот бой уже закончен.", show_alert=True)
        return

    chat_id, user_id = key[0], callback.from_user.id
    now = datetime.utcnow()
    last = fight["last_hit"].get(user_id)
    if last and (now - last).total_seconds() < boss_catalog.HIT_COOLDOWN_SECONDS:
        left = boss_catalog.HIT_COOLDOWN_SECONDS - int((now - last).total_seconds())
        await callback.answer(f"Отдышитесь — удар через {left} сек.", show_alert=False)
        return
    # Отметку ставим ДО похода в базу: иначе два быстрых нажатия успевают
    # пройти проверку оба, пока первое считает силу удара.
    fight["last_hit"][user_id] = now

    power = fight["power"].get(user_id)
    if power is None:
        try:
            power = await _boss_power(chat_id, user_id)
        except Exception:
            power = (0, 0, 0)
        fight["power"][user_id] = power

    dealt = boss_catalog.damage_for(
        *power,
        roll=random.uniform(boss_catalog.DAMAGE_SPREAD_MIN,
                            boss_catalog.DAMAGE_SPREAD_MAX),
    )
    # «Боевой» (питомец) бьёт вместе с хозяином.
    boevoy = await _pet_bonus(chat_id, user_id, "boss_damage")
    if boevoy:
        dealt += dealt * boevoy // 100

    # Между этой проверкой и записью НЕТ await: иначе два добивающих удара,
    # пришедшие одновременно, прошли бы оба. Это ПЕРВАЯ из двух защит от
    # двойной выплаты; вторая — снятие боя из реестра до раздачи денег в
    # _finish_boss_fight. Хватает любой, дублирование намеренное: состояние
    # живёт в памяти, и опереться на условие в SQL, как с поломкой бизнеса,
    # здесь не на что.
    if fight["closed"]:
        await callback.answer("Этот бой уже закончен.", show_alert=True)
        return
    fight["hp"] -= dealt
    fight["damage"][user_id] = fight["damage"].get(user_id, 0) + dealt
    fight["dirty"] = True
    await _add_season_points(chat_id, user_id, seasons.points_for_boss_damage(dealt))
    killed = fight["hp"] <= 0
    if killed:
        fight["closed"] = True

    await callback.answer(f"⚔️ −{dealt}")
    if killed:
        await _finish_boss_fight(key, won=True)


BOSS_STATUS_TRIGGERS = {"босс", "боссы", "!босс", "!боссы"}
BOSS_TOGGLE_TRIGGERS = {"+босс", "-босс", "+боссы", "-боссы"}
BOSS_SUMMON_RE = ru_text.rx(r"(?i)^!?босс\s+(?:призвать|спавн)(?:\s+(.+))?$")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and ru_text.yo(t.strip().casefold()) in BOSS_STATUS_TRIGGERS),
)
async def cmd_boss_status(message: Message):
    if not _check_misc_access(message.from_user.id, "boss_status"):
        return
    chat_id = message.chat.id
    active = next((f for (c, _m), f in _boss_fights.items() if c == chat_id), None)
    lines: list[str] = []
    if active is not None:
        left = active["expires_at"] - datetime.utcnow()
        lines += [
            f"⚔️ Сейчас в чате: <b>{active['boss'].title}</b>",
            f"Осталось здоровья: {max(0, active['hp'])} / {active['boss'].hp}",
            f"До конца боя: {format_duration_ru(left) if left.total_seconds() > 0 else '0 сек'}",
            "",
        ]
    lines.append(f"⚔️ <b>Боссы чата</b> ({len(boss_catalog.BOSSES)})")
    lines.append(DIVIDER)
    for boss in boss_catalog.BOSSES:
        lines.append(f"{boss.title} (<code>{boss.key}</code>) — "
                     f"{boss.hp} HP, награда {boss.pool} i¢")
    lines += [
        "",
        f"Бой идёт {boss_catalog.FIGHT_MINUTES} мин, удар раз в "
        f"{boss_catalog.HIT_COOLDOWN_SECONDS} сек.",
        "Урон зависит от профессии, бизнесов и звёздности — качаться выгодно.",
        "Награда делится по вкладу, топ-3 получают предмет.",
    ]
    if not await boss_enabled(chat_id):
        lines.append("\n⚠️ Боссы в этом чате выключены (<code>+босс</code> — включить).")
    if has_level(message.from_user.id, required_level("boss_toggle")):
        lines.append("Призвать вручную: <code>босс призвать {название}</code>")
    await message.answer("\n".join(lines))


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and ru_text.yo(t.strip().casefold()) in BOSS_TOGGLE_TRIGGERS),
)
async def cmd_boss_toggle(message: Message):
    min_level = required_level("boss_toggle")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Включать и выключать боссов может «{level_name(min_level)}» и выше.")
        return
    if message.text.strip().startswith("+"):
        await db.delete_data(_boss_off_key(message.chat.id))
        await message.reply("⚔️ Боссы включены — жди гостей.")
    else:
        await db.set_data(_boss_off_key(message.chat.id), "1",
                          updated_by=message.from_user.id)
        await message.reply("⚔️ Боссы выключены. Сами приходить не будут.")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(BOSS_SUMMON_RE.match(t.strip()))),
)
async def cmd_boss_summon(message: Message):
    min_level = required_level("boss_toggle")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Призывать боссов может «{level_name(min_level)}» и выше.")
        return
    chat_id = message.chat.id
    if any(c == chat_id for c, _m in _boss_fights):
        await message.reply("В чате уже идёт бой — сначала разберитесь с этим.")
        return

    raw = (BOSS_SUMMON_RE.match(message.text.strip()).group(1) or "").strip()
    if raw:
        boss = boss_catalog.resolve(raw)
        if boss is None:
            keys = ", ".join(f"<code>{b.key}</code>" for b in boss_catalog.BOSSES)
            await message.reply(f"Нет такого босса. Доступные:\n{keys}")
            return
    else:
        boss = random.choice(boss_catalog.BOSSES)

    # Ручной призыв работает и при выключенном спавне: выключатель гасит
    # случайные появления, а не саму механику — иначе админ не смог бы
    # устроить бой по случаю.
    if not await spawn_boss(chat_id, boss):
        await message.reply("Не удалось выпустить босса — попробуйте ещё раз.")


async def boss_spawn_loop() -> None:
    """Раз в BOSS_SPAWN_TICK с небольшой вероятностью выпускает босса.

    Вероятность выводится из желаемого срока (см. BOSS_SPAWN_EVERY), а не
    подбирается на глаз: поменяете тик — частота останется прежней.
    """
    while True:
        try:
            await asyncio.sleep(BOSS_SPAWN_TICK.total_seconds())
            for chat_id in await db.list_active_chat_ids():
                try:
                    if any(c == chat_id for c, _m in _boss_fights):
                        continue          # в чате уже идёт бой
                    if not await boss_enabled(chat_id):
                        continue
                    if random.random() >= BOSS_SPAWN_CHANCE:
                        continue
                    await spawn_boss(chat_id, random.choice(boss_catalog.BOSSES))
                except Exception:
                    logger.exception("Сбой призыва босса в чате %s", chat_id)
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception("Сбой в цикле боссов")


# ============================================================================
# 🐾 ЛИЧНЫЕ ПИТОМЦЫ. Числа и правила — в pets.py.
#
# Это НЕ питомцы пары из «Отношений 2.0»: те принадлежат двоим и живут на
# искрах. Эти закреплены за человеком и покупаются за i¢.
#
# Сытость и настроение падают сами и считаются ЛЕНИВО — как копилка бизнеса.
# Фонового цикла нет: бот может простоять сутки и ничего не потеряет.
#
# Все команды начинаются со слова «пет» или «питомец» — как у бизнесов, чтобы
# автоочистка и раздача прав опознавали их по тексту.
# ============================================================================
PET_WORD = r"(?:пет|питомец|питомцы|петы)"
PET_LIST_TRIGGERS = {"пет", "петы", "питомец", "питомцы", "!петы", "!питомцы"}
# Глаголы ухода. «Обнять» приравнено к «гладить»: разные слова для одной
# прибавки настроения, а не отдельная механика с отдельным откатом.
PET_CARE_VERBS = r"гладить|погладить|обнять|обнимать|поцеловать|целовать"
# Слова, означающие «сразу все мои». Вынесены в свою группу, потому что
# участвуют дважды: в массовых командах — как цель, в одиночных — как ЗАПРЕТ.
# Без запрета «пет покормить все» матчится одиночной командой, «все» уезжает
# в группу ключа питомца, и бот отвечает «такого питомца нет».
#
# Порядок регистрации обработчиков (массовые объявлены ВЫШЕ одиночных) тоже
# разводит их, но опираться только на него нельзя: перестановка функций в
# файле сломала бы команды молча, а тесты зовут обработчики напрямую и
# маршрутизацию не проверяют.
PET_ALL_WORD = r"(?:все|всех|всем)"
_NOT_ALL = rf"(?!{PET_ALL_WORD}$)"
PET_SHOP_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+(?:каталог|магазин|список)$")
PET_BUY_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+купить\s+(\S+)$")
PET_NAME_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+назвать\s+(\S+)\s+(.+)$")
PET_FEED_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+(?:кормить|покормить)(?:\s+{_NOT_ALL}(\S+))?$")
PET_FEED_ALL_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+(?:кормить|покормить)\s+{PET_ALL_WORD}$")
PET_CARE_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+({PET_CARE_VERBS})(?:\s+{_NOT_ALL}(\S+))?$")
PET_CARE_ALL_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+({PET_CARE_VERBS})\s+{PET_ALL_WORD}$")
# Ключ необязателен: с единственным питомцем «пет продать» и так понятно, о ком
# речь (как у кормёжки), а молчать в ответ на команду нельзя — это единственное
# необратимое действие с питомцем.
PET_SELL_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+продать(?:\s+(\S+))?(?:\s+(да))?$")
PET_FOOD_BUY_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+(?:корм|еда|еду)(?:\s+(\d+))?$")
PET_WALK_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+(?:гулять|погулять|прогулка)(?:\s+{_NOT_ALL}(\S+))?$")
PET_EVOLVE_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+(?:эволюция|эволюционировать|эвол)\s+(\S+)(?:\s+(да))?$")
PET_WALK_ALL_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+(?:гулять|погулять|прогулка)\s+{PET_ALL_WORD}$")
PET_FOOD_GRANT_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+раздать(?:\s+корм[а]?)?$")
# Метка последней раздачи корма живёт в bot_data по чату — там же, где метка
# ежедневной награды за активность.
PET_FOOD_GRANT_KEY = "pet_food_grant_last"
PET_PIN_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+закрепить\s+(\S+)$")
PET_UNPIN_TRIGGERS = {"пет открепить", "питомец открепить", "петы открепить"}
PET_ABILITY_RE = ru_text.rx(rf"(?i)^!?{PET_WORD}\s+способность\s+(\S+)(?:\s+(\d+))?$")
PET_ABILITY_LIST_TRIGGERS = {"пет способности", "питомец способности", "петы способности",
                             "!пет способности", "!питомец способности", "!петы способности"}


async def _pet_lucky(chat_id: int, user_id: int, amount: int, ability: str) -> int:
    """Прибавляет к сумме процент от питомца с этой способностью.

    Отдельный помощник, потому что таких мест несколько (все игры казино,
    лутбоксы), и повторять три строки в каждом — верный способ однажды
    забыть одно из них.
    """
    percent = await _pet_bonus(chat_id, user_id, ability)
    percent += await _pin_bonus(chat_id, user_id, ability)
    if not percent:
        return amount
    return amount + amount * percent // 100


async def _pet_bonus(chat_id: int, user_id: int, ability: str) -> int:
    """Прибавка в процентах от питомцев с этой способностью.

    Считаются ТОЛЬКО сытые и довольные (pets.is_active): в этом и смысл
    ухода — перестал кормить, потерял выгоду. Складывается, если питомцев
    с одной способностью несколько.

    Ошибку глотаем: способность питомца — приятный бонус, а не основа
    начисления, и упавший запрос не должен ронять саму ферму или налёт.
    """
    if not ability:
        return 0
    try:
        rows = await db.list_pets(chat_id, user_id)
        if not rows:
            return 0
        specs = await _pet_specs(chat_id)
    except Exception as exc:
        log_suppressed("_pet_bonus", exc)
        return 0

    # «Компаньон» замедляет падение настроения — учитываем его ДО проверки
    # активности остальных, иначе панда не могла бы вытянуть загрустившую
    # компанию, ради чего она и заводится.
    pinned_key = await _pinned_pet_key(chat_id, user_id)
    slowdown = _pet_mood_slowdown(rows, specs, pinned_key)
    # Закреплённому питомцу способность засыпает позже — это его слот
    # экипировки (см. pins.PET_LOW_STAT). Карточку читаем один раз на весь
    # проход, а не по разу на питомца.
    total = 0
    for row in rows:
        spec = specs.get(row["pet_key"])
        if spec is None:
            continue
        if ability not in _effective_abilities(row, spec):
            continue
        hunger, mood = _pet_now(row, slowdown)
        if not _pet_is_active(row, hunger, mood, pinned_key):
            continue
        total += pets_catalog.ability_percent(
            ability, _pet_level(row), evolved=bool(row.get("evolved")))
    return total


ABILITY_PET_MOOD = "pet_mood"


def _pet_is_active(row: dict, hunger: int, mood: int,
                   pinned_key: Optional[str]) -> bool:
    """Работает ли способность этого питомца прямо сейчас.

    У закреплённого порог ниже обычного: закреп — слот экипировки, и его
    смысл в том, что закреплённому прощается пропущенная кормёжка. Не
    «никогда не засыпает» — ухаживать всё равно надо.
    """
    if pinned_key and row.get("pet_key") == pinned_key:
        return hunger >= pins.PET_LOW_STAT and mood >= pins.PET_LOW_STAT
    return pets_catalog.is_active(hunger, mood)


async def _pinned_pet_key(chat_id: int, user_id: int) -> Optional[str]:
    try:
        card = await db.get_profile_card(chat_id, user_id)
    except Exception as exc:
        log_suppressed("_pinned_pet_key", exc)
        return None
    return (card or {}).get("pinned_pet")


def _pet_mood_slowdown(rows: list[dict], specs: dict,
                       pinned_key: Optional[str] = None) -> int:
    """На сколько процентов медленнее падает настроение у всех питомцев хозяина.

    Это способность «Компаньон» (панда). Раньше она применялась ровно в одном
    месте — при отрисовке списка «пет», — то есть меняла показанное число и
    больше ничего: способности не платили, а кормление и ласка записывали в
    базу настроение, посчитанное БЕЗ поблажки, тем самым стирая её при каждом
    взаимодействии. Панда за 45 000 i¢ была украшением, хотя каталог обещал
    работающий эффект, и её вдобавок можно купить за «пет способность».

    Рекурсии здесь нет намеренно: активность самого «Компаньона» определяется
    по его состоянию БЕЗ поблажки. Иначе панда поддерживала бы сама себя, и
    вопрос «работает ли она» не имел бы однозначного ответа.
    """
    total = 0
    ability = pets_catalog.ABILITY_BY_KEY.get(ABILITY_PET_MOOD)
    if ability is None:
        return 0
    for row in rows:
        spec = specs.get(row["pet_key"])
        if spec is None or ABILITY_PET_MOOD not in _effective_abilities(row, spec):
            continue
        hunger, mood = _pet_now(row)          # без поблажки — см. докстринг
        if not _pet_is_active(row, hunger, mood, pinned_key):
            continue
        total += pets_catalog.ability_percent(
            ABILITY_PET_MOOD, _pet_level(row), evolved=bool(row.get("evolved")))
    return total


async def _pet_slowdown_for(chat_id: int, user_id: int) -> int:
    """То же самое, но когда строк питомцев под рукой нет (поштучные команды).

    Ошибку глотаем по той же причине, что и в _pet_bonus: поблажка — приятная
    добавка, а не основа расчёта, и упавший запрос не должен ломать кормёжку.
    """
    try:
        rows = await db.list_pets(chat_id, user_id)
        if not rows:
            return 0
        return _pet_mood_slowdown(rows, await _pet_specs(chat_id),
                                  await _pinned_pet_key(chat_id, user_id))
    except Exception as exc:
        log_suppressed("_pet_slowdown_for", exc)
        return 0


def _effective_abilities(row: dict, spec) -> tuple[str, ...]:
    """Все способности питомца: своя (или вида) плюс вторая, если он
    эволюционировал. Считаются обе — в этом и смысл эволюции."""
    out = [_effective_ability(row, spec)]
    second = row.get("ability2")
    if second and second != pets_catalog.ABILITY_NONE:
        out.append(second)
    return tuple(a for a in out if a and a != pets_catalog.ABILITY_NONE)


def _effective_ability(row: dict, spec) -> str:
    """Способность питомца У ЭТОГО хозяина: своя, если её меняли за деньги
    (row['ability'] — override, см. пет способность), иначе — способность
    вида из каталога. NULL/пусто в row означает «override не задан»."""
    override = row.get("ability")
    if override:
        return override
    return spec.ability if spec else pets_catalog.ABILITY_NONE


# Настройки видов питомцев в конкретном чате: выключен ли вид и есть ли
# потолок численности. Заполняется _pet_specs(), читается покупкой.
_pet_settings: dict[str, dict] = {}


async def _pet_specs(chat_id: int) -> dict:
    """Каталог питомцев чата: встроенные из pets.py плюс заведённые админом.

    Живёт в БД, потому что админ может создать своего питомца в панели;
    встроенные при каждом обращении досеиваются, чтобы новые из кода доезжали
    и в чаты, где каталог уже есть.
    """
    await db.ensure_pet_catalog(chat_id, pets_catalog.PETS)
    out: dict = {}
    settings_by_key = _pet_settings
    for row in await db.list_pet_catalog(chat_id):
        spec = pets_catalog.Pet(
            key=row["pet_key"], name=row["name"], emoji=row["emoji"],
            price=int(row["price"]), sound=row["sound"],
            # Без этого способность терялась при чтении из базы и все питомцы
            # молча становились бесполезными: в каталоге эффект есть, а
            # в объекте — ABILITY_NONE по умолчанию.
            ability=row.get("ability") or pets_catalog.ABILITY_NONE,
        )
        # Выключатель и потолок численности живут только в базе (их правит
        # панель), поэтому кладём их рядом со спецификацией, а не в саму
        # неизменяемую Pet — она описывает вид, а не его настройку в чате.
        out[row["pet_key"]] = spec
        settings_by_key[row["pet_key"]] = {
            "is_active": bool(row.get("is_active", True)),
            "max_count": row.get("max_count"),
        }
    return out


async def _pet_spec(chat_id: int, raw: Optional[str]):
    """Питомец по ключу или по-русски, с учётом созданных админом."""
    if not raw:
        return None
    specs = await _pet_specs(chat_id)
    key = " ".join(raw.strip().casefold().split())
    if key in specs:
        return specs[key]
    # Русские названия: сначала встроенные синонимы, потом по самому названию.
    builtin = pets_catalog.resolve(raw)
    if builtin is not None and builtin.key in specs:
        return specs[builtin.key]
    for spec in specs.values():
        if spec.name.casefold() == key:
            return spec
    return None


def _pet_hours(row: dict) -> float:
    last = row.get("last_tick_at")
    if not last:
        return 0.0
    return max(0.0, (datetime.utcnow() - last).total_seconds() / 3600)


def _pet_xp_hours(row: dict) -> float:
    """Отдельная метка от _pet_hours: xp_tick_at не имеет истории с покупки
    питомца (см. миграцию в db.ensure_pets_table) — считать опыт от
    last_tick_at выдало бы старым питомцам мгновенный максимальный уровень."""
    last = row.get("xp_tick_at")
    if not last:
        return 0.0
    return max(0.0, (datetime.utcnow() - last).total_seconds() / 3600)


def _pet_xp_now(row: dict) -> int:
    return pets_catalog.xp_now(int(row.get("xp") or 0), _pet_xp_hours(row))


def _pet_level(row: dict) -> int:
    return pets_catalog.level_for_xp(_pet_xp_now(row))


def _pet_now(row: dict, mood_slowdown: int = 0) -> tuple[int, int]:
    """Сытость и настроение ПРЯМО СЕЙЧАС, с учётом прошедшего времени.

    mood_slowdown — на сколько процентов медленнее падает настроение
    («Компаньон»). Передаётся снаружи, чтобы расчёт остался синхронным:
    он зовётся в отрисовке списков и в профиле.
    """
    hours = _pet_hours(row)
    mood_hours = hours * (100 - max(0, min(mood_slowdown, 90))) / 100
    stored_hunger = int(row.get("hunger") or 0)
    hunger = (pets_catalog.hunger_now_evolved(stored_hunger, hours)
              if row.get("evolved")
              else pets_catalog.hunger_now(stored_hunger, hours))
    return hunger, pets_catalog.mood_now(int(row.get("mood") or 0), mood_hours)


def _pet_display(row: dict, spec=None) -> str:
    """Как питомец называется в тексте. spec можно передать снаружи, чтобы
    не ходить в каталог второй раз; без него берётся встроенный, а для
    заведённого админом — просто ключ.

    Эволюционировавший показывается НОВЫМ обликом: ради него эволюцию и
    делают, и видеть в списке прежнего хомяка было бы обидно."""
    spec = spec or pets_catalog.BY_KEY.get(row["pet_key"])
    grown = pets_catalog.evolution_of(row["pet_key"]) if row.get("evolved") else None
    if grown is not None:
        base = f"{grown.emoji} {grown.name}"
    else:
        base = spec.title if spec else row["pet_key"]
    given = row.get("pet_name")
    return f"{base} «{html.escape(given)}»" if given else base


async def _pets_text(chat_id: int, user_id: int, own: bool) -> str:
    rows = await db.list_pets(chat_id, user_id)
    if not rows:
        return ("🐾 <b>Питомцы</b>\n\nПока ни одного.\n"
                "Каталог — <code>пет каталог</code>, купить — "
                "<code>пет купить {ключ}</code>." if own
                else "🐾 У этого человека пока нет питомцев.")
    specs = await _pet_specs(chat_id)
    pinned_key = await _pinned_pet_key(chat_id, user_id)
    slowdown = _pet_mood_slowdown(rows, specs, pinned_key)
    lines = [f"🐾 <b>Питомцы</b> — {len(rows)}", DIVIDER]
    for row in rows:
        spec = specs.get(row["pet_key"])
        hunger, mood = _pet_now(row, slowdown)
        xp = _pet_xp_now(row)
        level, gained, needed = pets_catalog.level_progress(xp)
        level_label = (f"MAX" if level >= pets_catalog.MAX_PET_LEVEL
                       else f"{level}/{pets_catalog.MAX_PET_LEVEL}")
        line = (f"{_pet_display(row, spec)} (<code>{row['pet_key']}</code>) "
                f"— ⭐ ур. {level_label}\n"
                f"   🍽 {pets_catalog.bar(hunger)} {hunger}   "
                f"😊 {pets_catalog.bar(mood)} {mood}   {pets_catalog.state_text(hunger, mood)}")
        if level < pets_catalog.MAX_PET_LEVEL:
            progress = round(100 * gained / needed) if needed else 100
            line += f"\n   📈 {pets_catalog.bar(progress)} {gained}/{needed} опыта"
        # Способности и то, работают ли они сейчас: иначе непонятно, зачем
        # вообще кормить. Процент — уже с прибавкой за уровень, а у
        # эволюционировавшего ещё и с удвоенной базой. Способностей может быть
        # две — вторая появляется как раз с эволюцией.
        evolved = bool(row.get("evolved"))
        works = "✅" if _pet_is_active(row, hunger, mood, pinned_key) else "💤 спит"
        for ability_key in (_effective_abilities(row, spec) if spec else ()):
            found = pets_catalog.ABILITY_BY_KEY.get(ability_key)
            if found is None:
                continue
            percent = pets_catalog.ability_percent(ability_key, level, evolved)
            line += f"\n   ✨ {found.description.format(p=percent)} — {works}"
        if evolved:
            line += "\n   🌟 Эволюционировал(а)"
        lines.append(line)
    if own:
        food = await db.get_inventory_quantity(chat_id, user_id,
                                               pets_catalog.FOOD_ITEM_KEY)
        lines += ["", f"{pets_catalog.FOOD_ITEM_EMOJI} Корма у вас: {food} "
                      f"(одно кормление — один корм, "
                      f"<code>пет корм 10</code>)",
                  "<code>пет кормить {ключ}</code> · "
                  "<code>пет гладить {ключ}</code> · "
                  "<code>пет обнять {ключ}</code> · "
                  "<code>пет поцеловать {ключ}</code>",
                  "<code>пет гулять {ключ}</code> — питомец принесёт находку "
                  f"(раз в {pets_catalog.WALK_COOLDOWN_HOURS} ч)",
                  "<code>пет кормить все</code> · <code>пет обнять все</code> · "
                  "<code>пет гулять все</code> — сразу всем",
                  "<code>пет назвать {ключ} {имя}</code> · "
                  "<code>пет закрепить {ключ}</code>",
                  "<code>пет продать {ключ}</code> — вернуть половину цены",
                  "<code>пет способность {ключ} {номер}</code> — сменить "
                  "способность за i¢, список номеров: <code>пет способности</code>",
                  "⭐ Уровень растёт сам по себе со временем, кормёжка и "
                  "ласка ускоряют."]
    return "\n".join(lines)


