TRANSFER_CMD_RE = ru_text.rx(r"(?i)^(?:перевод|перевести)\b")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(TRANSFER_CMD_RE.match(t.strip()))),
)
async def cmd_transfer(message: Message):
    """«Перевод @username сумма» (или ответом на сообщение) — переводит i¢
    из личного кошелька отправителя получателю в пределах этого чата.
    Необязательное сообщение к переводу — второй строкой."""
    if not _check_misc_access(message.from_user.id, "coin_transfer"):
        return

    text = message.text.strip()
    first_line, _, rest = text.partition("\n")
    note = rest.strip()[:200] or None

    # allow_bare_id=False: число после «перевод» — это сумма, а не ID цели.
    # Цель указывается только @username/text_mention или ответом на сообщение.
    target, remaining = await resolve_command_target(
        message, trigger_words=1, allow_bare_id=False, text=first_line
    )
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Использование: <code>Перевод @username сумма</code> (или ответом на сообщение)\n"
            "Можно добавить сообщение к переводу второй строкой:\n"
            "<code>Перевод @username 100\nНа мороженое</code>"
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return
    if target.id == message.from_user.id:
        await message.reply("Самому себе переводить не имеет смысла 🙂")
        return
    if getattr(target, "is_bot", False):
        await message.reply("Боты монеты не тратят 🤖")
        return

    amount = find_amount(remaining)
    if amount is None:
        await message.reply(
            "Укажите сумму перевода, например:\n<code>Перевод @username 100</code> или <code>Перевод @username 10к</code>"
        )
        return
    if amount <= 0:
        await message.reply("Сумма перевода должна быть больше нуля.")
        return

    if await is_account_frozen(message.chat.id, message.from_user.id):
        await message.reply("🧊 Ваш счёт заморожен — переводы недоступны.")
        return

    if has_infinite_money(message.from_user.id):
        await db.add_coins(message.chat.id, target.id, amount)
    else:
        wallet = await db.get_wallet(message.chat.id, message.from_user.id)
        if int(wallet.get("coins", 0)) < amount:
            await message.reply(f"Недостаточно монет: у вас {wallet.get('coins', 0)} i¢, нужно {amount}.")
            return
        ok = await db.transfer_coins(message.chat.id, message.from_user.id, target.id, amount)
        if not ok:
            await message.reply("Не удалось выполнить перевод — попробуйте ещё раз.")
            return

    await db.add_log(
        "coin_transfer", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=str(amount),
    )
    sender_name = await display_name(message.chat.id, message.from_user)
    target_name = await display_name(message.chat.id, target)
    note_line = f"\n📝 с комментарием: {html.escape(note)}" if note else ""
    await message.reply(
        f"💸 {sender_name} перевёл(а) {target_name} <b>{amount}</b> i¢{note_line}"
    )


ITEM_USE_RE = ru_text.rx(r"(?i)^использовать\s+(\S+)")


async def _daily_item_payout(chat_id: int, user_id: int, shifts: int) -> int:
    """Сколько платит предмет «раз в сутки» — во столько-то смен.

    Считаем по ТЕКУЩЕЙ профессии человека, а не по фиксированному числу:
    иначе выплата разъехалась бы со шкалой заработков при следующей правке
    баланса. Профессии нет — берём самую скромную, чтобы предмет всё равно
    что-то давал.
    """
    stats = await db.get_profession_stats(chat_id, user_id)
    prof = PROFESSIONS.get(stats.get("profession_key") or "")
    if prof is None:
        prof = PROFESSIONS["уборщик"]
    low, high = prof["income"]
    return max(1, int((low + high) / 2 * max(1, shifts)))


async def _passive_bonus(chat_id: int, user_id: int, activity: str) -> int:
    """Прибавка в процентах от предметов за ачивки, лежащих в инвентаре.

    Ничего не тратит и ничего не требует нажимать: предмет работает самим
    фактом наличия (см. shop_effects.ACHIEVEMENT_ITEMS).
    """
    try:
        keys = [i["item_key"] for i in await db.list_inventory(chat_id, user_id)]
    except Exception:
        # Прибавка — приятный бонус, а не основа начисления: если инвентарь
        # почему-то не прочитался, заработок должен пройти без неё, а не упасть.
        log_suppressed("_passive_bonus", None)
        return 0
    percent = shop_effects.passive_percent(keys, activity)
    # Питомец с подходящей способностью прибавляет к тому же занятию —
    # ферма, рыбалка, клад, подработка, бонус, смена (см. pets.ABILITIES).
    percent += await _pet_bonus(chat_id, user_id, activity)
    # Закрепы профиля: тема «Труд» у ачивки прибавляет к любому занятию,
    # «Экономика» — к ежедневному бонусу, рыба-трофей — к улову.
    percent += await _pin_bonus(chat_id, user_id, activity)
    return percent


async def _pin_bonus(chat_id: int, user_id: int, effect_key: str) -> int:
    """Прибавка от закрепов профиля (см. pins.py) к этому эффекту.

    Закреп — экипировка: слот один на вид, и что он усиливает, выбирает сам
    игрок. Здесь считаются ачивка (по теме) и рыба-трофей (к улову); предмет
    усиливается в момент применения, бизнес чинится сам, а питомцу закреп
    опускает порог засыпания — те трое живут в своих местах.

    Ошибку глотаем по той же причине, что и _pet_bonus: прибавка — надстройка,
    и непрочитавшаяся карточка профиля не должна ронять саму ферму.
    """
    try:
        card = await db.get_profile_card(chat_id, user_id)
    except Exception as exc:
        log_suppressed("_pin_bonus", exc)
        return 0
    if not card:
        return 0
    total = pins.achievement_bonus(card.get("pinned_achievement"), effect_key)
    if card.get("pinned_fish") and effect_key == shop_effects.ACTIVITY_FISHING:
        total += pins.FISH_CATCH_PERCENT
    return total


async def _item_perk(chat_id: int, user_id: int, perk: str) -> int:
    """Сила постоянной привилегии от предметов за ачивки (см. shop_effects.PERK_*).

    Для привилегий-переключателей (FLAG_PERKS) возвращает 1 или 0 — вызывающему
    удобнее один вид проверки на все случаи.

    Ошибку глотаем по той же причине, что и _passive_bonus: привилегия —
    надстройка над механикой, и непрочитавшийся инвентарь не должен ронять
    саму ферму или ограбление.
    """
    try:
        keys = [i["item_key"] for i in await db.list_inventory(chat_id, user_id)]
    except Exception:
        log_suppressed("_item_perk", None)
        return 0
    if perk in shop_effects.FLAG_PERKS:
        return 1 if shop_effects.has_perk(keys, perk) else 0
    return shop_effects.perk_percent(keys, perk)


async def _with_passive(chat_id: int, user_id: int, activity: str,
                        amount: int) -> tuple[int, int]:
    """Награда с учётом пассивной прибавки. Возвращает (сумма, процент)."""
    percent = await _passive_bonus(chat_id, user_id, activity)
    if not percent:
        return amount, 0
    return max(1, round(amount * (100 + percent) / 100)), percent


async def _apply_lucky(chat_id: int, user_id: int, amount: int) -> tuple[int, bool]:
    """Талисман удачи: если у человека есть заряд — удваивает награду и тратит его.

    Заряд списывается ОДНИМ запросом (см. db.consume_item_effect): иначе две
    команды подряд — ферма и рыбалка — успели бы обе увидеть один и тот же
    заряд, и один талисман сработал бы дважды.
    """
    if not await db.consume_item_effect(chat_id, user_id, shop_effects.EFFECT_LUCKY):
        return amount, False
    return amount * shop_effects.LUCKY_MULTIPLIER, True


MEDVEZHATNIK_RE = ru_text.rx(r"(?i)^!?медвежатник\b\s*(.*)$")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(MEDVEZHATNIK_RE.match(t.strip()))),
)
async def cmd_steal_item(message: Message):
    """«медвежатник @кому {ключ}» — крадёт один выбранный предмет.

    Своя команда, а не общее «использовать»: это единственный предмет,
    которому нужны и цель, и что именно красть. Впихивать два аргумента
    в «использовать {ключ} @кому» значило бы, что ключ предмета стоит там,
    где у всех остальных стоит цель.
    """
    if not _check_misc_access(message.from_user.id, "item_steal"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    spec = shop_effects.BY_KEY["medvezhatnik"]

    if not any(i["item_key"] == spec.key
               for i in await db.list_inventory(chat_id, user_id)):
        await message.reply(
            f"У вас нет {spec.emoji} «{spec.name}» — он продаётся в «магазин» "
            f"за {spec.price} i¢."
        )
        return
    if await event_flag(chat_id, chat_events.F_NO_ROBBERY):
        await message.reply("🚓 Комендантский час — на улицах патрули. Не сегодня.")
        return

    target, rest = await resolve_command_target(message, trigger_words=1)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    # Ключ предмета — последнее слово, которое не является упоминанием.
    wanted = ""
    for word in reversed((rest or message.text).split()):
        if not word.startswith("@") and not word.casefold().startswith("медвежатник"):
            wanted = word.casefold()
            break

    if target is None or target.id is None or not wanted:
        await message.reply(
            "Использование: <code>медвежатник @кому {ключ предмета}</code> "
            "(или ответом на его сообщение).\n"
            "Ключ предмета видно в «инвентарь» — по нему можно нажать."
        )
        return
    if target.id == user_id:
        await message.reply("У себя красть нечего 🙂")
        return
    if getattr(target, "is_bot", False):
        await message.reply("У ботов инвентаря нет 🤖")
        return
    if shop_effects.is_reward(wanted):
        await message.reply(
            "🎖 Награды и предметы за ачивки не крадутся — это чужая заслуга."
        )
        return

    victim_items = {i["item_key"]: i["quantity"] for i in await db.list_inventory(chat_id, target.id)}
    if victim_items.get(wanted, 0) <= 0:
        target_name = await display_name(chat_id, target)
        await message.reply(f"У {target_name} нет предмета «{html.escape(wanted)}».")
        return

    # Медвежатник тратится в любом случае — иначе его можно было бы жать по
    # чужому инвентарю без риска, пока не найдётся что-то ценное.
    await db.remove_inventory_item(chat_id, user_id, spec.key, 1)
    if not await db.remove_inventory_item(chat_id, target.id, wanted, 1):
        await message.reply("Предмет успели потратить — вскрывать оказалось нечего.")
        return
    await db.add_inventory_item(chat_id, user_id, wanted, 1)
    await db.add_log("item_stolen", chat_id=chat_id, actor_id=user_id,
                     target_id=target.id, details=wanted)

    stolen = await db.get_shop_item(chat_id, wanted)
    stolen_name = stolen["name"] if stolen else wanted
    actor_name = await display_name(chat_id, message.from_user)
    target_name = await display_name(chat_id, target)
    await message.answer(
        f"🗝 {actor_name} вскрыл(а) закрома и унёс(ла) у {target_name} "
        f"предмет «{html.escape(stolen_name)}»."
    )
    await _dm_or_none(
        target.id,
        f"🗝 У вас украли предмет «{html.escape(stolen_name)}». "
        f"Работал медвежатник — от него не спасает ничего, кроме пустого инвентаря."
    )


# ============================================================================
# Рынок между участниками. Правила — в market.py, таблицы — в db.py.
#
# Участник заводит свой товар, администрация его подтверждает, и дальше в
# этом чате им торгует только он. Купленное падает в обычный инвентарь.
# ============================================================================
MARKET_APPLY_RE = ru_text.rx(r"(?i)^!?рынок\s+заявка\s+(\S+)\s+(\S+)\s+(.+)$")
MARKET_BUY_RE = ru_text.rx(r"(?i)^!?рынок\s+купить\s+(\S+)(?:\s+(\d+))?$")
MARKET_WITHDRAW_RE = ru_text.rx(r"(?i)^!?рынок\s+снять\s+(\S+)$")
MARKET_DECIDE_RE = ru_text.rx(r"(?i)^!?рынок\s+(принять|отклонить)\s+(\d+)$")
MARKET_MODE_RE = ru_text.rx(r"(?i)^!?рынок\s+режим\s+(ручной|авто|отклонять)$")
MARKET_CFG_RE = ru_text.rx(r"(?i)^!?рынок\s+(комиссия|потолок|лимит)\s+(\d+)$")
# Свои товары: то же самое, что делают кнопки в личке, но текстом — кнопки
# удобнее с телефона, а тем, кто привык набирать, ничего не отнимается.
MARKET_PRICE_RE = ru_text.rx(r"(?i)^!?рынок\s+цена\s+(\S+)\s+(\d+)$")
MARKET_DESC_RE = ru_text.rx(r"(?i)^!?рынок\s+описание\s+(\S+)\s+(.+)$")


def _market_settings(row: dict) -> market.Settings:
    return market.Settings(
        mode=row.get("mode") or market.DEFAULT_MODE,
        commission_percent=float(row.get("commission_percent") or market.DEFAULT_COMMISSION),
        max_price=int(row.get("max_price") or market.DEFAULT_MAX_PRICE),
        max_goods=int(row.get("max_goods") or market.DEFAULT_MAX_GOODS),
    )


async def _market_key_taken(chat_id: int, key: str) -> str:
    """Пустая строка — ключ свободен, иначе объяснение, чем он занят.

    ⚠️ Проверка встроенных каталогов здесь не формальность. Магазин
    досеивается функцией, которая молча пропускает уже существующие ключи
    (см. db.seed_extra_shop_items). Пусти на рынок товар с ключом «talisman» —
    и настоящий Талисман удачи в этом чате не появится уже никогда, причём
    без единой ошибки в логах.
    """
    if key in shop_effects.BY_KEY or key in shop_effects.ACHIEVEMENT_BY_KEY:
        return "Такой ключ занят предметом магазина."
    if key in shop_effects.REWARD_BY_KEY or key in robbery.ROBBERY_ITEMS:
        return "Такой ключ занят предметом бота."
    if await db.get_shop_item(chat_id, key) is not None:
        return "Такой ключ уже есть в магазине этого чата."
    if await db.get_market_good(chat_id, key) is not None:
        return "Этот товар в чате уже кто-то продаёт — ключ занят."
    return ""


async def _market_notify_request(
    chat_id: int, good_id: int, seller: str, name: str, key: str,
    price: int, chat_title: Optional[str],
) -> bool:
    """Отправляет заявку в чат уведомлений (settings.notify_chat_id) — туда же,
    куда идут заявки на вступление и жалобы. False — чат не настроен.

    Решение принимается кнопками, а не командой «рынок принять {номер}»:
    команда ищет заявку по чату, в котором её написали, а нажимают её как раз
    в ЧУЖОМ чате уведомлений. Поэтому id исходного чата едет в callback_data.
    """
    notify_chat_id = settings.get("notify_chat_id")
    if not notify_chat_id:
        return False
    where = f" · чат: {html.escape(chat_title)}" if chat_title else ""
    keyboard = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="✅ Принять",
                             callback_data=f"mktok:{chat_id}:{good_id}"),
        InlineKeyboardButton(text="🚫 Отклонить",
                             callback_data=f"mktno:{chat_id}:{good_id}"),
    ]])
    try:
        await bot.send_message(
            chat_id=notify_chat_id,
            message_thread_id=settings.get("notify_topic_id"),
            text=(
                f"🧺 <b>Заявка на рынок</b> №{good_id}{where}\n\n"
                f"Продавец: {seller}\n"
                f"Товар: {html.escape(name)} (<code>{html.escape(key)}</code>)\n"
                f"Цена: {price} i¢"
            ),
            reply_markup=keyboard,
        )
        return True
    except Exception:
        logger.exception("Не удалось отправить заявку рынка в notify_chat_id")
        return False


async def _market_apply_decision(chat_id: int, good_id: int, approve: bool,
                                 admin_id: int) -> Optional[dict]:
    """Общее решение по заявке для команды и для кнопки. None — заявки уже нет.

    Объявление о решении уходит в ИСХОДНЫЙ чат: продавец и покупатели живут
    там, а не в чате уведомлений.
    """
    good = await db.get_market_good_by_id(chat_id, good_id)
    if good is None or good["status"] != "pending":
        return None
    if not await db.decide_market_good(chat_id, good_id, approve, admin_id):
        return None

    await db.add_log(
        "market_approve" if approve else "market_reject",
        chat_id=chat_id, actor_id=admin_id,
        target_id=int(good["seller_id"]), details=good["item_key"],
    )
    seller = await display_name_by_id(chat_id, int(good["seller_id"]))
    if approve:
        text = (f"✅ Заявка №{good_id} одобрена: {seller} торгует "
                f"«{html.escape(good['name'])}» "
                f"(<code>{html.escape(good['item_key'])}</code>) по {good['price']} i¢.")
    else:
        text = (f"🚫 Заявка №{good_id} отклонена. Ключ "
                f"<code>{html.escape(good['item_key'])}</code> снова свободен.")
    try:
        await bot.send_message(chat_id, text)
    except Exception as exc:
        log_suppressed("_market_apply_decision", exc)
    await _dm_or_none(
        int(good["seller_id"]),
        f"{'✅ Ваш товар одобрен' if approve else '🚫 Ваша заявка отклонена'}: "
        f"«{html.escape(good['name'])}»."
    )
    return good


@router.callback_query(F.data.startswith("mktok:") | F.data.startswith("mktno:"))
async def market_decide_cb(callback: CallbackQuery):
    """Кнопки «Принять»/«Отклонить» под заявкой в чате уведомлений."""
    if not has_level(callback.from_user.id, required_level("market_manage")):
        await callback.answer("Разбирать заявки может только администрация.", show_alert=True)
        return
    action, chat_raw, good_raw = callback.data.split(":", maxsplit=2)
    approve = action == "mktok"
    good = await _market_apply_decision(
        int(chat_raw), int(good_raw), approve, callback.from_user.id
    )
    if good is None:
        await callback.answer("Заявку уже разобрали.", show_alert=True)
        return
    await callback.answer("✅ Принято" if approve else "🚫 Отклонено")
    who = await display_name_by_id(int(chat_raw), int(good["seller_id"]))
    try:
        await callback.message.edit_text(
            f"🧺 <b>Заявка на рынок</b> №{good_raw} — "
            f"{'✅ принята' if approve else '🚫 отклонена'}\n\n"
            f"Продавец: {who}\n"
            f"Товар: {html.escape(good['name'])} "
            f"(<code>{html.escape(good['item_key'])}</code>)\n"
            f"Цена: {good['price']} i¢"
        )
    except Exception as exc:
        log_suppressed("market_decide_cb", exc)


def _market_line(good: dict, seller: str) -> str:
    desc = f" — {html.escape(good['description'])}" if good.get("description") else ""
    return (f"{good['emoji']} <b>{html.escape(good['name'])}</b> "
            f"(<code>{html.escape(good['item_key'])}</code>) — "
            f"{good['price']} i¢ · продавец: {seller}{desc}")


# ============================================================================
# 🔨 КРАФТЫ. Рецепты и требования — в crafting.py, сами предметы — в
# shop_effects.CRAFT_ITEMS.
#
# Требование либо расходуется (предметы, монеты), либо только проверяется
# (титул, уровень питомца, ачивка). Расходуемое списывается ТОЛЬКО после того,
# как проверены все требования, а монеты уходят последними: если предметы уже
# списались, а монет не хватило, возвращать пришлось бы вручную.
# ============================================================================
CRAFT_LIST_TRIGGERS = {"крафты", "!крафты", "крафт", "!крафт", "рецепты"}
CRAFT_RE = ru_text.rx(r"(?i)^!?крафт\s+(\S+)(?:\s+(да))?$")
# Кукла — единственный рецепт с целью, поэтому и разбор свой: «крафт кукла
# @вася» в общий CRAFT_RE не влезает (там второй группой ждётся «да»).
CRAFT_DOLL_RE = ru_text.rx(r"(?i)^!?крафт\s+кукл[ауы](?:\s+(.+))?$")
DOLL_LIST_TRIGGERS = {"куклы", "!куклы", "мои куклы", "кукла", "!кукла"}
DOLL_PIN_RE = ru_text.rx(r"(?i)^!?закрепить\s+куклу(?:\s+(.+))?$")
DOLL_UNPIN_TRIGGERS = {"открепить куклу", "!открепить куклу"}


async def _craft_req_state(chat_id: int, user_id: int,
                           req) -> tuple[bool, str]:
    """(выполнено ли требование, как оно называется человеку).

    Один разбор на все виды: добавить новый — это ветка здесь и строка в
    рецепте, а не новое поле у всех рецептов сразу.
    """
    kind = req.kind
    if kind == crafting.REQ_ITEM:
        have = await db.get_inventory_quantity(chat_id, user_id, req.key)
        item = await db.get_shop_item(chat_id, req.key)
        name = (f"{item['emoji']} {item['name']}" if item else req.key)
        return have >= req.amount, crafting.req_text(req, item_name=name)
    if kind == crafting.REQ_COINS:
        wallet = await db.get_wallet(chat_id, user_id)
        return int(wallet.get("coins") or 0) >= req.amount, crafting.req_text(req)
    if kind == crafting.REQ_TITLE:
        if req.key:
            return await db.has_title(chat_id, user_id, req.key), crafting.req_text(req)
        return bool(await db.list_user_titles(chat_id, user_id)), crafting.req_text(req)
    if kind == crafting.REQ_PET_LEVEL:
        rows = await db.list_pets(chat_id, user_id)
        return (any(_pet_level(r) >= req.amount for r in rows),
                crafting.req_text(req))
    if kind == crafting.REQ_PET_EVOLVED:
        rows = await db.list_pets(chat_id, user_id)
        return any(r.get("evolved") for r in rows), crafting.req_text(req)
    if kind == crafting.REQ_ACHIEVEMENT:
        codes = await db.get_achievement_codes(chat_id, user_id)
        info = ACHIEVEMENTS.get(req.key) or {}
        return req.key in codes, crafting.req_text(
            req, achievement_name=info.get("title") or req.key)
    if kind == crafting.REQ_STARS:
        return (wallet_stars(await db.get_wallet(chat_id, user_id)) >= req.amount,
                crafting.req_text(req))
    if kind == crafting.REQ_PROF_LEVEL:
        stats = await db.get_profession_stats(chat_id, user_id)
        level = int(stats.get("prof_level") or 0) if stats.get("profession_key") else 0
        return level >= req.amount, crafting.req_text(req)
    # Неизвестный вид требования не пропускаем: молча разрешить крафт хуже,
    # чем сказать, что рецепт сломан.
    return False, crafting.req_text(req)


async def _craft_recipe_lines(chat_id: int, user_id: int,
                              recipe) -> tuple[bool, list[str]]:
    """(можно ли скрафтить, строки с галочками по каждому требованию)."""
    ready = True
    lines = []
    for req in recipe.reqs:
        ok, text = await _craft_req_state(chat_id, user_id, req)
        ready = ready and ok
        lines.append(f"   {'✅' if ok else '❌'} {text}")
    return ready, lines


# Куклу вуду описываем здесь, а не в shop_effects: это не предмет магазина —
# в инвентаре её нет, она живёт своей таблицей. Поля те же, что читает список
# крафтов, чтобы он не разбирал два разных случая.
class _DollSpec:
    emoji = "🧵"
    name = "Кукла вуду"
    description = ("Именной сувенир с лицом участника чата. Ничего не делает — "
                   "просто лежит и радует. Не теряется, не продаётся и не "
                   "крадётся: она вообще не в инвентаре")


DOLL_SPEC = _DollSpec()


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CRAFT_DOLL_RE.match(t.strip()))),
)
async def cmd_craft_doll(message: Message):
    """«крафт кукла @кому» — именной сувенир.

    Кукла НЕ кладётся в user_inventory, и это главное решение: по инвентарю
    ходят продажа, подарок, Медвежатник и лимит применений, а того, чего там
    нет, они физически не достанут. Список запретов пришлось бы дополнять при
    каждом новом способе отобрать предмет — про куклу такой способ просто не
    узнает.
    """
    if not _check_misc_access(message.from_user.id, "craft"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    recipe = crafting.BY_KEY["кукла"]
    target = await _target_for_item(
        message,
        "Использование: <code>крафт кукла @кому</code> "
        "(или ответом на его сообщение)."
    )
    if target is None:
        return
    existing = {int(d["target_id"]) for d in await db.list_voodoo_dolls(chat_id, user_id)}
    if target.id in existing:
        name = await display_name_by_id(chat_id, target.id)
        await message.reply(f"🧵 Кукла «{name}» у вас уже есть — вторая такая же "
                            f"ничего не добавит.")
        return
    await db.seed_extra_shop_items(chat_id, shop_effects.shop_rows())
    ready, lines = await _craft_recipe_lines(chat_id, user_id, recipe)
    if not ready:
        await message.reply("\n".join(
            [f"{DOLL_SPEC.emoji} <b>{DOLL_SPEC.name}</b>", DOLL_SPEC.description,
             DIVIDER, "Нужно:"] + lines + ["", "Чего-то не хватает — отмечено ❌."]))
        return
    if await is_account_frozen(chat_id, user_id):
        await message.reply("🧊 Ваш счёт заморожен администрацией.")
        return
    taken: list = []
    for req in recipe.consumed:
        if req.kind != crafting.REQ_ITEM:
            continue
        if not await db.remove_inventory_item(chat_id, user_id, req.key, req.amount):
            for done in taken:
                await db.add_inventory_item(chat_id, user_id, done.key, done.amount)
            await message.reply("Не хватило материалов — проверьте «инвентарь».")
            return
        taken.append(req)
    coins = sum(r.amount for r in recipe.consumed if r.kind == crafting.REQ_COINS)
    if coins and not await spend_coins(chat_id, user_id, coins):
        for done in taken:
            await db.add_inventory_item(chat_id, user_id, done.key, done.amount)
        await message.reply(f"Недостаточно монет: нужно {coins} i¢. "
                            f"Материалы остались у вас.")
        return
    # Имя храним БЕЗ разметки: display_name_by_id отдаёт HTML-ссылку, и она
    # при показе экранируется в теги прямо в тексте.
    target_name = plain_name(await display_name_by_id(chat_id, target.id))
    if not await db.add_voodoo_doll(chat_id, user_id, target.id, target_name,
                                    datetime.utcnow()):
        # Гонка: два «крафт кукла @вася» подряд. Возвращаем всё.
        for done in taken:
            await db.add_inventory_item(chat_id, user_id, done.key, done.amount)
        if coins:
            await db.add_coins(chat_id, user_id, coins)
        await message.reply("Такая кукла у вас уже есть.")
        return
    await db.add_log("craft_doll", chat_id=chat_id, actor_id=user_id,
                     details=str(target.id))
    actor_name = await display_name(chat_id, message.from_user)
    await message.answer(
        f"🧵 <b>{actor_name}</b> смастерил(а) куклу вуду с лицом "
        f"<b>{target_name}</b>.\nПросто на память, честное слово.\n"
        f"Свои куклы — <code>куклы</code>."
    )


async def _doll_link(chat_id: int, doll: dict) -> str:
    """Кликабельное имя того, с кого слеплена кукла.

    Ссылку строим ЖИВЬЁМ по target_id, а не храним готовую разметку: человек
    мог сменить ник или юзернейм, и сохранённая ссылка устарела бы. Хранимое
    имя остаётся запасным вариантом — на случай, если бот человека уже не
    видит.

    Возвращённое из display_name_by_id экранировать НЕЛЬЗЯ: оно уже готовая
    HTML-ссылка, и повторное экранирование выведет теги текстом (именно так и
    ломался список кукол).
    """
    try:
        return await display_name_by_id(chat_id, int(doll["target_id"]))
    except Exception as exc:
        log_suppressed("_doll_link", exc)
        return html.escape(plain_name(doll.get("target_name")))


async def _doll_names(chat_id: int, dolls: list[dict]) -> str:
    return ", ".join([await _doll_link(chat_id, d) for d in dolls])


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(DOLL_PIN_RE.match(t.strip()))),
)
async def cmd_doll_pin(message: Message):
    """«закрепить куклу @кому» — показывать сувенир в профиле.

    Закреп здесь ровно то же, чем он был у предметов до усиления: витрина.
    Кукла ничего не умеет, усиливать в ней нечего, и придумывать ей силу ради
    единообразия значило бы превратить сувенир в снаряжение.
    """
    if not _check_misc_access(message.from_user.id, "craft"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    dolls = await db.list_voodoo_dolls(chat_id, user_id)
    if not dolls:
        await message.reply("🧵 У вас нет ни одной куклы — "
                            "сделать: <code>крафт кукла @кому</code>")
        return
    target = await _target_for_item(
        message, "Использование: <code>закрепить куклу @кому</code> "
                 "(или ответом на его сообщение)."
    )
    if target is None:
        return
    doll = await db.get_voodoo_doll(chat_id, user_id, target.id)
    if doll is None:
        name = plain_name(await display_name_by_id(chat_id, target.id))
        await message.reply(f"🧵 Куклы «{html.escape(name)}» у вас нет — "
                            f"сделать: <code>крафт кукла @кому</code>")
        return
    await db.set_pinned_doll(chat_id, user_id, target.id)
    await message.reply(f"📌 Кукла «{await _doll_link(chat_id, doll)}» "
                        f"закреплена в профиле.")


