@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and ru_text.yo(t.strip().casefold()) in DOLL_LIST_TRIGGERS),
)
async def cmd_doll_list(message: Message):
    """«куклы» — своя коллекция сувениров (ответом — чужая)."""
