@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(MEGAFON_RE.match(t.strip()))),
)
async def cmd_megaphone(message: Message):
    """«мегафон» ответом на СВОЁ сообщение — закрепляет его на час.

    Именно реплай, а не «закрепит следующее»: отложенный вариант потребовал бы
    заглядывать в базу на каждом сообщении чата ради одного редкого предмета.
    """
    if not _check_misc_access(message.from_user.id, "item_megaphone"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    spec = await _require_item(message, "megafon")
    if spec is None:
        return
    src = message.reply_to_message
    if src is None:
        await message.reply(
            "Ответьте «мегафоном» на своё сообщение — то, которое нужно закрепить."
        )
        return
    if src.from_user is None or src.from_user.id != user_id:
        await message.reply("Мегафон закрепляет только ваши собственные сообщения.")
        return

    # Предмет списываем ПОСЛЕ успешного закрепления: прав на пин у бота может
    # не быть, и тогда покупка сгорела бы впустую.
    try:
        await bot.pin_chat_message(
            chat_id=chat_id, message_id=src.message_id, disable_notification=False
        )
    except Exception:
        logger.exception("Мегафон: не удалось закрепить сообщение")
        await message.reply(
            "📢 Не вышло закрепить — боту не хватает прав на закрепление сообщений. "
            "Мегафон остался у вас."
        )
        return

    await db.remove_inventory_item(chat_id, user_id, spec.key, 1)
    await db.add_log("megaphone", chat_id=chat_id, actor_id=user_id,
                     details=str(src.message_id))
    actor_name = await display_name(chat_id, message.from_user)
    await message.answer(
        f"📢 {actor_name} берёт мегафон — сообщение закреплено на "
        f"{format_duration_ru(timedelta(minutes=MEGAPHONE_PIN_MINUTES))}."
    )
    asyncio.create_task(_unpin_after(chat_id, src.message_id, MEGAPHONE_PIN_MINUTES))


async def _unpin_after(chat_id: int, message_id: int, minutes: int) -> None:
    """Снимает закреп мегафона по истечении срока. Отдельной задачей — как
    _schedule_event_end у событий чата."""
    try:
        await asyncio.sleep(minutes * 60)
        await bot.unpin_chat_message(chat_id=chat_id, message_id=message_id)
    except Exception as exc:
        log_suppressed("_unpin_after", exc)


# --- баланс предметов-событий ----------------------------------------------
# Ва-банк. Считать надо не «шанс меньше половины», а математическое ожидание:
# выигрыш даёт +100% кошелька, проигрыш забирает только треть, поэтому даже
# при 45% выходило +26.7% за применение — то есть станок, который печатает
# тем больше, чем толще кошелёк.
#
#   EV = p * 1.0 - (1 - p) * VABANK_LOSS_SHARE
#
# Ноль при p = 0.25; берём заметно ниже, чтобы ва-банк оставался азартной
# ставкой, а не способом заработка. Меняете числа — держите EV отрицательным,
# это проверяет тест в tests/test_event_items.py.
VABANK_WIN_CHANCE = 0.22
VABANK_LOSS_SHARE = 1 / 3
VABANK_MIN_COINS = 1_000
# Щедрость: фиксированная сумма делится на всех, а не выдаётся каждому. Иначе
# в большом чате один предмет вбрасывал бы в экономику сколько угодно монет.
GENEROSITY_COST = 30_000
GENEROSITY_MAX_TARGETS = 50


async def _is_item_pinned(chat_id: int, user_id: int, item_key: str) -> bool:
    card = await db.get_profile_card(chat_id, user_id)
    return bool(card and card.get("pinned_item") == item_key)


async def _spend_effect_item(chat_id: int, user_id: int, item_key: str,
                             pinned: bool) -> bool:
    """Списывает применённый предмет. True — штука ушла из инвентаря.

    Закреплённый расходуется раз в PIN_MULTIPLIER применений: у предметов с
    эффектом «лимит применений» — это само количество в инвентаре, поэтому
    впятеро больше применений и означает впятеро более редкий расход.

    Счётчик держим в общем KV-хранилище, а не в новой таблице: это одно число
    на связку чат-человек-предмет, и ради него городить схему незачем (так же
    сделана отметка «предмет за ачивку сегодня уже приносил доход»).
    """
    if not pinned:
        await db.remove_inventory_item(chat_id, user_id, item_key)
        return True
    stamp_key = f"pinuse:{chat_id}:{user_id}:{item_key}"
    row = await db.get_data(stamp_key)
    try:
        used = int((row or {}).get("data_value") or 0)
    except (TypeError, ValueError):
        used = 0
    used += 1
    if used < shop_effects.PIN_MULTIPLIER:
        await db.set_data(stamp_key, str(used), updated_by=user_id)
        return False
    # Пятое применение — штука уходит, счёт начинается заново.
    await db.set_data(stamp_key, "0", updated_by=user_id)
    await db.remove_inventory_item(chat_id, user_id, item_key)
    return True


async def _use_effect_item(message: Message, item_key: str) -> None:
    """Применяет полезный предмет (см. shop_effects) — на себя, без цели.

    Предмет списывается ТОЛЬКО если эффект реально сработал: чинить нечего —
    ремкомплект остаётся в инвентаре. Иначе человек тратил бы покупку впустую
    на опечатке или на исправном бизнесе.
    """
    chat_id, user_id = message.chat.id, message.from_user.id
    spec = shop_effects.BY_KEY.get(item_key) or shop_effects.ACHIEVEMENT_BY_KEY[item_key]

    inventory = await db.list_inventory(chat_id, user_id)
    if not any(i["item_key"] == item_key for i in inventory):
        await message.reply(
            f"У вас нет предмета «{html.escape(item_key)}». Проверьте «инвентарь»."
        )
        return

    # Закреп усиливает предмет впятеро (см. shop_effects.PIN_MULTIPLIER).
    # Считаем ОДИН раз здесь: ниже это нужно и заряду, и сумме, и расходу, а
    # три отдельных запроса за одним и тем же полем разошлись бы при правке.
    pinned = await _is_item_pinned(chat_id, user_id, item_key)

    result: Optional[str] = None

    if spec.effect == shop_effects.EFFECT_REPAIR:
        broken = [
            row for row in await db.list_user_businesses(chat_id, user_id)
            if row.get("broken_kind")
        ]
        if not broken:
            await message.reply("Ломаться нечему — все ваши бизнесы работают.")
            return
        row = broken[0]
        item = business_catalog.BY_KEY.get(row["business_key"])
        if not await db.repair_business(chat_id, user_id, row["business_key"],
                                        datetime.utcnow()):
            await message.reply("Бизнес уже починили — ремкомплект остался у вас.")
            return
        name = item.name if item else row["business_key"]
        result = f"🧰 {name} починен бесплатно. Доход пошёл заново."

    elif spec.effect == shop_effects.EFFECT_REFRESH:
        await db.reset_earning_cooldowns(chat_id, user_id)
        result = ("⚡ Кулдауны сброшены: ферма, рыбалка и клад доступны "
                  "прямо сейчас.")

    elif spec.effect == shop_effects.EFFECT_WORK_REFRESH:
        stats = await db.get_profession_stats(chat_id, user_id)
        if not stats.get("profession_key"):
            await message.reply(
                "Сначала устройтесь на работу: "
                "<code>!работа устроиться {профессия}</code>."
            )
            return
        await db.reset_work_cooldown(chat_id, user_id)
        result = "☕ Кулдаун смены сброшен — можно работать прямо сейчас."

    elif spec.effect == shop_effects.EFFECT_HEAL:
        stats = await db.get_profession_stats(chat_id, user_id)
        if not stats.get("profession_key"):
            await message.reply("Аптечка нужна работающим — профессии у вас пока нет.")
            return
        if all(int(stats.get(f) or 0) >= 100 for f in ("energy", "mood", "health")):
            await message.reply("Вы и так в полном порядке — аптечка не понадобилась.")
            return
        await db.restore_profession_state(chat_id, user_id)
        result = "⛑ Энергия, настроение и здоровье восстановлены до 100."

    elif spec.effect == shop_effects.EFFECT_ICE:
        now = datetime.utcnow()
        net = await db.list_net(chat_id, user_id)
        if not net:
            await message.reply(
                "🧊 Сетка пуста — лёд пересыпать нечем. Предмет остался у вас."
            )
            return
        # Лёд не «замораживает время», а обнуляет отсчёт порчи, поэтому на
        # полностью свежей сетке он не сделал бы ничего — и сгорел бы впустую.
        stale = [
            row for row in net
            if fishing.freshness((now - row["caught_at"]).total_seconds() / 3600) < 1.0
        ]
        if not stale:
            await message.reply(
                "🧊 Вся рыба в сетке и так свежая — лёд не понадобился."
            )
            return
        await db.refresh_net(chat_id, user_id, now)
        result = (f"🧊 Сетка пересыпана льдом: {len(stale)} шт. снова свежие. "
                  f"Можно спокойно ждать клёва.")

    elif spec.effect == shop_effects.EFFECT_EVENT_TICKET:
        if not await events_enabled(chat_id):
            await message.reply(
                "🎪 События в этом чате выключены — билету некуда сработать. "
                "Предмет остался у вас."
            )
            return
        if await get_active_event(chat_id) is not None:
            await message.reply(
                "🎪 В чате уже идёт событие — дождитесь, пока оно кончится. "
                "Билет остался у вас."
            )
            return
        # История нужна, чтобы билет не выдавал одно и то же подряд, — pick()
        # сам её и учитывает.
        state = await db.get_data(_events_state_key(chat_id))
        history = []
        if state:
            try:
                history = json.loads(state["data_value"]).get("history") or []
            except (ValueError, TypeError):
                history = []
        event = chat_events.pick(history)
        if event is None or not await fire_chat_event(chat_id, event):
            await message.reply(
                "🎪 Событие не завелось — попробуйте ещё раз. Билет остался у вас."
            )
            return
        result = "🎪 Билет предъявлен — событие объявлено выше!"

    elif spec.effect == shop_effects.EFFECT_VABANK:
        wallet = await db.get_wallet(chat_id, user_id)
        coins = int(wallet.get("coins") or 0)
        if coins < VABANK_MIN_COINS:
            await message.reply(
                f"🃏 Ва-банк идут с деньгами: нужно хотя бы {VABANK_MIN_COINS} i¢. "
                "Предмет остался у вас."
            )
            return
        actor = await display_name(chat_id, message.from_user)
        if random.random() < VABANK_WIN_CHANCE:
            await db.add_coins(chat_id, user_id, coins)
            await message.answer(
                f"🃏 {actor} идёт ва-банк на <b>{coins}</b> i¢…\n"
                f"🎉 <b>ОРЁЛ!</b> Кошелёк удвоен: теперь <b>{coins * 2}</b> i¢."
            )
        else:
            lost = int(coins * VABANK_LOSS_SHARE)
            await db.add_coins(chat_id, user_id, -lost)
            await message.answer(
                f"🃏 {actor} идёт ва-банк на <b>{coins}</b> i¢…\n"
                f"💀 <b>РЕШКА.</b> Минус <b>{lost}</b> i¢, осталось {coins - lost}."
            )
        await db.add_log("item_vabank", chat_id=chat_id, actor_id=user_id,
                         details=str(coins))
        # Объявление уже ушло в чат своим сообщением — общий хвост дублировать
        # его не должен, поэтому пустая строка вместо текста (см. конец функции).
        result = ""

    elif spec.effect == shop_effects.EFFECT_GENEROSITY:
        wallet = await db.get_wallet(chat_id, user_id)
        coins_now = int(wallet.get("coins") or 0)
        # Закреплённая щедрость раздаёт впятеро больше и столько же списывает.
        # Если на пятикратную сумму не хватает — раздаём обычную, а не
        # отказываем: предмет уже применён, и отказ был бы худшим исходом.
        cost = GENEROSITY_COST
        pin_boosted = False
        if pinned and coins_now >= GENEROSITY_COST * shop_effects.PIN_MULTIPLIER:
            cost = GENEROSITY_COST * shop_effects.PIN_MULTIPLIER
            pin_boosted = True
        if coins_now < GENEROSITY_COST:
            await message.reply(
                f"🎁 На широкий жест нужно {GENEROSITY_COST} i¢ в кошельке. "
                "Предмет остался у вас."
            )
            return
        # Потолок как у созыва (CALL_MAX_TARGETS): щедрость не должна
        # превращаться в рассылку по тысяче человек.
        targets = [
            int(r["user_id"])
            for r in await db.list_today_active_users(chat_id, utc_today())
            if int(r["user_id"]) != user_id
        ][:GENEROSITY_MAX_TARGETS]
        if not targets:
            await message.reply(
                "🎁 Сегодня в чате, кроме вас, никто не писал — дарить некому. "
                "Предмет остался у вас."
            )
            return
        share = max(1, cost // len(targets))
        await db.add_coins(chat_id, user_id, -cost)
        for uid in targets:
            await db.add_coins(chat_id, uid, share)
        actor = await display_name(chat_id, message.from_user)
        names = ", ".join([await display_name_by_id(chat_id, uid) for uid in targets[:15]])
        more = f" и ещё {len(targets) - 15}" if len(targets) > 15 else ""
        await db.add_log("item_generosity", chat_id=chat_id, actor_id=user_id,
                         details=f"{len(targets)}x{share}")
        boost = (f"\n📌 Закреплён — раздача в {shop_effects.PIN_MULTIPLIER} раз щедрее."
                 if pin_boosted else "")
        await message.answer(
            f"🎁 <b>{actor} угощает весь чат!</b>\n"
            f"По <b>{share}</b> i¢ получают: {names}{more}.{boost}"
        )
        result = ""

    elif spec.effect in shop_effects.PENDING_EFFECTS:
        # Отложенные эффекты и так живут зарядами — закрепу достаточно выдать
        # их сразу пять вместо одного.
        charges = shop_effects.PIN_MULTIPLIER if pinned else 1
        await db.add_item_effect(chat_id, user_id, spec.effect, charges=charges)
        times = f" (зарядов: {charges})" if charges > 1 else ""
        if spec.effect == shop_effects.EFFECT_LUCKY:
            result = (f"🍀 Талисман активирован: следующая ферма, рыбалка или клад "
                      f"принесут в {shop_effects.LUCKY_MULTIPLIER} раза больше{times}.")
        elif spec.effect == shop_effects.EFFECT_FREE_UPGRADE:
            result = ("📈 Бизнес-план готов: следующий апгрейд бизнеса "
                      f"обойдётся бесплатно{times}.")
        elif spec.effect == shop_effects.EFFECT_MIRROR:
            result = ("🪞 Зеркало повешено: ближайшее ограбление против вас "
                      f"отразится на самого грабителя{times}.")
        else:
            result = f"🛡 Страховка оформлена: ближайшая поломка бизнеса пройдёт мимо{times}."

    elif spec.effect == shop_effects.EFFECT_DAILY_CASH:
        # Предмет за ачивку не тратится — он остаётся навсегда, ограничение
        # только по времени: раз в сутки. Отметку держим в общем KV-хранилище,
        # отдельная таблица ради одной даты не нужна.
        stamp_key = f"itemdaily:{chat_id}:{user_id}:{item_key}"
        row = await db.get_data(stamp_key)
        today = utc_today().isoformat()
        if row and row.get("data_value") == today:
            await message.reply(
                f"{spec.emoji} «{spec.name}» сегодня уже приносил доход. "
                "Приходите завтра."
            )
            return
        payout = await _daily_item_payout(chat_id, user_id, spec.shifts)
        await db.set_data(stamp_key, today, updated_by=user_id)
        await db.add_coins(chat_id, user_id, payout)
        await db.add_log("item_daily", chat_id=chat_id, actor_id=user_id,
                         details=f"{item_key}:{payout}")
        await _check_coin_achievements(chat_id, user_id)
        await message.reply(
            f"{spec.emoji} «{spec.name}» принёс <b>{payout}</b> i¢ "
            f"(как {spec.shifts} смены).\nСледующий раз — завтра."
        )
        return

    if result is None:
        # У предметов с собственной командой (медвежатник, саботаж, компромат,
        # досье, мегафон) веток здесь нет — им нужна цель или реплай. Раньше
        # такой предмет отвечал «пока ничего не умеет», хотя всё он умеет,
        # просто вызывается иначе.
        if spec.effect in shop_effects.OWN_COMMAND_EFFECTS:
            hint = spec.description.split("Использовать:")[-1].strip() or spec.name
            await message.reply(
                f"{spec.emoji} «{spec.name}» применяется своей командой, а не "
                f"через «использовать»:\n{hint}"
            )
            return
        await message.reply("Этот предмет пока ничего не умеет.")
        return

    # Эффект сработал — только теперь предмет уходит. Медленный расход — это
    # усиление ТОЛЬКО для тех, кому нечего усилить иначе. Отложенным эффектам
    # закреп уже выдал пятикратные заряды, щедрости — пятикратную раздачу;
    # добавить им сюда ещё и пятикратный срок службы значило бы усилить их
    # в двадцать пять раз с одной штуки.
    slow_spend = (pinned
                  and spec.effect not in shop_effects.PENDING_EFFECTS
                  and spec.effect not in shop_effects.PIN_AMOUNT_EFFECTS)
    spent = await _spend_effect_item(chat_id, user_id, item_key, slow_spend)
    await db.add_log("item_effect", chat_id=chat_id, actor_id=user_id, details=item_key)
    # Пустая строка — предмет уже сам всё объявил в чат (ва-банк, щедрость):
    # общий хвост в таком случае повторил бы объявление одним эмодзи.
    if result:
        # Про усиление говорим только там, где оно не видно из самого текста:
        # у отложенных эффектов число зарядов уже названо, у щедрости —
        # приписка ушла вместе с объявлением в чат.
        note = ""
        if slow_spend:
            note = (f"\n📌 Закреплён — расходуется раз в "
                    f"{shop_effects.PIN_MULTIPLIER} применений"
                    + ("." if spent else ", штука осталась у вас."))
        await message.reply(f"{spec.emoji} {result}{note}")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(ITEM_USE_RE.match(t.strip()))),
)
async def cmd_item_use(message: Message):
    """«использовать {ключ} @username» (или ответом на сообщение) — применяет
    предмет из инвентаря на цель. У каждого предмета лимит 10 применений
    всего — после 10-го использования предмет полностью пропадает из
    инвентаря (независимо от quantity)."""
    if not _check_misc_access(message.from_user.id, "item_use"):
        return

    match = ITEM_USE_RE.match(message.text.strip())
    item_key = match.group(1).casefold()

    # Полезные предметы действуют НА СЕБЯ (ремкомплект чинит свой бизнес,
    # энергетик сбрасывает свои кулдауны) — цель им не нужна и требовать её
    # нельзя, иначе их вообще не применить. Уходят в отдельную ветку до
    # разбора цели.
    if shop_effects.effect_of(item_key):
        await _use_effect_item(message, item_key)
        return
    if shop_effects.is_reward(item_key):
        spec = shop_effects.ACHIEVEMENT_BY_KEY.get(item_key)
        if spec is not None and spec.effect == shop_effects.EFFECT_EVOLUTION:
            # Расходник, но со своей командой: общий ответ про «награду»
            # сбивал бы с толку — предмет как раз тратится, просто иначе.
            await message.reply(
                f"{spec.emoji} «{html.escape(spec.name)}» тратится не здесь, а "
                f"на эволюцию питомца: <code>пет эволюция {{ключ}}</code>."
            )
            return
        await message.reply(
            "🎖 Награду не «используют» — она просто есть у вас и видна в профиле."
        )
        return

    target, _remaining = await resolve_command_target(message, trigger_words=2)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Использование: <code>использовать {ключ} @username</code> (или ответом на сообщение).\n"
            "Посмотреть ключи предметов — «инвентарь»."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return
    if getattr(target, "is_bot", False):
        await message.reply("На ботов предметы не действуют 🤖")
        return

    chat_id, user_id = message.chat.id, message.from_user.id

    items = await db.list_inventory(chat_id, user_id)
    item = next((i for i in items if i["item_key"] == item_key), None)
    if item is None:
        await message.reply(f"У вас нет предмета «{html.escape(item_key)}». Проверьте «инвентарь».")
        return

    item_name = item.get("name") or item_key
    emoji = item.get("emoji") or "🎁"

    # Предмет за достижение не расходуется: применять его на людей можно
    # сколько угодно, счётчик применений ему просто не ведётся. Иначе
    # десятое применение сносило бы из инвентаря вещь, которую выдают
    # ровно один раз и вернуть нельзя.
    permanent = shop_effects.is_reward(item_key)
    new_count = 0 if permanent else await db.increment_item_usage(chat_id, user_id, item_key)

    actor_name = await display_name(chat_id, message.from_user)
    target_name = await display_name(chat_id, target)
    await message.answer(
        f"{emoji} {actor_name} использовал(а) «{html.escape(item_name)}» на {target_name}"
    )
    await db.add_log(
        "item_use", chat_id=chat_id, actor_id=user_id, target_id=target.id, details=item_key
    )

    if new_count >= db.ITEM_USE_LIMIT:
        await db.remove_inventory_item_completely(chat_id, user_id, item_key)
        await db.reset_item_usage(chat_id, user_id, item_key)

        # Предмет исчез из инвентаря целиком — если он был закреплён, снимаем закреп
        card = await db.get_profile_card(chat_id, user_id)
        if card and card.get("pinned_item") == item_key:
            await db.set_pinned_item(chat_id, user_id, None)

        await message.answer(
            f"⚠️ «{html.escape(item_name)}» исчерпал лимит применений ({db.ITEM_USE_LIMIT}) и пропал из инвентаря."
        )


SELL_ITEM_RE = ru_text.rx(r"(?i)^(?:!?магазин\s+продать|!продать)\s+(\S+)(?:\s+(\d+))?$")
# «!продать 500» одинаково похоже на продажу акций и на продажу предмета
# с ключом «500» — раньше эту форму молча забирал продавец предметов, и
# продажа акций была недостижима. Теперь голое число просит уточнения.
LEGACY_SELL_AMOUNT_RE = ru_text.rx(r"(?i)^!продать\s+(\S+)$")


def _is_legacy_sell_amount(text: str) -> bool:
    m = LEGACY_SELL_AMOUNT_RE.match(text.strip())
    if m is None:
        return False
    amount = parse_amount(m.group(1))
    return amount is not None and amount > 0


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and _is_legacy_sell_amount(t)),
)
async def cmd_legacy_sell_amount_hint(message: Message):
    arg = html.escape(LEGACY_SELL_AMOUNT_RE.match(message.text.strip()).group(1))
    await message.reply(
        "⚠️ Команда «!продать» разделена — уточните, что именно продаёте:\n"
        f"• <code>биржа продать {arg}</code> — акции на бирже\n"
        f"• <code>магазин продать {arg}</code> — предмет из инвентаря"
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(SELL_ITEM_RE.match(t.strip()))),
)
async def cmd_sell_item(message: Message):
    """«магазин продать {ключ} [количество]» — продаёт предмет(ы) из инвентаря за 80%
    их цены в магазине. Продать можно только предмет, который ни разу не
    использовался (см. item_usage / ITEM_USE_LIMIT)."""
    match = SELL_ITEM_RE.match(message.text.strip())
    item_key = match.group(1).casefold()
    amount = int(match.group(2)) if match.group(2) else 1
    if amount <= 0:
        await message.reply("Количество должно быть больше нуля.")
        return
    if shop_effects.is_reward(item_key):
        await message.reply("🎖 Награды не продаются — это знак отличия, а не товар.")
        return

    chat_id, user_id = message.chat.id, message.from_user.id

    items = await db.list_inventory(chat_id, user_id)
    item = next((i for i in items if i["item_key"] == item_key), None)
    if item is None:
        await message.reply(f"У вас нет предмета «{html.escape(item_key)}».")
        return
    if item["quantity"] < amount:
        await message.reply(f"У вас только {item['quantity']} шт. — не хватает, чтобы продать {amount}.")
        return

    used = await db.get_item_usage_count(chat_id, user_id, item_key)
    if used > 0:
        await message.reply("⚠️ Этот предмет уже был в использовании — продать его нельзя.")
        return

    shop_item = await db.get_shop_item(chat_id, item_key)
    if shop_item is None or shop_item.get("price") is None:
        await message.reply("Этот предмет нельзя продать — он не продаётся в магазине.")
        return

    price = int(shop_item["price"])
    total_sell = max(int(price * amount * 0.8), 0)

    ok = await db.remove_inventory_item(chat_id, user_id, item_key, amount)
    if not ok:
        await message.reply("Не удалось продать — попробуйте ещё раз.")
        return

    await db.add_coins(chat_id, user_id, total_sell)

    card = await db.get_profile_card(chat_id, user_id)
    if card and card.get("pinned_item") == item_key:
        remaining = await db.list_inventory(chat_id, user_id)
        if not any(i["item_key"] == item_key for i in remaining):
            await db.set_pinned_item(chat_id, user_id, None)

    item_name = shop_item["name"]
    emoji = shop_item.get("emoji") or "🎁"
    await message.reply(
        f"✅ Продано: {emoji} <b>{html.escape(item_name)}</b> × {amount} за <b>{total_sell}</b> i¢ "
        f"(80% от {price * amount} i¢)."
    )
    await db.add_log("item_sell", chat_id=chat_id, actor_id=user_id, details=f"{item_key}x{amount}")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold().split()[:2] == ["ферма", "урожайность"]),
)
async def cmd_farm_set_yield(message: Message):
    if not has_level(message.from_user.id, required_level("farm_yield_set")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Настраивать урожайность фермы может «{level_name(required_level('farm_yield_set'))}» и выше.")
        return
    parts = message.text.strip().split()
    if len(parts) < 3 or not parts[2].replace(".", "", 1).isdigit():
        await message.reply(
            "Использование: <code>ферма урожайность {число}</code> — множитель выдачи в % "
            "(100 — обычная сумма).\nНапример: <code>ферма урожайность 150</code>"
        )
        return
    percent = float(parts[2])
    percent = max(10.0, min(1000.0, percent))
    await db.set_farm_yield(message.chat.id, percent)
    await db.add_log("farm_yield_set", actor_id=message.from_user.id, details=f"{message.chat.id} -> {percent}")
    await message.reply(f"✅ Урожайность фермы этого чата: <b>{percent:g}%</b>.")



def _is_robbery_command(text: Optional[str]) -> bool:
    if not text or not text.strip():
        return False
    first = (text.strip().casefold().split() or [""])[0]
    return first in ("!ограбить", "ограбить")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_robbery_command),
)
async def cmd_robbery(message: Message):
    if not _check_misc_access(message.from_user.id, "robbery_run"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    if await event_flag(chat_id, chat_events.F_NO_ROBBERY):
        await message.reply("🚓 Комендантский час — на улицах патрули. Пока не грабим.")
        return
    stats = await db.get_robbery_stats(chat_id, user_id)
    if await db.is_under_surveillance(chat_id, user_id):
        await message.reply(
            "🚨 Вы под надзором — грабежи для вас недоступны.\n"
            f"Снять надзор: <code>откуп</code> ({robbery.SURVEILLANCE_PARDON_PRICE} i¢)."
        )
        return
    now = datetime.utcnow()
    last = stats.get("last_robbery_at")
    if last and (now - last) < robbery.ROBBERY_COOLDOWN:
        remaining = robbery.ROBBERY_COOLDOWN - (now - last)
        await message.reply(f"⏳ Слишком рано — следующая попытка через {format_duration_ru(remaining)}.")
        return

    text = message.text.strip()
    tokens = text.split(maxsplit=1)
    rest = tokens[1].strip() if len(tokens) > 1 else ""
    using_binokl = rest.casefold().startswith("бинокль")

    inventory = await db.list_inventory(chat_id, user_id)
    inv_qty = {i["item_key"]: i["quantity"] for i in inventory}

    victim_id: Optional[int] = None
    if using_binokl:
        if inv_qty.get("binokl", 0) <= 0:
            await message.reply("У вас нет 🔭 бинокля — купите его в «магазин».")
            return
        target_obj, _ = await resolve_command_target(message, trigger_words=2)
        if target_obj is None and message.reply_to_message:
            target_obj = message.reply_to_message.from_user
        if target_obj is None or target_obj.id is None:
            await message.reply("Укажите цель: «!ограбить бинокль @username» или ответом на его сообщение.")
            return
        if target_obj.id == user_id:
            await message.reply("Себя грабить бессмысленно 🙂")
            return
        if getattr(target_obj, "is_bot", False):
            await message.reply("Ботов грабить нет смысла 🤖")
            return
        victim_id = target_obj.id

    if victim_id is None:
        victim_row = await db.pick_random_robbery_victim(chat_id, user_id, robbery.ROBBERY_MIN_VICTIM_BALANCE)
        if victim_row is None:
            await message.reply("😔 Грабить некого — ни у кого поблизости нет достаточно денег.")
            return
        victim_id = victim_row["user_id"]

    victim_wallet = await db.get_wallet(chat_id, victim_id)
    victim_balance = int(victim_wallet.get("coins") or 0)
    if victim_balance < robbery.ROBBERY_MIN_VICTIM_BALANCE:
        await message.reply("😔 У этой цели слишком пусто в кошельке — грабить нечего.")
        return

    if using_binokl:
        await db.remove_inventory_item(chat_id, user_id, "binokl", 1)

    victim_inventory = await db.list_inventory(chat_id, victim_id)
    victim_bronik = next((i["quantity"] for i in victim_inventory if i["item_key"] == "bronik"), 0)
    actor_name = await display_name(chat_id, message.from_user)
    if victim_bronik > 0:
        await db.remove_inventory_item(chat_id, victim_id, "bronik", 1)
        await db.apply_robbery_blocked(chat_id, user_id, victim_id)
        await message.answer(
            f"🦺 {actor_name} попытался(-лась) кого-то ограбить, но жертву спас бронежилет — "
            "попытка провалилась без последствий."
        )
        return

    has_rabbit_paw = inv_qty.get("rabbit_paw", 0) > 0
    has_gold_pig = inv_qty.get("gold_pig", 0) > 0
    has_lucky_coin = inv_qty.get("lucky_coin", 0) > 0
    has_dymovushka = inv_qty.get("dymovushka", 0) > 0
    has_getaway_car = inv_qty.get("getaway_car", 0) > 0

    if has_rabbit_paw:
        await db.remove_inventory_item(chat_id, user_id, "rabbit_paw", 1)
    # Питомцы: «Подельник» помогает грабителю, «Телохранитель» — жертве.
    chance = robbery.success_chance(has_rabbit_paw)
    chance += await _pet_bonus(chat_id, user_id, "attack_robbery")
    chance -= await _pet_bonus(chat_id, victim_id, "guard_robbery")
    # Постоянные привилегии предметов за ачивки: «Мастер-отмычка» помогает
    # грабителю, «Портфель карьериста» защищает жертву. Ничего не тратится.
    chance += await _item_perk(chat_id, user_id, shop_effects.PERK_ROBBERY_ATTACK)
    chance -= await _item_perk(chat_id, victim_id, shop_effects.PERK_ROBBERY_DEFENSE)
    success = random.randint(1, 100) <= max(1, min(chance, 95))

    victim_name = await display_name_by_id(chat_id, victim_id)
    robber_wallet = await db.get_wallet(chat_id, user_id)

    # Зеркало жертвы разворачивает удачное ограбление на самого грабителя.
    # Проверяем ПОСЛЕ броска и только при успехе: провалившееся ограбление
    # отражать нечего, и тратить на него заряд было бы обидно.
    if success and await db.consume_item_effect(chat_id, victim_id, shop_effects.EFFECT_MIRROR):
        robber_balance = int(robber_wallet.get("coins") or 0)
        back = robbery.compute_steal_amount(robber_balance, False) if robber_balance else 0
        # Попытку записываем ТЕМ ЖЕ способом, что бронежилет: кулдаун
        # ограбления живёт в robbery_stats.last_robbery_at и ставится только
        # внутри apply_robbery_*. Без этой строки отражённое ограбление не
        # оставляло следа, и команду можно было жать подряд без остановки.
        await db.apply_robbery_blocked(chat_id, user_id, victim_id)
        if back:
            await db.add_coins(chat_id, user_id, -back)
            await db.add_coins(chat_id, victim_id, back)
        await db.add_log("robbery_mirrored", chat_id=chat_id, actor_id=user_id,
                         target_id=victim_id, details=str(back))
        await message.answer(
            f"🪞 {actor_name} полез(ла) в чужой карман — и наткнулся(-ась) на зеркало.\n"
            f"Ограбление развернулось: {victim_name} забирает у него(неё) <b>{back}</b> i¢."
        )
        return

    if success:
        amount = robbery.compute_steal_amount(victim_balance, has_gold_pig)
        # Налёт на банк (событие чата) удваивает добычу, но не больше того,
        # что у жертвы реально есть, — иначе кража ушла бы ей в минус.
        amount = min(
            max(1, round(amount * await event_multiplier(chat_id, chat_events.T_ROBBERY))),
            int(victim_balance),
        )
        baryga = await _pet_bonus(chat_id, user_id, "robbery_loot")
        if baryga:
            amount = min(int(victim_balance), amount + amount * baryga // 100)
        if has_gold_pig:
            await db.remove_inventory_item(chat_id, user_id, "gold_pig", 1)
        await db.apply_robbery_success(chat_id, user_id, victim_id, amount)
        await message.answer(f"🥷 {actor_name} успешно ограбил(а) {victim_name} на <b>{amount}</b> i¢!")
        stats = await db.get_robbery_stats(chat_id, user_id)
        if stats.get("successes", 0) >= 20:
            await grant_achievement(chat_id, user_id, "robber_20")
    else:
        loss = robbery.compute_fail_loss(int(robber_wallet.get("coins") or 0), has_lucky_coin, has_gold_pig)
        # «Золотой слиток» смягчает провал. Считаем ПОСЛЕ предметов-расходников:
        # это надстройка над готовой суммой, а не ещё одно слагаемое в формуле.
        loss_cut = await _item_perk(chat_id, user_id, shop_effects.PERK_FAIL_LOSS_CUT)
        if loss_cut:
            loss = max(0, round(loss * (100 - loss_cut) / 100))
        if has_lucky_coin:
            await db.remove_inventory_item(chat_id, user_id, "lucky_coin", 1)
        elif has_gold_pig:
            await db.remove_inventory_item(chat_id, user_id, "gold_pig", 1)
        await db.apply_robbery_fail(chat_id, user_id, loss)
        loss_text = f"потерял(а) {loss} i¢" if loss else "ничего не потерял(а)"

        has_pass = inv_qty.get(robbery.SURVEILLANCE_PASS_ITEM_KEY, 0) > 0
        surveillance_line = ""
        if await event_flag(chat_id, chat_events.F_NO_SURVEILLANCE):
            # Налёт на банк: полиции не до вас, провал не идёт в счёт надзора.
            surveillance_line = "\n🚨 Полиции сейчас не до вас — провал не пошёл в счёт надзора."
        elif has_pass:
            await db.remove_inventory_item(chat_id, user_id, robbery.SURVEILLANCE_PASS_ITEM_KEY, 1)
            surveillance_line = "\n🕶️ Отмазка сработала — этот провал не пошёл в счёт «под надзором»."
        else:
            strikes, newly_caught = await db.add_robbery_strike(
                chat_id, user_id, robbery.SURVEILLANCE_STRIKES_LIMIT
            )
            if newly_caught:
                surveillance_line = (
                    f"\n🚨 Вас поймали {strikes}-й раз — теперь вы <b>под надзором</b> и не можете "
                    f"грабить.\nСнять: <code>откуп</code> ({robbery.SURVEILLANCE_PARDON_PRICE} i¢)."
                )
            elif strikes < robbery.SURVEILLANCE_STRIKES_LIMIT:
                left = robbery.SURVEILLANCE_STRIKES_LIMIT - strikes
                surveillance_line = f"\n⚠️ Поимка {strikes}/{robbery.SURVEILLANCE_STRIKES_LIMIT} — ещё {left} и попадёте под надзор."

        if has_dymovushka:
            await db.remove_inventory_item(chat_id, user_id, "dymovushka", 1)
            await message.answer(
                f"💨 Кто-то попытался кого-то ограбить, но замешкался и {loss_text}. "
                f"Личность осталась загадкой.{surveillance_line}"
            )
        else:
            await message.answer(
                f"🚨 {actor_name} попытался(-лась) ограбить {victim_name}, не вышло — {loss_text}.{surveillance_line}"
            )

    if has_getaway_car:
        await db.remove_inventory_item(chat_id, user_id, "getaway_car", 1)
        await db.set_robbery_last_at(chat_id, user_id, datetime.utcnow() - robbery.ROBBERY_COOLDOWN / 2)


# ---------- Налёт на бизнес («налёт») ----------
# Второй вид ограбления: берёт из КОПИЛКИ бизнеса, а не из кошелька. Правила
# (надзор, предметы, комендантский час) те же, что у обычного ограбления —
# см. robbery.py, там же и числа. Свой у налёта только кулдаун: это отдельное
# занятие, и делить откат с обычным ограблением значило бы, что одно молча
# отменяет другое.
EARN_BUSINESS_RAID = "business_raid"
RAID_TRIGGERS = {"налёт", "налет", "!налёт", "!налет"}
RAID_RE = ru_text.rx(r"(?i)^!?(?:бизнес\s+)?нал[её]т\b")


def _is_raid_command(text: Optional[str]) -> bool:
    if not text:
        return False
    low = text.strip().casefold()
    return low in RAID_TRIGGERS or bool(RAID_RE.match(low))


async def _best_pot(chat_id: int, user_id: int) -> tuple[Optional[dict], int]:
    """Бизнес жертвы с самой полной копилкой и сколько в ней сейчас.

    Берём самый жирный, а не случайный: налёт — событие редкое, и попасть
    в пустой ларёк при полном аэропорте рядом выглядело бы как поломка.
    """
    best_row, best_pot = None, 0
    for row in await _load_businesses(chat_id, user_id):
        pot = _business_pending(row)
        if pot > best_pot:
            best_row, best_pot = row, pot
    return best_row, best_pot


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_raid_command),
)
async def cmd_business_raid(message: Message):
    if not _check_misc_access(message.from_user.id, "business_raid"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id

    if await event_flag(chat_id, chat_events.F_NO_ROBBERY):
        await message.reply("🚓 Комендантский час — на улицах патрули. Налёты отменяются.")
        return
    if await db.is_under_surveillance(chat_id, user_id):
        await message.reply(
            "🚨 Вы под надзором — налёты для вас недоступны.\n"
            f"Снять надзор: <code>откуп</code> ({robbery.SURVEILLANCE_PARDON_PRICE} i¢)."
        )
        return
    now = datetime.utcnow()
    row = await db.get_earning_activity(chat_id, user_id, EARN_BUSINESS_RAID)
    last = (row or {}).get("last_at")
    if last and (now - last) < robbery.RAID_COOLDOWN:
        left = robbery.RAID_COOLDOWN - (now - last)
        await message.reply(f"⏳ Слишком рано — следующий налёт через {format_duration_ru(left)}.")
        return

    # Цель: указанная (@username / ответом) либо самая жирная копилка в чате.
    target, _rest = await resolve_command_target(message, trigger_words=1)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    victim_id: Optional[int] = None
    if target is not None and target.id is not None:
        if target.id == user_id:
            await message.reply("Свой же бизнес? Он и так ваш 🙂")
            return
        if getattr(target, "is_bot", False):
            await message.reply("У ботов бизнеса нет 🤖")
            return
        victim_id = target.id
    else:
        candidates: dict[int, int] = {}
        for biz in await db.list_chat_businesses(chat_id):
            owner = int(biz["user_id"])
            if owner == user_id:
                continue
            candidates[owner] = max(candidates.get(owner, 0), _business_pending(biz))
        rich = [u for u, pot in candidates.items() if pot >= robbery.RAID_MIN_POT]
        if not rich:
            await message.reply("😔 Налетать не на что — у всех копилки пустые.")
            return
        victim_id = random.choice(rich)

    biz_row, pot = await _best_pot(chat_id, victim_id)
    if biz_row is None or pot < robbery.RAID_MIN_POT:
        await message.reply("😔 У этой цели в копилках пусто — брать нечего.")
        return

    item = business_catalog.BY_KEY.get(biz_row["business_key"])
    victim_name = await display_name_by_id(chat_id, victim_id)
    actor_name = await display_name(chat_id, message.from_user)

    # Кулдаун ставим ДО исхода: провалившийся налёт не должен позволять
    # повторить попытку немедленно — иначе кнопку жмут до победного.
    await db.touch_earning_activity(chat_id, user_id, EARN_BUSINESS_RAID, now)

    # Страховка бизнеса гасит налёт целиком. Тот же предмет, что спасает от
    # поломки: одна покупка — одна беда, какая придёт первой.
    if await db.consume_item_effect(chat_id, victim_id, shop_effects.EFFECT_SHIELD):
        await db.add_log("raid_blocked", chat_id=chat_id, actor_id=user_id,
                         target_id=victim_id, details=biz_row["business_key"])
        await message.answer(
            f"🛡 {actor_name} наведался(-ась) в чужой бизнес — но там оказалась "
            f"страховка. Налёт сорвался, страховка потрачена."
        )
        await _dm_or_none(
            victim_id,
            f"🛡 На ваш бизнес ({item.name if item else '—'}) был налёт. "
            f"Сработала страховка — деньги целы, страховка потрачена."
        )
        return

    inv_qty = {i["item_key"]: i["quantity"]
               for i in await db.list_inventory(chat_id, user_id)}
    has_rabbit_paw = inv_qty.get("rabbit_paw", 0) > 0
    has_gold_pig = inv_qty.get("gold_pig", 0) > 0
    has_lucky_coin = inv_qty.get("lucky_coin", 0) > 0
    if has_rabbit_paw:
        await db.remove_inventory_item(chat_id, user_id, "rabbit_paw", 1)

    # Охрана (оснащение бизнеса) сбивает шанс удачного налёта.
    guarded = business_catalog.UPGRADE_GUARD in (biz_row.get("upgrades") or set())
    chance = robbery.success_chance(has_rabbit_paw)
    if guarded:
        chance = max(1, chance - business_catalog.GUARD_RAID_PENALTY)
    # Питомцы: «Наводчик» помогает налётчику, «Сторож» — хозяину.
    chance += await _pet_bonus(chat_id, user_id, "attack_raid")
    chance -= await _pet_bonus(chat_id, victim_id, "guard_raid")
    chance = max(1, min(chance, 95))
    if random.randint(1, 100) <= chance:
        amount = robbery.compute_raid_amount(pot, has_gold_pig)
        skupshchik = await _pet_bonus(chat_id, user_id, "raid_loot")
        if skupshchik:
            amount = min(pot, amount + amount * skupshchik // 100)
        if has_gold_pig:
            await db.remove_inventory_item(chat_id, user_id, "gold_pig", 1)
        # Из копилки вычитаем ровно столько же, сколько отдали грабителю:
        # копилка пересчитывается лениво, поэтому её нужно зафиксировать
        # на этот момент, иначе украденное «отрастёт» задним числом.
        await db.set_business_accrual(chat_id, victim_id, biz_row["business_key"],
                                      max(0, pot - amount), now)
        await db.add_coins(chat_id, user_id, amount)
        await db.add_log("raid_success", chat_id=chat_id, actor_id=user_id,
                         target_id=victim_id, details=f"{biz_row['business_key']}:{amount}")
        await message.answer(
            f"🥷 {actor_name} вынес(ла) из бизнеса {victim_name} "
            f"<b>{amount}</b> i¢!\nБизнес: {item.name if item else biz_row['business_key']}."
        )
        # Жертве — в личку: иначе пропажу из копилки нечем объяснить, и она
        # выглядит как ошибка бота.
        await _dm_or_none(
            victim_id,
            f"🥷 На ваш бизнес ({item.name if item else '—'}) был налёт.\n"
            f"Из копилки унесли <b>{amount}</b> i¢. Осталось: {max(0, pot - amount)} i¢.\n"
            f"Защита от налётов — 🛡 страховка бизнеса в «магазин»."
        )
        return

    # Провал — по правилам обычного ограбления: потеря денег и надзор.
    wallet = await db.get_wallet(chat_id, user_id)
    loss = robbery.compute_fail_loss(int(wallet.get("coins") or 0),
                                     has_lucky_coin, has_gold_pig)
    # «Золотой слиток» смягчает провал и здесь: для человека это тот же
    # «провалился на деле», и правило должно работать одинаково в обоих.
    loss_cut = await _item_perk(chat_id, user_id, shop_effects.PERK_FAIL_LOSS_CUT)
    if loss_cut:
        loss = max(0, round(loss * (100 - loss_cut) / 100))
    if has_lucky_coin:
        await db.remove_inventory_item(chat_id, user_id, "lucky_coin", 1)
    elif has_gold_pig:
        await db.remove_inventory_item(chat_id, user_id, "gold_pig", 1)
    if loss:
        await db.add_coins(chat_id, user_id, -loss)

    surveillance_line = ""
    if await event_flag(chat_id, chat_events.F_NO_SURVEILLANCE):
        surveillance_line = "\n🚨 Полиции сейчас не до вас — провал не пошёл в счёт надзора."
    elif inv_qty.get(robbery.SURVEILLANCE_PASS_ITEM_KEY, 0) > 0:
        await db.remove_inventory_item(chat_id, user_id,
                                       robbery.SURVEILLANCE_PASS_ITEM_KEY, 1)
        surveillance_line = "\n🕶️ Отмазка сработала — провал не пошёл в счёт «под надзором»."
    else:
        strikes, newly_caught = await db.add_robbery_strike(
            chat_id, user_id, robbery.SURVEILLANCE_STRIKES_LIMIT
        )
        if newly_caught:
            surveillance_line = (
                f"\n🚨 Вас поймали {strikes}-й раз — теперь вы <b>под надзором</b>.\n"
                f"Снять: <code>откуп</code> ({robbery.SURVEILLANCE_PARDON_PRICE} i¢)."
            )
        elif strikes < robbery.SURVEILLANCE_STRIKES_LIMIT:
            left = robbery.SURVEILLANCE_STRIKES_LIMIT - strikes
            surveillance_line = (f"\n⚠️ Поимка {strikes}/{robbery.SURVEILLANCE_STRIKES_LIMIT} — "
                                 f"ещё {left} и попадёте под надзор.")

    await db.add_log("raid_fail", chat_id=chat_id, actor_id=user_id, target_id=victim_id)
    loss_text = f"потерял(а) {loss} i¢" if loss else "ничего не потерял(а)"
    await message.answer(
        f"🚨 {actor_name} попытался(-лась) обнести чужой бизнес, но попался(-ась). "
        f"Охрана вызвана, налётчик {loss_text}.{surveillance_line}"
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and ru_text.yo(t.strip().casefold()) in ("стата ограблений", "моя стата ограблений")),
)
async def cmd_robbery_stats(message: Message):
    if not _check_misc_access(message.from_user.id, "robbery_stats"):
        return
    target = message.reply_to_message.from_user if message.reply_to_message else message.from_user
    stats = await db.get_robbery_stats(message.chat.id, target.id)
    name = await display_name(message.chat.id, target)
    await message.reply(
        f"🥷 <b>Стата ограблений — {name}</b>\n{DIVIDER}\n"
        f"Попыток: {stats['attempts']} (успешных {stats['successes']}, неудачных {stats['fails']}, "
        f"заблокировано бронёй {stats['blocked']})\n"
        f"Награблено всего: {stats['stolen_total']} i¢\n"
        f"Потеряно на провалах: {stats['lost_total']} i¢\n"
        f"Обокрали вас: {stats['times_robbed']} раз(а), на {stats['money_lost_as_victim']} i¢"
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "топ грабителей"),
)
async def cmd_robbery_top(message: Message):
    if not _check_misc_access(message.from_user.id, "robbery_top"):
        return
    rows = await db.list_robbery_top(message.chat.id, limit=10)
    if not rows:
        await message.reply("Пока никто никого не ограбил.")
        return
    lines = ["🥷 <b>Топ грабителей</b>", DIVIDER]
    for i, row in enumerate(rows, start=1):
        name = await display_name_by_id(message.chat.id, row["user_id"])
        rate = f"{row['successes']}/{row['attempts']}" if row["attempts"] else "0/0"
        lines.append(f"{i}. {name} — награблено {row['stolen_total']} i¢ ({rate})")
    await message.reply("\n".join(lines))



@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and ru_text.yo(t.strip().casefold()) in ("!откуп", "купить откуп", "откуп")),
)
async def cmd_robbery_pardon(message: Message):
    if not _check_misc_access(message.from_user.id, "robbery_pardon"):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    if not await db.is_under_surveillance(chat_id, user_id):
        await message.reply("Вы и так не под надзором.")
        return
    price = robbery.SURVEILLANCE_PARDON_PRICE
    if not await spend_coins(chat_id, user_id, price):
        wallet = await db.get_wallet(chat_id, user_id)
        await message.reply(f"Недостаточно монет: у вас {wallet.get('coins', 0)} i¢, нужно {price}.")
        return
    await db.clear_robbery_surveillance(chat_id, user_id)
    await message.reply(f"✅ Откуп оплачен ({price} i¢) — надзор снят, можно грабить снова.")
    await db.add_log("robbery_pardon", chat_id=chat_id, actor_id=user_id)

# ============================================================================
# Казино: Рулетка (красное/чёрное/зелёное) — ставка i¢ из личного кошелька.
# Классическая механика: число 0-36, 0 — зелёное, остальные 18/18 по цветам.
# Выигрыш красное/чёрное — x2, зелёное — x14 (шанс всего 1/37, поэтому выше).
# ============================================================================
CASINO_COLOR_ALIASES = {
    "красное": "red", "красный": "red", "red": "red", "кр": "red", "р": "red",
    "черное": "black", "чёрное": "black", "черный": "black", "чёрный": "black",
    "black": "black", "чб": "black", "ч": "black",
    "зеленое": "green", "зелёное": "green", "зеленый": "green", "зелёный": "green",
    "green": "green", "зел": "green", "з": "green",
}
CASINO_COLOR_EMOJI = {"red": "🔴", "black": "⚫", "green": "🟢"}
CASINO_COLOR_LABEL = {"red": "Красное", "black": "Чёрное", "green": "Зелёное"}
# Рулетка вызывается просто словом «рулетка». Точка и «!» перед ним
# необязательны и оставлены ради тех, кто привык к старой форме «.рулетка».
# Со словом «русскаяру» (шуточная игра с киком) это не пересекается: у неё
# другое слово, а её переключатели «+рулетка»/«-рулетка» идут без аргументов.
CASINO_ROULETTE_RE = ru_text.rx(r"(?i)^[.!]?рулетка\s+(\S+)\s+(\S+)$")
# Голое «рулетка» без ставки — подсказка, а не игра: иначе человек, узнавший
# о команде, получает молчание и решает, что её нет.
CASINO_ROULETTE_BARE_RE = ru_text.rx(r"(?i)^[.!]?рулетка$")

_CASINO_ROULETTE_USAGE = (
    "🎰 <b>Рулетка</b>\n"
    "Использование: <code>рулетка {ставка} {цвет}</code>\n"
    "Цвет — красное / чёрное / зелёное.\n"
    "Например: <code>рулетка 100 красное</code>\n\n"
    "Красное и чёрное — x2, зелёное — x14.\n"
    "Играют с баланса казино: <code>казино баланс</code>, "
    "<code>казино пополнить {сумма}</code>."
)
CASINO_ROULETTE_MAX_BET = 100_000  # предохранитель от переполнения/абсурдных ставок
CASINO_DAILY_BONUS = 100
CASINO_MAX_BET = 100_000
CASINO_DICE_RE = ru_text.rx(r"(?i)^!кости\s+(\S+)\s+([1-6])$")
CASINO_COIN_RE = ru_text.rx(r"(?i)^!(орёл|орел|решка)\s+(\S+)$")
CASINO_POKER_RE = ru_text.rx(r"(?i)^!?покер\s+(\S+)$")
CASINO_TOPUP_RE = ru_text.rx(r"(?i)^!?казино\s+пополнить\s+(\S+)$")

@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CASINO_ROULETTE_BARE_RE.match(t.strip()))),
)
async def cmd_casino_roulette_help(message: Message):
    if not _check_misc_access(message.from_user.id, "casino_roulette"):
        return
    await message.reply(_CASINO_ROULETTE_USAGE)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CASINO_ROULETTE_RE.match(t.strip()))),
)
async def cmd_casino_roulette(message: Message):
    if not _check_misc_access(message.from_user.id, "casino_roulette"):
        return

    m = CASINO_ROULETTE_RE.match(message.text.strip())
    bet_amount = parse_amount(m.group(1))
    color = CASINO_COLOR_ALIASES.get(m.group(2).casefold())

    if color is None:
        await message.reply(_CASINO_ROULETTE_USAGE)
        return
    if bet_amount is None or bet_amount <= 0:
        await message.reply("Ставка должна быть больше нуля.")
        return
    if bet_amount > CASINO_ROULETTE_MAX_BET:
        await message.reply(f"Слишком большая ставка (максимум {CASINO_ROULETTE_MAX_BET} i¢).")
        return

    chat_id, user_id = message.chat.id, message.from_user.id
    # Играем с БАЛАНСА КАЗИНО — того же, что у костей, орла/решки и покера
    # (пополняется «казино пополнить»). Раньше рулетка была единственной игрой,
    # тянувшей деньги прямо из кошелька i¢: выигрыш в казино нельзя было
    # проиграть в казино, а вывод через «казино вывести» её не касался.
    #
    # Списание — одним атомарным запросом ДО розыгрыша, как и было. Заменять
    # его на «прочитать баланс, сравнить, потом вычесть» нельзя: две рулетки,
    # посланные подряд, обе прошли бы проверку с одними и теми же деньгами.
    if not await try_spend_casino(chat_id, user_id, bet_amount):
        wallet = await db.get_casino_wallet(chat_id, user_id)
        await message.reply(
            f"Недостаточно средств в казино: у вас {wallet['balance']} i¢, "
            f"ставка {bet_amount} i¢.\n"
            "Пополнить — <code>казино пополнить {сумма}</code>, "
            "бонус — <code>казино баланс</code>."
        )
        return

    number = random.randint(0, 36)
    result_color = roulette_number_color(number)

    if result_color == color:
        multiplier = 14 if color == "green" else 2
        winnings = bet_amount * multiplier
        delta = winnings - bet_amount  # ставка не сгорает, засчитывается в выигрыш
        # Фартовый час / крупье не в духе — событие чата множит только
        # выигрыш, ставка не трогается (см. chat_events.py).
        delta = max(1, round(delta * await event_multiplier(chat_id, chat_events.T_CASINO)))
        # «Везунчик» (питомец) прибавляет к выигрышу.
        delta = await _pet_lucky(chat_id, user_id, delta, "casino_win")
        # Ставка уже списана выше — возвращаем её вместе с выигрышем.
        new_balance = await db.add_casino_balance(chat_id, user_id, bet_amount + delta)
        outcome_text = f"✅ <b>Выигрыш!</b> +{delta} i¢ (x{multiplier})"
    else:
        # Ставка уже списана — доплачивать нечего.
        new_balance = (await db.get_casino_wallet(chat_id, user_id))["balance"]
        outcome_text = f"❌ <b>Проигрыш.</b> -{bet_amount} i¢"

    await message.answer(
        "🎰 <b>Казино: Рулетка</b>\n"
        f"{DIVIDER}\n"
        f"Ставка: {bet_amount} i¢ на {CASINO_COLOR_LABEL[color]}\n"
        f"Выпало: {CASINO_COLOR_EMOJI[result_color]} <b>{number}</b> ({CASINO_COLOR_LABEL[result_color]})\n"
        f"{outcome_text}\n"
        f"Баланс казино: {new_balance} i¢"
    )
    await db.add_log(
        "casino_roulette", chat_id=chat_id, actor_id=user_id,
        details=f"bet={bet_amount} color={color} number={number}",
    )
# ---------- Покер: оценка руки из 5 карт ----------
POKER_SUITS = "♠♥♦♣"
POKER_RANK_NAMES = {11: "J", 12: "Q", 13: "K", 14: "A"}


def _poker_rank_label(rank: int) -> str:
    return POKER_RANK_NAMES.get(rank, str(rank))


def _draw_poker_hand() -> list[tuple[int, str]]:
    deck = [(rank, suit) for rank in range(2, 15) for suit in POKER_SUITS]
    return random.sample(deck, 5)


def _evaluate_poker_hand(cards: list[tuple[int, str]]) -> tuple[int, str]:
    """(множитель выигрыша, название комбинации). 0 — без выигрыша."""
    ranks = sorted((r for r, _ in cards), reverse=True)
    suits = [s for _, s in cards]
    is_flush = len(set(suits)) == 1

    unique_ranks = sorted(set(ranks), reverse=True)
    is_straight = False
    if len(unique_ranks) == 5:
        if unique_ranks[0] - unique_ranks[4] == 4:
            is_straight = True
        elif unique_ranks == [14, 5, 4, 3, 2]:  # туз как низшая карта (А-2-3-4-5)
            is_straight = True

    counts: dict[int, int] = {}
    for r in ranks:
        counts[r] = counts.get(r, 0) + 1
    count_values = sorted(counts.values(), reverse=True)

    if is_straight and is_flush:
        return 10, "стрит-флеш"
    if count_values[0] == 4:
        return 10, "каре"
    if count_values[0] == 3 and count_values[1] == 2:
        return 8, "фулл-хаус"
    if is_flush:
        return 6, "флеш"
    if is_straight:
        return 5, "стрит"
    if count_values[0] == 3:
        return 3, "тройка"
    if count_values[0] == 2 and count_values[1] == 2:
        return 2, "две пары"
    return 0, "пусто (пара или меньше)"


def _format_poker_hand(cards: list[tuple[int, str]]) -> str:
    return " ".join(f"{_poker_rank_label(r)}{s}" for r, s in cards)


