CASINO_WITHDRAW_RE = ru_text.rx(r"(?i)^!?казино\s+вывести\s+(\S+)$")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CASINO_WITHDRAW_RE.match(t.strip()))),
)
async def cmd_casino_withdraw(message: Message):
    if not _check_misc_access(message.from_user.id, "casino_withdraw"):
        return
    amount = parse_amount(CASINO_WITHDRAW_RE.match(message.text.strip()).group(1))
    if amount is None or amount <= 0:
        await message.reply("Сумма вывода должна быть больше нуля.")
        return

    chat_id, user_id = message.chat.id, message.from_user.id
    wallet = await db.get_casino_wallet(chat_id, user_id)
    if int(wallet.get("balance", 0)) < amount:
        await message.reply(
            f"Недостаточно средств в казино: у вас {wallet.get('balance', 0)} i¢, нужно {amount}."
        )
        return

    await db.add_casino_balance(chat_id, user_id, -amount)
    new_balance = await db.add_coins(chat_id, user_id, amount)
    await message.reply(
        f"✅ Выведено {amount} i¢ из казино в кошелёк.\n"
        f"Баланс кошелька: {new_balance} i¢"
    )
    await db.add_log("casino_withdraw", chat_id=chat_id, actor_id=user_id, details=str(amount))


