# ---------- Казино: Кости ----------
@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CASINO_DICE_RE.match(t.strip()))),
)
async def cmd_casino_dice(message: Message):
    if not _check_misc_access(message.from_user.id, "casino_dice"):
        return
    m = CASINO_DICE_RE.match(message.text.strip())
    bet, guess = parse_amount(m.group(1)), int(m.group(2))
    if bet is None or bet <= 0 or bet > CASINO_MAX_BET:
        await message.reply(f"Ставка должна быть от 1 до {CASINO_MAX_BET} i¢.")
        return

    chat_id, user_id = message.chat.id, message.from_user.id
    wallet = await db.get_casino_wallet(chat_id, user_id)
    if wallet["balance"] < bet and not has_infinite_money(user_id):
        await message.reply(
            f"Недостаточно средств в казино: у вас {wallet['balance']} i¢. "
            "Проверьте бонус — «!казино баланс»."
        )
        return

    roll = random.randint(1, 6)
    if roll == guess:
        delta = bet * 6 - bet
        # Фартовый час / крупье не в духе — событие чата множит только
        # выигрыш, ставка не трогается (см. chat_events.py).
        delta = max(1, round(delta * await event_multiplier(chat_id, chat_events.T_CASINO)))
        # «Везунчик» (питомец) прибавляет к выигрышу.
        delta = await _pet_lucky(chat_id, user_id, delta, "casino_win")
        new_balance = await db.add_casino_balance(chat_id, user_id, delta)
        outcome = f"✅ <b>Выигрыш!</b> +{delta} i¢ (x6)"
    else:
        new_balance = await db.add_casino_balance(chat_id, user_id, -bet)
        outcome = f"❌ <b>Проигрыш.</b> -{bet} i¢"

    await message.answer(
        "🎲 <b>Казино: Кости</b>\n"
        f"{DIVIDER}\n"
        f"Ставка: {bet} i¢ на число {guess}\n"
        f"Выпало: 🎲 <b>{roll}</b>\n"
        f"{outcome}\n"
        f"Баланс казино: {new_balance} i¢"
    )
    await db.add_log(
        "casino_dice", chat_id=chat_id, actor_id=user_id,
        details=f"bet={bet} guess={guess} roll={roll}",
    )
    games_played = await db.increment_casino_games(chat_id, user_id)
    if games_played >= 100:
        await grant_achievement(chat_id, user_id, "casino_100_games")
    if roll == guess and delta >= 5000:
        await grant_achievement(chat_id, user_id, "casino_jackpot")


