# Модуль «Гонки» — ставки на лошадей, баланс общий с «!казино баланс».
# ============================================================================
RACE_CMD_RE = ru_text.rx(r"(?i)^!?гонки\s+(\S+)$")
RACE_JOIN_SECONDS = 15
RACE_STEPS = 15
RACE_TRACK_WIDTH = 15
RACE_TICK_SECONDS = 0.2

active_races: dict[int, dict] = {}


def _race_pick_kb(chat_id: int) -> InlineKeyboardMarkup:
    buttons = [
        InlineKeyboardButton(text=f"🐎 {i}", callback_data=f"race_pick:{chat_id}:{i}")
        for i in range(1, 6)
    ]
    return InlineKeyboardMarkup(inline_keyboard=[buttons])


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(RACE_CMD_RE.match(t.strip()))),
)
async def cmd_race_start(message: Message):
    amount = parse_amount(RACE_CMD_RE.match(message.text.strip()).group(1))
    if amount is None or amount <= 0:
        await message.reply("Не понял ставку. Например: <code>!гонки 300</code>")
        return
    if amount > CASINO_MAX_BET:
        await message.reply(f"Слишком большая ставка (максимум {CASINO_MAX_BET} i¢).")
        return

    chat_id, user_id = message.chat.id, message.from_user.id
    wallet = await db.get_casino_wallet(chat_id, user_id)
    if wallet["balance"] < amount:
        await message.reply(
            f"Недостаточно средств в казино: у вас {wallet['balance']} i¢. "
            "Пополнить — «!казино пополнить {сумма}», бонус — «!казино баланс»."
        )
        return

    race = active_races.get(chat_id)
    if race is not None and user_id in race["bets"]:
        await message.reply("Вы уже участвуете в текущем забеге.")
        return

    if race is None:
        weights = [random.randint(2, 10) for _ in range(5)]
        multipliers = [max(2, min(10, round(20 / w))) for w in weights]
        race = {"weights": weights, "multipliers": multipliers, "bets": {}, "pending": {}}
        active_races[chat_id] = race
        asyncio.create_task(_race_countdown(chat_id))
        lineup = "\n".join(f"{i}. 🐎 — выигрыш x{multipliers[i - 1]}" for i in range(1, 6))
        header = (
            "🐎 <b>Гонки начинаются!</b>\n\n"
            f"{lineup}\n\n"
            f"Ставки принимаются {RACE_JOIN_SECONDS} сек. Выберите лошадь для ставки {amount} i¢:"
        )
    else:
        header = f"🐎 Ставки ещё открыты. Выберите лошадь для ставки {amount} i¢:"

    race["pending"][user_id] = amount
    await message.answer(header, reply_markup=_race_pick_kb(chat_id))


@router.callback_query(F.data.startswith("race_pick:"))
async def cb_race_pick(callback: CallbackQuery):
    _, chat_id_s, horse_s = callback.data.split(":")
    chat_id, horse = int(chat_id_s), int(horse_s)
    race = active_races.get(chat_id)
    if race is None:
        await callback.answer("Гонка уже завершилась.", show_alert=True)
        return
    user_id = callback.from_user.id
    if user_id in race["bets"]:
        await callback.answer("Вы уже сделали ставку.", show_alert=True)
        return
    amount = race["pending"].pop(user_id, None)
    if amount is None:
        await callback.answer("Сначала укажите ставку: «!гонки 300».", show_alert=True)
        return
    wallet = await db.get_casino_wallet(chat_id, user_id)
    if wallet["balance"] < amount:
        await callback.answer("Недостаточно средств в казино.", show_alert=True)
        return
    await db.add_casino_balance(chat_id, user_id, -amount)
    race["bets"][user_id] = {"horse": horse, "amount": amount}
    name = await display_name_by_id(chat_id, user_id)
    await callback.answer(f"Ставка {amount} i¢ на лошадь {horse} принята!")
    try:
        await callback.message.edit_text(
            (callback.message.html_text or callback.message.text or "")
            + f"\n✅ {name} ставит {amount} i¢ на 🐎{horse}",
            reply_markup=_race_pick_kb(chat_id),
        )
    except TelegramBadRequest:
        pass


async def _race_countdown(chat_id: int) -> None:
    await asyncio.sleep(RACE_JOIN_SECONDS)
    race = active_races.get(chat_id)
    if race is None:
        return
    if not race["bets"]:
        active_races.pop(chat_id, None)
        try:
            await bot.send_message(chat_id, "🐎 Никто не сделал ставку — гонка отменена.")
        except Exception as exc:
            log_suppressed("_race_countdown", exc)
        return
    await _run_race(chat_id, race)


def _render_race_track(weights: list[int], positions: list[int]) -> str:
    lines = []
    for i, pos in enumerate(positions):
        pos = min(pos, RACE_TRACK_WIDTH)
        lines.append("—" * pos + f"🐎({weights[i]})")
    return "\n".join(lines)


async def _run_race(chat_id: int, race: dict) -> None:
    weights = race["weights"]
    multipliers = race["multipliers"]
    positions = [0] * len(weights)

    try:
        msg = await bot.send_message(
            chat_id, "🏁 <b>Старт!</b>\n\n" + _render_race_track(weights, positions)
        )
    except Exception:
        active_races.pop(chat_id, None)
        return

    winner = None
    for _step in range(RACE_STEPS):
        await asyncio.sleep(RACE_TICK_SECONDS)
        for i in range(len(weights)):
            if positions[i] >= RACE_TRACK_WIDTH:
                continue
            positions[i] += random.randint(2, 10)
        try:
            await msg.edit_text("🏁 <b>Гонка!</b>\n\n" + _render_race_track(weights, positions))
        except TelegramBadRequest:
            pass
        finishers = [i for i, p in enumerate(positions) if p >= RACE_TRACK_WIDTH]
        if finishers:
            winner = finishers[0]
            break

    if winner is None:
        winner = positions.index(max(positions))

    winner_num = winner + 1
    multiplier = multipliers[winner]

    lines = [f"🏆 <b>Победила лошадь 🐎{winner_num}!</b> (x{multiplier})", ""]
    for user_id, bet in race["bets"].items():
        name = await display_name_by_id(chat_id, user_id)
        won = bet["horse"] == winner_num
        if won:
            win_amount = bet["amount"] * multiplier
            await db.add_casino_balance(chat_id, user_id, win_amount)
            lines.append(f"✅ {name} выиграл(а) {win_amount} i¢!")
        else:
            lines.append(f"❌ {name} проиграл(а) {bet['amount']} i¢.")
        stats = await db.record_race_bet(chat_id, user_id, won)
        if won:
            await grant_achievement(chat_id, user_id, "race_win")
            if stats and stats.get("wins", 0) >= 10:
                await grant_achievement(chat_id, user_id, "race_master")

    try:
        await bot.send_message(chat_id, "\n".join(lines))
    except Exception as exc:
        log_suppressed("_run_race", exc)

    await db.add_log("race_finished", chat_id=chat_id, details=f"winner={winner_num}")
    active_races.pop(chat_id, None)
def roulette_number_color(n: int) -> str:
    if n == 0:
        return "green"
    return "red" if n in RED_ROULETTE_NUMBERS else "black"
