def _stock_holding_lines(price: float, holding: dict) -> list[str]:
    shares = float(holding["shares"])
    invested = int(holding["invested"])
    current_value = shares * price
    pending = float(holding["pending_dividends"])
    profit_total = int(holding["total_profit"])
    lines = [
        f"📈 Ваши акции: {shares:.4f} шт. на сумму {current_value:.0f} i¢",
        f"💼 Вложено: {invested} i¢ / {STOCK_MAX_INVEST} i¢",
    ]
    if pending > 0:
        lines.append(f"💰 Накопленные дивиденды: {pending:.0f} i¢ (забрать — «биржа дивиденды»)")
    lines.append(f"🏆 Всего заработано на бирже: {profit_total} i¢")
    return lines


# Команды биржи сгруппированы под общим словом-разделом «биржа» («!» перед
# ним необязателен), чтобы «купить»/«продать» нельзя было спутать с магазином.
# Старые одиночные формы «!купить»/«!продать» неоднозначны и теперь отвечают
# подсказкой (cmd_legacy_buy_hint / cmd_legacy_sell_amount_hint), а «!дивиденды»
# однозначна и работает молчаливым алиасом.
STOCK_BUY_RE = ru_text.rx(r"(?i)^!?биржа\s+купить(?:\s+(\S+))?$")
STOCK_SELL_RE = ru_text.rx(r"(?i)^!?биржа\s+продать(?:\s+(\S+))?$")
STOCK_TOGGLE_RE = ru_text.rx(r"(?i)^!?биржа\s+(вкл|включить|выкл|выключить)$")


async def _stock_off(message: Message) -> bool:
    """True (и ответ в чат), если биржа в этом чате выключена.

    Стоит во всех четырёх пользовательских командах биржи, а не только в
    «биржа»: выключенная биржа заморожена целиком, иначе «биржа продать»
    работала бы в чате, где биржи как бы нет.
    """
    if await db.is_stock_enabled(message.chat.id):
        return False
    await message.reply(
        "🔒 Биржа в этом чате выключена.\n"
        "Купленные акции и накопленные дивиденды никуда не делись — они ждут, "
        "пока администрация включит биржу обратно (<code>биржа вкл</code>)."
    )
    return True


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(STOCK_TOGGLE_RE.match(t.strip()))),
)
async def cmd_stock_toggle(message: Message):
    """«биржа вкл» / «биржа выкл» — выключатель биржи в отдельном чате.

    Выключение НИЧЕГО не отнимает: акции остаются на руках, дивиденды —
    накопленными. Просто курс замирает и команды биржи перестают работать
    до включения обратно.
    """
    if not has_level(message.from_user.id, required_level("stock_toggle")):
        if get_level(message.from_user.id) > 0:
            await message.reply(
                f"⛔ Включать и выключать биржу может «{level_name(required_level('stock_toggle'))}» и выше."
            )
        return
    word = STOCK_TOGGLE_RE.match(message.text.strip()).group(1).casefold()
    enabled = word in ("вкл", "включить")
    if await db.is_stock_enabled(message.chat.id) == enabled:
        await message.reply(
            f"Биржа в этом чате и так {'включена' if enabled else 'выключена'}."
        )
        return
    await db.set_stock_enabled(message.chat.id, enabled)
    await db.add_log(
        "stock_toggle", chat_id=message.chat.id, actor_id=message.from_user.id,
        details="вкл" if enabled else "выкл",
    )
    if enabled:
        await message.answer(
            "✅ <b>Биржа включена.</b>\n"
            "Курс снова начнёт меняться с ближайшего часа, дивиденды — капать."
        )
    else:
        await message.answer(
            "🔒 <b>Биржа выключена.</b>\n"
            "Курс заморожен, дивиденды не начисляются, команды биржи не работают.\n"
            "Акции и накопленные дивиденды сохранены — вернуть всё как было: "
            "<code>биржа вкл</code>."
        )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and ru_text.yo(t.strip().casefold()) in ("!биржа", "биржа")),
)
async def cmd_stock_market(message: Message):
    if not _check_misc_access(message.from_user.id, "stock_market"):
        return
    if await _stock_off(message):
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    price = await db.get_stock_price(chat_id)
    holding = await db.get_stock_holding(chat_id, user_id)

    lines = [
        "📊 <b>Биржа</b>",
        DIVIDER,
        f"💹 Текущий курс акций: <b>{price:.2f}</b> i¢/акция",
        "",
    ]
    lines.extend(_stock_holding_lines(price, holding))
    lines.append("")
    lines.append("<code>биржа купить {сумма}</code> · <code>биржа продать {сумма}</code> · <code>биржа дивиденды</code>")
    await message.answer("\n".join(lines))


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(STOCK_BUY_RE.match(t.strip()))),
)
async def cmd_stock_buy(message: Message):
    if not _check_misc_access(message.from_user.id, "stock_market"):
        return
    if await _stock_off(message):
        return
    raw = STOCK_BUY_RE.match(message.text.strip()).group(1)
    amount = parse_amount(raw) if raw else None
    if amount is None or amount <= 0:
        await message.reply("Использование: <code>биржа купить {сумма}</code>\nНапример: <code>биржа купить 500</code> или <code>биржа купить 5к</code>")
        return

    
    chat_id, user_id = message.chat.id, message.from_user.id
    holding = await db.get_stock_holding(chat_id, user_id)
    if int(holding["invested"]) + amount > STOCK_MAX_INVEST:
        available = STOCK_MAX_INVEST - int(holding["invested"])
        await message.reply(
            f"⚠️ Максимум вложений на человека — {STOCK_MAX_INVEST} i¢. "
            f"Сейчас можно вложить ещё максимум {max(available, 0)} i¢."
        )
        return

    if not await spend_coins(chat_id, user_id, amount):
        await message.reply(f"Недостаточно монет: нужно {amount} i¢.")
        return

    price = await db.get_stock_price(chat_id)
    holding = await db.buy_stock(chat_id, user_id, amount, price)
    await db.add_log("stock_buy", chat_id=chat_id, actor_id=user_id, details=f"{amount}@{price:.2f}")

    shares_bought = amount / price
    await message.reply(
        f"✅ Куплено {shares_bought:.4f} акций по курсу {price:.2f} i¢ на сумму {amount} i¢.\n"
        f"Всего вложено: {int(holding['invested'])}/{STOCK_MAX_INVEST} i¢."
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(STOCK_SELL_RE.match(t.strip()))),
)
async def cmd_stock_sell(message: Message):
    if not _check_misc_access(message.from_user.id, "stock_market"):
        return
    if await _stock_off(message):
        return
    raw = STOCK_SELL_RE.match(message.text.strip()).group(1)
    amount = parse_amount(raw) if raw else None
    if amount is None or amount <= 0:
        await message.reply("Использование: <code>биржа продать {сумма}</code>\nНапример: <code>биржа продать 300</code> или <code>биржа продать 3к</code>")
        return

    chat_id, user_id = message.chat.id, message.from_user.id
    price = await db.get_stock_price(chat_id)
    result = await db.sell_stock(chat_id, user_id, amount, price)
    if result is None:
        holding = await db.get_stock_holding(chat_id, user_id)
        current_value = float(holding["shares"]) * price
        await message.reply(
            f"⚠️ У вас акций максимум на {current_value:.0f} i¢ — столько продать нельзя."
        )
        return

    await db.add_coins(chat_id, user_id, amount)
    await db.add_log("stock_sell", chat_id=chat_id, actor_id=user_id, details=f"{amount}@{price:.2f}")

    profit = result["profit"]
    profit_text = f"прибыль +{profit:.0f} i¢" if profit > 0 else (
        f"убыток {profit:.0f} i¢" if profit < 0 else "без прибыли и убытка"
    )
    await message.reply(f"✅ Продано акций на {amount} i¢ по курсу {price:.2f} ({profit_text}).")

    holding = await db.get_stock_holding(chat_id, user_id)
    if int(holding["total_profit"]) >= 1000:
        await grant_achievement(chat_id, user_id, "investor")


