def _bank_auto_reject_key(chat_id: int) -> str:
    return f"bank_autoreject:{chat_id}"


async def is_bank_auto_reject_enabled(chat_id: int) -> bool:
    row = await db.get_data(_bank_auto_reject_key(chat_id))
    return row is not None and row.get("data_value") == "1"


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and ru_text.yo(t.strip().casefold()) in ("+банк автоотказ-кредит", "-банк автоотказ-кредит")),
)
async def cmd_bank_auto_reject_toggle(message: Message):
    min_level = required_level("bank_auto_reject_toggle")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше.")
        return
    enable = message.text.strip().casefold() == "+банк автоотказ-кредит"
    key = _bank_auto_reject_key(message.chat.id)
    if enable:
        await db.set_data(key, "1", updated_by=message.from_user.id)
        await message.reply(
            "🚫 Автоотказ кредитов включён — новые заявки на кредит теперь отклоняются "
            "автоматически, без рассмотрения администраторами."
        )
    else:
        await db.delete_data(key)
        await message.reply("✅ Автоотказ кредитов выключен — заявки снова идут на рассмотрение администраторам.")
    await db.add_log(
        "bank_auto_reject_toggle", chat_id=message.chat.id, actor_id=message.from_user.id, details=str(enable)
    )


BANK_BLACKLIST_ADD_RE = ru_text.rx(r"(?i)^банк\s+чс\s+добавить\b\s*(.*)$")
BANK_BLACKLIST_REMOVE_RE = ru_text.rx(r"(?i)^банк\s+чс\s+удалить\b\s*(.*)$")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(BANK_BLACKLIST_ADD_RE.match(t.strip()))),
)
async def cmd_bank_blacklist_add(message: Message):
    min_level = required_level("bank_blacklist_manage")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше.")
        return
    target, _remaining = await resolve_command_target(message, trigger_words=2)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply("Укажите цель: ответом на сообщение или @username/ID сразу после «банк чс добавить».")
        return
    if target.id is None:
        await message.reply(f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате.")
        return
    added = await db.add_bank_blacklist(message.chat.id, target.id, message.from_user.id)
    name = await display_name_by_id(message.chat.id, target.id)
    if added:
        await message.reply(f"🚫 {name} добавлен(а) в чёрный список банка — кредиты недоступны.")
        await db.add_log("bank_blacklist_add", chat_id=message.chat.id, actor_id=message.from_user.id, target_id=target.id)
    else:
        await message.reply(f"{name} уже в чёрном списке банка.")


