@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(TITLE_BUY_RE.match(t.strip()))),
)
async def cmd_title_buy(message: Message):
    if not _check_misc_access(message.from_user.id, "title_buy"):
        return
    key = TITLE_BUY_RE.match(message.text.strip()).group(1).casefold()
    title = await db.get_title(key)
    if title is None or title.get("price") is None:
        await message.reply("Такого титула нет в продаже. Список — «титул».")
        return

    chat_id, user_id = message.chat.id, message.from_user.id
    if await db.has_title(chat_id, user_id, key):
        await message.reply("У вас уже есть этот титул.")
        return

    if not await spend_coins(chat_id, user_id, title["price"]):
        await message.reply(f"Недостаточно монет: нужно {title['price']} i¢.")
        return
    await db.grant_title(chat_id, user_id, key)
    await db.add_log("title_bought", chat_id=chat_id, actor_id=user_id, details=key)
    await message.reply(f"✅ Куплено: {title['name']} за {title['price']} i¢.\nНадеть: «титул надеть {key}»")


