@router.message(StateFilter(AdminStates.waiting_shop_new_stock), F.chat.type == "private")
async def shop_add_stock(message: Message, state: FSMContext):
    raw = (message.text or "").strip()
    if raw == BTN_SHOP_UNLIMITED:
        stock = None
    elif raw.isdigit() and int(raw) >= 0:
        stock = int(raw)
    else:
        await message.answer(
            f"Нужно неотрицательное целое число, либо «{BTN_SHOP_UNLIMITED}».",
            reply_markup=_reply_kb([[BTN_SHOP_UNLIMITED], [BTN_CANCEL]]),
        )
        return
    await state.update_data(shop_stock=stock)
    await state.set_state(AdminStates.waiting_shop_new_description)
    await message.answer("Добавьте короткое описание товара (или «Пропустить»):",
                          reply_markup=_reply_kb([["Пропустить"], [BTN_CANCEL]]))


@router.message(StateFilter(AdminStates.waiting_shop_new_description), F.chat.type == "private")
async def shop_add_description(message: Message, state: FSMContext):
    raw = (message.text or "").strip()
    description = None if raw == "Пропустить" else raw[:255]
    data = await state.get_data()
    chat_id = _shop_chat_id()
    ok = await db.add_shop_item(
        chat_id, data["shop_key"], data["shop_name"], data["shop_price"],
        description=description, stock=data.get("shop_stock"),
    )
    await state.clear()
    if not ok:
        await message.answer("⚠️ Не удалось добавить товар — возможно, ключ уже занят.")
    else:
        stock_text = "без лимита" if data.get("shop_stock") is None else f"{data['shop_stock']} шт."
        await message.answer(f"✅ Товар «{html.escape(data['shop_name'])}» добавлен: {data['shop_price']} i¢, {stock_text}.")
        await db.add_log("shop_item_added", chat_id=chat_id, actor_id=message.from_user.id, details=data["shop_key"])
    await _show_shop_menu(message, state)


