# ============================================================================
# Модуль «Лутбоксы» — случайные коробки за i¢, дающие случайный предмет из
# магазина ЭТОГО чата или случайный титул (глобальный каталог, см. «Титулы»).
# Пять уровней редкости с разной ценой и разным шансом попасть в «дорогой»
# пул (LOOTBOX_TYPES ниже). Ассортимент не хардкодится: пул каждый раз
# собирается заново из ТЕКУЩЕГО магазина чата + всех купленных титулов —
# если админ добавил новый товар в магазин, он сразу участвует в лутбоксах.
# Внутри пула шанс предмета обратно пропорционален его цене — чем дороже
# вещь, тем реже она выпадает, даже среди «редкого» набора.
# ============================================================================
LOOTBOX_TYPES: dict[str, dict] = {
    "common":    {"name": "Обычный",     "emoji": "🟢", "price": 500,   "rare_chance": 5},
    "uncommon":  {"name": "Необычный",   "emoji": "🔵", "price": 2000,  "rare_chance": 15},
    "rare":      {"name": "Редкий",      "emoji": "🟣", "price": 5000,  "rare_chance": 35},
    "epic":      {"name": "Эпический",   "emoji": "🟠", "price": 10000, "rare_chance": 60},
    "legendary": {"name": "Легендарный", "emoji": "🔴", "price": 25000, "rare_chance": 85},
}
LOOTBOX_ORDER = ["common", "uncommon", "rare", "epic", "legendary"]
LOOTBOX_ALIASES: dict[str, str] = {
    "обычный": "common", "обычные": "common", "обычная": "common", "common": "common", "1": "common",
    "необычный": "uncommon", "необычные": "uncommon", "uncommon": "uncommon", "2": "uncommon",
    "редкий": "rare", "редкие": "rare", "rare": "rare", "3": "rare",
    "эпический": "epic", "эпические": "epic", "epic": "epic", "4": "epic",
    "легендарный": "legendary", "легендарные": "legendary", "legendary": "legendary", "5": "legendary",
}
LOOTBOX_MAX_PER_COMMAND = 20     # предохранитель: не купить/не открыть 100000 за раз
LOOTBOX_RARE_POOL_SHARE = 0.25   # доля самых дорогих позиций каталога — это «редкий» пул


def _lootbox_resolve_rarity(token: str) -> Optional[str]:
    return LOOTBOX_ALIASES.get(token.strip().casefold())


async def _lootbox_build_pools(chat_id: int) -> tuple[list[dict], list[dict]]:
    """Собирает пул наград лутбокса из ТЕКУЩЕГО ассортимента: активные товары
    магазина этого чата + все титулы с ценой (титулы, выдаваемые только за
    ачивку — price IS NULL — в лутбоксах не участвуют, их нельзя купить).
    Возвращает (common_pool, rare_pool) — топ LOOTBOX_RARE_POOL_SHARE по цене
    уходит в rare_pool, остальное в common_pool (rare_pool не бывает пустым,
    если пул вообще не пуст).

    Если магазин чата ещё ни разу не открывали — досеиваем его дефолтным
    ассортиментом (как это делает shop_list_page), чтобы лутбокс не оказался
    пустым просто потому, что никто ещё не писал «магазин» в этом чате.
    """
    await db.seed_default_shop_items(chat_id)
    # Дозасев (не требует пустого магазина): так новые товары доезжают
    # и в чаты, где магазин давно наполнен, — иначе они не появились бы
    # никогда, ведь seed_default_shop_items у непустого магазина молчит.
    await db.seed_extra_shop_items(chat_id, robbery.ROBBERY_SHOP_ITEMS)
    await db.seed_extra_shop_items(chat_id, shop_effects.shop_rows())
    await db.seed_extra_shop_items(chat_id, pets_catalog.SHOP_ITEMS)

    pool: list[dict] = []
    for item in await db.list_shop_items(chat_id, active_only=True):
        pool.append({
            "kind": "item", "key": item["item_key"], "name": item["name"],
            "emoji": item.get("emoji") or "🎁", "price": int(item["price"]),
        })
    for title in await db.list_titles():
        if title.get("price") is not None:
            pool.append({
                "kind": "title", "key": title["title_key"], "name": title["name"],
                "emoji": "🎖", "price": int(title["price"]),
            })
    if not pool:
        return [], []

    pool.sort(key=lambda x: x["price"], reverse=True)
    rare_count = max(1, round(len(pool) * LOOTBOX_RARE_POOL_SHARE))
    rare_pool = pool[:rare_count]
    common_pool = pool[rare_count:] or rare_pool
    return common_pool, rare_pool


def _lootbox_weighted_pick(pool: list[dict]) -> dict:
    weights = [1 / max(entry["price"], 1) for entry in pool]
    return random.choices(pool, weights=weights, k=1)[0]


async def _lootbox_grant(chat_id: int, user_id: int, reward: dict) -> str:
    """Выдаёт награду, возвращает короткую пометку для сообщения (например,
    если титул уже был — вместо повтора выдаётся компенсация i¢)."""
    if reward["kind"] == "item":
        await db.add_inventory_item(chat_id, user_id, reward["key"], 1)
        return ""
    already = await db.has_title(chat_id, user_id, reward["key"])
    if already:
        compensation = max(reward["price"] // 2, 1)
        await db.add_coins(chat_id, user_id, compensation)
        return f" (титул уже был — начислена компенсация {compensation} i¢)"
    await db.grant_title(chat_id, user_id, reward["key"])
    return ""


def _lootbox_reward_line(reward: dict, is_rare: bool, note: str = "") -> str:
    mark = "🌟 РЕДКИЙ ПРЕДМЕТ! " if is_rare else ""
    value = f"{reward['price']:,}".replace(",", " ")
    return f"{mark}{reward['emoji']} {html.escape(reward['name'])} (ценность: {value} i¢){note}"


LOOTBOX_USAGE = (
    "🎁 <b>Лутбоксы</b>\n\n"
    "<code>!лутбокс</code> — список редкостей и ваши боксы\n"
    "<code>!лутбокс купить {редкость} [количество]</code>\n"
    "<code>!лутбокс открыть {редкость} [количество]</code>\n"
    "<code>!лутбокс топ</code> — топ по открытым лутбоксам\n\n"
    "Редкость: обычный / необычный / редкий / эпический / легендарный (или 1-5)."
)


async def lootbox_list_text(chat_id: int, user_id: int) -> str:
    lines = ["🎁 <b>Лутбоксы</b>", DIVIDER]
    for key in LOOTBOX_ORDER:
        info = LOOTBOX_TYPES[key]
        price = f"{info['price']:,}".replace(",", " ")
        lines.append(f"{info['emoji']} <b>{info['name']}</b> — {price} i¢ · шанс редкого: {info['rare_chance']}%")
    owned = await db.list_user_lootboxes(chat_id, user_id)
    lines.append("")
    if owned:
        lines.append("📦 <b>У вас есть:</b>")
        for row in owned:
            info = LOOTBOX_TYPES.get(row["rarity"])
            if not info:
                continue
            lines.append(f"{info['emoji']} {info['name']} × {row['quantity']}")
    else:
        lines.append("📦 У вас пока нет лутбоксов.")
    lines.append("")
    lines.append("Купить: <code>!лутбокс купить {редкость} [кол-во]</code>")
    lines.append("Открыть: <code>!лутбокс открыть {редкость} [кол-во]</code>")
    return "\n".join(lines)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().casefold().split() or [""])[0] in ("!лутбокс", "лутбокс")),
)
async def cmd_lootbox(message: Message):
    if not _check_misc_access(message.from_user.id, "lootbox_info"):
        return
    parts = message.text.strip().split()
    sub = parts[1].casefold() if len(parts) > 1 else None
    chat_id, user_id = message.chat.id, message.from_user.id

    if sub is None:
        await message.reply(await lootbox_list_text(chat_id, user_id))
        return

    if sub in ("топ", "top"):
        if not _check_misc_access(user_id, "lootbox_top"):
            return
        rows = await db.list_lootbox_top(chat_id, limit=10)
        if not rows:
            await message.reply("🎰 Пока никто не открывал лутбоксы в этом чате.")
            return
        lines = ["🎰 <b>Топ по открытым лутбоксам</b>", DIVIDER]
        for i, row in enumerate(rows, start=1):
            name = await display_name_by_id(chat_id, row["user_id"])
            lines.append(f"{i}. {name} — {row['opened_count']} (редких: {row['rare_count']})")
        await message.reply("\n".join(lines))
        return

    if sub == "купить":
        if not _check_misc_access(user_id, "lootbox_buy"):
            return
        if len(parts) < 3:
            await message.reply(LOOTBOX_USAGE)
            return
        rarity = _lootbox_resolve_rarity(parts[2])
        if rarity is None:
            await message.reply("Не понял редкость. Варианты: обычный / необычный / редкий / эпический / легендарный.")
            return
        count = 1
        if len(parts) > 3 and parts[3].isdigit():
            count = max(1, min(int(parts[3]), LOOTBOX_MAX_PER_COMMAND))
        info = LOOTBOX_TYPES[rarity]
        # Чёрная пятница (событие чата) — скидка на лутбоксы.
        total_price = max(1, round(info["price"] * count
                                   * await event_multiplier(chat_id, chat_events.T_LOOTBOX)))
        if not await spend_coins(chat_id, user_id, total_price):
            total_text = f"{total_price:,}".replace(",", " ")
            await message.reply(f"Недостаточно монет: нужно {total_text}.")
            return
        await db.add_lootbox(chat_id, user_id, rarity, count)
        total_text = f"{total_price:,}".replace(",", " ")
        count_word = f"{count}x " if count > 1 else ""
        await message.reply(
            f"🎁 Вы купили {count_word}{info['emoji']} <b>{info['name']}</b> "
            f"лутбокс{'ов' if count != 1 else ''} за {total_text} i¢!"
        )
        await db.add_log("lootbox_buy", chat_id=chat_id, actor_id=user_id, details=f"{rarity}x{count}")
        return

    if sub == "открыть":
        if not _check_misc_access(user_id, "lootbox_open"):
            return
        if len(parts) < 3:
            await message.reply(LOOTBOX_USAGE)
            return
        rarity = _lootbox_resolve_rarity(parts[2])
        if rarity is None:
            await message.reply("Не понял редкость. Варианты: обычный / необычный / редкий / эпический / легендарный.")
            return
        count = 1
        if len(parts) > 3 and parts[3].isdigit():
            count = max(1, min(int(parts[3]), LOOTBOX_MAX_PER_COMMAND))

        owned = await db.get_lootbox_count(chat_id, user_id, rarity)
        if owned < count:
            info = LOOTBOX_TYPES[rarity]
            await message.reply(
                f"У вас только {owned}x {info['emoji']} {info['name']} — не хватает, чтобы открыть {count}."
            )
            return

        # Пробуем собрать пул ДО списания боксов — если магазин и титулы
        # совсем пусты, боксы не тратим и сообщаем, что открывать нечего.
        common_pool, rare_pool = await _lootbox_build_pools(chat_id)
        if not common_pool and not rare_pool:
            await message.reply(
                "🎁 В этом чате пока нет ни товаров в магазине, ни титулов с ценой — "
                "открывать лутбокс не на что. Попросите админов добавить товары в «магазин»."
            )
            return

        await db.remove_lootbox(chat_id, user_id, rarity, count)
        info = LOOTBOX_TYPES[rarity]

        # «Нюхач» (питомец) поднимает шанс редкого приза. Именно шанс, а не
        # «содержимое»: лутбокс выдаёт предмет или титул, а не монеты, и
        # умножать там попросту нечего.
        rare_chance = info["rare_chance"]
        nyuhach = await _pet_bonus(chat_id, user_id, "lootbox")
        nyuhach += await _pin_bonus(chat_id, user_id, "lootbox")   # тема «Коллекции»
        if nyuhach:
            rare_chance = min(100, rare_chance + rare_chance * nyuhach // 100)

        results: list[tuple[dict, bool, str]] = []
        for _ in range(count):
            is_rare = random.randint(1, 100) <= rare_chance
            pool = rare_pool if (is_rare and rare_pool) else (common_pool or rare_pool)
            reward = _lootbox_weighted_pick(pool)
            note = await _lootbox_grant(chat_id, user_id, reward)
            results.append((reward, pool is rare_pool, note))

        rare_hits = sum(1 for _, is_rare, _ in results if is_rare)
        stats = await db.increment_lootbox_stats(chat_id, user_id, count, rare_hits)

        if count == 1:
            reward, is_rare, note = results[0]
            header = "🎉 <b>ПОЗДРАВЛЯЮ!</b> Вы получили:" if is_rare else "Вы получили:"
            await message.reply(f"{header}\n{_lootbox_reward_line(reward, is_rare, note)}")
        else:
            lines = [f"{info['emoji']} Открыто {count}x {info['name']} лутбокс(ов):", DIVIDER]
            for reward, is_rare, note in results:
                lines.append(f"• {_lootbox_reward_line(reward, is_rare, note)}")
            if rare_hits:
                lines.append("")
                lines.append(f"🌟 Редких предметов: {rare_hits}")
            await message.reply("\n".join(lines))

        await db.add_log(
            "lootbox_open", chat_id=chat_id, actor_id=user_id, details=f"{rarity}x{count} rare={rare_hits}"
        )

        if stats["opened_count"] >= 100:
            await grant_achievement(chat_id, user_id, "lootbox_master")
        return

    await message.reply(LOOTBOX_USAGE)




# «куклу» и «рыбу» — свои команды со своими обработчиками. Порядок регистрации
# их и так разводит, но опираться только на него нельзя: перестановка функций в
# файле сломала бы команды молча (так уже было с массовыми командами питомцев).
PIN_ITEM_RE = ru_text.rx(r"(?i)^закрепить\s+(?!кукл[уы]$|рыбу$)(\S+)$")

@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(PIN_ITEM_RE.match(t.strip()))),
)
async def cmd_pin_item(message: Message):
    item_key = PIN_ITEM_RE.match(message.text.strip()).group(1).casefold()
    items = await db.list_inventory(message.chat.id, message.from_user.id)
    if not any(i["item_key"] == item_key for i in items):
        await message.reply("У вас нет такого предмета в инвентаре.")
        return
    await db.set_pinned_item(message.chat.id, message.from_user.id, item_key)
    await message.reply("📌 Предмет закреплён в профиле.")

@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "открепить предмет"),
)
async def cmd_unpin_item(message: Message):
    await db.set_pinned_item(message.chat.id, message.from_user.id, None)
    await message.reply("Предмет откреплён.")

# ============================================================================
# Предупреждения (варны). При достижении WARN_LIMIT — автобан и сброс варнов.
# ============================================================================
def _warn_card(
    *,
    actor_name: str,
    target_name: str,
    reason_text: str,
    expiry_text: str,
    count: int,
    footer: Optional[str] = None,
) -> str:
    """Карточка выданного варна.

    Одна на настоящий варн и на обманный («&варн»): если бы фейк собирал текст
    сам, любая правка формулировки здесь делала бы розыгрыш заметным.
    """
    card = (
        "⚠️ <b>Предупреждение выдано</b>\n"
        f"{DIVIDER}\n"
        f"👤 Кто: {actor_name}\n"
        f"🎯 Кому: {target_name}\n"
        f"📝 Причина: {reason_text}\n"
        f"⏳ Срок варна: {expiry_text}\n"
        f"🔢 Варн: {count}/{WARN_LIMIT}"
    )
    return f"{card}\n\n{footer}" if footer else card


async def _deliver_warn_card(message: Message, text: str):
    """Отправляет карточку варна и убирает из чата сообщение с командой.

    Обязательно ОДИН код на настоящий и на обманный варн: вся маскировка
    «&варн» держится на том, что в чате они выглядят одинаково. Разойдись
    доставка хоть в мелочи — на что отвечает карточка, остаётся ли команда, —
    и подделка видна без всякого амперсанда.

    Карточка отвечает на сообщение нарушителя, если варн выдан ответом. Если
    выдан по @username — отвечать не на что, уходит обычным сообщением.

    Удаляем команду ПОСЛЕ отправки: иначе Telegram не даст сослаться на
    сообщение, которого уже нет. Нет прав на удаление — не беда, карточка
    всё равно отправлена; молча продолжаем, как и соседние «&варны».
    """
    reply_to = message.reply_to_message.message_id if message.reply_to_message else None
    sent = await bot.send_message(message.chat.id, text, reply_to_message_id=reply_to)
    try:
        await message.delete()
    except (TelegramBadRequest, TelegramForbiddenError):
        pass
    return sent


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split() or [""])[0].casefold() == "варн"),
)
async def cmd_warn(message: Message):
    target, remaining = await _require_moderation_target(message, command_key="warn")
    if target is None:
        return

    duration, reason = _extract_leading_duration(remaining.strip(), skip_words=1)
    duration = duration if duration is not None else WARN_DEFAULT_DURATION
    expires_at = datetime.utcnow() + duration

    # Запоминаем, ГДЕ выдан варн: если это ответ на сообщение нарушителя —
    # ссылаемся на само нарушение; иначе на сообщение-команду. По этому id
    # список «варны» строит кликабельную ссылку на место в чате.
    warn_message_id = (
        message.reply_to_message.message_id if message.reply_to_message else message.message_id
    )
    count = await db.add_warn(
        message.chat.id, target.id, message.from_user.id, reason, expires_at,
        message_id=warn_message_id,
    )
    await db.add_log(
        "warn", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=reason,
    )

    actor_name = await display_name(message.chat.id, message.from_user)
    target_name = await display_name(message.chat.id, target)
    reason_text = html.escape(reason) if reason else "не указана"
    expiry_text = f"{format_duration_ru(duration)} (до {fmt_dt(expires_at)})"

    if count >= WARN_LIMIT:
        await db.clear_warns(message.chat.id, target.id)
        try:
            await bot.ban_chat_member(chat_id=message.chat.id, user_id=target.id)
            await db.add_ban(message.chat.id, target.id, message.from_user.id, f"{WARN_LIMIT} варна")
            await db.remove_mute(message.chat.id, target.id)
            await _deliver_warn_card(message, _warn_card(
                actor_name=actor_name, target_name=target_name, reason_text=reason_text,
                expiry_text=expiry_text, count=count,
                footer=f"🔨 Лимит варнов достигнут — {target_name} автоматически забанен(а).",
            ))
            await db.add_log(
                "warn_autoban", chat_id=message.chat.id, actor_id=message.from_user.id,
                target_id=target.id,
            )
        except TelegramForbiddenError:
            await message.reply(
                f"⚠️ Предупреждение выдано, но у бота недостаточно прав для автобана "
                f"(лимит {WARN_LIMIT} варнов достигнут)."
            )
        except TelegramBadRequest as e:
            await message.reply(f"⚠️ Предупреждение выдано, но автобан не удался: {e.message}")
        await _tell_moderator_warn_kind(message, target_name, fake=False, count=count)
        return

    sent = await _deliver_warn_card(message, _warn_card(
        actor_name=actor_name, target_name=target_name, reason_text=reason_text,
        expiry_text=expiry_text, count=count,
    ))
    # Варн выдан не ответом, а по @username: ссылка вела бы на сообщение с
    # командой, которого больше нет. Переставляем её на карточку — она
    # осталась в чате и показывает то же самое.
    if message.reply_to_message is None and sent is not None:
        await db.update_last_warn_message_id(message.chat.id, target.id, sent.message_id)
    # Сообщаем и про настоящий варн тоже: если в личку приходит только про
    # розыгрыш, то само наличие письма становится ответом, и модератор
    # перестаёт читать — а с ним теряется весь смысл напоминания.
    await _tell_moderator_warn_kind(message, target_name, fake=False, count=count)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split() or [""])[0].casefold() == "-варн"),
)
async def cmd_unwarn(message: Message):
    target, _remaining = await _require_moderation_target(message, command_key="unwarn")
    if target is None:
        return

    removed = await db.remove_last_warn(message.chat.id, target.id)
    if not removed:
        await message.reply("У этого пользователя сейчас нет варнов.")
        return

    count = await db.count_warns(message.chat.id, target.id)
    target_name = await display_name(message.chat.id, target)
    await message.reply(f"✅ Снято одно предупреждение у {target_name}. Осталось варнов: {count}/{WARN_LIMIT}")
    await db.add_log("unwarn", chat_id=message.chat.id, actor_id=message.from_user.id, target_id=target.id)


# ---------- Обманные варны («&варн») ----------
# Розыгрыш: выглядит в чате ровно как настоящий варн (та же карточка, тот же
# счёт, та же строка в списке «варны»), но ничего не пишет в базу и на лимите
# не банит. Подробности и причины решений — в fake_warns.py.

FAKE_WARNS_IN_LIST_DEFAULT = True


async def _tell_moderator_warn_kind(message: Message, target_name: str,
                                    *, fake: bool, count: int) -> None:
    """Пишет выдавшему в личку, настоящий это был варн или розыгрыш.

    Нужно ровно затем, чтобы модератор не запутался в собственной шутке:
    разыграв двоих, легко забыть, кому что выдано, и добить человека
    НАСТОЯЩИМ третьим варном по ложному следу. В журнале это видно, но в лс
    приходит сразу и без похода в панель.

    В чат такое писать нельзя ни при каких условиях — это выдало бы розыгрыш.
    Личка закрыта — молча пропускаем: у соседних команд («&варны», «&-варн»)
    ровно то же поведение и по той же причине.
    """
    kind = ("🃏 <b>Это был ОБМАННЫЙ варн.</b> В базе его нет, бана не будет."
            if fake else
            "⚠️ <b>Это был НАСТОЯЩИЙ варн.</b> Он записан в базу.")
    try:
        await bot.send_message(
            message.from_user.id,
            f"{kind}\nКому: {target_name}\nВсего варнов у него сейчас: {count}.",
        )
    except (TelegramForbiddenError, TelegramBadRequest):
        pass
    except Exception as exc:
        log_suppressed("_tell_moderator_warn_kind", exc)


def fake_warns_in_list() -> bool:
    """Показывать ли обманные варны самому разыгранному в его списке «варны».

    Включено — розыгрыш выглядит достовернее всего: человек видит ровно то, что
    бот объявил в чате. Выключено — обманные варны копятся отдельно, в списке
    остаются только настоящие, а модератор смотрит розыгрыш командой «&варны».
    NULL в настройке (админ не трогал) — дефолт из кода.
    """
    raw = settings.get("fake_warns_in_list")
    if raw is None:
        return FAKE_WARNS_IN_LIST_DEFAULT
    return str(raw).strip().casefold() not in ("0", "", "нет", "false", "off")

@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split() or [""])[0].casefold() == "&варн"),
)
async def cmd_fake_warn(message: Message):
    # Права те же, что у настоящего варна, и отдельной записи в COMMAND_REGISTRY
    # у розыгрыша намеренно нет: дерево команд («команды») открыто всем, и
    # строка «&варн (обманный)» в нём выдала бы шутку первому же любопытному.
    target, remaining = await _require_moderation_target(message, command_key="warn")
    if target is None:
        return

    duration, reason = _extract_leading_duration(remaining.strip(), skip_words=1)
    duration = duration if duration is not None else WARN_DEFAULT_DURATION
    now = datetime.utcnow()
    expires_at = now + duration

    fake_warns.add(
        message.chat.id, target.id,
        reason=reason, warned_by=message.from_user.id,
        created_at=now, expires_at=expires_at,
    )
    # Счёт показываем вместе с настоящими варнами: если у человека уже есть
    # реальный варн, «1/3» вместо «2/3» выдало бы подделку сразу.
    count = await db.count_warns(message.chat.id, target.id) + fake_warns.count(
        message.chat.id, target.id, now
    )

    # В чате розыгрыш неотличим, но в журнале он помечен: иначе другой
    # модератор увидит «у человека уже два варна», выдаст третий — настоящий —
    # и шутка закончится настоящим баном.
    await db.add_log(
        "fake_warn", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=reason,
    )

    actor_name = await display_name(message.chat.id, message.from_user)
    target_name = await display_name(message.chat.id, target)
    # На лимите розыгрыш раскрывается сам: вместо «забанен» — признание. Так
    # шутка доигрывается до конца и не оставляет человека в уверенности, что
    # его вот-вот выкинут из чата.
    footer = (
        "🃏 <b>Ха, обманул!</b>\n"
        "Все эти варны были шуточными — на самом деле ничего не произошло, "
        f"{target_name} никуда не забанен(а)."
        if count >= WARN_LIMIT else None
    )
    # Доставка — тем же помощником, что у настоящего варна. Любая своя
    # отправка здесь рано или поздно разойдётся с ней в мелочи и выдаст шутку.
    await _deliver_warn_card(message, _warn_card(
        actor_name=actor_name,
        target_name=target_name,
        reason_text=html.escape(reason) if reason else "не указана",
        expiry_text=f"{format_duration_ru(duration)} (до {fmt_dt(expires_at)})",
        count=count,
        footer=footer,
    ))

    await _tell_moderator_warn_kind(message, target_name, fake=True, count=count)

    if footer:
        # Шутка доиграна — обнуляем, иначе следующий «&варн» покажет 4/3, а в
        # списке «варны» останется висеть уже раскрытый розыгрыш.
        fake_warns.clear(message.chat.id, target.id)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split() or [""])[0].casefold() in ("&-варн", "&варн-")),
)
async def cmd_fake_unwarn(message: Message):
    """Снять обманный варн — вернуть разыгранного в исходное состояние.
    Отвечает в личку инициатору, а не в чат: ответ в чате раскрыл бы розыгрыш."""
    target, _remaining = await _require_moderation_target(message, command_key="unwarn")
    if target is None:
        return

    left = fake_warns.drop(message.chat.id, target.id, datetime.utcnow())
    target_name = await display_name(message.chat.id, target)
    try:
        await bot.send_message(
            message.from_user.id,
            f"🃏 Снят один обманный варн у {target_name}. Осталось обманных: {left}.",
        )
    except (TelegramForbiddenError, TelegramBadRequest):
        # Личка боту не открыта — молчим: писать в чат нельзя, это выдаст шутку.
        pass
    try:
        await message.delete()
    except (TelegramBadRequest, TelegramForbiddenError):
        pass


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "&варны"),
)
async def cmd_list_fake_warns(message: Message):
    """Обманные варны человека — для модератора, ответом на сообщение.
    Отвечает в личку и удаляет команду: список в чате раскрыл бы розыгрыш."""
    target, _remaining = await _require_moderation_target(message, command_key="warn")
    if target is None:
        return

    rows = fake_warns.active(message.chat.id, target.id, datetime.utcnow())
    target_name = await display_name(message.chat.id, target)
    if rows:
        lines = []
        for row in rows:
            reason_text = f" — {html.escape(row['reason'])}" if row["reason"] else ""
            when = fmt_dt(row["created_at"])
            expires = row["expires_at"]
            expiry_text = f" · сгорит {fmt_dt(expires)}" if expires else " · бессрочный"
            lines.append(f"• {when}{reason_text}{expiry_text}")
        text = (
            f"🃏 <b>Обманные варны {target_name}: {len(rows)}/{WARN_LIMIT}</b>\n"
            f"<i>Их нет в базе, бот по ним не банит.</i>\n\n" + "\n".join(lines)
        )
    else:
        text = f"🃏 У {target_name} нет обманных варнов."

    try:
        await bot.send_message(message.from_user.id, text)
    except (TelegramForbiddenError, TelegramBadRequest):
        pass
    try:
        await message.delete()
    except (TelegramBadRequest, TelegramForbiddenError):
        pass


def chat_message_link(chat_id: int, message_id: Optional[int]) -> Optional[str]:
    """Ссылка t.me/c/… на конкретное сообщение в супергруппе — или None, если
    ссылку не построить: нет message_id, либо это не супергруппа с внутренним
    id (публичные ссылки на сообщения есть только у супергрупп/каналов с
    префиксом -100 в chat_id; в обычных группах их нет)."""
    if not message_id:
        return None
    raw = str(chat_id)
    if not raw.startswith("-100"):
        return None
    internal = raw[4:]
    if not internal.isdigit():
        return None
    return f"https://t.me/c/{internal}/{message_id}"


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold() == "варны"),
)
async def cmd_list_warns(message: Message):
    target = message.reply_to_message.from_user if message.reply_to_message else message.from_user
    # Обманные варны («&варн») подмешиваются к настоящим и сортируются вместе:
    # человек, решивший проверить свой список, не должен увидеть расхождение с
    # тем, что бот только что объявил в чате. В базе их нет — см. fake_warns.py.
    # Настройкой это выключается: тогда розыгрыш копится отдельно и виден
    # модератору по «&варны».
    rows = list(await db.list_warns(message.chat.id, target.id))
    if fake_warns_in_list():
        rows += fake_warns.active(message.chat.id, target.id, datetime.utcnow())
        rows.sort(key=lambda r: r["created_at"])
    target_name = await display_name(message.chat.id, target)
    if not rows:
        await message.reply(f"У {target_name} нет предупреждений.")
        return
    lines = []
    for row in rows:
        reason_text = f" — {html.escape(row['reason'])}" if row["reason"] else ""
        when = fmt_dt(row["created_at"])
        # Дата — ссылка на сообщение, где варн выдали (если id сохранён и это
        # супергруппа). У обманных варнов message_id нет — они просто без ссылки.
        link = chat_message_link(message.chat.id, row.get("message_id"))
        when_text = f'<a href="{link}">{when}</a>' if link else when
        expires = row.get("expires_at")
        expiry_text = f" · сгорит {fmt_dt(expires)}" if expires else " · бессрочный"
        lines.append(f"• {when_text}{reason_text}{expiry_text}")
    await message.reply(
        f"⚠️ <b>Варны {target_name}: {len(rows)}/{WARN_LIMIT}</b>\n\n" + "\n".join(lines)
    )


