@router.callback_query(F.data.startswith("rewardsclear_yes:"))
async def confirm_reward_remove_all(callback: CallbackQuery):
    try:
        _, initiator_str, target_str = callback.data.split(":", maxsplit=2)
        initiator_id, target_id = int(initiator_str), int(target_str)
    except (ValueError, IndexError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Подтвердить может только тот, кто вызвал команду.", show_alert=True)
        return

    actor_level = get_level(initiator_id)
    required = required_level("reward_remove_all")
    removing_own = target_id == initiator_id
    if not removing_own and actor_level < required:
        await callback.answer(f"⛔ Только «{level_name(required)}» и выше может это сделать.", show_alert=True)
        return

    chat_id = callback.message.chat.id
    removed = await db.remove_all_rewards(chat_id, target_id)
    await db.add_log(
        "reward_remove_all", chat_id=chat_id, actor_id=initiator_id,
        target_id=target_id, details=str(removed),
    )
    try:
        await callback.message.edit_text(f"🗑 <b>Готово</b>\nСнято наград: {removed}.")
    except TelegramBadRequest:
        pass
    await callback.answer("Снято ✅")


@router.callback_query(F.data.startswith("rewardsclear_no:"))
async def cancel_reward_remove_all(callback: CallbackQuery):
    try:
        _, initiator_id_str, _ = callback.data.split(":", maxsplit=2)
        initiator_id = int(initiator_id_str)
    except (ValueError, IndexError):
        await callback.answer()
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Отменить может только тот, кто вызвал команду.", show_alert=True)
        return
    try:
        await callback.message.edit_text("Отменено.")
    except TelegramBadRequest:
        pass
    await callback.answer()


# ============================================================================
# Статистика сообщений: профиль и топ активности (работают только в группах)
# ============================================================================
TOP_PAGE_SIZE = 10


# ============================================================================
# Карточка пользователя — как у Iris, где «кто я», «кто ты {ссылка}» и
# «профиль {ссылка}» являются синонимами одной и той же команды (см. раздел
# «8. Анкета пользователя» → «Карточка пользователя» в списке команд Iris).
# Без ответа на сообщение — показывает карточку вызвавшего, ответом на чьё-то
# сообщение — карточку этого человека.
#
# В группе — полная карточка: ранг, ID, юзернейм, ник, звание, пол/город (если
# анкета не скрыта), девиз, гражданство, статистика сообщений, награды/варны,
# брак/отношения, мут, дата первого появления в чате.
# В личных сообщениях бота (как «Профиль» в л/с у Iris) — сокращённая
# карточка: ID, юзернейм, ранг, — потому что анкета, ник и статистика
# привязаны к конкретному групповому чату, а не к пользователю в целом.
# ============================================================================
PROFILE_CARD_PHRASES = ("кто ты", "ктоты", "кто это", "кто я", "профиль", "проф")


def _profile_command_match(text: Optional[str]) -> Optional[str]:
    """Совпавшая фраза, если текст начинается с одной из PROFILE_CARD_PHRASES
    (дальше может идти @username/ID цели или ничего). Проверяем от самых
    длинных фраз к коротким, чтобы двухсловные не терялись за односложными."""
    if not text or not text.strip():
        return None
    low_words = text.strip().casefold().split()
    for phrase in sorted(PROFILE_CARD_PHRASES, key=lambda p: len(p.split()), reverse=True):
        words = phrase.split()
        n = len(words)
        if len(low_words) >= n and low_words[:n] == words:
            return phrase
    return None


PROFILE_CAPTION_LIMIT = 1024  # жёсткий лимит Telegram на подпись к фото

# ----------------------------------------------------------------------------
# Тумблер «+Стата» / «-Стата» — вкл/выкл отображение графика активности в
# «Чат инфо» и «Профиль» (карточка/текст всё равно показывается — тумблер
# управляет только картинкой). Хранится в общей kv-таблице bot_data (см.
# db.set_data/get_data — тот же механизм, что и у «-чат»/«+чат»). По
# умолчанию (нет строки в БД) график включён — это прежнее поведение бота.
# ----------------------------------------------------------------------------
def _stat_chart_key(chat_id: int) -> str:
    return f"statchart:{chat_id}"


async def is_stat_chart_enabled(chat_id: int) -> bool:
    row = await db.get_data(_stat_chart_key(chat_id))
    if row is None:
        return True
    return row.get("data_value") != "0"


# ----------------------------------------------------------------------------
# Уведомления о входах и выходах («+входы» / «-выходы» и т.п.).
#
# Хранятся там же, где тумблер графика — в bot_data по ключу на чат. По
# умолчанию ВЫКЛЮЧЕНО: иначе после обновления бота во всех чатах разом
# посыпались бы сообщения, которых там раньше не было.
#
# Формулировки — в настоящем времени («заходит», «покидает»), чтобы не
# угадывать род участника: у нас есть анкетный пол, но он заполнен далеко
# не у всех, а «вышел(а)» в каждой строке выглядит плохо.
# ----------------------------------------------------------------------------
