@router.callback_query(F.data.startswith("sellitem:"))
async def sell_item_cb(callback: CallbackQuery):
    """Кнопка «💰 Продать» в инвентаре — продаёт 1 шт. предмета за 80% его
    цены в магазине. Доступно, только если предмет ни разу не использовался
    (см. item_usage / ITEM_USE_LIMIT)."""
    _, item_key, target_id_str, requester_id_str = callback.data.split(":", maxsplit=3)
    target_id, requester_id = int(target_id_str), int(requester_id_str)
    chat_id = callback.message.chat.id

    if callback.from_user.id != target_id:
        await callback.answer("Продавать можно только свои предметы.", show_alert=True)
        return

    # Та же проверка, что в текстовой «магазин продать». Раньше её здесь не
    # было, и кнопка продавала предмет за ачивку по его витринной цене
    # (999 999 999 i¢) — то есть за 799 999 999 i¢ в карман.
    if shop_effects.is_reward(item_key):
        await callback.answer(
            "🎖 Предметы за достижения и награды не продаются.", show_alert=True
        )
        return

    used = await db.get_item_usage_count(chat_id, target_id, item_key)
    if used > 0:
        await callback.answer("Этот предмет уже использовался — продать нельзя.", show_alert=True)
        return

    shop_item = await db.get_shop_item(chat_id, item_key)
    if shop_item is None or shop_item.get("price") is None:
        await callback.answer("Этот предмет нельзя продать.", show_alert=True)
        return

    ok = await db.remove_inventory_item(chat_id, target_id, item_key, 1)
    if not ok:
        await callback.answer("У вас нет этого предмета.", show_alert=True)
        return

    price = int(shop_item["price"])
    sell_price = max(int(price * 0.8), 0)
    await db.add_coins(chat_id, target_id, sell_price)

    card = await db.get_profile_card(chat_id, target_id)
    if card and card.get("pinned_item") == item_key:
        remaining = await db.list_inventory(chat_id, target_id)
        if not any(i["item_key"] == item_key for i in remaining):
            await db.set_pinned_item(chat_id, target_id, None)

    await db.add_log("item_sell", chat_id=chat_id, actor_id=target_id, details=f"{item_key}x1")
    await callback.answer(f"✅ Продано за {sell_price} i¢!")

    text, keyboard = await _inventory_view(chat_id, target_id, requester_id, callback.from_user.id)
    await edit_profile_message(callback, text, keyboard)


