async def show_profile_bookmarks(callback: CallbackQuery):
    """Кнопка «🔖 Закладки» под карточкой профиля — показывает закладки того
    пользователя, чья карточка открыта, в текущем чате (с пагинацией),
    меняя текущее сообщение вместо отправки нового; клавиатура — «Назад»
    (плюс навигация по страницам, если закладок много)."""
    try:
        _, target_id_str, requester_id_str, page_str = callback.data.split(":", maxsplit=3)
        target_id, requester_id, page = int(target_id_str), int(requester_id_str), int(page_str)
    except (ValueError, IndexError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    await callback.answer()
    name = await display_name_by_id(callback.message.chat.id, target_id)
    text, nav_kb = await user_bookmarks_page_text(
        callback.message.chat.id, target_id, page, "bookmarks_profile_nav", f"🔖 <b>Закладки</b> — {name}"
    )
    # Кнопки пагинации из user_bookmarks_page_text используют свой префикс
    # (без requester_id), поэтому переносим номер страницы вручную в наш
    # собственный callback_data — иначе «Назад» на второй и следующих
    # страницах потерял бы requester_id и перестал бы работать.
    rows: list[list[InlineKeyboardButton]] = []
    if nav_kb:
        nav_row = []
        for btn in nav_kb.inline_keyboard[0]:
            if btn.callback_data == "noop":
                nav_row.append(btn)
                continue
            try:
                _, _, page_part = btn.callback_data.split(":", maxsplit=2)
            except ValueError:
                nav_row.append(btn)
                continue
            nav_row.append(
                InlineKeyboardButton(
                    text=btn.text, callback_data=f"bookmarks_profile:{target_id}:{requester_id}:{page_part}"
                )
            )
        rows.append(nav_row)
    rows.append([InlineKeyboardButton(text="⬅️ Назад", callback_data=f"profile_back:{target_id}:{requester_id}")])
    await edit_profile_message(callback, text, InlineKeyboardMarkup(inline_keyboard=rows))


