async def top_page(chat_id: int, page: int) -> tuple[str, InlineKeyboardMarkup | None]:
    page = max(page, 0)
    rows, total = await db.list_top_messages(chat_id, limit=TOP_PAGE_SIZE, offset=page * TOP_PAGE_SIZE)
    if not rows and page:
        page = 0
        rows, total = await db.list_top_messages(chat_id, limit=TOP_PAGE_SIZE)
    if not rows:
        return "💬 <b>Топ по сообщениям</b>\n\nПока нет статистики — напишите что-нибудь!", None

    lines = await _stat_rank_lines(chat_id, rows, start=page * TOP_PAGE_SIZE)
    pages = (total + TOP_PAGE_SIZE - 1) // TOP_PAGE_SIZE
    text = (f"💬 <b>Топ активности — {total} участников</b>\n{DIVIDER}\n"
            + "\n".join(lines) + "\n"
            + await _stat_total_line(chat_id, None, ""))
    if pages == 1:
        return text, None

    buttons = []
    if page > 0:
        buttons.append(InlineKeyboardButton(text="⬅️", callback_data=f"top_page:{page - 1}"))
    buttons.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page + 1 < pages:
        buttons.append(InlineKeyboardButton(text="➡️", callback_data=f"top_page:{page + 1}"))
    return text, InlineKeyboardMarkup(inline_keyboard=[buttons])


