# ============================================================================
# Модуль 9 — «Статистическая информация» (как в Iris).
# Периодическая статистика сообщений, общая информация о чате, старожилы и
# новички, список никнеймов чата, неактивные участники и молчуны, кто кого
# пригласил. Реализовано текстом (без графиков/картинок — в этом боте нет
# инфраструктуры для рисования изображений, в отличие от оригинального Ириса).
# ============================================================================
STAT_PERIOD_ALIASES = {
    "сутки": "day", "сегодня": "day", "день": "day",
    "неделя": "week", "недели": "week", "неделю": "week",
    "месяц": "month", "месяца": "month",
    "вся": "all", "все": "all", "всё": "all",
}
STAT_PERIOD_TITLES = {"day": "сутки", "week": "неделю", "month": "месяц", "all": "всё время"}
STAT_PAGE_SIZE = 10


def _period_cutoff_day(period: str):
    today = datetime.utcnow().date()
    if period == "day":
        return today
    if period == "week":
        return today - timedelta(days=6)
    if period == "month":
        return today - timedelta(days=29)
    return None  # "all" — используем message_stats напрямую, без даты отсечения


def _parse_stat_args(tokens: list[str]) -> tuple[str, Optional[int]]:
    """Разбирает хвост команды «стата»/«топ»: период и (опционально) число
    участников в списке, в любом порядке — «стата неделя 5» или «топ 5 неделя».
    limit=None означает, что число явно не указано — тогда список постраничный
    (см. stat_period_page), а не срез фиксированной длины."""
    period = "day"
    limit = None
    for tok in tokens:
        low = tok.casefold()
        if low.isdigit():
            limit = max(1, min(int(low), 100))
        elif low in STAT_PERIOD_ALIASES:
            period = STAT_PERIOD_ALIASES[low]
    return period, limit


async def _stat_rank_lines(chat_id: int, rows: list, start: int = 0) -> list:
    """Строки рейтинга: место, домик у гражданина, имя, счёт.

    ОДИН код на все три вывода топа — постраничный, с явно указанным числом
    и общий «топ». Они уже разошлись однажды: домик и итог появились в двух
    из трёх, а форма «топ 20 неделя» осталась без них, потому что идёт своим
    путём. Держим рендер в одном месте, чтобы это не повторилось.
    """
    medals = {0: "🥇", 1: "🥈", 2: "🥉"}
    # Гражданство — одним запросом на всю страницу, а не по строке на человека.
    citizens = await db.list_citizens(chat_id)
    out = []
    for offset, row in enumerate(rows):
        index = start + offset
        name = await display_name_link_by_id(chat_id, row["user_id"])
        place = medals.get(index, f"{index + 1}.")
        home = "🏠 " if int(row["user_id"]) in citizens else ""
        out.append(f"{place} {home}{name} — <b>{row['message_count']}</b>")
    return out


async def _stat_total_line(chat_id: int, cutoff, label: str) -> str:
    """Итог под списком — всегда за ТОТ ЖЕ период, что и сам список."""
    total = await db.sum_messages_period(chat_id, cutoff)
    return f"{DIVIDER}\n💬 Всего сообщений{label}: <b>{total}</b>"


async def stat_period_text(chat_id: int, period: str, limit: int) -> str:
    """Статический список фиксированной длины — используется, когда число
    явно указано в команде («стата неделя 5»): пагинация тут не нужна,
    человек попросил ровно limit строк."""
    cutoff = _period_cutoff_day(period)
    if cutoff is None:
        rows, total = await db.list_top_messages(chat_id, limit=limit)
    else:
        rows, total = await db.list_top_messages_period(chat_id, cutoff, limit=limit)
    title = STAT_PERIOD_TITLES[period]
    if not rows:
        return f"💬 <b>Статистика за {title}</b>\n\nПока нет сообщений за этот период."
    lines = await _stat_rank_lines(chat_id, rows)
    return (f"💬 <b>Статистика за {title}</b> — {total} участников\n{DIVIDER}\n"
            + "\n".join(lines) + "\n"
            + await _stat_total_line(chat_id, cutoff, f" за {title}"))


async def stat_period_page(chat_id: int, period: str, page: int) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    """Постраничный список (как «топ»/«топ активность») — используется, когда
    число не указано явно: по умолчанию показывает всех, а не только первых 10,
    листая их стрелками внизу."""
    page = max(page, 0)
    cutoff = _period_cutoff_day(period)
    if cutoff is None:
        rows, total = await db.list_top_messages(chat_id, limit=STAT_PAGE_SIZE, offset=page * STAT_PAGE_SIZE)
        if not rows and page:
            page = 0
            rows, total = await db.list_top_messages(chat_id, limit=STAT_PAGE_SIZE)
    else:
        rows, total = await db.list_top_messages_period(chat_id, cutoff, limit=STAT_PAGE_SIZE, offset=page * STAT_PAGE_SIZE)
        if not rows and page:
            page = 0
            rows, total = await db.list_top_messages_period(chat_id, cutoff, limit=STAT_PAGE_SIZE)

    title = STAT_PERIOD_TITLES[period]
    if not rows:
        return f"💬 <b>Статистика за {title}</b>\n\nПока нет сообщений за этот период.", None

    lines = await _stat_rank_lines(chat_id, rows, start=page * STAT_PAGE_SIZE)
    pages = max((total + STAT_PAGE_SIZE - 1) // STAT_PAGE_SIZE, 1)
    text = (f"💬 <b>Статистика за {title}</b> — {total} участников\n{DIVIDER}\n"
            + "\n".join(lines) + "\n"
            + await _stat_total_line(chat_id, cutoff, f" за {title}"))
    if pages == 1:
        return text, None

    buttons = []
    if page > 0:
        buttons.append(InlineKeyboardButton(text="⬅️", callback_data=f"statpage:{period}:{page - 1}"))
    buttons.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page + 1 < pages:
        buttons.append(InlineKeyboardButton(text="➡️", callback_data=f"statpage:{period}:{page + 1}"))
    return text, InlineKeyboardMarkup(inline_keyboard=[buttons])


# Второе слово команды, которое означает СОВСЕМ другой отчёт и должно уйти
# своему обработчику: «топ кланов», «топ браков», «стата по часам» и т.п.
# «стриков»/«стрик» — тоже чужие: их берёт cmd_streak_top. Без них фильтр
# подходил и сюда, и туда, и «топ стриков» доставался тому обработчику, который
# просто зарегистрирован раньше, — то есть работал по случайности порядка строк
# в файле, а не по правилу.
_STAT_FOREIGN_SECOND_WORDS = (
    "кланов", "монет", "ачивок", "репутации", "браков", "уловов", "рыбалки", "по",
    "стриков", "стрик",
)


def _is_stat_period_command(t: Optional[str]) -> bool:
    """«стата за неделю», «топ 20» и подобное.

    Раньше это был лямбда-фильтр, который брал split()[1] БЕЗ проверки длины:
    на однословном «стата» он падал IndexError прямо в проверке фильтра —
    то есть обычное слово в чате роняло обработку апдейта.
    """
    if not t or not t.strip():
        return False
    low = t.strip().casefold()
    words = low.split()
    if words[0] not in ("стата", "топ"):
        return False
    if low in ("топ", "актив"):
        return False  # эти два случая уже обрабатывает cmd_top
    if len(words) < 2:
        return False  # голое «стата» — без периода показывать нечего
    return words[1] not in _STAT_FOREIGN_SECOND_WORDS


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_stat_period_command),
)
async def cmd_stat_period(message: Message):
    tokens = message.text.strip().split()[1:]
    period, limit = _parse_stat_args(tokens)
    if limit is None:
        text, keyboard = await stat_period_page(message.chat.id, period, 0)
        await message.reply(text, reply_markup=keyboard)
    else:
        await message.reply(await stat_period_text(message.chat.id, period, limit))


@router.callback_query(F.data.startswith("statpage:"))
async def paginate_stat_period(callback: CallbackQuery):
    try:
        _, period, page_str = callback.data.split(":", maxsplit=2)
        page = int(page_str)
    except (ValueError, IndexError):
        await callback.answer("Не удалось открыть эту страницу.", show_alert=True)
        return
    text, keyboard = await stat_period_page(callback.message.chat.id, period, page)
    try:
        await callback.message.edit_text(text, reply_markup=keyboard)
    except TelegramBadRequest:
        pass
    await callback.answer()


