    is_locked = bool(locked_row)

    lines = [f"ℹ️ <b>Информация о чате</b>", DIVIDER, f"📛 Название: <b>{html.escape(chat.title or '—')}</b>"]
    lines.append(f"🆔 ID: <code>{chat.id}</code>")
