@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold().split()[0:2] == ["чат", "стата"]
                and t.strip().casefold().split()[2:3] != ["по"]),
)
async def cmd_chat_stat_chart(message: Message):
    """«Чат стата» / «Чат стата {дни}» — график активности чата за указанный
    период (30-5000 дней, по умолчанию 365). Игнорирует «чат стата по
    часам» — тем занимается отдельный хендлер ниже."""
    tokens = message.text.strip().split()[2:]
    days = CHAT_STAT_CHART_DEFAULT_DAYS
    if tokens and tokens[0].isdigit():
        days = int(tokens[0])
    days = max(CHAT_STAT_CHART_MIN_DAYS, min(CHAT_STAT_CHART_MAX_DAYS, days))

    if not await is_stat_chart_enabled(message.chat.id):
        await message.reply("📊 График статистики выключен в этом чате — включите его командой «+Стата».")
        return

    png_buf = await _render_chat_chart(message.chat.id, days)
    if not png_buf:
        await message.reply("Пока нет данных для графика — напишите что-нибудь!")
        return
    await message.reply_photo(
        BufferedInputFile(png_buf.read(), filename="chat_activity.png"),
        caption=f"📊 <b>Статистика чата</b> за последние {days} дн.",
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold().split()[0:3] == ["стата", "по", "часам"]),
)
async def cmd_user_hourly_stat(message: Message):
    """«Стата по часам» / «Стата по часам {ссылка}» — почасовая активность
    пользователя (типичный день, агрегат за тот же период, что и обычный
    график профиля — ACTIVITY_CHART_DAYS дней). Без ссылки и без ответа на
    сообщение — по вызвавшему."""
    if not await is_stat_chart_enabled(message.chat.id):
        await message.reply("📊 График статистики выключен в этом чате — включите его командой «+Стата».")
        return

    target, _ = await resolve_command_target(message, trigger_words=3)
    if target is None:
        target = message.reply_to_message.from_user if message.reply_to_message else message.from_user
    if target.id is None:
        await message.reply("Не удалось определить пользователя — укажите @username или ответьте на его сообщение.")
        return
    if getattr(target, "is_bot", False):
        await message.reply("У ботов почасовой статистики нет 🤖")
        return

    since_day = utc_today() - timedelta(days=ACTIVITY_CHART_DAYS - 1)
    rows = await db.list_hourly_pattern_for_user(message.chat.id, target.id, since_day)
    if not rows:
        await message.reply("Пока нет данных для графика — напишите что-нибудь!")
        return

    name = await display_name_by_id(message.chat.id, target.id)
    rows = hours_to_local(rows)
    current_hour = local_hour()
    try:
        png_buf = await asyncio.to_thread(
            render_hourly_chart, rows, "Активность по часам", current_hour
        )
    except Exception:
        logger.exception("Не удалось построить почасовой график пользователя")
        await message.reply("Не удалось построить график — попробуйте позже.")
        return
    await message.reply_photo(
        BufferedInputFile(png_buf.read(), filename="hourly_activity.png"),
        caption=f"🕐 <b>Почасовая активность</b> — {name} (UTC)",
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and t.strip().casefold().split() == ["чат", "стата", "по", "часам"]),
)
async def cmd_chat_hourly_stat(message: Message):
    """«Чат стата по часам» — почасовая статистика сообщений чата за
    последние 24 часа (не «типичный день», а реальный срез времени)."""
    if not await is_stat_chart_enabled(message.chat.id):
        await message.reply("📊 График статистики выключен в этом чате — включите его командой «+Стата».")
        return

    raw_rows = await db.list_hourly_last_24h_for_chat(message.chat.id)
    if not raw_rows:
        await message.reply("Пока нет данных за последние 24 часа.")
        return

    # Сворачиваем (day, hour) в один час суток — на графике 24 столбца
    # (0-23), а не отдельные точки для «вчера» и «сегодня».
    merged: dict[int, int] = {}
    for row in raw_rows:
        merged[row["hour"]] = merged.get(row["hour"], 0) + int(row["message_count"])
    rows = hours_to_local([{"hour": h, "message_count": c} for h, c in merged.items()])
    total = sum(merged.values())

    current_hour = local_hour()
    try:
        png_buf = await asyncio.to_thread(
            render_hourly_chart, rows, "Статистика чата по часам", current_hour
        )
    except Exception:
        logger.exception("Не удалось построить почасовой график чата")
        await message.reply("Не удалось построить график — попробуйте позже.")
        return
    await message.reply_photo(
        BufferedInputFile(png_buf.read(), filename="chat_hourly_activity.png"),
        caption=f"🕐 <b>Статистика чата по часам</b> — {total} сообщений за 24ч (UTC)",
    )


