# ---------- Олды / Новички ----------
OLDTIMER_ACTIVE_WINDOW = timedelta(days=30)


async def _oldtimers_newcomers_text(chat_id: int, rows: list[dict], title: str, mark_active: bool = False) -> str:
    """mark_active=True (только для «Олды») добавляет 🔥 рядом с ником тех,
    кто писал в чате за последний месяц (по last_message_at из message_stats,
    см. db.list_oldtimers) — как у Iris."""
    if not rows:
        return f"{title}\n\nПока нет данных."
    lines = [title, DIVIDER]
    now = datetime.utcnow()
    for i, row in enumerate(rows, start=1):
        name = mention_id(row["user_id"], full_name=row.get("full_name"), username=row.get("username"))
        seen: datetime = row["first_seen_at"]
        fire = ""
        if mark_active:
            last_message_at = row.get("last_message_at")
            if last_message_at and (now - last_message_at) <= OLDTIMER_ACTIVE_WINDOW:
                fire = " 🔥"
        lines.append(f"{i}. {name}{fire} — с {fmt_date(seen)}")
    return "\n".join(lines)


