NEW_MEMBERS_MAX_ROWS = 100  # предохранитель от гигантского списка в одном сообщении


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().casefold().split() or [""])[0] == "нью"),
)
async def cmd_new_members(message: Message):
    """«нью {период}» — кто вступил в чат за последние {период} (по first_seen_at).
    Период в том же формате, что и везде в боте: «2д», «3ч», «1нед», «30м» и т.п.
    Без периода — по умолчанию сутки."""
    tokens = message.text.strip().split()[1:]
    duration = None
    period_text = "1д"
    if tokens:
        duration = parse_duration(tokens[0])
        if duration is not None:
            period_text = tokens[0]
        elif len(tokens) >= 2 and _LONE_NUMBER_RE.match(tokens[0]):
            # Раздельная запись вида «нью 3 дня»
            combined = parse_duration(tokens[0] + tokens[1])
            if combined is not None:
                duration = combined
                period_text = f"{tokens[0]} {tokens[1]}"
    if duration is None:
        duration = timedelta(days=1)

    since = datetime.utcnow() - duration
    rows = await db.list_new_members_since(message.chat.id, since, limit=NEW_MEMBERS_MAX_ROWS)

    title = f"🆕 <b>Вступили за последние {html.escape(period_text)}</b>"
    if not rows:
        await message.reply(f"{title}\n\nНикто не вступал за этот период.")
        return

    lines = [title, DIVIDER]
    for i, row in enumerate(rows, start=1):
        name = mention_id(row["user_id"], full_name=row.get("full_name"), username=row.get("username"))
        seen: datetime = row["first_seen_at"]
        lines.append(f"{i}. {name} — {fmt_dt(seen)}")
    if len(rows) >= NEW_MEMBERS_MAX_ROWS:
        lines.append(f"\n… показаны первые {NEW_MEMBERS_MAX_ROWS}, возможно вступивших больше.")
    await message.reply("\n".join(lines))


