    if not rows:
        await message.reply("✏️ В этом чате пока никто не установил себе ник (команда «+ник»).")
        return
    pages = (total + NICK_PAGE_SIZE - 1) // NICK_PAGE_SIZE
    lines = [f"✏️ <b>Ники чата</b> — {total} (стр. {page + 1}/{pages})", DIVIDER]
    lines.extend(f"• {mention_id(r['user_id'])} — {html.escape(r['nickname'])}" for r in rows)
    if pages > 1:
        lines.append(f"\nСледующая страница: <code>ники {page + 2}</code>")
