@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split(maxsplit=1) or [""])[0].casefold() == "сетник"),
)
async def cmd_setnick(message: Message):
    """«сетник @username Ник» / «сетник Ник» (ответом на сообщение) —
    админ устанавливает ник ДРУГОМУ участнику. В отличие от «+ник», где
    цель всегда сам вызвавший, здесь цель обязательно кто-то другой:
    для себя по-прежнему используется «+ник»."""
    min_level = required_level("nick_set")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше.")
        return

    target, remaining = await resolve_command_target(message)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "Использование: <code>сетник @username Ник</code>, либо ответом на сообщение "
            "человека: <code>сетник Ник</code>."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return
    if target.is_bot:
        await message.reply("Ботам ник не нужен 🤖")
        return

    # remaining может по-прежнему начинаться со слова-триггера «сетник»
    # (resolve_command_target вырезает только саму цель, а не сам триггер —
    # так же, как и в остальных командах бота, см. skip_words=1 у «варн»).
    rest_tokens = remaining.strip().split(maxsplit=1)
    if rest_tokens and rest_tokens[0].casefold() == "сетник":
        value = rest_tokens[1].strip() if len(rest_tokens) > 1 else ""
    else:
        value = remaining.strip()

    if not value:
        await message.reply("Укажите ник после цели, например: <code>сетник @username Крутыш</code>.")
        return
    if len(value) > 32:
        await message.reply("⚠️ Слишком длинный ник (максимум 32 символа).")
        return

    await db.set_nickname(message.chat.id, target.id, value)
    await db.add_log(
        "nickname_set", chat_id=message.chat.id, actor_id=message.from_user.id,
        target_id=target.id, details=value,
    )
    target_name = await display_name(message.chat.id, target)
    await message.reply(f"✅ Ник {target_name} в этом чате теперь: <b>{html.escape(value)}</b>")



