@router.callback_query(F.data.startswith("nickreset_yes:"))
async def confirm_nick_reset_all(callback: CallbackQuery):
    try:
        initiator_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Подтвердить может только тот, кто вызвал команду.", show_alert=True)
        return
    if not has_level(callback.from_user.id, required_level("nick_reset_all")):
        await callback.answer(f"⛔ Только «{level_name(required_level('nick_reset_all'))}» и выше может это сделать.", show_alert=True)
        return
    chat_id = callback.message.chat.id
    removed = await db.delete_all_nicknames(chat_id)
    await db.add_log("nickname_reset", chat_id=chat_id, actor_id=callback.from_user.id, details=f"все ({removed})")
    try:
        await callback.message.edit_text(f"🗑 <b>Готово</b>\nУдалено ников: {removed}.")
    except TelegramBadRequest:
        pass
    await callback.answer("Сброшено ✅")


@router.callback_query(F.data.startswith("nickreset_no:"))
async def cancel_nick_reset_all(callback: CallbackQuery):
    try:
        initiator_id = int(callback.data.split(":", 1)[1])
    except (IndexError, ValueError):
        await callback.answer()
        return
    if callback.from_user.id != initiator_id and not is_admin(callback.from_user.id):
        await callback.answer("Это не ваша кнопка 🙂", show_alert=True)
        return
    try:
        await callback.message.edit_text("Отменено — ники не тронуты.")
    except TelegramBadRequest:
        pass
    await callback.answer()


# ---------- Неактивные участники и молчуны ----------
async def _drop_left_members(chat_id: int, rows: list[dict]) -> list[dict]:
    """Убирает из списка тех, кого в чате уже нет, и чистит за собой ростер.

    Одной сверки с базой мало. Ростер current_users чистится в
    handle_member_left, то есть ТОЛЬКО когда бот получил событие выхода.
    Пропустил его — был выключен, Telegram не доставил апдейт в большой
    супергруппе — и человек остаётся в ростере навсегда. В списке неактивных
    такой призрак вылезает первым: он «не писал» дольше всех.

    Поэтому спрашиваем Telegram напрямую. Заодно удаляем найденных из
    ростера: список сам себя лечит, и со второго вызова лишних запросов уже
    не будет.

    Не смогли узнать статус (сеть, права) — человека ОСТАВЛЯЕМ. Выкинуть
    настоящего участника из-за сетевого сбоя хуже, чем показать лишнего.
    """
    alive: list[dict] = []
    for row in rows:
        user_id = int(row["user_id"])
        try:
            member = await bot.get_chat_member(chat_id, user_id)
        except (TelegramBadRequest, TelegramForbiddenError):
            # Telegram отвечает ошибкой и на «пользователь не найден» — такого
            # в чате точно нет, и держать его в ростере незачем.
            await db.delete_current_user(chat_id, user_id)
            continue
        except Exception as exc:
            log_suppressed("_drop_left_members", exc)
            alive.append(row)
            continue
        if member.status in ("left", "kicked"):
            await db.delete_current_user(chat_id, user_id)
            continue
        alive.append(row)
    return alive


async def _inactive_silent_text(rows: list[dict], title: str, date_field: str) -> str:
    if not rows:
        return f"{title}\n\nТаких не нашлось 🎉"
    lines = [title, DIVIDER]
    for i, row in enumerate(rows, start=1):
        name = mention_id(row["user_id"], full_name=row.get("full_name"), username=row.get("username"))
        ts: datetime = row[date_field]
        lines.append(f"{i}. {name} — {fmt_date(ts)}")
    return "\n".join(lines)


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(
        lambda t: bool(t)
        and (t.strip().casefold().split(maxsplit=1) or [""])[0] in ("неактив", "кто", "список")
        and "неактив" in t.strip().casefold()
    ),
)
async def cmd_inactive_list(message: Message):
    if not has_level(message.from_user.id, required_level("inactive_list")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('inactive_list'))}» и выше.")
        return
    # Период — только если последний токен реально парсится как длительность.
    # Иначе (напр. «кто неактив» без времени) берём дефолтную неделю, а не ругаемся.
    tokens = message.text.strip().split()
    duration = parse_duration(tokens[-1]) if len(tokens) > 1 else None
    if duration is None:
        duration = timedelta(days=7)
    cutoff = datetime.utcnow() - duration
    # Берём с запасом: часть строк отсеется как вышедшие, и без запаса
    # список после чистки оказался бы короче запрошенного.
    rows = await db.list_inactive(message.chat.id, cutoff, limit=50)
    rows = (await _drop_left_members(message.chat.id, rows))[:30]
    await message.reply(await _inactive_silent_text(rows, f"😴 <b>Неактивные с {fmt_date(cutoff)}</b>", "last_seen_at"))


