# ============================================================================
# Случайные события чата (каталог и правила — chat_events.py).
#
# Активное событие лежит одной JSON-строкой в bot_data: срок жизни у него
# минуты, отдельная таблица ради этого не нужна, а перезапуск бота посреди
# «золотой лихорадки» не должен её отменять — поэтому не память, а БД.
# ============================================================================
CHAT_EVENTS_TICK = 600  # как часто цикл заглядывает в каждый чат, сек


def _events_state_key(chat_id: int) -> str:
    return f"chat_event:{chat_id}"


def _events_off_key(chat_id: int) -> str:
    return f"chat_events_off:{chat_id}"


async def events_enabled(chat_id: int) -> bool:
    return (await db.get_data(_events_off_key(chat_id))) is None


async def get_active_event(chat_id: int) -> Optional[dict]:
    """Активное событие чата или None. Истёкшие подчищает на месте, поэтому
    вызывающему коду не нужно самому сверяться с часами."""
    row = await db.get_data(_events_state_key(chat_id))
    if not row:
        return None
    try:
        state = json.loads(row["data_value"])
    except (ValueError, TypeError):
        await db.delete_data(_events_state_key(chat_id))
        return None
    until = state.get("until")
    if until:
        try:
            if datetime.utcnow() >= datetime.fromisoformat(until):
                return None
        except ValueError:
            return None
    return state


async def event_multiplier(chat_id: int, tag: str) -> float:
    """Во сколько раз активное событие меняет награду с этим тегом."""
    return chat_events.multiplier(await get_active_event(chat_id), tag)


async def event_flag(chat_id: int, name: str) -> bool:
    return chat_events.flag(await get_active_event(chat_id), name)


async def _apply_moment_event(chat_id: int, event: chat_events.Event) -> Optional[str]:
    """Мгновенное событие: делает всё прямо здесь и возвращает готовый текст
    объявления. None — событие не к месту (некого награждать, нечего пополнять),
    тогда цикл просто промолчит и попробует в следующий раз."""
    key = event.key

    if key in ("stock_crash", "stock_rally"):
        old = await db.get_stock_price(chat_id)
        new_price = max(old * (1 + event.amount / 100), 0.01)
        now = datetime.utcnow()
        await db.set_stock_price(chat_id, new_price, now)
        await db.add_stock_price_point(chat_id, new_price, event.amount, now, "event")
        return chat_events.describe(event, amount=abs(event.amount), price=f"{new_price:.2f}")

    if key in ("meteor", "lottery", "inheritance", "bank_error"):
        holders = await db.list_wallet_holders(chat_id, min_coins=0, limit=200)
        if not holders:
            return None
        winner = random.choice(holders)
        await db.add_coins(chat_id, int(winner["user_id"]), int(event.amount))
        # display_name_by_id() отдаёт ГОТОВУЮ HTML-ссылку (имя внутри уже
        # экранировано). Экранировать её ещё раз нельзя: тогда в чат уходит
        # «&lt;a href=…&gt;», и Telegram рисует это видимым текстом вместо
        # кликабельного имени — именно так ломался «Метеоритный дождь».
        name = await display_name_by_id(chat_id, int(winner["user_id"]))
        return chat_events.describe(event, name=name, amount=int(event.amount))

    if key == "pickpocket":
        holders = await db.list_wallet_holders(chat_id, min_coins=100, limit=200)
        if not holders:
            return None
        victim = random.choice(holders)
        stolen = max(1, int(int(victim["coins"]) * event.amount / 100))
        stolen = await db.take_coins_up_to(chat_id, int(victim["user_id"]), stolen)
        if not stolen:
            return None      # у жертвы уже пусто — событие не состоялось
        name = await display_name_by_id(chat_id, int(victim["user_id"]))  # уже HTML-ссылка, см. выше
        return chat_events.describe(event, name=name, amount=stolen)

    if key == "handout":
        treasury = await db.get_chat_coins(chat_id)
        recent = await db.list_recent_active_users(chat_id, limit=300)
        if not recent:
            return None
        per_head = int(event.amount)
        need = per_head * len(recent)
        if treasury < need:                       # в казне пусто — не выдумываем деньги
            return None
        await db.add_chat_coins(chat_id, -need)
        got = await db.add_coins_to_users(chat_id, [int(u["user_id"]) for u in recent], per_head)
        return chat_events.describe(event, amount=per_head, count=got)

    if key == "tax":
        total = await db.tax_all_wallets(chat_id, event.amount)
        if total <= 0:
            return None
        await db.add_chat_coins(chat_id, total)
        return chat_events.describe(event, amount=f"{event.amount:.0f}", total=total)

    if key == "chat_bonus":
        await db.add_chat_coins(chat_id, int(event.amount))
        return chat_events.describe(event, amount=int(event.amount))

    if key == "amnesty":
        freed = await db.clear_all_surveillance(chat_id)
        if not freed:
            return None
        return chat_events.describe(event, count=freed)

    if key == "shop_restock":
        touched = await db.restock_shop_items(chat_id)
        if not touched:
            return None
        return chat_events.describe(event, count=touched)

    if key == "charity":
        # Единственное событие, которое платит адресно: тем, у кого в кармане
        # меньше порога. Порог — event.amount, размер выплаты считаем от того,
        # что реально лежит в казне: выдумывать деньги нельзя, поэтому если на
        # всех не хватает — событие просто не состоялось.
        threshold = int(event.amount)
        poor = await db.list_poor_wallets(chat_id, threshold, limit=100)
        if not poor:
            return None
        treasury = int(await db.get_chat_coins(chat_id))
        per_head = min(threshold // 2, treasury // len(poor))
        if per_head < 1:
            return None
        payout = per_head * len(poor)
        await db.add_chat_coins(chat_id, -payout)
        got = await db.add_coins_to_users(chat_id, [int(u["user_id"]) for u in poor], per_head)
        return chat_events.describe(event, amount=threshold, per_head=per_head, count=got)

    logger.warning("Мгновенное событие «%s» не имеет обработчика", key)
    return None


async def _announce_event_end(chat_id: int, key: str) -> None:
    event = chat_events.EVENTS_BY_KEY.get(key)
    if not event or not event.ends_text:
        return
    try:
        await bot.send_message(chat_id, event.ends_text)
    except Exception as exc:
        log_suppressed("_announce_event_end", exc)


async def fire_chat_event(chat_id: int, event: chat_events.Event,
                          minutes: Optional[int] = None) -> bool:
    """Запускает конкретное событие в чате. True — получилось и объявлено.

    minutes — своя длительность вместо штатной (команда «ивент {название}
    {время}»). Мгновенных событий не касается: им длиться нечем.
    """
    if event.kind == chat_events.MOMENT:
        text = await _apply_moment_event(chat_id, event)
        if text is None:
            return False
        state = {"key": event.key, "until": None}
    else:
        lasts = minutes if minutes else event.minutes
        until = datetime.utcnow() + timedelta(minutes=lasts)
        state = {"key": event.key, "until": until.isoformat()}
        text = chat_events.describe(event)
        if minutes and minutes != event.minutes:
            # Тексты событий описывают срок прозой («ближайший час»), поэтому
            # при своей длительности к ним дописывается честная строка —
            # иначе объявление противоречило бы тому, что реально произойдёт.
            text += f"\n⏱ Продлится: {format_duration_ru(timedelta(minutes=lasts))}."

    # История нужна, чтобы pick() не гонял одно и то же по кругу.
    history = state.get("history") or []
    prev = await db.get_data(_events_state_key(chat_id))
    if prev:
        try:
            history = (json.loads(prev["data_value"]).get("history") or [])
        except (ValueError, TypeError):
            history = []
    state["history"] = (history + [event.key])[-chat_events.NO_REPEAT_LAST:]
    state["started"] = datetime.utcnow().isoformat()

    await db.set_data(_events_state_key(chat_id), json.dumps(state, ensure_ascii=False))
    try:
        await bot.send_message(chat_id, text)
    except Exception:
        logger.exception("Не удалось объявить событие «%s» в чате %s", event.key, chat_id)
        return False
    await db.add_log("chat_event", chat_id=chat_id, details=event.key)

    if event.kind == chat_events.BUFF:
        asyncio.create_task(_schedule_event_end(chat_id, event, minutes))
    return True


async def _schedule_event_end(chat_id: int, event: chat_events.Event,
                              minutes: Optional[int] = None) -> None:
    """Объявляет конец баффа. Отдельной задачей, а не в цикле, чтобы «кончилось»
    приходило вовремя, а не с точностью до тика в 10 минут."""
    try:
        await asyncio.sleep((minutes if minutes else event.minutes) * 60)
        current = await db.get_data(_events_state_key(chat_id))
        if not current:
            return
        try:
            if json.loads(current["data_value"]).get("key") != event.key:
                return          # за это время успело начаться другое событие
        except (ValueError, TypeError):
            return
        await _announce_event_end(chat_id, event.key)
    except asyncio.CancelledError:
        raise
    except Exception:
        logger.exception("Сбой при объявлении конца события «%s»", event.key)


async def chat_events_loop() -> None:
    """Раз в CHAT_EVENTS_TICK заглядывает в каждый чат и с некоторой
    вероятностью запускает событие. Пропускает чаты, где события выключены,
    где уже что-то идёт и где недавно уже было."""
    while True:
        try:
            await asyncio.sleep(CHAT_EVENTS_TICK)
            now = datetime.utcnow()
            for chat_id in await db.list_active_chat_ids():
                try:
                    if not await events_enabled(chat_id):
                        continue
                    row = await db.get_data(_events_state_key(chat_id))
                    history: list[str] = []
                    if row:
                        try:
                            state = json.loads(row["data_value"])
                        except (ValueError, TypeError):
                            state = {}
                        history = state.get("history") or []
                        until = state.get("until")
                        if until:
                            try:
                                if now < datetime.fromisoformat(until):
                                    continue          # бафф ещё идёт
                            except ValueError:
                                pass
                        started = state.get("started")
                        if started:
                            try:
                                if (now - datetime.fromisoformat(started)).total_seconds() \
                                        < chat_events.MIN_MINUTES_BETWEEN * 60:
                                    continue          # слишком рано для следующего
                            except ValueError:
                                pass
                    if not chat_events.should_fire():
                        continue
                    event = chat_events.pick(history)
                    if event is not None:
                        await fire_chat_event(chat_id, event)
                except Exception:
                    logger.exception("Сбой события в чате %s", chat_id)
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception("Сбой в цикле событий чата")


# «Ивент» и «событие» — одно и то же, просто кто-то говорит так, кто-то эдак.
# Обе формы держим в одном месте, чтобы синонимы не расползались по файлу.
# Голого «ивент» здесь нет намеренно: это слово занято запуском
# («ивент {название} {время}»), и держать его в обоих списках значило бы
# сделать «ивент» неоднозначным для опознавания команды по тексту. Смотреть —
# «ивенты», во множественном числе.
EVENT_STATUS_TRIGGERS = {
    "события", "!события", "событие",
    "ивенты", "!ивенты",
}
EVENT_TOGGLE_TRIGGERS = {"+события", "-события", "+ивент", "-ивент", "+ивенты", "-ивенты"}


def _event_status_lines(state: Optional[dict]) -> list[str]:
    event = chat_events.EVENTS_BY_KEY.get((state or {}).get("key") or "")
    if event is None or event.kind != chat_events.BUFF:
        return ["🎲 <b>События чата</b>", DIVIDER, "Сейчас ничего не происходит — ждите."]
    left = ""
    until = (state or {}).get("until")
    if until:
        try:
            remaining = datetime.fromisoformat(until) - datetime.utcnow()
            if remaining.total_seconds() > 0:
                left = f"\nОсталось: {format_duration_ru(remaining)}."
        except ValueError:
            pass
    return ["🎲 <b>Сейчас в чате</b>", DIVIDER, chat_events.describe(event) + left]


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and ru_text.yo(t.strip().casefold()) in EVENT_STATUS_TRIGGERS),
)
async def cmd_chat_event_status(message: Message):
    if not _check_misc_access(message.from_user.id, "chat_events"):
        return
    lines = _event_status_lines(await get_active_event(message.chat.id))
    if not await events_enabled(message.chat.id):
        lines.append("\n⚠️ События в этом чате выключены (<code>+ивент</code> — включить).")
    # Список названий нужен прямо здесь: без него человек не знает, что писать
    # в «ивент {название} {время}», и идёт искать в справке.
    lines.append("")
    lines.append(f"📋 <b>Какие бывают</b> ({len(chat_events.EVENTS)}):")
    lines.append(", ".join(f"<code>{e.key}</code>" for e in chat_events.EVENTS))
    if has_level(message.from_user.id, required_level("chat_events_toggle")):
        lines.append("")
        lines.append("Запустить: <code>ивент {название} {время}</code> — "
                     "например <code>ивент gold_rush 30м</code>")
    await message.answer("\n".join(lines))


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and ru_text.yo(t.strip().casefold()) in EVENT_TOGGLE_TRIGGERS),
)
async def cmd_chat_events_toggle(message: Message):
    min_level = required_level("chat_events_toggle")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Включать и выключать события может «{level_name(min_level)}» и выше.")
        return
    on = message.text.strip().startswith("+")
    if on:
        await db.delete_data(_events_off_key(message.chat.id))
        await message.reply("🎲 Случайные события включены. Ждите сюрпризов.")
    else:
        await db.set_data(_events_off_key(message.chat.id), "1", updated_by=message.from_user.id)
        await message.reply("🎲 Случайные события выключены.")


# «ивент {название} {время}» и старая форма «событие запустить {ключ}».
# Название ловим жадно и разбираем уже в обработчике: у событий есть
# многословные заголовки («золотая лихорадка»), и резать по первому пробелу
# значило бы принимать только ключи.
# Голого «событие {что-то}» здесь намеренно НЕТ: «событие века», «событие
# произошло вчера» — обычные фразы, и админ, написавший такое в чате, получал
# бы в ответ простыню со списком событий. У «ивент» такой проблемы нет: в
# живой речи оно почти не встречается отдельным словом с продолжением.
EVENT_FORCE_RE = ru_text.rx(
    r"(?i)^!?(?:событие\s+запустить|ивент)\s+(.+)$"
)
# Верхний предел — чтобы «ивент gold_rush 100д» не подвесил бафф на неделю:
# задача события — встряхнуть чат на время, а не поменять правила навсегда.
EVENT_MAX_MINUTES = 24 * 60


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(EVENT_FORCE_RE.match(t.strip()))),
)
async def cmd_chat_event_force(message: Message):
    min_level = required_level("chat_events_toggle")
    if not has_level(message.from_user.id, min_level):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Запускать события вручную может «{level_name(min_level)}» и выше.")
        return

    rest = EVENT_FORCE_RE.match(message.text.strip()).group(1).strip()
    # Время — последнее слово, но только если оно и правда время: у события
    # может быть многословное название, и «ивент золотая лихорадка» без срока
    # обязано работать так же, как с ним.
    minutes: Optional[int] = None
    parts = rest.rsplit(maxsplit=1)
    if len(parts) == 2:
        duration = parse_duration(parts[1])
        if duration is not None:
            rest = parts[0]
            minutes = max(1, int(duration.total_seconds() // 60))

    event = chat_events.resolve(rest)
    if event is None:
        keys = ", ".join(f"<code>{e.key}</code>" for e in chat_events.EVENTS)
        await message.reply(
            f"Нет такого события — или название подходит сразу к нескольким.\n"
            f"Доступные:\n{keys}"
        )
        return

    if minutes is not None:
        if event.kind == chat_events.MOMENT:
            await message.reply(
                f"«{event.title}» срабатывает мгновенно — длительность ему не задать. "
                f"Запускаю как есть."
            )
            minutes = None
        elif minutes > EVENT_MAX_MINUTES:
            await message.reply(
                f"Слишком долго: максимум "
                f"{format_duration_ru(timedelta(minutes=EVENT_MAX_MINUTES))}."
            )
            return

    if not await fire_chat_event(message.chat.id, event, minutes):
        await message.reply(
            "Событие не подошло к текущему состоянию чата "
            "(например, пустая казна или некого награждать). Попробуйте другое."
        )


# Час завоза — по настроенной зоне: с message_daily завоз никак не связан,
# а «магазин обновляется в 15:00» человек читает как своё местное время.
SHOP_RESTOCK_HOUR_LOCAL = 15
SHOP_RESTOCK_CHECK_INTERVAL = 300
_SHOP_RESTOCK_LAST_KEY_PREFIX = "shop_restock_last:"


async def shop_restock_loop() -> None:
    while True:
        try:
            await asyncio.sleep(SHOP_RESTOCK_CHECK_INTERVAL)
            now = local_now()
            if now.hour != SHOP_RESTOCK_HOUR_LOCAL:
                continue
            today_str = now.date().isoformat()
            chat_ids = await db.list_shop_chat_ids()
            for chat_id in chat_ids:
                last_key = _SHOP_RESTOCK_LAST_KEY_PREFIX + str(chat_id)
                last_row = await db.get_data(last_key)
                if last_row and last_row.get("data_value") == today_str:
                    continue

                rows = await db.list_shop_items_for_restock(chat_id)
                lines = ["🔄 <b>Магазин обновился!</b>", DIVIDER]
                restocked_any = False
                for row in rows:
                    max_amount = int(row["restock_max"] or 0)
                    if max_amount <= 0:
                        continue
                    added = random.randint(0, max_amount)
                    if added <= 0:
                        continue
                    await db.restock_shop_item(chat_id, row["item_key"], added)
                    item = await db.get_shop_item(chat_id, row["item_key"])
                    if item:
                        lines.append(f"{item['emoji']} {html.escape(item['name'])} +{added}")
                        restocked_any = True

                await db.set_data(last_key, today_str)
                notify_chat = settings.get("complaint_chat_id")
                if restocked_any and notify_chat:
                    try:
                        await bot.send_message(notify_chat, "\n".join(lines))
                    except Exception:
                        logger.warning(
                            "shop_restock_loop: не удалось отправить в чат %s", notify_chat, exc_info=True
                        )
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception("Сбой в цикле пополнения магазина")


# Здесь лежал недописанный черновик birthday_congrats_loop: он подставлял в
# текст несуществующее имя (`{mention/имя}`) и всё равно никогда не выполнялся —
# рабочая версия ниже объявлена под тем же именем и перекрывала его. Удалён,
# чтобы при следующей правке никто не «починил» и не запустил именно его.

BIRTHDAY_CHECK_INTERVAL = 3600  # проверяем раз в час, шлём раз в сутки


async def birthday_congrats_loop() -> None:
    """Раз в сутки проверяет, у кого сегодня день рождения (по UTC-дате),
    и поздравляет в каждом чате, где бот видел этого пользователя.

    Защита от повторной отправки при рестарте бота в тот же день — метка
    последней отправки хранится в bot_data (db.set_data/get_data), как и
    в weekly_digest_loop выше."""
    while True:
        try:
            await asyncio.sleep(BIRTHDAY_CHECK_INTERVAL)
            now = datetime.utcnow()
            today_key = f"birthday_sent:{now.date().isoformat()}"

            rows = await db.list_birthdays_for_day(now.day, now.month)
            if not rows:
                continue

            sent_row = await db.get_data(today_key)
            already_sent = set((sent_row.get("data_value") or "").split(",")) if sent_row else set()

            newly_sent = []
            for row in rows:
                user_id = int(row["user_id"])
                if str(user_id) in already_sent:
                    continue
                chats = await db.list_user_chats(user_id)
                for chat_id in chats:
                    try:
                        name = await display_name_by_id(chat_id, user_id)
                        await bot.send_message(
                            chat_id,
                            f"🎉🎂 Сегодня день рождения у {name}! Поздравляем и желаем всего самого лучшего! 🥳",
                        )
                    except Exception:
                        logger.warning(
                            "Не удалось отправить поздравление в чат %s для %s",
                            chat_id, user_id, exc_info=True,
                        )
                newly_sent.append(str(user_id))

            if newly_sent:
                await db.set_data(today_key, ",".join(already_sent | set(newly_sent)))
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception("Сбой в цикле поздравлений с ДР")
# ---------- Репутация: «+5» / «-3» ответом на сообщение ----------
#
# Плюсы работают всегда, минусы — только если админ включил «+минусит».
# Пока минусы выключены, «-5» игнорируется МОЛЧА: подсказку «включите
# минусит» пришлось бы писать на каждый минус, а в живом чате это быстро
# превращается в спам от бота.

REPUTATION_MAX_PER_VOTE = 5      # сколько очков можно дать за один раз
REPUTATION_DAILY_LIMIT = 20      # сколько всего очков в сутки на человека
REPUTATION_SAME_TARGET_COOLDOWN = 3600  # секунд между голосами за одного и того же

# Только знак и (необязательно) число: «+», «+5», «-3». Ничего больше в
# сообщении быть не должно, иначе поймали бы обычный текст вроде «-5 градусов».
REPUTATION_RE = ru_text.rx(r"^([+\-])\s*(\d{1,2})?$")


def _minus_enabled_key(chat_id: int) -> str:
    return f"minusit:{chat_id}"


async def is_minus_enabled(chat_id: int) -> bool:
    """Минусы выключены по умолчанию — репутация начинается с плюсов."""
    row = await db.get_data(_minus_enabled_key(chat_id))
    return row is not None and row.get("data_value") == "1"


# Плюс можно поставить не только знаком, но и словом — так живее и не надо
# помнить синтаксис. Слова подобраны однозначно-оценочные: обычные реплики
# вроде «согласен» или «реально» намеренно НЕ включены, иначе суточный лимит
# сгорал бы на обычном разговоре. «топ» тоже нельзя — это уже команда.
REPUTATION_PLUS_WORDS = {
    "респект", "жиза", "база", "красава", "красавчик", "годнота", "годно",
    "шедевр", "огонь", "пушка", "уважение", "плюсую", "плюс", "спасибо",
    "благодарю", "мощно",
}
REPUTATION_MINUS_WORDS = {
    "кринж", "бред", "дичь", "минусую", "позор",
}


def _reputation_word_sign(text: Optional[str]) -> int:
    """+1 / -1, если сообщение целиком состоит из оценочного слова, иначе 0.

    Знаки препинания и эмодзи по краям отбрасываем: «респект!!!» и «жиза🔥»
    люди пишут чаще, чем сухое слово.
    """
    if not text:
        return 0
    word = re.sub(r"^[^\w]+|[^\w]+$", "", text.strip().casefold())
    if word in REPUTATION_PLUS_WORDS:
        return 1
    if word in REPUTATION_MINUS_WORDS:
        return -1
    return 0


async def _apply_reputation(message: Message, sign: int, amount: int, quiet: bool) -> None:
    """Общая механика начисления.

    quiet=True — путь «словом»: об отказах молчим и вместо текста ставим
    реакцию. Слово могло быть просто репликой в разговоре, и отвечать на неё
    «лимит исчерпан» — то же самое навязчивое поведение, от которого мы
    избавились у минусов.
    """
    # Минусы выключены — молчим всегда: это настройка чата, а не ошибка
    # пользователя, и напоминать о ней на каждый минус значит спамить.
    if sign < 0 and not await is_minus_enabled(message.chat.id):
        return

    target_user = message.reply_to_message.from_user
    if target_user is None or target_user.is_bot:
        return
    if target_user.id == message.from_user.id:
        if not quiet:
            await message.reply("Себе репутацию не ставят 🙂")
        return

    chat_id = message.chat.id
    actor_id = message.from_user.id

    ago = await db.seconds_since_last_vote(chat_id, actor_id, target_user.id)
    if ago is not None and ago < REPUTATION_SAME_TARGET_COOLDOWN:
        if not quiet:
            left = (REPUTATION_SAME_TARGET_COOLDOWN - ago + 59) // 60
            await message.reply(
                f"Этому человеку вы уже ставили недавно. Можно снова через {left} мин."
            )
        return

    given = await db.sum_reputation_given(chat_id, actor_id, 24)
    if given + amount > REPUTATION_DAILY_LIMIT:
        if not quiet:
            left = max(0, REPUTATION_DAILY_LIMIT - given)
            await message.reply(
                f"На сегодня лимит: {REPUTATION_DAILY_LIMIT} очков в сутки, осталось {left}."
            )
        return

    # «Час признания» удваивает только плюсы: удваивать минусы — это уже
    # не праздник, а травля.
    granted = amount
    if sign > 0:
        granted = max(1, round(amount * await event_multiplier(chat_id, chat_events.T_REPUTATION)))
        # «Обаяшка» (питомец ПОЛУЧАТЕЛЯ) — репутацию ему дают охотнее.
        # Именно получателя, а не дарителя: способность про то, как человека
        # воспринимают, а не про его щедрость.
        granted = await _pet_lucky(chat_id, target_user.id, granted, "reputation")
    total = await db.change_reputation(chat_id, actor_id, target_user.id, sign * granted)
    await db.add_log(
        "reputation", chat_id=chat_id, actor_id=actor_id,
        target_id=target_user.id, details=str(sign * granted),
    )

    if quiet:
        # тихий отклик: реакция на само похвалённое сообщение
        await react(chat_id, message.reply_to_message.message_id, "🔥" if sign > 0 else "👎")
        return

    who = await display_name_by_id(chat_id, target_user.id)
    verb = "повысилась" if sign > 0 else "понизилась"
    emoji = "📈" if sign > 0 else "📉"
    await message.reply(f"{emoji} {who}: репутация {verb} на {amount}. Теперь {total}.")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.reply_to_message,
    F.text.func(lambda t: bool(t) and bool(REPUTATION_RE.match(t.strip()))),
)
async def cmd_reputation_vote(message: Message):
    if not _check_misc_access(message.from_user.id, "reputation"):
        return
    match = REPUTATION_RE.match(message.text.strip())
    sign = 1 if match.group(1) == "+" else -1
    amount = int(match.group(2)) if match.group(2) else 1
    if amount == 0:
        return
    await _apply_reputation(message, sign, min(amount, REPUTATION_MAX_PER_VOTE), quiet=False)


