# Бонус монет, который выдаётся ОДИН РАЗ вместе с соответствующей ачивкой
# стрика (grant_achievement идемпотентен — повторно не начислит).
STREAK_BONUS_COINS = {"streak_7": 100, "streak_30": 500, "streak_100": 2000}

async def _check_coin_achievements(chat_id: int, user_id: int) -> None:
    wallet = await db.get_wallet(chat_id, user_id)
    coins = int(wallet.get("coins") or 0)
    if coins >= 100_000:
        await grant_achievement(chat_id, user_id, "coins_100000")
    elif coins >= 10_000:
        await grant_achievement(chat_id, user_id, "coins_10000")


async def _increment_quote_count(chat_id: int, user_id: int) -> int:
    key = f"quotecount:{chat_id}:{user_id}"
    row = await db.get_data(key)
    count = int(row["data_value"]) + 1 if row and row.get("data_value") else 1
    await db.set_data(key, str(count))
    return count


