# ---------- Ники (персональные для каждого чата, как у Iris) ----------
@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and (t.strip().split(maxsplit=1) or [""])[0].casefold() in ("+ник", "ник", "-ник")),
)
async def cmd_nick(message: Message):
    parts = (message.text or "").strip().split(maxsplit=1)
    word = parts[0].casefold()
    target = message.reply_to_message.from_user if message.reply_to_message else message.from_user

    if word == "-ник":
        if target.id != message.from_user.id and not has_level(message.from_user.id, LEVEL_ADMIN):
            await message.reply("⛔ Убрать чужой ник может только администратор.")
            return
        await db.delete_nickname(message.chat.id, target.id)
        await db.add_log("nickname_reset", chat_id=message.chat.id, actor_id=message.from_user.id)
        if target.id == message.from_user.id:
            await message.reply("✅ Ник сброшен, снова будет отображаться ваше имя из Telegram.")
        else:
            name = await display_name(message.chat.id, target)
            await message.reply(f"✅ Ник {name} сброшен.")
        return

    if word == "ник":
        current = await db.get_nickname(message.chat.id, target.id)
        if target.id == message.from_user.id:
            if current:
                await message.reply(
                    f"Ваш текущий ник в этом чате: <b>{html.escape(current)}</b>\n\n"
                    "Изменить: <code>+ник Новый Ник</code>\n"
                    "Сбросить: <code>-ник</code>"
                )
            else:
                await message.reply(
                    "У вас пока нет ника в этом чате.\n\nЗадать: <code>+ник Ваш Ник</code>"
                )
        else:
            name = await display_name(message.chat.id, target)
            if current:
                await message.reply(f"✏️ Ник {name} в этом чате: <b>{html.escape(current)}</b>")
            else:
                await message.reply(f"У {name} пока нет ника в этом чате.")
        return

    # word == "+ник"
    if len(parts) < 2 or not parts[1].strip():
        await message.reply("Использование: <code>+ник Ваш Ник</code> (до 32 символов).")
        return
    value = parts[1].strip()
    if len(value) > 32:
        await message.reply("⚠️ Слишком длинный ник (максимум 32 символа).")
        return

    await db.set_nickname(message.chat.id, message.from_user.id, value)
    await db.add_log("nickname_set", chat_id=message.chat.id, actor_id=message.from_user.id, details=value)
    await message.reply(f"✅ Теперь в этом чате вы — <b>{html.escape(value)}</b>")


