# ---------- Карточка анкеты ----------
@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and ru_text.yo(t.strip().casefold()) in ("анкета", "моя анкета")),
)
async def cmd_anketa(message: Message):
    target = message.reply_to_message.from_user if message.reply_to_message else message.from_user
    if target.is_bot:
        await message.reply("У ботов анкеты нет 🤖")
        return

    card = await db.get_profile_card(message.chat.id, target.id)
    is_self = target.id == message.from_user.id

    if not is_self and card and not card.get("anketa_visible", 1):
        await message.reply("🔒 Этот пользователь скрыл свою анкету.\n\nПоказать её снова: <code>+анкета</code>")
        return

    name = await display_name(message.chat.id, target)
    lines = [f"🪪 <b>Анкета — {name}</b>", DIVIDER]

    has_data = False
    if card and card.get("gender"):
        lines.append(f"{GENDER_EMOJI[card['gender']]} Пол: <b>{GENDER_LABEL[card['gender']]}</b>")
        has_data = True
    if card and card.get("city"):
        lines.append(f"🏙 Город: <b>{html.escape(card['city'])}</b>")
        has_data = True
    if card and card.get("title"):
        lines.append(f"🎖 Звание: <b>{html.escape(card['title'])}</b>")
        has_data = True
    if card and card.get("motto"):
        lines.append(f"💬 Девиз: «{html.escape(card['motto'])}»")
        has_data = True
    if card and card.get("is_citizen"):
        lines.append("🏡 Гражданство: есть")
        has_data = True
    if card and card.get("about_text"):
        lines.append(f"\n📝 <b>О себе:</b>\n{html.escape(card['about_text'])}")
        has_data = True

    if not has_data:
        if is_self:
            await message.reply(
                "Ваша анкета пока пуста.\n\n"
                "Заполнить: <code>мой пол м|ж|др</code>, <code>!мой город Текст</code>, "
                "<code>о себе\nТекст</code>, <code>+звание Текст</code>, <code>+девиз Текст</code>"
            )
        else:
            await message.reply("У этого пользователя пока пустая анкета.")
        return

    if is_self and card and not card.get("anketa_visible", 1):
        lines.append("\n🔒 Анкета скрыта от других (<code>+анкета</code> — снова показать)")

    await message.reply("\n".join(lines))


# ---------- Браки ----------
# У слова «Брак» есть подкоманды (20-й модуль Iris): «брак да», «брак нет»,
# «брак продлить …», «брак цена продления …», «брак режим развода …». Все они
# обрабатываются отдельными хендлерами ниже, поэтому предложение руки и сердца
# обязано их пропускать — иначе «Брак да» уходило бы в предложение самому себе.
MARRIAGE_SUBCOMMANDS = ("да", "нет", "продлить", "цена", "режим")


def _is_marriage_proposal(text: Optional[str]) -> bool:
    if not text:
        return False
    parts = text.strip().casefold().split()
    if not parts or parts[0] != "брак":
        return False
    return len(parts) < 2 or parts[1] not in MARRIAGE_SUBCOMMANDS


# Ожидающие ответа предложения: (chat_id, кому предложили) → (кто предложил,
# когда). Нужны только для текстовых ответов «Брак да» / «Брак нет» — у кнопок
# всё необходимое лежит прямо в callback_data. В памяти, а не в БД: живёт
# предложение час, и переживать перезапуск ему незачем (кнопки после
# перезапуска продолжат работать, а текстовый ответ можно повторить).
_marriage_proposals: dict[tuple[int, int], tuple[int, datetime]] = {}
MARRIAGE_PROPOSAL_TTL = timedelta(hours=1)


def _remember_proposal(chat_id: int, target_id: int, proposer_id: int) -> None:
    now = datetime.utcnow()
    # Заодно подчищаем протухшие, чтобы словарь не рос вечно в шумном чате.
    for key, (_, created) in list(_marriage_proposals.items()):
        if now - created > MARRIAGE_PROPOSAL_TTL:
            _marriage_proposals.pop(key, None)
    _marriage_proposals[(chat_id, target_id)] = (proposer_id, now)


def _take_proposal(chat_id: int, target_id: int) -> Optional[int]:
    """Забирает (и удаляет) ожидающее предложение. None — если его нет/протухло."""
    found = _marriage_proposals.pop((chat_id, target_id), None)
    if not found:
        return None
    proposer_id, created = found
    if datetime.utcnow() - created > MARRIAGE_PROPOSAL_TTL:
        return None
    return proposer_id


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_marriage_proposal),
)
async def propose_marriage(message: Message):
    proposer = message.from_user
    target, _remaining = await resolve_command_target(message)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    if target is None:
        await message.reply(
            "💍 Чтобы сделать предложение, ответьте на сообщение человека словом <b>Брак</b>, "
            "либо укажите @username или ID сразу после «Брак»."
        )
        return
    if target.id is None:
        await message.reply(
            f"Не удалось найти @{html.escape(target.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение, если оно есть."
        )
        return

    if target.id == proposer.id:
        await message.reply("Нельзя сделать предложение самому себе 🙂")
        return
    if target.is_bot:
        await message.reply("Боты пока не выходят замуж/женятся 🤖")
        return

    existing_proposer = await db.get_marriage(message.chat.id, proposer.id)
    if existing_proposer:
        partner_name = await display_name_by_id(message.chat.id, existing_proposer["partner_id"])
        await message.reply(f"Вы уже состоите в браке с {partner_name} 💍")
        return

    existing_target = await db.get_marriage(message.chat.id, target.id)
    if existing_target:
        target_name = await display_name(message.chat.id, target)
        await message.reply(f"{target_name} уже состоит в браке 💍")
        return

    actor_name = await display_name(message.chat.id, proposer)
    target_name = await display_name(message.chat.id, target)
    kb = InlineKeyboardMarkup(
        inline_keyboard=[[
            InlineKeyboardButton(text="💍 Принять", callback_data=f"marriage_accept:{proposer.id}:{target.id}"),
            InlineKeyboardButton(text="💔 Отказать", callback_data=f"marriage_decline:{proposer.id}:{target.id}"),
        ]]
    )
    _remember_proposal(message.chat.id, target.id, proposer.id)
    await message.reply(
        "💌 <b>Предложение руки и сердца</b>\n\n"
        f"{actor_name} предлагает {target_name} вступить в брак! 💍\n\n"
        f"{target_name}, выберите свой ответ — кнопкой или словами "
        "<b>Брак да</b> / <b>Брак нет</b>:",
        reply_markup=kb,
    )


async def _seal_marriage(chat_id: int, proposer_id: int, target_id: int) -> tuple[bool, str]:
    """Заключает брак и выдаёт готовый текст-ответ.

    Общая для кнопки «💍 Принять» и текстового «Брак да» — иначе два пути
    заключения брака разъезжались бы по проверкам и по ачивкам.
    """
    if await db.get_marriage(chat_id, proposer_id) or await db.get_marriage(chat_id, target_id):
        return False, "Похоже, один из вас уже успел вступить в брак 💍"
    if not await db.create_marriage(chat_id, proposer_id, target_id):
        return False, "Один из вас уже успел вступить в брак 💍"

    _marriage_proposals.pop((chat_id, target_id), None)
    await db.add_log("marriage_created", chat_id=chat_id, actor_id=proposer_id, target_id=target_id)
    for spouse_id in (proposer_id, target_id):
        await grant_achievement(chat_id, spouse_id, "married")

    actor_name = await display_name_by_id(chat_id, proposer_id)
    target_name = await display_name_by_id(chat_id, target_id)
    return True, f"💍🎉 {actor_name} и {target_name} теперь официально в браке! Поздравляем!"


@router.callback_query(F.data.startswith("marriage_accept:"))
async def accept_marriage(callback: CallbackQuery):
    try:
        _, proposer_id_s, target_id_s = (callback.data or "").split(":")
        proposer_id, target_id = int(proposer_id_s), int(target_id_s)
    except (TypeError, ValueError):
        await callback.answer("Это предложение повреждено или устарело.", show_alert=True)
        return

    if callback.from_user.id != target_id:
        await callback.answer("Это предложение адресовано не вам 🙂", show_alert=True)
        return

    chat_id = callback.message.chat.id
    ok, text = await _seal_marriage(chat_id, proposer_id, target_id)
    if not ok:
        await callback.answer(text, show_alert=True)
        try:
            await callback.message.edit_reply_markup(reply_markup=None)
        except TelegramBadRequest:
            pass
        return
    try:
        await callback.message.edit_text(text)
    except TelegramBadRequest:
        pass
    await callback.answer("Поздравляем с браком! 🎉")


@router.callback_query(F.data.startswith("marriage_decline:"))
async def decline_marriage(callback: CallbackQuery):
    try:
        _, proposer_id_s, target_id_s = (callback.data or "").split(":")
        proposer_id, target_id = int(proposer_id_s), int(target_id_s)
    except (TypeError, ValueError):
        await callback.answer("Это предложение повреждено или устарело.", show_alert=True)
        return

    if callback.from_user.id != target_id:
        await callback.answer("Это предложение адресовано не вам 🙂", show_alert=True)
        return

    chat_id = callback.message.chat.id
    _marriage_proposals.pop((chat_id, target_id), None)
    actor_name = await display_name_by_id(chat_id, proposer_id)
    target_name = await display_name_by_id(chat_id, target_id)
    try:
        await callback.message.edit_text(f"💔 {target_name} отказал(а) {actor_name}.")
    except TelegramBadRequest:
        pass
    await db.add_log("marriage_declined", chat_id=chat_id, actor_id=proposer_id, target_id=target_id)
    await callback.answer("Предложение отклонено")


# «поженить пару @a @b» (или ответом на одного + @второй) — модератор женит двух
# ДРУГИХ людей напрямую, без предложения/согласия (в отличие от «брак», где
# человек сам предлагает партнёру). Доступ настраивается через ДК/сайт: ключ
# marry_pair в дереве команд, по умолчанию — модератор.
def _is_marry_pair_command(text: str | None) -> bool:
    if not text:
        return False
    parts = text.strip().casefold().split()
    return len(parts) >= 2 and parts[0] == "поженить" and parts[1] == "пару"


async def _collect_pair_targets(message: Message) -> list[SimpleNamespace]:
    """Собирает участников для «поженить пару»: ответ на сообщение + все
    @упоминания/text_mention + голые числовые ID после триггера «поженить пару».
    Порядок появления, без повторов по id. Неизвестный @ добавляется с id=None —
    чтобы дать понятную ошибку вместо тихого пропуска."""
    text = message.text or ""
    targets: list[SimpleNamespace] = []
    seen: set[int] = set()

    def add(u: SimpleNamespace) -> None:
        if u.id is not None:
            if u.id in seen:
                return
            seen.add(u.id)
        targets.append(u)

    if message.reply_to_message and message.reply_to_message.from_user:
        r = message.reply_to_message.from_user
        add(SimpleNamespace(id=r.id, full_name=r.full_name, username=r.username, is_bot=r.is_bot))

    for entity in message.entities or []:
        if entity.type == "text_mention" and entity.user is not None:
            u = entity.user
            add(SimpleNamespace(id=u.id, full_name=u.full_name, username=u.username, is_bot=u.is_bot))
        elif entity.type == "mention":
            username = text[entity.offset + 1: entity.offset + entity.length]
            known = await db.get_known_user_by_username_in_chat(message.chat.id, username)
            if known:
                add(SimpleNamespace(
                    id=known["user_id"], full_name=known.get("full_name"),
                    username=known.get("username") or username, is_bot=False,
                ))
            else:
                add(SimpleNamespace(id=None, full_name=None, username=username, is_bot=None))

    for w in text.split()[2:]:  # первые два слова — сам триггер «поженить пару»
        if w.isdigit():
            add(SimpleNamespace(id=int(w), full_name=None, username=None, is_bot=None))

    return targets


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_marry_pair_command),
)
async def cmd_marry_pair(message: Message):
    min_level = required_level("marry_pair")
    actor_level = get_level(message.from_user.id)
    if actor_level < min_level:
        if actor_level > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(min_level)}» и выше.")
        return

    targets = await _collect_pair_targets(message)
    unknown = next((t for t in targets if t.id is None), None)
    if unknown is not None:
        await message.reply(
            f"Не удалось найти @{html.escape(unknown.username or '')} — бот его ещё не видел в этом чате. "
            "Попробуйте ответом на его сообщение или укажите по ID."
        )
        return
    if len(targets) < 2:
        await message.reply(
            "Укажите двоих: <code>поженить пару @первый @второй</code> — либо ответом на "
            "сообщение одного и <code>@второй</code> в тексте."
        )
        return

    a, b = targets[0], targets[1]
    if a.id == b.id:
        await message.reply("Это один и тот же человек 🙂 Нужны двое разных.")
        return
    if a.is_bot or b.is_bot:
        await message.reply("Ботов женить нельзя 🤖")
        return

    for person in (a, b):
        existing = await db.get_marriage(message.chat.id, person.id)
        if existing:
            who = await display_name_by_id(message.chat.id, person.id)
            partner = await display_name_by_id(message.chat.id, existing["partner_id"])
            await message.reply(f"{who} уже состоит в браке с {partner} 💍")
            return

    if not await db.create_marriage(message.chat.id, a.id, b.id):
        await message.reply("Не удалось поженить — возможно, кто-то из них только что вступил в брак 💍")
        return

    a_name = await display_name_by_id(message.chat.id, a.id)
    b_name = await display_name_by_id(message.chat.id, b.id)
    await message.reply(f"💍🎉 {a_name} и {b_name} теперь официально в браке! Поздравляем!")
    await db.add_log(
        "marriage_created_by_admin", chat_id=message.chat.id,
        actor_id=message.from_user.id, target_id=a.id, details=str(b.id),
    )
    for spouse_id in (a.id, b.id):
        await grant_achievement(message.chat.id, spouse_id, "married")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    # «!Развод» — написание из 20-го модуля Iris; «.развод» работал раньше и
    # остаётся, чтобы не переучивать чат.
    F.text.func(lambda t: bool(t) and ru_text.yo(t.strip().casefold()) in (".развод", "!развод")),
)
async def cmd_divorce(message: Message):
    marriage = await db.get_marriage(message.chat.id, message.from_user.id)
    if not marriage:
        await message.reply("Вы пока ни с кем не в браке 🙂")
        return
