async def _restore_marriage(chat_id: int, user_id: int) -> str:
    """Общий возврат брака (кнопка/команда «вернуть брак»). Возвращает текст-ответ."""
    undo = await db.get_recent_dissolution("marriage", chat_id, user_id)
    if not undo:
        return "↩️ Нечего возвращать — либо вы не разводились, либо прошло больше 72 часов."
    a, b = undo["user_a"], undo["user_b"]
    if await db.get_marriage(chat_id, a) or await db.get_marriage(chat_id, b):
        return "Кто-то из вас уже вступил в новый брак 💍"
    if not await db.create_marriage(chat_id, a, b):
        return "Не удалось восстановить брак."
    await db.consume_dissolution(undo["id"])
    na = await display_name_by_id(chat_id, a)
    nb = await display_name_by_id(chat_id, b)
    return f"💞 {na} и {nb} восстановили брак!"


