def format_log_entry(e: dict) -> str:
    # created_at приходит из БД наивным UTC — без перевода журнал показывал
    # время на несколько часов назад независимо от настройки «часовой пояс».
    ts: datetime = to_local(e["created_at"])
    label = LOG_LABELS.get(e["event_type"], e["event_type"])
    parts = [f"<code>{ts.strftime('%d.%m %H:%M')}</code> {label}"]
    if e.get("actor_id"):
        parts.append(f"от {mention_id(e['actor_id'])}")
    if e.get("target_id"):
        parts.append(f"→ {mention_id(e['target_id'])}")
    if e.get("chat_id"):
        parts.append(f"(чат <code>{e['chat_id']}</code>)")
    if e.get("details"):
        parts.append(f"— {html.escape(str(e['details']))}")
    return " ".join(parts)


@router.message(F.text.func(lambda t: bool(t) and t.strip().casefold() == "логи"))
async def cmd_log(message: Message):
    if not has_level(message.from_user.id, required_level("log")):
        if get_level(message.from_user.id) > 0:
            await message.reply("⛔ Команда доступна только администраторам.")
        return
    entries = await db.get_recent_logs(limit=15)
    if not entries:
        await message.reply("🧾 Лог пуст.")
        return
    text = "🧾 <b>Последние события</b>\n\n" + "\n".join(format_log_entry(e) for e in entries)
    await message.answer(text)


