def themes_list_text() -> str:
    lines = ["🎭 <b>Доступные темы модераторов</b>", DIVIDER]
    for i, theme in enumerate(PRESET_THEMES, start=1):
        names = theme["names"]
        preview = ", ".join(
            f"{level_name_from(names, lvl)}" for lvl in (LEVEL_MODERATOR, LEVEL_ADMIN, LEVEL_SENIOR)
        )
        lines.append(f"{i}. {theme['icon']} <b>{theme['title']}</b> — {preview}")
    lines.append(f"\nПрименить: <code>!темы {{номер}}</code>, например <code>!темы 2</code>.")
    lines.append("Свои названия: <code>названия рангов</code> — покажет пример команды.")
    return "\n".join(lines)


def level_name_from(names: dict[int, str], level: int) -> str:
    return names.get(level, LEVEL_NAMES.get(level, f"Уровень {level}"))


async def apply_theme(theme: dict, actor_id: int) -> None:
    global custom_level_names, admin_icon
    custom_level_names = dict(theme["names"])
    admin_icon = theme["icon"]
    await db.save_setting("level_names", json.dumps(theme["names"], ensure_ascii=False))
    await db.save_setting("admin_icon", theme["icon"])
    await db.add_log("themes_changed", actor_id=actor_id, details=theme["title"])


@router.message(F.text.func(lambda t: bool(t) and bool(t.strip()) and (t.strip().casefold().split() or [""])[0].lstrip("!") == "темы"))
async def cmd_themes(message: Message):
    if not has_level(message.from_user.id, required_level("mod_themes")):
        if get_level(message.from_user.id) > 0:
            await message.reply(f"⛔ Команда доступна только с уровнем «{level_name(required_level('mod_themes'))}» и выше.")
        return

    
    args = message.text.strip().split(maxsplit=1)
    if len(args) < 2:
        await message.answer(themes_list_text())
        return
    arg = args[1].strip().casefold()
    theme = None
    if arg.isdigit():
        idx = int(arg)
        if 1 <= idx <= len(PRESET_THEMES):
            theme = PRESET_THEMES[idx - 1]
    else:
        for t in PRESET_THEMES:
            if t["title"].casefold() == arg:
                theme = t
                break
    if theme is None:
        await message.reply("🔍 Такой темы не найдено. Используйте <code>!темы</code>, чтобы увидеть список.")
        return
    await apply_theme(theme, message.from_user.id)
    preview = ", ".join(
        f"{level_name_from(theme['names'], lvl)}" for lvl in (LEVEL_MODERATOR, LEVEL_ADMIN, LEVEL_SENIOR)
    )
    await message.reply(f"✅ Установлена тема «{theme['icon']} {theme['title']}»: {preview}")


