# ----------------------------------------------------------------------------
# Точка входа
# ----------------------------------------------------------------------------
async def reschedule_chat_locks() -> None:
    """При старте бота восстанавливает таймеры авто-открытия для чатов,
    закрытых командой «-чат {срок}» до перезапуска бота."""
    rows, total = await db.list_data(limit=1000)
    restored = 0
    for row in rows:
        key = row.get("data_key") or ""
        if not key.startswith("chatlock:"):
            continue
        try:
            chat_id = int(key.split(":", 1)[1])
            data = json.loads(row.get("data_value") or "{}")
        except (ValueError, TypeError):
            continue
        until_iso = data.get("until") if isinstance(data, dict) else None
        if not until_iso:
            continue  # закрыт без срока — ждёт ручной команды +чат
        try:
            until_dt = datetime.fromisoformat(until_iso)
        except ValueError:
            continue
        delay = (until_dt - datetime.utcnow()).total_seconds()
        if delay <= 0:
            await _unlock_chat(chat_id)
            continue
        asyncio.create_task(_auto_unlock_chat(chat_id, delay, until_iso))
        restored += 1
    if restored:
        logger.info("Восстановлено таймеров авто-открытия чата: %d", restored)


async def reschedule_admin_holds() -> None:
    """При старте бота восстанавливает отложенные задачи возврата прав
    администратора для мутов с холдом (модуль «Холды администраторов»),
    оформленных до перезапуска бота. Холды без срока (бан или бессрочный
    мут) ждут только ручного снятия — фоновая задача им не нужна."""
    rows = await db.list_all_pending_admin_holds()
    restored = 0
    for row in rows:
        until: datetime = row["until"]
        asyncio.create_task(_auto_restore_admin_hold(row["chat_id"], row["user_id"], until.isoformat()))
        restored += 1
    if restored:
        logger.info("Восстановлено холдов администраторов: %d", restored)


async def reschedule_user_timers() -> None:
    """При старте бота восстанавливает отложенные задачи asyncio для таймеров
    из модуля «Таймеры», созданных командами «Таймер через» / «Таймер на»
    до перезапуска бота (сами таймеры хранятся в MySQL и переживают рестарт,
    но фоновая задача ожидания — нет)."""
    rows = await db.list_all_pending_timers()
    restored = 0
    for row in rows:
        fire_at: datetime = row["fire_at"]
        delay = (fire_at - datetime.utcnow()).total_seconds()
        asyncio.create_task(_fire_timer(row["id"], row["chat_id"], max(delay, 0), row["text"]))
        restored += 1
    if restored:
        logger.info("Восстановлено пользовательских таймеров: %d", restored)


# ============================================================================
# Модуль «Созывы» — упрощённая версия функций бота @ZazyvalaTagBot:
#   • свой позывной-эмодзи (мой эмодзи / сменить эмодзи / эмодзи)
#   • анрег — временный выход из созывов чата (до своего следующего сообщения)
#   • сами созывы — упомянуть всех известных боту участников чата, либо
#     только администраторов, батчами с задержкой (см. CALL_* константы выше)
#
# Как и остальная модерация в этом боте, запуск созыва доступен только
# «Модератору» и выше — это не публичная команда для всех подряд, чтобы
# созывами не могли злоупотреблять рядовые участники чата.
# ============================================================================

# Триггеры и разбор команд созыва живут в call_commands.py — там же их тесты
# (bot.py целиком в тестах не поднять: он тянет aiogram и базу).
CALL_TRIGGERS = call_commands.CALL_TRIGGERS
CALL_ADMIN_PHRASES = call_commands.CALL_ADMIN_PHRASES
CALL_STOP_TRIGGERS = call_commands.CALL_STOP_TRIGGERS

_first_word = call_commands.first_word


def _is_call_emoji_cmd(text: Optional[str]) -> bool:
    if not text or not text.strip():
        return False
    words = text.strip().casefold().split()
    return len(words) >= 2 and words[0] in ("мой", "-мой","мое","моё") and words[1] == "эмодзи" 


def _extract_custom_emoji_html(message: Message) -> Optional[str]:
    """Если в тексте команды есть кастомный (Telegram Premium) эмодзи —
    Telegram прикрепляет к нему entity type == "custom_emoji" с
    .custom_emoji_id; сам message.text в этом месте содержит лишь
    эмодзи-заглушку (обычный юникод-символ для отображения там, где кастомные
    эмодзи не поддерживаются) — настоящий кастомный вид виден только через
    эту entity. Возвращает HTML-фрагмент
    '<tg-emoji emoji-id="...">заглушка</tg-emoji>', который при отправке с
    parse_mode=HTML (как везде в этом боте) отрендерится как настоящий
    кастомный эмодзи. None, если кастомного эмодзи в тексте нет — тогда
    вызывающий код обрабатывает текст как обычный юникод-эмодзи, как раньше."""
    text = message.text or ""
    for entity in message.entities or []:
        if entity.type == "custom_emoji" and entity.custom_emoji_id:
            placeholder = text[entity.offset: entity.offset + entity.length]
            return f'<tg-emoji emoji-id="{entity.custom_emoji_id}">{html.escape(placeholder)}</tg-emoji>'
    return None


_is_call_admins_cmd = call_commands.is_call_admins_cmd
_is_call_all_cmd = call_commands.is_call_all_cmd
_is_call_stop_cmd = call_commands.is_call_stop_cmd

# Команду созыва часто пишут подписью к картинке («созыв, все сюда» + афиша).
# У такого сообщения message.text пустой — подпись лежит в caption.
call_command_text = call_commands.command_text


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(_is_call_emoji_cmd),
)
async def cmd_call_emoji(message: Message):
    """«мой эмодзи 🔥» — установить позывной (принимает и обычный эмодзи, и
    кастомный Premium-эмодзи — распознаётся через entity, см.
    _extract_custom_emoji_html), «мой эмодзи» — посмотреть свой, «-мой
    эмодзи» — сбросить."""
    parts = message.text.strip().split(maxsplit=2)
    is_reset = parts[0].casefold() == "-мой"
    rest = parts[2] if len(parts) > 2 else None

    if is_reset or (rest and rest.strip() in ("сброс", "убрать", "-")):
        await db.clear_call_emoji(message.chat.id, message.from_user.id)
        await message.reply("✅ Позывной-эмодзи сброшен.")
        return

    if not rest or not rest.strip():
        current = await db.get_call_emoji(message.chat.id, message.from_user.id)
        if current:
            await message.reply(f"Ваш текущий позывной: {current}\nСменить: <code>мой эмодзи 🙂</code>, сбросить: <code>-мой эмодзи</code>")
        else:
            await message.reply("Позывной пока не установлен.\nУстановить: <code>мой эмодзи 🙂</code> (пришлите один эмодзи, обычный или кастомный Premium), либо «сменить эмодзи» — для случайного.")
        return

    custom_emoji_html = _extract_custom_emoji_html(message)
    if custom_emoji_html:
        candidate = custom_emoji_html
    else:
        candidate = rest.strip()
        if not is_single_emoji(candidate):
            await message.reply("Похоже, это не один эмодзи 🙂 Пришлите что-то вроде <code>мой эмодзи 🔥</code>.")
            return

    await db.set_call_emoji(message.chat.id, message.from_user.id, candidate)
    await message.reply(f"✅ Ваш позывной теперь: {candidate}")


