# ============================================================================
# Модуль «Кланы» (по образцу Iris, раздел 17) — в отличие от «Кружков», у
# клана есть иерархия (лидер / замы / участники), казна, звание и девиз,
# а также войны между кланами на очки с общим топом. Состоять можно только
# в одном клане одновременно — вступление в другой автоматически снимает
# членство в прежнем (см. db.join_clan). Создать клан может любой участник.
#
# «{номер}» в командах — это id клана из таблицы clans, его видно в любом
# списке кланов рядом с названием (как «{номер}» у кружков).
# ============================================================================
CLAN_NAME_MAX = 64
CLAN_DESCRIPTION_MAX = 1000
CLAN_TITLE_MAX = 100
CLAN_MOTTO_MAX = 100
CLAN_LIST_PAGE_SIZE = 10


def _clan_role_mark(role: Optional[str]) -> str:
    if role == "leader":
        return "👑"
    if role == "deputy":
        return "⭐"
    return ""


async def clan_line(clan: dict, with_description: bool = False) -> str:
    members = clan.get("members_count")
    members_part = f" · 👥 {members}" if members is not None else ""
    line = (
        f"#{clan['id']} <b>{html.escape(clan['name'])}</b>{members_part} · "
        f"⚔️ {clan['war_points']} · 🪙 {clan['coins']}"
    )
    if clan.get("motto"):
        line += f"\n<i>«{html.escape(clan['motto'])}»</i>"
    if with_description and clan.get("description"):
        line += f"\n{html.escape(clan['description'])}"
    return line


async def clans_list_text(chat_id: int, page: int) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    page = max(page, 0)
    rows, total = await db.list_clans(chat_id, CLAN_LIST_PAGE_SIZE, page * CLAN_LIST_PAGE_SIZE)
    if not rows and page:
        page = 0
        rows, total = await db.list_clans(chat_id, CLAN_LIST_PAGE_SIZE, 0)
    if not rows:
        return "🏰 <b>Кланы чата</b>\n\nВ этом чате пока нет ни одного клана (см. «создать клан {название}»).", None

    lines = [await clan_line(r) for r in rows]
    pages = max((total + CLAN_LIST_PAGE_SIZE - 1) // CLAN_LIST_PAGE_SIZE, 1)
    text = f"🏰 <b>Кланы чата</b> ({total})\n{DIVIDER}\n" + f"\n{DIVIDER}\n".join(lines)
    if pages == 1:
        return text, None

    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="⬅️", callback_data=f"clans_page:{page - 1}"))
    nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page + 1 < pages:
        nav.append(InlineKeyboardButton(text="➡️", callback_data=f"clans_page:{page + 1}"))
    return text, InlineKeyboardMarkup(inline_keyboard=[nav])


async def clan_top_text(chat_id: int) -> str:
    rows = await db.list_clan_war_top(chat_id, 10)
    if not rows:
        return "⚔️ <b>Топ кланов по войнам</b>\n\nВ этом чате пока нет ни одного клана."
    lines = []
    for i, clan in enumerate(rows, start=1):
        lines.append(
            f"{i}. <b>{html.escape(clan['name'])}</b> — ⚔️ {clan['war_points']} очк. "
            f"({clan['wars_won']}/{clan['wars_drawn']}/{clan['wars_lost']})"
        )
    return (
        "⚔️ <b>Топ кланов по войнам</b>\n"
        f"{DIVIDER}\n" + "\n".join(lines) + "\n\n<i>(победы/ничьи/поражения)</i>"
    )


async def clan_info_text(chat_id: int, clan: dict) -> str:
    lines = [f"🏰 <b>{html.escape(clan['name'])}</b> (#{clan['id']})"]
    if clan.get("title"):
        lines.append(f"🎖 Звание: <b>{html.escape(clan['title'])}</b>")
    if clan.get("motto"):
        lines.append(f"💬 Девиз: «{html.escape(clan['motto'])}»")
    if clan.get("description"):
        lines.append(html.escape(clan["description"]))
    lines.append(DIVIDER)
    lines.append(f"👑 Лидер: {mention_id(clan['leader_id'])}")
    members_count = await db.count_clan_members(chat_id, clan["id"])
    lines.append(f"👥 Участников: <b>{members_count}</b>")
    lines.append(f"🪙 Казна: <b>{clan['coins']}</b>")
    lines.append(
        f"⚔️ Очки войн: <b>{clan['war_points']}</b> "
        f"({clan['wars_won']} побед / {clan['wars_drawn']} ничьих / {clan['wars_lost']} поражений)"
    )
    return "\n".join(lines)


async def clan_members_text(chat_id: int, clan_id: int, page: int) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    clan = await db.get_clan(chat_id, clan_id)
    if clan is None:
        return "Клан с таким номером не найден.", None
    page = max(page, 0)
    rows, total = await db.list_clan_members(chat_id, clan_id, CLAN_LIST_PAGE_SIZE, page * CLAN_LIST_PAGE_SIZE)
    if not rows and page:
        page = 0
        rows, total = await db.list_clan_members(chat_id, clan_id, CLAN_LIST_PAGE_SIZE, 0)
    title = f"👥 <b>Участники клана «{html.escape(clan['name'])}»</b> ({total})"
    if not rows:
        return f"{title}\n\nВ этом клане пока никого нет.", None
    lines = []
    for r in rows:
        mark = _clan_role_mark(r["role"])
        mark_part = f" {mark}" if mark else ""
        lines.append(f"{mention_id(r['user_id'])}{mark_part}")
    pages = max((total + CLAN_LIST_PAGE_SIZE - 1) // CLAN_LIST_PAGE_SIZE, 1)
    text = f"{title}\n{DIVIDER}\n" + "\n".join(lines) + "\n\n<i>👑 — лидер, ⭐ — зам</i>"
    if pages == 1:
        return text, None
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="⬅️", callback_data=f"clanmembers_page:{clan_id}:{page - 1}"))
    nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page + 1 < pages:
        nav.append(InlineKeyboardButton(text="➡️", callback_data=f"clanmembers_page:{clan_id}:{page + 1}"))
    return text, InlineKeyboardMarkup(inline_keyboard=[nav])


def _split_clan_name_and_description(raw: str) -> tuple[str, Optional[str]]:
    parts = raw.split("\n", 1)
    name = parts[0].strip()[:CLAN_NAME_MAX]
    description = parts[1].strip()[:CLAN_DESCRIPTION_MAX] if len(parts) > 1 and parts[1].strip() else None
    return name, description


CLAN_CREATE_RE = ru_text.rx(r"(?is)^создать\s+клан\s+(.+)$")
CLAN_EDIT_RE = ru_text.rx(r"(?is)^клан\s+изменить\s+(.+)$")
CLAN_TITLE_SET_RE = ru_text.rx(r"(?i)^\+клан\s+звание\s+(.+)$")
CLAN_TITLE_UNSET_RE = ru_text.rx(r"(?i)^-клан\s+звание$")
CLAN_MOTTO_SET_RE = ru_text.rx(r"(?i)^\+клан\s+девиз\s+(.+)$")
CLAN_MOTTO_UNSET_RE = ru_text.rx(r"(?i)^-клан\s+девиз$")
CLAN_DELETE_RE = ru_text.rx(r"(?i)^удалить\s+клан$")
CLAN_DELETE_ADMIN_RE = ru_text.rx(r"(?i)^!удалить\s+клан\s+(\d+)$")
CLAN_JOIN_RE = ru_text.rx(r"(?i)^(?:клан\s+вступить\s+(\d+)|\+клан\s+(\d+))$")
CLAN_LEAVE_RE = ru_text.rx(r"(?i)^(?:выйти\s+из\s+клана|-клан)$")
CLAN_LIST_RE = ru_text.rx(r"(?i)^кланы(?:\s+(\d+))?$")
CLAN_TOP_RE = ru_text.rx(r"(?i)^топ\s+кланов$")
CLAN_MY_RE = ru_text.rx(r"(?i)^мой\s+клан$")
CLAN_MEMBERS_RE = ru_text.rx(r"(?i)^участники\s+клана\s+(\d+)$")
CLAN_WAR_CHALLENGE_RE = ru_text.rx(r"(?i)^война\s+клана\s+(\d+)$")
CLAN_WAR_YES_RE = ru_text.rx(r"(?i)^война\s+да$")
CLAN_WAR_NO_RE = ru_text.rx(r"(?i)^война\s+нет$")
CLAN_WAR_CANCEL_RE = ru_text.rx(r"(?i)^война\s+отмена$")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CLAN_CREATE_RE.match(t.strip()))),
)
async def cmd_clan_create(message: Message):
    min_level = required_level("clan_create")
    if not has_level(message.from_user.id, min_level):
        await message.reply(f"⛔ Создавать кланы может «{level_name(min_level)}» и выше.")
        return
    existing = await db.get_user_clan(message.chat.id, message.from_user.id)
    if existing is not None:
        await message.reply(
            f"Вы уже состоите в клане «{html.escape(existing['name'])}» — сначала выйдите из него "
            "(«выйти из клана»; если вы лидер — сначала «передать клан {ссылка}» или «удалить клан»)."
        )
        return
    m = CLAN_CREATE_RE.match(message.text.strip())
    name, description = _split_clan_name_and_description(m.group(1))
    if not name:
        await message.reply("Укажите название клана: «создать клан {название}».")
        return
    clan_id = await db.create_clan(message.chat.id, message.from_user.id, name, description)
    await db.add_log("clan_create", chat_id=message.chat.id, actor_id=message.from_user.id, details=name)
    await message.reply(
        f"🏰 Клан «{html.escape(name)}» создан (#{clan_id}). Вы стали его лидером 👑."
    )
    await grant_achievement(message.chat.id, message.from_user.id, "clan_founder")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CLAN_EDIT_RE.match(t.strip()))),
)
async def cmd_clan_edit(message: Message):
    membership = await db.get_user_clan(message.chat.id, message.from_user.id)
    if membership is None or membership["role"] not in ("leader", "deputy"):
        await message.reply("⛔ Изменять клан может только его лидер или зам.")
        return
    m = CLAN_EDIT_RE.match(message.text.strip())
    name, description = _split_clan_name_and_description(m.group(1))
    if not name:
        await message.reply("Укажите название: «клан изменить {название}».")
        return
    await db.update_clan(message.chat.id, membership["id"], name=name, description=description)
    await db.add_log("clan_edit", chat_id=message.chat.id, actor_id=message.from_user.id, details=name)
    await message.reply(f"✏️ Клан #{membership['id']} обновлён: «{html.escape(name)}».")


