@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CLAN_DELETE_RE.match(t.strip()))),
)
async def cmd_clan_delete(message: Message):
    membership = await db.get_user_clan(message.chat.id, message.from_user.id)
    if membership is None:
        await message.reply("Вы не состоите ни в одном клане.")
        return
    if membership["role"] != "leader":
        await message.reply("⛔ Удалить клан может только его лидер (см. «передать клан {ссылка}»).")
        return
    kb = confirm_kb(
        yes_data=f"clandel_yes:{message.from_user.id}:{membership['id']}",
        no_data=f"clandel_no:{message.from_user.id}:{membership['id']}",
        yes_text="✅ Да, удалить",
    )
    members = await db.count_clan_members(message.chat.id, membership["id"])
    await message.reply(
        confirm_text(
            f"Удалить клан «{membership['name']}»?",
            [f"Участников в клане: <b>{members}</b>."],
        ),
        reply_markup=kb,
    )


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CLAN_DELETE_ADMIN_RE.match(t.strip()))),
)
async def cmd_clan_delete_admin(message: Message):
    clan_id = int(CLAN_DELETE_ADMIN_RE.match(message.text.strip()).group(1))
    clan = await db.get_clan(message.chat.id, clan_id)
    if clan is None:
        await message.reply("Клан с таким номером не найден.")
        return
    min_level = required_level("clan_delete_admin")
    if not has_level(message.from_user.id, min_level):
        await message.reply(f"⛔ Удалять чужие кланы может только «{level_name(min_level)}» и выше.")
        return
    kb = confirm_kb(
        yes_data=f"clandel_yes:{message.from_user.id}:{clan_id}",
        no_data=f"clandel_no:{message.from_user.id}:{clan_id}",
        yes_text="✅ Да, удалить",
    )
    members = await db.count_clan_members(message.chat.id, clan_id)
    await message.reply(
        confirm_text(
            f"Удалить клан «{clan['name']}»?",
            [f"Участников в клане: <b>{members}</b>."],
        ),
        reply_markup=kb,
    )


@router.callback_query(F.data.startswith("clandel_yes:"))
async def confirm_clan_delete(callback: CallbackQuery):
    try:
        _, initiator_str, clan_id_str = callback.data.split(":", maxsplit=2)
        initiator_id, clan_id = int(initiator_str), int(clan_id_str)
    except (ValueError, IndexError):
        await callback.answer("Кнопка устарела.", show_alert=True)
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Подтвердить может только тот, кто вызвал команду.", show_alert=True)
        return
    chat_id = callback.message.chat.id
    clan = await db.get_clan(chat_id, clan_id)
    if clan is None:
        await callback.answer("Клан уже удалён.", show_alert=True)
        try:
            await callback.message.edit_text("Клан уже удалён.")
        except TelegramBadRequest:
            pass
        return
    await db.delete_clan(chat_id, clan_id)
    await db.add_log("clan_delete", chat_id=chat_id, actor_id=initiator_id, details=clan["name"])
    try:
        await callback.message.edit_text(f"🗑 Клан «{html.escape(clan['name'])}» удалён.")
    except TelegramBadRequest:
        pass
    await callback.answer("Удалено ✅")


@router.callback_query(F.data.startswith("clandel_no:"))
async def cancel_clan_delete(callback: CallbackQuery):
    try:
        _, initiator_id_str, _ = callback.data.split(":", maxsplit=2)
        initiator_id = int(initiator_id_str)
    except (ValueError, IndexError):
        await callback.answer()
        return
    if callback.from_user.id != initiator_id:
        await callback.answer("Отменить может только тот, кто вызвал команду.", show_alert=True)
        return
    try:
        await callback.message.edit_text("Отменено.")
    except TelegramBadRequest:
        pass
    await callback.answer()


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CLAN_JOIN_RE.match(t.strip()))),
)
async def cmd_clan_join(message: Message):
    m = CLAN_JOIN_RE.match(message.text.strip())
    clan_id = int(m.group(1) or m.group(2))
    clan = await db.get_clan(message.chat.id, clan_id)
    if clan is None:
        await message.reply("Клан с таким номером не найден.")
        return
    existing = await db.get_user_clan(message.chat.id, message.from_user.id)
    if existing is not None and existing["id"] == clan_id:
        await message.reply(f"Вы уже состоите в клане «{html.escape(clan['name'])}».")
        return
    if existing is not None and existing["role"] == "leader":
        await message.reply(
            f"Вы лидер клана «{html.escape(existing['name'])}» — сначала передайте лидерство "
            "(«передать клан {ссылка}») или удалите клан («удалить клан»)."
        )
        return
    previous_id = await db.join_clan(message.chat.id, clan_id, message.from_user.id)
    await grant_achievement(message.chat.id, message.from_user.id, "clan_member")
    text = f"✅ Вы вступили в клан «{html.escape(clan['name'])}»."
    if previous_id is not None and previous_id != clan_id:
        prev = await db.get_clan(message.chat.id, previous_id)
        if prev is not None:
            text += f"\n👋 Вы автоматически покинули клан «{html.escape(prev['name'])}»."
    await message.reply(text)


