CLAN_TREASURY_DEPOSIT_RE = ru_text.rx(r"(?i)^клан\s+пополнить\s+казну\s+(\S+)$")
CLAN_TREASURY_WITHDRAW_RE = ru_text.rx(r"(?i)^клан\s+взять\s+с\s+казны\s+(\S+)$")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CLAN_TREASURY_DEPOSIT_RE.match(t.strip()))),
)
async def cmd_clan_treasury_deposit(message: Message):
    membership = await db.get_user_clan(message.chat.id, message.from_user.id)
    if membership is None:
        await message.reply("Вы не состоите ни в одном клане.")
        return
    amount = parse_amount(CLAN_TREASURY_DEPOSIT_RE.match(message.text.strip()).group(1))
    if amount is None or amount <= 0:
        await message.reply("Сумма должна быть больше нуля.")
        return
    if not await spend_coins(message.chat.id, message.from_user.id, amount):
        await message.reply(f"Недостаточно монет: нужно {amount}.")
        return
    new_coins = await db.add_clan_coins(message.chat.id, membership["id"], amount)
    await message.reply(
        f"🪙 Вы пополнили казну клана «{html.escape(membership['name'])}» на {amount} i¢.\n"
        f"Казна теперь: <b>{new_coins}</b>."
    )
    await db.add_log("clan_treasury_deposit", chat_id=message.chat.id, actor_id=message.from_user.id, details=str(amount))


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(CLAN_TREASURY_WITHDRAW_RE.match(t.strip()))),
)
async def cmd_clan_treasury_withdraw(message: Message):
    membership = await db.get_user_clan(message.chat.id, message.from_user.id)
    if membership is None or membership["role"] not in ("leader", "deputy"):
        await message.reply("⛔ Брать деньги из казны может только лидер или зам клана.")
        return
    amount = parse_amount(CLAN_TREASURY_WITHDRAW_RE.match(message.text.strip()).group(1))
    if amount is None or amount <= 0:
        await message.reply("Сумма должна быть больше нуля.")
        return
    if membership["coins"] < amount:
        await message.reply(f"В казне клана только {membership['coins']} i¢.")
        return
    new_coins = await db.add_clan_coins(message.chat.id, membership["id"], -amount)
    await db.add_coins(message.chat.id, message.from_user.id, amount)
    await message.reply(
        f"🪙 Вы забрали из казны клана «{html.escape(membership['name'])}» {amount} i¢.\n"
        f"Казна теперь: <b>{new_coins}</b>."
    )
    await db.add_log("clan_treasury_withdraw", chat_id=message.chat.id, actor_id=message.from_user.id, details=str(amount))

