# ----------------------------------------------------------------------------
# Инлайн-меню «мой клан» — полное управление кланом кнопками, без набора
# текстовых команд руками. Дублирует всю логику текстовых команд выше
# (те же проверки прав, те же db-вызовы) — просто другой UI поверх той же
# бизнес-логики. Открывается кнопкой из «мой клан» и из карточки клана
# в списке «кланы»/«участники клана №».
# ----------------------------------------------------------------------------
CLAN_MANAGE_PAGE_SIZE = 8
CLAN_WAR_PICK_PAGE_SIZE = 8


async def _clan_member_label(chat_id: int, user_id: int) -> str:
    """Обычный (не HTML) текст для подписи инлайн-кнопки — в кнопки Telegram
    HTML/ссылки не поместишь, поэтому берём как в пикере жалоб/анонимок."""
    row = await db.get_known_user(chat_id, user_id)
    if row:
        label = row["full_name"] or str(user_id)
        if row.get("username"):
            label += f" (@{row['username']})"
        return label
    try:
        member = await bot.get_chat_member(chat_id, user_id)
        label = member.user.full_name or str(user_id)
        if member.user.username:
            label += f" (@{member.user.username})"
        return label
    except Exception:
        return str(user_id)


def clan_menu_kb(clan_id: int, role: Optional[str]) -> InlineKeyboardMarkup:
    rows: list[list[InlineKeyboardButton]] = []
    if role in ("leader", "deputy"):
        rows.append([InlineKeyboardButton(text="✏️ Изменить", callback_data=f"clanmenu_edit:{clan_id}")])
        rows.append([
            InlineKeyboardButton(text="🎖 Звание", callback_data=f"clanmenu_title:{clan_id}"),
            InlineKeyboardButton(text="💬 Девиз", callback_data=f"clanmenu_motto:{clan_id}"),
        ])
    rows.append([InlineKeyboardButton(text="👥 Участники", callback_data=f"clanmenu_members:{clan_id}:0")])
    if role in ("leader", "deputy"):
        rows.append([InlineKeyboardButton(text="🛡 Управление участниками", callback_data=f"clanmenu_manage:{clan_id}:0")])
    rows.append([InlineKeyboardButton(text="🪙 Пополнить казну", callback_data=f"clanmenu_coins:{clan_id}")])
    if role in ("leader", "deputy"):
        rows.append([InlineKeyboardButton(text="⚔️ Война", callback_data=f"clanmenu_war:{clan_id}")])
    if role == "leader":
        rows.append([InlineKeyboardButton(text="🗑 Удалить клан", callback_data=f"clanmenu_delete:{clan_id}")])
    elif role is not None:
        rows.append([InlineKeyboardButton(text="🚪 Выйти из клана", callback_data=f"clanmenu_leave:{clan_id}")])
    rows.append([InlineKeyboardButton(text="🔄 Обновить", callback_data=f"clanmenu_open:{clan_id}")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


def _clan_back_kb(clan_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(
        inline_keyboard=[[InlineKeyboardButton(text="⬅️ Назад в меню клана", callback_data=f"clanmenu_open:{clan_id}")]]
    )


async def _open_clan_menu(callback: CallbackQuery, clan_id: int):
    chat_id = callback.message.chat.id
    clan = await db.get_clan(chat_id, clan_id)
    if clan is None:
        try:
            await callback.message.edit_text("Клан уже не существует.")
        except TelegramBadRequest:
            pass
        await callback.answer()
        return
    membership = await db.get_user_clan(chat_id, callback.from_user.id)
    role = membership["role"] if membership and membership["id"] == clan_id else None
    text = await clan_info_text(chat_id, clan)
    try:
        await callback.message.edit_text(text, reply_markup=clan_menu_kb(clan_id, role))
    except TelegramBadRequest:
        pass
    await callback.answer()


@router.callback_query(F.data.startswith("clanmenu_open:"))
async def clanmenu_open_cb(callback: CallbackQuery, state: FSMContext):
    await state.clear()
    clan_id = int(callback.data.split(":", maxsplit=1)[1])
    await _open_clan_menu(callback, clan_id)


# --- Изменить название/описание ---------------------------------------------

@router.callback_query(F.data.startswith("clanmenu_edit:"))
async def clanmenu_edit_cb(callback: CallbackQuery, state: FSMContext):
    clan_id = int(callback.data.split(":", maxsplit=1)[1])
    membership = await db.get_user_clan(callback.message.chat.id, callback.from_user.id)
    if membership is None or membership["id"] != clan_id or membership["role"] not in ("leader", "deputy"):
        await callback.answer("⛔ Изменять клан может только его лидер или зам.", show_alert=True)
        return
    await state.set_state(ClanMenuStates.waiting_edit)
    await state.update_data(clan_id=clan_id, menu_chat_id=callback.message.chat.id, menu_message_id=callback.message.message_id)
    try:
        await callback.message.edit_text(
            "✏️ Пришлите новое название клана (и, если нужно, описание отдельной строкой ниже — "
            "первая строка станет названием, остальное — описанием).\n\n"
            f"Максимум {CLAN_NAME_MAX} символов на название и {CLAN_DESCRIPTION_MAX} на описание.",
            reply_markup=_clan_back_kb(clan_id),
        )
    except TelegramBadRequest:
        pass
    await callback.answer()


@router.message(StateFilter(ClanMenuStates.waiting_edit), F.chat.type.in_({"group", "supergroup"}))
async def clanmenu_edit_process(message: Message, state: FSMContext):
    data = await state.get_data()
    clan_id = data.get("clan_id")
    membership = await db.get_user_clan(message.chat.id, message.from_user.id)
    if membership is None or membership["id"] != clan_id or membership["role"] not in ("leader", "deputy"):
        await state.clear()
        return
    name, description = _split_clan_name_and_description(message.text or "")
    if not name:
        await message.reply("Название не может быть пустым. Пришлите название ещё раз.", reply_markup=_clan_back_kb(clan_id))
        return
    await db.update_clan(message.chat.id, clan_id, name=name, description=description)
    await db.add_log("clan_edit", chat_id=message.chat.id, actor_id=message.from_user.id, details=name)
    await state.clear()
    clan = await db.get_clan(message.chat.id, clan_id)
    text = await clan_info_text(message.chat.id, clan) if clan else "Клан обновлён."
    await message.reply(f"✅ Клан обновлён.\n\n{text}", reply_markup=clan_menu_kb(clan_id, membership["role"]))


