async def clan_war_pick_text(chat_id: int, clan_id: int, page: int) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    page = max(page, 0)
    rows, total = await db.list_clans(chat_id, CLAN_WAR_PICK_PAGE_SIZE, page * CLAN_WAR_PICK_PAGE_SIZE)
    rows = [r for r in rows if r["id"] != clan_id]
    if not rows and page:
        page = 0
        rows, total = await db.list_clans(chat_id, CLAN_WAR_PICK_PAGE_SIZE, 0)
        rows = [r for r in rows if r["id"] != clan_id]
    if not rows:
        return "Нет других кланов, которых можно вызвать на войну.", _clan_back_kb(clan_id)
    buttons = [
        [InlineKeyboardButton(text=f"#{r['id']} {r['name'][:40]}", callback_data=f"clanmenu_war_challenge:{clan_id}:{r['id']}")]
        for r in rows
    ]
    pages = max((total + CLAN_WAR_PICK_PAGE_SIZE - 1) // CLAN_WAR_PICK_PAGE_SIZE, 1)
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="⬅️", callback_data=f"clanmenu_war_pick:{clan_id}:{page - 1}"))
    if pages > 1:
        nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page + 1 < pages:
        nav.append(InlineKeyboardButton(text="➡️", callback_data=f"clanmenu_war_pick:{clan_id}:{page + 1}"))
    if nav:
        buttons.append(nav)
    buttons.append([InlineKeyboardButton(text="⬅️ Назад", callback_data=f"clanmenu_war:{clan_id}")])
    return "⚔️ Выберите клан, которому хотите объявить войну:", InlineKeyboardMarkup(inline_keyboard=buttons)


