@router.callback_query(F.data.startswith("clanmenu_war_yes:"))
async def clanmenu_war_yes_cb(callback: CallbackQuery):
    clan_id = int(callback.data.split(":", maxsplit=1)[1])
    chat_id = callback.message.chat.id
    membership = await db.get_user_clan(chat_id, callback.from_user.id)
    if membership is None or membership["id"] != clan_id or membership["role"] not in ("leader", "deputy"):
        await callback.answer("⛔ Принять вызов может только лидер или зам клана.", show_alert=True)
        return
    war = await db.get_pending_clan_war_for(chat_id, clan_id)
    if war is None or war["target_clan_id"] != clan_id:
        await callback.answer("Нет ожидающего вас вызова на войну.", show_alert=True)
        return
    challenger = await db.get_clan(chat_id, war["challenger_clan_id"])
    target = await db.get_clan(chat_id, war["target_clan_id"])
    await db.delete_clan_war(war["id"])
    if challenger is None or target is None:
        await callback.answer("Один из кланов уже не существует — война отменена.", show_alert=True)
        await _open_clan_menu(callback, clan_id)
        return
    roll_challenger, roll_target = random.randint(1, 6), random.randint(1, 6)
    if roll_challenger > roll_target:
        winner, loser = challenger, target
    elif roll_target > roll_challenger:
        winner, loser = target, challenger
    else:
        winner = loser = None
    if winner is not None:
        await db.record_clan_war_result(chat_id, winner["id"], loser["id"])
        await db.add_log(
            "clan_war_result", chat_id=chat_id, actor_id=callback.from_user.id,
            details=f"{winner['name']} > {loser['name']}",
        )
        result_text = (
            f"⚔️ <b>Война кланов!</b>\n«{html.escape(challenger['name'])}» 🎲{roll_challenger} — "
            f"🎲{roll_target} «{html.escape(target['name'])}»\n\n"
            f"🏆 Победил клан «{html.escape(winner['name'])}»! +3 очка."
        )
    else:
        await db.record_clan_war_result(chat_id, None, None)
        result_text = (
            f"⚔️ <b>Война кланов!</b>\n«{html.escape(challenger['name'])}» 🎲{roll_challenger} — "
            f"🎲{roll_target} «{html.escape(target['name'])}»\n\n🤝 Ничья, очки не начислены."
        )
    await callback.answer()
    try:
        await callback.message.edit_text(result_text, reply_markup=_clan_back_kb(clan_id))
    except TelegramBadRequest:
        pass


