# ============================================================================
# Модуль «Закладки» (по образцу Iris, раздел 23) — разметка длинных потоков
# переписки по темам. Закладка хранит название, необязательный текст и,
# если создана ответом на сообщение, «якорь» — ссылку на это сообщение,
# по которой можно перейти прямо к обсуждению. Закладки всех участников
# чата образуют общий «чатбук».
# ============================================================================
BOOKMARK_TITLE_MAX = 40
BOOKMARK_TEXT_MAX = 3800
BOOKMARK_PAGE_SIZE = 10


async def bookmark_message_link(chat_id: int, message_id: int) -> Optional[str]:
    """Прямая ссылка на сообщение-якорь закладки: публичная (t.me/{user}/{id}),
    если у чата есть юзернейм, иначе приватная (t.me/c/{internal_id}/{id})."""
    try:
        chat = await bot.get_chat(chat_id)
    except Exception:
        chat = None
    username = getattr(chat, "username", None) if chat else None
    if username:
        return f"https://t.me/{username}/{message_id}"
    cid = str(chat_id)
    if cid.startswith("-100"):
        return f"https://t.me/c/{cid[4:]}/{message_id}"
    return None


def _split_bookmark_title_and_text(raw: str) -> tuple[str, Optional[str]]:
    parts = raw.split("\n", 1)
    title = parts[0].strip()[:BOOKMARK_TITLE_MAX]
    text = parts[1].strip()[:BOOKMARK_TEXT_MAX] if len(parts) > 1 and parts[1].strip() else None
    return title, text


async def bookmark_line(bookmark: dict, show_author: bool = True) -> str:
    title = html.escape(bookmark["title"])
    if bookmark.get("anchor_chat_id") and bookmark.get("anchor_message_id"):
        link = await bookmark_message_link(bookmark["anchor_chat_id"], bookmark["anchor_message_id"])
    else:
        link = None
    title_part = f'<a href="{link}">{title}</a>' if link else f"<b>{title}</b>"
    line = f"#{bookmark['id']} {title_part}"
    if show_author:
        line += f" — {mention_id(bookmark['author_id'])}"
    return line


async def bookmark_detail_text(bookmark: dict) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    lines = [
        f"🔖 <b>{html.escape(bookmark['title'])}</b>",
        DIVIDER,
        f"Автор: {mention_id(bookmark['author_id'])}",
    ]
    if bookmark.get("description"):
        lines.append("")
        lines.append(html.escape(bookmark["description"]))
    kb = None
    if bookmark.get("anchor_chat_id") and bookmark.get("anchor_message_id"):
        link = await bookmark_message_link(bookmark["anchor_chat_id"], bookmark["anchor_message_id"])
        if link:
            kb = InlineKeyboardMarkup(inline_keyboard=[[
                InlineKeyboardButton(text="➡️ Перейти к сообщению", url=link)
            ]])
    return "\n".join(lines), kb


async def chatbook_page_text(chat_id: int, page: int) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    page = max(page, 0)
    rows, total = await db.list_chatbook(chat_id, BOOKMARK_PAGE_SIZE, page * BOOKMARK_PAGE_SIZE)
    if not rows and page:
        page = 0
        rows, total = await db.list_chatbook(chat_id, BOOKMARK_PAGE_SIZE, 0)
    if not rows:
        return "📚 <b>Чатбук</b>\n\nЗакладок пока нет (см. «+закладка {название}»).", None
    lines = [await bookmark_line(r) for r in rows]
    pages = max((total + BOOKMARK_PAGE_SIZE - 1) // BOOKMARK_PAGE_SIZE, 1)
    text = f"📚 <b>Чатбук</b> ({total})\n{DIVIDER}\n" + "\n".join(lines)
    if pages == 1:
        return text, None
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="⬅️", callback_data=f"chatbook_page:{page - 1}"))
    nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page + 1 < pages:
        nav.append(InlineKeyboardButton(text="➡️", callback_data=f"chatbook_page:{page + 1}"))
    return text, InlineKeyboardMarkup(inline_keyboard=[nav])


async def user_bookmarks_page_text(
    chat_id: int, author_id: int, page: int, callback_prefix: str, title: str
) -> tuple[str, Optional[InlineKeyboardMarkup]]:
    page = max(page, 0)
    rows, total = await db.list_user_bookmarks(chat_id, author_id, BOOKMARK_PAGE_SIZE, page * BOOKMARK_PAGE_SIZE)
    if not rows and page:
        page = 0
        rows, total = await db.list_user_bookmarks(chat_id, author_id, BOOKMARK_PAGE_SIZE, 0)
    if not rows:
        return f"{title}\n\nЗакладок пока нет.", None
    lines = []
    for r in rows:
        line = await bookmark_line(r, show_author=False)
        if r["excluded"]:
            line += " 🚫"
        lines.append(line)
    pages = max((total + BOOKMARK_PAGE_SIZE - 1) // BOOKMARK_PAGE_SIZE, 1)
    text = f"{title} ({total})\n{DIVIDER}\n" + "\n".join(lines)
    if any(r["excluded"] for r in rows):
        text += "\n\n<i>🚫 — исключена из чатбука</i>"
    if pages == 1:
        return text, None
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="⬅️", callback_data=f"{callback_prefix}:{author_id}:{page - 1}"))
    nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="noop"))
    if page + 1 < pages:
        nav.append(InlineKeyboardButton(text="➡️", callback_data=f"{callback_prefix}:{author_id}:{page + 1}"))
    return text, InlineKeyboardMarkup(inline_keyboard=[nav])


BOOKMARK_ADD_RE = ru_text.rx(r"(?is)^\+закладка\s+(.+)$")
BOOKMARK_VIEW_RE = ru_text.rx(r"(?i)^закладка\s+(\d+)$")
BOOKMARK_CHATBOOK_RE = ru_text.rx(r"(?i)^чатбук(?:\s+(\d+))?$")
BOOKMARK_MY_RE = ru_text.rx(r"(?i)^мои\s+закладки(?:\s+(\d+))?$")
BOOKMARK_OF_RE = ru_text.rx(r"(?i)^закладки\s+")
BOOKMARK_DELETE_RE = ru_text.rx(r"(?i)^(?:удалить\s+закладку|-закладка)\s+(\d+)$")
BOOKMARK_EXCLUDE_RE = ru_text.rx(r"(?i)^(?:исключить\s+закладку|убрать\s+закладку)\s+(\d+)$")
BOOKMARK_KLADMEN_RETURN_RE = ru_text.rx(r"(?i)^(?:\+кладмен|вернуть\s+кладмена|освободить\s+кладмена)\b\s*(.*)$")
BOOKMARK_KLADMEN_EXCLUDE_RE = ru_text.rx(r"(?i)^(?:-кладмен|закрыть\s+кладмена|убрать\s+кладмена)\b\s*(.*)$")


@router.message(
    F.chat.type.in_({"group", "supergroup"}),
    F.text.func(lambda t: bool(t) and bool(BOOKMARK_ADD_RE.match(t.strip()))),
)
async def cmd_bookmark_add(message: Message):
    min_level = required_level("bookmark_add")
    if not has_level(message.from_user.id, min_level):
        await message.reply(f"⛔ Добавлять закладки может «{level_name(min_level)}» и выше.")
        return
    m = BOOKMARK_ADD_RE.match(message.text.strip())
    title, text = _split_bookmark_title_and_text(m.group(1))
    if not title:
        await message.reply("Укажите название закладки: «+закладка {название}».")
        return
    anchor_chat_id = anchor_message_id = None
    if message.reply_to_message:
        anchor_chat_id = message.reply_to_message.chat.id
        anchor_message_id = message.reply_to_message.message_id
    bookmark_id = await db.create_bookmark(
        message.chat.id, message.from_user.id, title, text, anchor_chat_id, anchor_message_id
    )
    await db.add_log("bookmark_add", chat_id=message.chat.id, actor_id=message.from_user.id, details=title)
    _rows, total_bookmarks = await db.list_user_bookmarks(message.chat.id, message.from_user.id, 1, 0)
    if total_bookmarks >= 10:
        await grant_achievement(message.chat.id, message.from_user.id, "bookmarks_10")
    suffix = " (со ссылкой на отмеченное сообщение)" if anchor_message_id else ""
    await message.reply(f"🔖 Закладка «{html.escape(title)}» добавлена (#{bookmark_id}){suffix}.")


