async def _resolve_kladmen_target(message: Message) -> Optional[SimpleNamespace]:
    """Цель для «+кладмен/-кладмен {ссылка}» (и словесных синонимов «вернуть
    кладмена»/«закрыть кладмена» и т.п.) — резолвим прямо из исходного
    сообщения, чтобы смещения entity (@username) остались верными, а не
    из обрезанного текста (offset считается от начала ИСХОДНОГО message.text)."""
    first_word = (message.text or "").strip().split(" ", 1)[0].casefold()
    trigger_words = 1 if first_word in ("+кладмен", "-кладмен") else 2
    target, _ = await resolve_command_target(message, trigger_words=trigger_words)
    if target is None and message.reply_to_message:
        target = message.reply_to_message.from_user
    return target


