async def warn_expiry_loop():
    """Раз в час физически подчищает сгоревшие варны (см. purge_expired_warns —
    на подсчёт активных варнов это не влияет, тот и так фильтрует по expires_at;
    это чисто хозяйственная уборка таблицы)."""
    while True:
        try:
            await db.purge_expired_warns()
        except Exception:
            logger.exception("Ошибка при очистке сгоревших варнов")
        await asyncio.sleep(3600)


# Раз в 15 секунд, а не раз в минуту: настройка задаётся в минутах, и при
# «чистка команд 1» разброс в целую минуту означал удаление вдвое позже
# обещанного. Запрос лёгкий (индекс по delete_at), четыре обращения в минуту
# базу не нагружают.
CMD_CLEANUP_CHECK_INTERVAL = 15
CMD_CLEANUP_BATCH = 200


async def cmd_cleanup_loop() -> None:
    """Удаляет просроченные команды и ответы бота.

    Порядок «сначала проверить, потом спать» — намеренный: после перезапуска в
    очереди уже лежат просроченные записи, и заставлять чат ждать ещё интервал
    незачем. Внутри одного круга выгребаем очередь до конца (пачками), иначе
    завал разбирался бы по CMD_CLEANUP_BATCH записей за раз и старые сообщения
    висели бы часами.
    """
    while True:
        try:
            while True:
                rows = await db.list_due_cleanup_entries(
                    datetime.utcnow(), limit=CMD_CLEANUP_BATCH
                )
                for row in rows:
                    try:
                        await bot.delete_message(row["chat_id"], row["message_id"])
                    except (TelegramBadRequest, TelegramForbiddenError):
                        # Сообщение уже удалили руками, либо оно старше 48 часов
                        # (Telegram такие удалять не даёт) — запись всё равно
                        # убираем, чтобы очередь не копила мёртвые строки.
                        pass
                    except Exception:
                        logger.exception("Ошибка удаления сообщения при очистке команд")
                    await db.delete_cleanup_entry(row["id"])
                if len(rows) < CMD_CLEANUP_BATCH:
                    break  # очередь разобрана до конца
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception("Сбой в цикле очистки команд")
        await asyncio.sleep(CMD_CLEANUP_CHECK_INTERVAL)


MUTE_SWEEP_INTERVAL = 300  # 5 минут


async def mute_expiry_sweep_loop() -> None:
    """Раз в 5 минут сверяет ВСЕ активные муты из БД с текущим временем и
    принудительно снимает мут у тех, чей срок истёк — подстраховка на случай,
    если одноразовая задача _auto_unmute не сработала (потеряна при
    рестарте, упала с исключением, или разошлась в сравнении timestamp'ов
    с точностью до секунды)."""
    while True:
        try:
            rows = await db.list_all_active_mutes()
            now = datetime.utcnow()
            for row in rows:
                muted_until = row.get("muted_until")
                if muted_until is None:
                    continue  # бессрочный мут — не трогаем
                if muted_until > now:
                    continue  # ещё не истёк

                chat_id, user_id = row["chat_id"], row["user_id"]
                try:
                    await bot.restrict_chat_member(
                        chat_id=chat_id, user_id=user_id, permissions=UNMUTE_PERMISSIONS
                    )
                except (TelegramForbiddenError, TelegramBadRequest):
                    pass  # бот мог потерять права/выйти из чата — БД всё равно чистим

                await db.remove_mute(chat_id, user_id)
                await db.add_log(
                    "unmute", chat_id=chat_id, target_id=user_id,
                    details="авто (плановая проверка каждые 5 мин)",
                )
                try:
                    name = await display_name_by_id(chat_id, user_id)
                    await bot.send_message(chat_id, f"🔊 Мут {name} истёк — снят автоматически.")
                except Exception as exc:
                    log_suppressed("mute_expiry_sweep_loop", exc)
        except Exception:
            logger.exception("Ошибка в mute_expiry_sweep_loop")
        await asyncio.sleep(MUTE_SWEEP_INTERVAL)

async def role_reservation_expiry_loop():
    """Раз в час снимает протухшие брони ролей (см. ROLE_RESERVE_TIMEOUT_HOURS)
    и уведомляет тех, чья бронь сгорела."""
    while True:
        try:
            expired = await db.expire_stale_reservations(ROLE_RESERVE_TIMEOUT_HOURS)
            for role in expired:
                if not role.get("reserved_user_id"):
                    continue
                try:
                    await bot.send_message(
                        role["reserved_user_id"],
                        f"⌛ Бронь роли «{html.escape(role['name'])}» истекла — роль снова свободна.",
                    )
                except Exception as exc:
                    log_suppressed("role_reservation_expiry_loop", exc)
        except Exception:
            logger.exception("Ошибка при снятии протухших броней ролей")
        await asyncio.sleep(3600)


